            // 从基因控制器获取当前飞行速度属性
            float moveSpeed = _context.Genes.GetAttribute("moveSpeed");
            if (moveSpeed > 0)
            {
                // 简单测试：让实体沿球体切线方向移动
                // 实际项目中可以加上飞行高度、耗能等逻辑
            }
