using System;
using System.IO;
using UnityEngine;

namespace DarwinPark.Core
{
    // ★ 新增：安装目录中可直接修改的全局数值；重启后同时作用于新旧世界，不覆盖世界保存的基因配置。
    [Serializable] public sealed class GameplayTuning
    {
        public int version=1;
        public float baseMetabolismMultiplier=1, movementMetabolismMultiplier=1;
        public float repairFoodPerHealth=.5f, starvationDamagePerSecond=1;
        public float manualAimPadding=.85f, manualHitboxScale=1.5f, manualAttackReachBonus=.35f;
        public float supplyActivityRadiusRatio=1;
        public float colonyActivityRadiusMultiplier=.35f, populationFillOpacity=.22f;
        // ★ 新增：成年且无合适配偶的连续等待天数，外部配置可热更新。
        public float parthenogenesisWaitDays=5;
        private static GameplayTuning _current;
        private static long _stamp;private static float _nextPoll;
        public static string FilePath=>Path.Combine(GamePaths.Root,"config","gameplay.json");
        public static GameplayTuning Current {get{if(_current==null)Reload();return _current;}}
        public static GameplayTuning Parse(string json)
        {
            var value=JsonUtility.FromJson<GameplayTuning>(CommentedJson.Strip(json));
            if(value==null||value.version!=1)throw new InvalidDataException("游戏数值配置版本无效");
            foreach(var field in typeof(GameplayTuning).GetFields())if(field.FieldType==typeof(float))
            {float n=(float)field.GetValue(value);if(float.IsNaN(n)||float.IsInfinity(n)||n<0)throw new InvalidDataException("数值必须为非负有限数："+field.Name);}
            if(value.manualHitboxScale<1||value.supplyActivityRadiusRatio<=0||value.colonyActivityRadiusMultiplier<=0||value.populationFillOpacity>1)throw new InvalidDataException("判定框倍率至少为1，活动半径倍率必须大于0，透明度须在0到1之间");
            return value;
        }
        public static void Reload()
        {
            var asset=Resources.Load<TextAsset>("gameplay_tuning");
            if(asset==null)throw new InvalidDataException("缺少 gameplay_tuning 默认配置");
            var fallback=Parse(asset.text);
            try
            {
                if(!File.Exists(FilePath)){Directory.CreateDirectory(Path.GetDirectoryName(FilePath));File.WriteAllText(FilePath,asset.text,new System.Text.UTF8Encoding(false));}
                _current=Parse(File.ReadAllText(FilePath));_stamp=File.GetLastWriteTimeUtc(FilePath).Ticks;
            }
            catch(Exception ex){if(_current==null)_current=fallback;Debug.LogWarning("[游戏数值] "+FilePath+" 无法读取，保留上次有效配置："+ex.Message);}
        }
        public static void Poll()
        {
            // ★ 适配：编辑器和发布版均检测外部文件变化；不在属性热路径逐实体访问磁盘。
            if(Time.unscaledTime<_nextPoll)return;_nextPoll=Time.unscaledTime+2;
            try{long stamp=File.GetLastWriteTimeUtc(FilePath).Ticks;if(stamp!=_stamp){_stamp=stamp;Reload();}}catch(Exception ex)when(ex is IOException||ex is UnauthorizedAccessException){Debug.LogWarning("[游戏数值] 检查外部配置失败："+ex.Message);}
        }
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)] private static void Reset(){_current=null;_stamp=0;_nextPoll=0;}
    }
}

using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;

namespace DarwinPark.Core
{
    // ★ 新增：共享读取、原子替换和有界导出只处理诊断目录，不遍历存档、账号或命令行。
    public static class DiagnosticFiles
    {
        public static readonly Encoding Utf8=new UTF8Encoding(false);
        public static void AtomicText(string file,string text)
        {
            string temp=file+".tmp";
            using(var stream=new FileStream(temp,FileMode.Create,FileAccess.Write,FileShare.Read))
            {var bytes=Utf8.GetBytes(text??"");stream.Write(bytes,0,bytes.Length);stream.Flush(true);}
            if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);
        }
        public static byte[] Tail(string file,int maximum)
        {
            using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))
            {
                int count=(int)Math.Min(stream.Length,maximum);bool trimmed=stream.Length>count;stream.Seek(-count,SeekOrigin.End);
                var bytes=new byte[count];int read=0,n;while(read<count&&(n=stream.Read(bytes,read,count-read))>0)read+=n;
                // ★ 修复（防Bug回归）：从完整下一行开始，避免截在中文UTF-8编码中间。
                int start=trimmed?Array.IndexOf(bytes,(byte)'\n',0,read)+1:0;
                return bytes.Skip(start).Take(read-start).ToArray();
            }
        }
        public static bool IsOwnedRun(string directory)=>Path.GetFileName(directory).StartsWith("run-",StringComparison.Ordinal)&&
            Guid.TryParseExact(Path.GetFileName(directory).Substring(4),"N",out _)&&File.Exists(Path.Combine(directory,"session.txt"));
        public static bool IsInactive(string directory)
        {
            try{using(new FileStream(Path.Combine(directory,"active.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))return true;}
            catch(IOException){return false;}catch(UnauthorizedAccessException){return false;}
        }
        public static string[] Runs(string root)=>Directory.Exists(root)?Directory.GetDirectories(root,"run-*")
            .Where(d=>(File.GetAttributes(d)&FileAttributes.ReparsePoint)==0&&IsOwnedRun(d)).OrderByDescending(Directory.GetCreationTimeUtc).ToArray():Array.Empty<string>();
        public static void RetainRuns(string root,int retained)
        {
            foreach(string old in Runs(root).Skip(retained))
                if(IsInactive(old))try{Directory.Delete(old,true);}catch(IOException){ }catch(UnauthorizedAccessException){ }
        }
        public static string Export(string root,string nativeDirectory,RuntimeDiagnosticSettings settings)
        {
            string exportRoot=Path.Combine(root,"exports");Directory.CreateDirectory(exportRoot);
            string output=Path.Combine(exportRoot,"diagnostics-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N")+".zip");
            string temporary=output+".tmp";long remaining=settings.exportMaximumBytes;var notes=new StringBuilder();
            try
            {
                using(var zip=ZipFile.Open(temporary,ZipArchiveMode.Create))
                {
                    foreach(string run in Runs(root).Take(settings.retainedSessions))
                    {
                        // 白名单禁止把锁文件、临时文件和意外放入目录的存档打包。
                        foreach(string name in new[]{"session.txt","state.json","health.txt","critical.log","critical-previous.log","events-tail.log","player-tail.log","completed.txt","abnormal-exit.txt"})
                            Add(zip,Path.Combine(run,name),Path.GetFileName(run)+"/"+name,ref remaining,notes);
                    }
                    // 原生转储仅为同一游戏崩溃目录中的近期候选，不能据此断言属于当前实例。
                    try
                    {
                        if(!string.IsNullOrEmpty(nativeDirectory)&&Directory.Exists(nativeDirectory))
                        {
                            var candidates=NativeFiles(nativeDirectory,settings.nativeSearchDepth).Where(f=>File.GetLastWriteTimeUtc(f)>=DateTime.UtcNow.AddHours(-settings.nativeLookbackHours))
                                .OrderByDescending(File.GetLastWriteTimeUtc).Take(settings.nativeMaximumFiles);
                            foreach(string file in candidates)Add(zip,file,"native-candidates/"+Path.GetRelativePath(nativeDirectory,file).Replace('\\','/'),ref remaining,notes);
                        }
                    }
                    catch(IOException ex){notes.AppendLine("原生报告目录读取失败："+ex.Message);}
                    catch(UnauthorizedAccessException ex){notes.AppendLine("原生报告目录读取失败："+ex.Message);}
                    var entry=zip.CreateEntry("README.txt");using(var writer=new StreamWriter(entry.Open(),Utf8))writer.Write(
                        "诊断包：请同时提供复现步骤、发生时间和游戏版本。\nabnormal-exit 只表示未完成正常关闭，也可能是强制结束或断电，不代表已确定崩溃原因。\n"+
                        "state 为最近主线程采样，health 为后台心跳。卡死时两者时间差有助定位。critical 为独立刷盘的错误/异常；events 为最近游戏日志；player 为发布版Unity原始日志尾部。\n"+
                        "native-candidates 如存在，是最近"+settings.nativeLookbackHours+"小时同游戏目录的候选报告；编辑器不自动采集Editor.log，以避免混入Unity授权信息。没有转储不代表没有崩溃。\n"+
                        "未打包存档或完整基因数据。文件仍可能含本机路径/玩家命名/网络地址，分享前可检查。\n"+notes);
                }
                File.Move(temporary,output);
                foreach(var old in new DirectoryInfo(exportRoot).GetFiles("diagnostics-*.zip").OrderByDescending(f=>f.CreationTimeUtc).Skip(settings.retainedExports))
                    try{old.Delete();}catch(IOException){ }catch(UnauthorizedAccessException){ }
                return output;
            }
            catch{try{File.Delete(temporary);}catch(IOException){ }throw;}
        }
        private static System.Collections.Generic.IEnumerable<string> NativeFiles(string root,int depth)
        {
            if((File.GetAttributes(root)&FileAttributes.ReparsePoint)!=0)yield break;
            foreach(string file in Directory.GetFiles(root))if((File.GetAttributes(file)&FileAttributes.ReparsePoint)==0&&
                (Path.GetExtension(file).Equals(".dmp",StringComparison.OrdinalIgnoreCase)||Path.GetExtension(file).Equals(".log",StringComparison.OrdinalIgnoreCase)||Path.GetFileName(file)=="error.txt"))yield return file;
            if(depth>0)foreach(string child in Directory.GetDirectories(root))foreach(string file in NativeFiles(child,depth-1))yield return file;
        }
        private static void Add(ZipArchive zip,string file,string name,ref long remaining,StringBuilder notes)
        {
            if(!File.Exists(file))return;
            try
            {
                using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))
                {
                    long length=input.Length;if(length>remaining){notes.AppendLine("预算不足，未包含："+name+" ("+length+" bytes)");return;}
                    using(var output=zip.CreateEntry(name,CompressionLevel.Fastest).Open())
                    {
                        var buffer=new byte[8192];long left=length;while(left>0){int n=input.Read(buffer,0,(int)Math.Min(buffer.Length,left));if(n==0)break;output.Write(buffer,0,n);left-=n;}
                    }
                    remaining-=length;
                }
            }
            catch(IOException ex){notes.AppendLine("读取失败："+name+"："+ex.Message);}catch(UnauthorizedAccessException ex){notes.AppendLine("读取失败："+name+"："+ex.Message);}
        }
    }
}

using System;
using System.Diagnostics;
using System.Runtime.InteropServices;

namespace DarwinPark.Core
{
    // ★ 修复（防Bug回归）：部分Windows Mono的Process.WorkingSet64恒为0，用系统计数避免把内存不足误报为零占用。
    public static class DiagnosticMemory
    {
#if UNITY_STANDALONE_WIN || UNITY_EDITOR_WIN
        [StructLayout(LayoutKind.Sequential)] private struct Counters
        {
            public uint size,pageFaults;
            public UIntPtr peakWorkingSet,workingSet,peakPagedPool,pagedPool,peakNonPagedPool,nonPagedPool,pageFile,peakPageFile;
        }
        [DllImport("kernel32.dll")] private static extern IntPtr GetCurrentProcess();
        [DllImport("psapi.dll",SetLastError=true)] [return:MarshalAs(UnmanagedType.Bool)]
        private static extern bool GetProcessMemoryInfo(IntPtr process,ref Counters counters,uint size);
#endif
        public static string WorkingSetBytes()
        {
            try
            {
#if UNITY_STANDALONE_WIN || UNITY_EDITOR_WIN
                var counters=new Counters{size=(uint)Marshal.SizeOf(typeof(Counters))};
                if(GetProcessMemoryInfo(GetCurrentProcess(),ref counters,counters.size)&&counters.workingSet.ToUInt64()>0)return counters.workingSet.ToUInt64().ToString();
#endif
                using(var process=Process.GetCurrentProcess()){process.Refresh();return process.WorkingSet64>0?process.WorkingSet64.ToString():"不可用";}
            }
            catch(Exception ex){return "不可用："+ex.GetType().Name;}
        }
    }
}

using UnityEngine;

namespace DarwinPark.Core
{
    /// <summary>
    /// 统一日志出口。
    /// ★ 新增：给所有模块打标签前缀，方便 Console 过滤；禁用时可按 tag 关闭。
    /// 规则1：加载失败/引用缺失必须走这里，不允许空 catch 吞错误。
    /// </summary>
    public static class Log
    {
        [System.Flags]
        public enum Tag
        {
            None = 0,
            Data = 1 << 0,
            Genetics = 1 << 1,
            Mutation = 1 << 2,
            Reproduction = 1 << 3,
            Entity = 1 << 4,
            AI = 1 << 5,
            Planet = 1 << 6,
            Environment = 1 << 7,
            Stats = 1 << 8,
            UI = 1 << 9,
            Bootstrap = 1 << 10
        }

        public static Tag Mask = Tag.None; // 设为 None 表示全部输出

        public static void Info(Tag tag, string msg)
        {
            if (Mask != Tag.None && (Mask & tag) == 0) return;
            Debug.Log($"[{tag}] {msg}");
        }

        public static void Warn(Tag tag, string msg)
        {
            if (Mask != Tag.None && (Mask & tag) == 0) return;
            Debug.LogWarning($"[{tag}] {msg}");
        }

        public static void Error(Tag tag, string msg)
        {
            Debug.LogError($"[{tag}] {msg}"); // 错误永远输出
        }

        public static void Exception(Tag tag, string msg, System.Exception e)
        {
            Debug.LogError($"[{tag}] {msg}：{e}");
        }
    }
}

using System;
using System.IO;
using System.Threading.Tasks;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace DarwinPark.Core
{
    // ★ 新增：Unity只在主线程采样；线程异常处理器只能访问纯托管会话，不能查询场景或显卡API。
    public static class RuntimeCrashDiagnostics
    {
        private static RuntimeDiagnosticSession _session;
        private static RuntimeDiagnosticSettings _settings;
        public static Func<Snapshot> SampleState;
        private static string _nativeFolder="",_root="";
        private static double _sampleAt;
        private static float _worstFrame;
        private static string _startupFailure="";
        public static string DirectoryPath=>_session?.DirectoryPath??"";
        public static string Failure=>_session?.Failure??_startupFailure;
        public static int PreviousAbnormalSessions=>_session?.RecoveredSessions??0;
        [Serializable] public sealed class Snapshot
        {
            public string utc,scene,worldId,worldName,loadingStatus,saveStatus,networkRole,fileLogFailure;
            public int frame,entities,members;
            public bool ready,loading,running,focused;
            public float lastFrameMilliseconds,worstFrameMilliseconds,configuredSpeed,actualSpeed,gameTime;
            public double pendingSimulationSeconds;
            public long unityAllocatedBytes,unityReservedBytes;
        }
        public static void Start(Func<string> logFile=null)
        {
            Stop("重置诊断会话");_startupFailure="";
            try
            {
                _settings=RuntimeDiagnosticSettings.Load();if(!_settings.enabled)return;
                // 错误/异常总保留脚本调用栈，普通输出不打开Full堆栈，避免额外性能开销。
                foreach(var type in new[]{LogType.Error,LogType.Exception,LogType.Assert})Application.SetStackTraceLogType(type,StackTraceLogType.ScriptOnly);
                _root=Path.Combine(RuntimeFileLog.DirectoryPath,"diagnostics");_nativeFolder="";
#if UNITY_STANDALONE_WIN && !UNITY_EDITOR
                _nativeFolder=UnityEngine.Windows.CrashReporting.crashReportFolder;
#endif
                string header="游戏="+Application.productName+"\n版本="+Application.version+"\n构建GUID="+Application.buildGUID+"\nUnity="+Application.unityVersion+"\n编辑器="+Application.isEditor+
                    "\n系统="+SystemInfo.operatingSystem+"\nCPU="+SystemInfo.processorType+"\n内存MB="+SystemInfo.systemMemorySize+
                    "\nGPU="+SystemInfo.graphicsDeviceName+"\n图形API="+SystemInfo.graphicsDeviceType+"\nUnity日志="+Application.consoleLogPath+"\n原生崩溃目录="+_nativeFolder+
                    "\n游戏日志="+RuntimeFileLog.CurrentFilePath+"\n";
                string initialLog=RuntimeFileLog.CurrentFilePath;
                _session=new RuntimeDiagnosticSession(_root,_settings,header,logFile??(()=>initialLog),Application.isEditor?null:Application.consoleLogPath);
                _sampleAt=0;_worstFrame=0;
                AppDomain.CurrentDomain.UnhandledException+=Unhandled;TaskScheduler.UnobservedTaskException+=Unobserved;
                Tick();
                Debug.Log("[诊断] 崩溃前状态与独立错误记录："+DirectoryPath);
                if(PreviousAbnormalSessions>0)Debug.LogWarning("[诊断] 发现 "+PreviousAbnormalSessions+" 次未正常结束的会话，已标记abnormal-exit.txt；请导出诊断包排查，标记本身不代表已确定原因。");
            }
            catch(Exception ex){_startupFailure=ex.ToString();Debug.LogError("[诊断] 启动失败："+ex.Message);}
        }
        public static void Receive(string message,string stack,LogType type)
        {if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)_session?.RecordCritical("["+type+"] "+message,stack);}
        public static void Tick()
        {
            var session=_session;if(session==null)return;session.Pulse();
            _worstFrame=Mathf.Max(_worstFrame,Time.unscaledDeltaTime*1000);
            double now=Time.realtimeSinceStartupAsDouble;if(now<_sampleAt)return;_sampleAt=now+_settings.sampleMilliseconds/1000.0;
            ServiceLocator.TryGet<SimulationClock>(out var clock);
            var state=SampleState?.Invoke()??new Snapshot();
            state.utc=DateTime.UtcNow.ToString("O");state.scene=SceneManager.GetActiveScene().name;state.frame=Time.frameCount;
            state.fileLogFailure=RuntimeFileLog.Failure;
            state.ready=WorldRuntimeGate.Ready;state.loading|=WorldRuntimeGate.Loading;state.running=clock!=null&&clock.IsRunning;
            state.focused=Application.isFocused;state.lastFrameMilliseconds=Time.unscaledDeltaTime*1000;state.worstFrameMilliseconds=_worstFrame;
            state.configuredSpeed=clock?.ConfiguredTimeScale??0;state.actualSpeed=clock?.MotionTimeScale??0;state.gameTime=clock?.GameTime??0;
            state.pendingSimulationSeconds=clock?.PendingGameTime??0;
            state.unityAllocatedBytes=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong();
            state.unityReservedBytes=UnityEngine.Profiling.Profiler.GetTotalReservedMemoryLong();
            session.Pulse(JsonUtility.ToJson(state,true));_worstFrame=0;
        }
        private static void Unhandled(object sender,UnhandledExceptionEventArgs args)
        {
            _session?.RecordCritical("[未处理异常] terminating="+args.IsTerminating,args.ExceptionObject?.ToString(),args.IsTerminating);
            RuntimeFileLog.Flush();
        }
        private static void Unobserved(object sender,UnobservedTaskExceptionEventArgs args)
        {
            _session?.RecordCritical("[未观察的Task异常]",args.Exception.ToString());
            // 不SetObserved，不改变游戏原本的异常传播策略。
        }
        public static Task<string> ExportAsync()
        {
            if(_session==null)return Task.FromException<string>(new InvalidOperationException("诊断系统未启用："+Failure));
            var session=_session;var settings=_settings;string root=_root,native=_nativeFolder;
            return Task.Run(()=>{RuntimeFileLog.Flush();session.Checkpoint();return DiagnosticFiles.Export(root,native,settings);});
        }
        public static void Stop(string reason)
        {
            AppDomain.CurrentDomain.UnhandledException-=Unhandled;TaskScheduler.UnobservedTaskException-=Unobserved;
            var session=_session;_session=null;session?.Close(true,reason);
        }
    }
}

using System;
using System.Diagnostics;
using System.IO;
using System.Text;
using System.Threading;

namespace DarwinPark.Core
{
    // ★ 新增：独立于Unity主线程的心跳与紧急错误文件；主线程卡死时仍能保存最后状态及停顿时间。
    public sealed class RuntimeDiagnosticSession : IDisposable
    {
        private readonly RuntimeDiagnosticSettings _settings;
        private readonly Func<string> _logFile;
        private readonly string _nativeLog;
        private readonly FileStream _active;
        private readonly ManualResetEventSlim _stop=new ManualResetEventSlim();
        private readonly object _disk=new object(),_critical=new object();
        private readonly Thread _worker;
        private long _heartbeat=Stopwatch.GetTimestamp(),_window;
        private int _windowCount,_suppressed,_closed,_fatal;
        private bool _clean;
        private string _state="{}",_failure,_lastError="",_reason="";
        public string DirectoryPath {get;}
        public string Failure=>Volatile.Read(ref _failure);
        public int RecoveredSessions {get;}
        public RuntimeDiagnosticSession(string root,RuntimeDiagnosticSettings settings,string header,Func<string> logFile,string nativeLog)
        {
            settings.Validate();_settings=settings;_logFile=logFile;_nativeLog=nativeLog;Directory.CreateDirectory(root);
            foreach(string old in DiagnosticFiles.Runs(root))
            {
                if(File.Exists(Path.Combine(old,"completed.txt"))||File.Exists(Path.Combine(old,"abnormal-exit.txt"))||!DiagnosticFiles.IsInactive(old))continue;
                DiagnosticFiles.AtomicText(Path.Combine(old,"abnormal-exit.txt"),"发现时间 UTC="+DateTime.UtcNow.ToString("O")+
                    "\n上次会话没有正常关闭标记。可能为崩溃、强制结束、断电或日志自身故障；此标记不确定原因。请查看critical、health、state以及Unity原生崩溃报告。\n");RecoveredSessions++;
            }
            DirectoryPath=Path.Combine(root,"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(DirectoryPath);
            _active=new FileStream(Path.Combine(DirectoryPath,"active.lock"),FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None);
            try
            {
                DiagnosticFiles.AtomicText(Path.Combine(DirectoryPath,"session.txt"),"格式=1\n开始UTC="+DateTime.UtcNow.ToString("O")+"\n进程="+Process.GetCurrentProcess().Id+"\n"+header);
                DiagnosticFiles.RetainRuns(root,settings.retainedSessions);
                Checkpoint();
                _worker=new Thread(Loop){IsBackground=true,Name="DarwinPark.Diagnostics"};_worker.Start();
            }
            catch{_active.Dispose();throw;}
        }
        public void Pulse(string state=null)
        {
            Interlocked.Exchange(ref _heartbeat,Stopwatch.GetTimestamp());
            if(state!=null)Volatile.Write(ref _state,state);
        }
        public void RecordCritical(string message,string stack,bool fatal=false)
        {
            if(Volatile.Read(ref _closed)!=0)return;
            if(fatal)Interlocked.Exchange(ref _fatal,1);
            try
            {
                lock(_critical)
                {
                    // ★ 修复（防Bug回归）：错误风暴必须限流且留计数；真正未处理异常始终越过限流写入。
                    long window=Stopwatch.GetTimestamp()/Stopwatch.Frequency;
                    if(window!=_window){_window=window;_windowCount=0;}
                    if(++_windowCount>_settings.criticalPerSecond&&!fatal){Interlocked.Increment(ref _suppressed);return;}
                    string detail=(message??"")+"\n"+(stack??"");int limit=_settings.criticalBytes/4;
                    if(detail.Length>limit)detail=detail.Substring(0,limit)+"…[已截断]";
                    _lastError=DateTimeOffset.Now.ToString("O")+" [线程 "+Thread.CurrentThread.ManagedThreadId+"] "+detail;
                    string file=Path.Combine(DirectoryPath,"critical.log");
                    if(File.Exists(file)&&new FileInfo(file).Length+Encoding.UTF8.GetByteCount(_lastError)+2>_settings.criticalBytes)
                    {string previous=Path.Combine(DirectoryPath,"critical-previous.log");if(File.Exists(previous))File.Delete(previous);File.Move(file,previous);}
                    using(var stream=new FileStream(file,FileMode.Append,FileAccess.Write,FileShare.Read))
                    {byte[] bytes=DiagnosticFiles.Utf8.GetBytes(_lastError+"\n");stream.Write(bytes,0,bytes.Length);stream.Flush(true);}
                }
            }
            catch(Exception ex){Volatile.Write(ref _failure,"紧急日志："+ex.Message);}
        }
        public void Checkpoint()
        {
            lock(_disk)
            {
                DiagnosticFiles.AtomicText(Path.Combine(DirectoryPath,"state.json"),Volatile.Read(ref _state));
                double age=(Stopwatch.GetTimestamp()-Interlocked.Read(ref _heartbeat))*1000.0/Stopwatch.Frequency;
                DiagnosticFiles.AtomicText(Path.Combine(DirectoryPath,"health.txt"),"写入UTC="+DateTime.UtcNow.ToString("O")+
                        "\n主线程心跳间隔ms="+age.ToString("F0",System.Globalization.CultureInfo.InvariantCulture)+
                        "\n疑似主线程停顿="+(age>=_settings.stallMilliseconds)+"\n进程工作集bytes="+DiagnosticMemory.WorkingSetBytes()+
                        "\n托管内存bytes="+GC.GetTotalMemory(false)+"\n紧急日志限流数="+Volatile.Read(ref _suppressed)+
                        "\n诊断写盘故障="+Failure+"\n最近错误="+Volatile.Read(ref _lastError));
                CopyTail(_logFile?.Invoke(),"events-tail.log");CopyTail(_nativeLog,"player-tail.log");
            }
        }
        private void CopyTail(string source,string name)
        {
            if(string.IsNullOrEmpty(source)||!File.Exists(source))return;
            try{DiagnosticFiles.AtomicText(Path.Combine(DirectoryPath,name),DiagnosticFiles.Utf8.GetString(DiagnosticFiles.Tail(source,_settings.tailBytes)));}
            catch(IOException ex){Volatile.Write(ref _failure,"日志尾部："+ex.Message);}catch(UnauthorizedAccessException ex){Volatile.Write(ref _failure,"日志尾部："+ex.Message);}
        }
        private void Loop()
        {
            try
            {
                while(!_stop.Wait(_settings.snapshotMilliseconds))
                {try{Checkpoint();}catch(Exception ex){Volatile.Write(ref _failure,"诊断快照："+ex.Message);}}
                Checkpoint();
                if(_clean&&Volatile.Read(ref _fatal)==0&&Failure==null)
                    DiagnosticFiles.AtomicText(Path.Combine(DirectoryPath,"completed.txt"),DateTime.UtcNow.ToString("O")+"\n"+_reason);
            }
            catch(Exception ex){Volatile.Write(ref _failure,"诊断结束："+ex.Message);}
            finally{_active.Dispose();}
        }
        public void Close(bool clean,string reason)
        {
            if(Interlocked.Exchange(ref _closed,1)!=0)return;
            _clean=clean;_reason=reason;_stop.Set();
            if(!_worker.Join(_settings.shutdownMilliseconds))Volatile.Write(ref _failure,"诊断写盘结束等待超时");
        }
        public void Dispose()=>Close(true,"日志系统正常关闭");
    }
}

using System;
using System.IO;
using UnityEngine;

namespace DarwinPark.Core
{
    // ★ 新增：诊断频率和磁盘预算独立配置，不能为排查卡顿引入逐帧写盘。
    [Serializable] public sealed class RuntimeDiagnosticSettings
    {
        public int version=1;
        public bool enabled=true;
        public int snapshotMilliseconds=5000, sampleMilliseconds=1000, stallMilliseconds=15000;
        public int shutdownMilliseconds=3000;
        public int retainedSessions=8, criticalBytes=524288, criticalPerSecond=8;
        public int tailBytes=262144, retainedExports=3, exportMaximumBytes=67108864, nativeMaximumFiles=16;
        public int nativeLookbackHours=48,nativeSearchDepth=2;
        public void Validate()
        {
            if(version!=1||snapshotMilliseconds<100||sampleMilliseconds<100||shutdownMilliseconds<100||stallMilliseconds<snapshotMilliseconds*2L||
               retainedSessions<2||criticalBytes<4096||criticalPerSecond<1||tailBytes<1024||retainedExports<1||
               exportMaximumBytes<tailBytes*4L||nativeMaximumFiles<1||nativeLookbackHours<1||nativeLookbackHours>8760||nativeSearchDepth<0||nativeSearchDepth>8)throw new InvalidDataException("崩溃诊断配置无效");
        }
        public static RuntimeDiagnosticSettings Load()
        {
            var asset=Resources.Load<TextAsset>("runtime_diagnostics");
            if(asset==null)throw new InvalidDataException("缺少 Resources/runtime_diagnostics.json");
            var settings=JsonUtility.FromJson<RuntimeDiagnosticSettings>(asset.text);
            if(settings==null)throw new InvalidDataException("崩溃诊断配置为空");settings.Validate();return settings;
        }
    }
}

using System;
using System.IO;
using UnityEngine;

namespace DarwinPark.Core
{
    // ★ 新增：场景Awake之前接收Unity所有线程的输出；正常版和开发版均自动保存，不要求用户打开调试模式。
    public static class RuntimeFileLog
    {
        private static SessionLogWriter _writer;
        private static string _startupFailure;
        public static string DirectoryPath=>_writer?.DirectoryPath??"";
        public static string CurrentFilePath=>_writer?.CurrentFilePath??"";
        public static string Failure=>_writer?.Failure??_startupFailure;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void Reset()=>Shutdown("重置运行会话");
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
        public static void Initialize()
        {
            try
            {
                var settings=RuntimeLogSettings.Load();
                StartSession(settings,Path.Combine(GamePaths.Root,settings.directoryName),Path.Combine(Application.persistentDataPath,settings.directoryName));
                if(_writer==null)return;
                // ★ 适配：普通日志之外单独保存异常和心跳，避免进程突然消失只剩Console输出。
                var activeWriter=_writer;RuntimeCrashDiagnostics.Start(()=>activeWriter.CurrentFilePath);
                Debug.Log("[日志] 文件："+CurrentFilePath);
                Debug.Log("[运行] 游戏="+Application.productName+"，版本="+Application.version+"，Unity="+Application.unityVersion+"，平台="+Application.platform+"，编辑器="+Application.isEditor);
                Debug.Log("[系统] "+SystemInfo.operatingSystem+"，CPU="+SystemInfo.processorType+"，内存MB="+SystemInfo.systemMemorySize+"，GPU="+SystemInfo.graphicsDeviceName+"，图形接口="+SystemInfo.graphicsDeviceType);
                Debug.Log("[路径] 世界存档="+GamePaths.Saves+"，自定义基因="+GamePaths.Mods);
                if(Application.isPlaying){var host=new GameObject("RuntimeFileLog");UnityEngine.Object.DontDestroyOnLoad(host);host.AddComponent<RuntimeLogLifecycle>().Bind(_writer);}
            }
            catch(Exception ex){_startupFailure=ex.ToString();Debug.LogError("[日志] 文件日志未能启用："+ex.Message);}
        }
        public static void StartSession(RuntimeLogSettings settings,string preferredDirectory,string fallbackDirectory)
        {
            Shutdown("切换日志会话");_startupFailure=null;if(!settings.enabled)return;
            _writer=new SessionLogWriter(settings,preferredDirectory,fallbackDirectory);
            Application.logMessageReceivedThreaded+=Receive;
            if(_writer.FallbackReason!=null)Debug.LogWarning("[日志] 游戏目录不可写，已保存到 "+DirectoryPath+"；原因："+_writer.FallbackReason);
            Debug.Log("[日志] 会话开始");
        }
        private static void Receive(string message,string stack,LogType type)
        {
            _writer?.Write(message,stack,type);
            RuntimeCrashDiagnostics.Receive(message,stack,type);
        }
        public static bool Flush()=>_writer?.Flush()??false;
        public static void Shutdown(string reason="正常关闭")
        {
            Application.logMessageReceivedThreaded-=Receive;
            var writer=_writer;_writer=null;if(writer==null){RuntimeCrashDiagnostics.Stop(reason);return;}
            writer.Write("[日志] 会话结束："+reason,"",LogType.Log);writer.Dispose();
            // ★ 适配：先排空普通日志，再关闭诊断心跳；正常关闭标记不能早于末尾输出。
            RuntimeCrashDiagnostics.Stop(reason);
        }
        internal static void ShutdownIfCurrent(SessionLogWriter writer){if(ReferenceEquals(_writer,writer))Shutdown();}
        public static void OpenDirectory()
        {
            if(string.IsNullOrEmpty(DirectoryPath))return;
            try{Application.OpenURL(new Uri(DirectoryPath+Path.DirectorySeparatorChar).AbsoluteUri);}catch(Exception ex){Debug.LogWarning("[日志] 打开日志目录失败："+ex.Message);}
        }
    }
}

using UnityEngine;

namespace DarwinPark.Core
{
    // ★ 新增：退出、后台挂起时主动刷新；禁用域重载重复播放仍可成对注销，旧对象不能关闭新会话。
    public sealed class RuntimeLogLifecycle : MonoBehaviour
    {
        private SessionLogWriter _writer;private bool _reported,_diagnosticsReported;
        public void Bind(SessionLogWriter writer)=>_writer=writer;
        private void Update()
        {
            // ★ 适配：主线程仅更新内存心跳，每秒采样；后台线程负责持久化。
            RuntimeCrashDiagnostics.Tick();
            if(!_reported&&_writer?.Failure!=null){_reported=true;Debug.LogWarning("[日志] 文件写入已停止："+_writer.Failure+"；Unity原始日志仍可使用。");}
            // ★ 适配：磁盘满或权限变化时明确提示诊断故障，不能只在导出时才知道快照缺失。
            if(!_diagnosticsReported&&!string.IsNullOrEmpty(RuntimeCrashDiagnostics.Failure)){_diagnosticsReported=true;Debug.LogWarning("[诊断] 写入异常："+RuntimeCrashDiagnostics.Failure);}
        }
        private void OnApplicationPause(bool paused){if(paused){Debug.Log("[运行] 应用转入后台");RuntimeFileLog.Flush();}}
        private void OnApplicationQuit(){Debug.Log("[运行] 正常退出");RuntimeFileLog.Shutdown("收到正常退出事件");}
        private void OnDestroy()=>RuntimeFileLog.ShutdownIfCurrent(_writer);
    }
}

using System;
using System.IO;
using UnityEngine;

namespace DarwinPark.Core
{
    // ★ 新增：日志容量、排队与写盘频率配置化，避免测试时大量输出拖慢游戏或无限占用磁盘。
    [Serializable]
    public sealed class RuntimeLogSettings
    {
        public int version,maximumFileBytes,retainedFiles,queuedEntries,maximumEntryCharacters,flushIntervalMilliseconds,shutdownTimeoutMilliseconds;
        public bool enabled;
        public string directoryName;
        public void Validate()
        {
            if(version!=1||string.IsNullOrWhiteSpace(directoryName)||directoryName!=Path.GetFileName(directoryName)||directoryName=="."||directoryName==".."||
                maximumEntryCharacters<64||maximumFileBytes<(long)maximumEntryCharacters*4+256||retainedFiles<2||queuedEntries<8||flushIntervalMilliseconds<10||shutdownTimeoutMilliseconds<100)
                throw new InvalidDataException("运行日志配置无效");
        }
        public static RuntimeLogSettings Load()
        {
            var asset=Resources.Load<TextAsset>("runtime_logging");if(asset==null)throw new InvalidDataException("缺少 Resources/runtime_logging.json，无法启用文件日志");
            var settings=JsonUtility.FromJson<RuntimeLogSettings>(asset.text);if(settings==null)throw new InvalidDataException("运行日志配置为空");settings.Validate();return settings;
        }
    }
}

using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using UnityEngine;

namespace DarwinPark.Core
{
    // ★ 新增：任意线程只做有界排队；单独写盘线程处理刷新、轮转和保留策略，不在每帧主线程同步写文件。
    public sealed class SessionLogWriter : IDisposable
    {
        private sealed class Entry
        {public string text;public bool important;public ManualResetEventSlim barrier;}
        private readonly RuntimeLogSettings _settings;
        private readonly BlockingCollection<Entry> _queue;
        private readonly Thread _thread;
        private readonly string _session;
        private StreamWriter _stream;private long _bytes;private int _part,_stopped,_dropped;
        private string _file,_failure;
        public string DirectoryPath {get;}
        public string CurrentFilePath=>Volatile.Read(ref _file);
        public string Failure=>Volatile.Read(ref _failure);
        public string FallbackReason {get;}
        public SessionLogWriter(RuntimeLogSettings settings,string preferredDirectory,string fallbackDirectory)
        {
            settings.Validate();_settings=settings;
            _session="session-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+"-"+System.Diagnostics.Process.GetCurrentProcess().Id+"-"+Guid.NewGuid().ToString("N").Substring(0,8);
            DirectoryPath=Path.GetFullPath(preferredDirectory);
            try{OpenPart();}
            catch(Exception ex)when(ex is IOException||ex is UnauthorizedAccessException)
            {
                // ★ 修复（防Bug回归）：游戏目录只读时改用用户数据目录，记录原因且不妨碍游戏启动。
                FallbackReason=ex.Message;DirectoryPath=Path.GetFullPath(fallbackDirectory);OpenPart();
            }
            _queue=new BlockingCollection<Entry>(settings.queuedEntries);
            _thread=new Thread(WriteLoop){IsBackground=true,Name="DarwinPark.FileLog"};_thread.Start();
        }
        public void Write(string message,string stack,LogType type)
        {
            if(Volatile.Read(ref _stopped)!=0||Failure!=null)return;
            string detail=message??"";
            if(type!=LogType.Log&&!string.IsNullOrWhiteSpace(stack))detail+="\n"+stack;
            if(detail.Length>_settings.maximumEntryCharacters)detail=detail.Substring(0,_settings.maximumEntryCharacters)+"…[已截断]";
            var entry=new Entry{text=DateTimeOffset.Now.ToString("O")+" ["+type+"] [线程 "+Thread.CurrentThread.ManagedThreadId+"] "+detail,important=type==LogType.Error||type==LogType.Exception||type==LogType.Assert};
            try{if(!_queue.TryAdd(entry))Interlocked.Increment(ref _dropped);}catch(InvalidOperationException){ }
        }
        public bool Flush()
        {
            if(Volatile.Read(ref _stopped)!=0)return Failure==null;
            // 不在超时后Dispose信号，后台仍可能需要设置它；托管信号随队列项回收。
            var signal=new ManualResetEventSlim();
            try{return _queue.TryAdd(new Entry{barrier=signal},_settings.shutdownTimeoutMilliseconds)&&signal.Wait(_settings.shutdownTimeoutMilliseconds)&&Failure==null;}
            catch(InvalidOperationException){return false;}
        }
        private void WriteLoop()
        {
            var timer=System.Diagnostics.Stopwatch.StartNew();
            try
            {
                while(!_queue.IsCompleted)
                {
                    if(_queue.TryTake(out var entry,_settings.flushIntervalMilliseconds))
                    {
                        if(entry.barrier!=null){_stream.Flush();entry.barrier.Set();}
                        else{Append(entry.text);if(entry.important)_stream.Flush();}
                    }
                    int dropped=Interlocked.Exchange(ref _dropped,0);
                    if(dropped>0)Append(DateTimeOffset.Now.ToString("O")+" [Warning] [日志] 队列已满，省略 "+dropped+" 条消息");
                    if(timer.ElapsedMilliseconds>=_settings.flushIntervalMilliseconds){_stream.Flush();timer.Restart();}
                }
                _stream.Flush();
            }
            catch(Exception ex)
            {
                // ★ 修复（防Bug回归）：日志自身失败不能再Debug.Log造成递归，也不能从后台访问Unity对象。
                Volatile.Write(ref _failure,ex.Message);
            }
            finally
            {
                try{_stream?.Dispose();}catch(Exception ex){Volatile.Write(ref _failure,ex.Message);}
                while(_queue.TryTake(out var remaining))remaining.barrier?.Set();
            }
        }
        private void Append(string text)
        {
            long size=Encoding.UTF8.GetByteCount(text)+Encoding.UTF8.GetByteCount(Environment.NewLine);
            if(_bytes+size>_settings.maximumFileBytes&&_bytes>0){_stream.Dispose();_part++;OpenPart();}
            _stream.WriteLine(text);_bytes+=size;
        }
        private void OpenPart()
        {
            Directory.CreateDirectory(DirectoryPath);string file=Path.Combine(DirectoryPath,_session+"-"+_part.ToString("D3")+".log");
            _stream=new StreamWriter(new FileStream(file,FileMode.CreateNew,FileAccess.Write,FileShare.Read),new UTF8Encoding(false));_bytes=0;Volatile.Write(ref _file,file);
            // ★ 新增：只管理本功能的session日志，其他文件不删；其他游戏实例仍打开的日志由系统共享锁保护。
            try
            {
                foreach(var old in new DirectoryInfo(DirectoryPath).GetFiles("session-*.log").OrderByDescending(f=>f.LastWriteTimeUtc).Skip(_settings.retainedFiles))
                    if(old.FullName!=file)try{old.Delete();}catch(IOException){ }catch(UnauthorizedAccessException){ }
            }
            catch(IOException){ }catch(UnauthorizedAccessException){ }
            try{File.WriteAllText(Path.Combine(DirectoryPath,"latest-log.txt"),file,new UTF8Encoding(false));}catch(IOException){ }catch(UnauthorizedAccessException){ }
        }
        public void Dispose()
        {
            if(Interlocked.Exchange(ref _stopped,1)!=0)return;_queue.CompleteAdding();
            // ★ 修复（防Bug回归）：先排空再关文件；慢磁盘退出等待有上限，不能永久阻塞关闭游戏。
            if(!_thread.Join(_settings.shutdownTimeoutMilliseconds))Volatile.Write(ref _failure,"等待日志写盘超时");
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;

namespace DarwinPark.Core
{
    public class OrbitCamera : MonoBehaviour
    {
        public Transform target;
        public float distance = 800f;
        public float maxDistance = 3000f;
        [Tooltip("最小距离必须大于“星球半径 + 最大地形高度”，否则相机会钻进山峰")]
        public float minDistance = 305f;
        [Header("近距离观察")]
        public float surfaceClearance = 3f;
        // ★ 适配：独立海面生成后下发真实半径，海床不能成为轨道相机的最近边界。
        [HideInInspector] public float minimumSurfaceRadius;

        [Header("聚焦")]
        [Tooltip("聚焦实体时，相机在实体地表之上额外保持的高度")]
        public float focusAltitude = 20f;

        [Header("速度控制")]
        public float baseRotateSpeed = 300f; // 基础旋转速度
        public float zoomSpeed = 2000f;      // 缩放速度
        [Header("左键拖动")]
        public float dragSpeedMultiplier=.2f, shiftDragMultiplier=4f, dragThresholdPixels=6f;
        private bool _leftDragStarted;
        private Vector2 _leftDragOrigin;

        private float x = 45f;
        private float y = 25f;
        private float targetDistance;
        private Quaternion targetRotation;
        private Vector3 targetPosition;
        private bool _isFocusing = false;

        public static bool IsDraggingUI = false;
        // ★ 适配：实体跟随组件接管镜头时，保留轨道状态但停止本组件写相机位置。
        public bool EntityViewActive { get; set; }

        // ★ 适配：读档同步轨道缓存，恢复位置后不会在下一帧跳回旧镜头。
        public void RestoreView(Vector3 position,Quaternion rotation,float savedDistance)
        {transform.SetPositionAndRotation(position,rotation);distance=targetDistance=savedDistance;x=rotation.eulerAngles.y;y=Mathf.DeltaAngle(0,rotation.eulerAngles.x);_isFocusing=false;}
        void Start()
        {
            if (target == null) target = GameObject.Find("Planet")?.transform;
            targetDistance = distance;
            UpdateCameraPos(true);

            // ★ 核心修复：强制相机能看到极远处的星空
            var cam = GetComponent<Camera>();
            if (cam != null)
            {
                cam.farClipPlane = 10000f; // 提高到 10000
            }
        }

        void LateUpdate()
        {
            // ★ 适配：覆盖菜单拥有输入时不处理世界操作。
            if (DarwinPark.Core.GameInputGate.Blocked) return;
            if (EntityViewActive) return;
            if (target == null) return;

            // ★ 修复：鼠标在 UI 上时不再旋转/缩放，右键收藏条目不会带动星球。
            bool pointerOverUI = EventSystem.current != null && EventSystem.current.IsPointerOverGameObject();

            // ★ 修复（防Bug回归）：仅从世界开始的左键拖动旋转；点击和 UI 拖动不抢占相机。
            // ★ 适配：RTS左键属于框选，改用中键旋转，避免选框同时拖动相机。
            int dragButton=WorldAuthority.RtsMode?2:0;
            if(Input.GetMouseButtonDown(dragButton))
            {_leftDragStarted=!IsDraggingUI && !pointerOverUI;_leftDragOrigin=Input.mousePosition;}
            if(Input.GetMouseButtonUp(dragButton) || IsDraggingUI) _leftDragStarted=false;
            if (_leftDragStarted && !pointerOverUI && Input.GetMouseButton(dragButton) &&
                Vector2.Distance(_leftDragOrigin,(Vector2)Input.mousePosition)>dragThresholdPixels)
            {
                _isFocusing = false; // 打断聚焦动画

                // ★ 核心修复：根据当前距离计算灵敏度
                // 拉到最近(minDistance)时，灵敏度只有 5%；拉到最远时，灵敏度 100%
                float distRatio = Mathf.InverseLerp(minDistance, maxDistance, distance);
                float sensitivity = Mathf.Lerp(0.05f, 1.0f, distRatio);

                float multiplier=dragSpeedMultiplier*((Input.GetKey(KeyCode.LeftShift)||Input.GetKey(KeyCode.RightShift))?shiftDragMultiplier:1);
                x += Input.GetAxis("Mouse X") * baseRotateSpeed * sensitivity * 0.02f * multiplier;
                y -= Input.GetAxis("Mouse Y") * baseRotateSpeed * sensitivity * 0.02f * multiplier;
                y = Mathf.Clamp(y, -85f, 85f);
            }

            // ★ 修复（防Bug回归）：投放/拖拽期间同样屏蔽缩放，避免瞄准地表时相机被滚轮带走。
            float scroll = Input.GetAxis("Mouse ScrollWheel");
            if (!IsDraggingUI && !pointerOverUI && Mathf.Abs(scroll) > 0.001f)
            {
                _isFocusing = false;
                targetDistance -= scroll * zoomSpeed;
                targetDistance = Mathf.Clamp(targetDistance, minDistance, maxDistance);
            }

            // 平滑过渡逻辑
            if (_isFocusing)
            {
                // 聚焦飞行逻辑
                transform.rotation = Quaternion.Slerp(transform.rotation, targetRotation, Time.deltaTime * 5f);
                // ★ 修复（防Bug回归）：对侧聚焦不能沿穿过星球的直线飞行，按旋转圆弧和半径插值。
                float focusRadius = Mathf.Lerp(Vector3.Distance(transform.position,target.position),
                    Vector3.Distance(targetPosition,target.position),Time.deltaTime*5f);
                transform.position = target.position + transform.rotation * Vector3.back * focusRadius;

                Vector3 euler = transform.rotation.eulerAngles;
                x = euler.y;
                y = euler.x > 180 ? euler.x - 360 : euler.x;
                distance = Vector3.Distance(transform.position, target.position);
                targetDistance = distance;

                if (Vector3.Distance(transform.position, targetPosition) < 0.5f) _isFocusing = false;
            }
            else
            {
                distance = Mathf.Lerp(distance, targetDistance, Time.deltaTime * 8f);
                UpdateCameraPos(false);
            }
            // ★ 修复（防Bug回归）：允许贴近地面观察，但按实际地形射线避免钻进山峰。
            KeepAboveSurface();
        }

        private void KeepAboveSurface()
        {
            if (target == null) return;
            var collider = target.GetComponent<MeshCollider>();
            Vector3 direction = (transform.position - target.position).normalized;
            if(direction.sqrMagnitude<.5f) direction=-(transform.forward);
            float safe = Mathf.Max(minDistance,minimumSurfaceRadius+surfaceClearance);
            // ★ 修复（防Bug回归）：探测起点必须在整个碰撞体外，且检查实际位置而非过渡中的缓存 distance。
            if(collider != null)
            {
                float outsideRadius=Mathf.Max(maxDistance,collider.bounds.extents.magnitude+surfaceClearance);
                Vector3 outside=target.position+direction*outsideRadius;
                if(collider.Raycast(new Ray(outside,-direction),out var hit,outsideRadius))
                    safe=Mathf.Max(safe,Vector3.Distance(hit.point,target.position)+surfaceClearance);
            }
            distance=Mathf.Max(Vector3.Distance(transform.position,target.position),safe);
            targetDistance=Mathf.Max(targetDistance,safe);
            transform.position=target.position+direction*distance;
        }

        private void UpdateCameraPos(bool immediate)
        {
            if (target == null) return;
            Quaternion rotation = Quaternion.Euler(y, x, 0);
            Vector3 position = rotation * new Vector3(0.0f, 0.0f, -distance) + target.position;

            transform.rotation = rotation;
            transform.position = position;
        }

        // ★ 修复（防Bug回归）：退出操控需要同步轨道角度和距离，否则下一帧会被旧轨道状态拉回原处。
        public void ReturnToEntity(Vector3 worldPosition)
        {
            FocusOn(worldPosition);
            if(target == null) return;
            transform.SetPositionAndRotation(targetPosition,targetRotation);
            Vector3 euler=targetRotation.eulerAngles;
            x=euler.y; y=euler.x>180?euler.x-360:euler.x;
            distance=targetDistance=Vector3.Distance(targetPosition,target.position);
            _isFocusing=false;
            KeepAboveSurface();
        }

        // 平滑聚焦到目标实体
        public void FocusOn(Vector3 targetWorldPos)
        {
            if (target == null) target = GameObject.Find("Planet")?.transform;
            if (target == null) return;

            Vector3 center = target.position;
            Vector3 dirFromCenter = (targetWorldPos - center);
            if (dirFromCenter.sqrMagnitude < 1e-6f) return;
            dirFromCenter.Normalize();

            // ★ 修复（防Bug回归）：旧版把相机放到目标点的反方向，而且距离固定 180，
            // 小于星球半径 300，会直接钻进星球内部，表现为“定位不准/看不到实体”。
            // 现在沿实体所在球面法线向外放相机，并保证距离大于地表半径。
            Vector3 up = Mathf.Abs(Vector3.Dot(dirFromCenter, Vector3.up)) > 0.99f
                ? Vector3.right
                : Vector3.up;

            float surfaceRadius = Vector3.Distance(targetWorldPos, center);
            float targetDist = Mathf.Clamp(surfaceRadius + focusAltitude, minDistance, maxDistance);

            targetRotation = Quaternion.LookRotation(-dirFromCenter, up);
            targetPosition = center + dirFromCenter * targetDist;
            targetDistance = targetDist;

            _isFocusing = true;
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Core
{
    /// <summary>
    /// 轻量级服务定位器。
    /// ★ 新增：统一管理 EnvironmentSystem / SimulationClock / UIRoot 等单例，
    /// 场景缺组件时一次报错而不是各处 NRE（规则3.6）。
    /// </summary>
    public static class ServiceLocator
    {
        private static readonly Dictionary<Type, object> _services = new();

        public static void Register<T>(T service) where T : class
        {
            if (service == null) { Log.Error(Log.Tag.Bootstrap, $"注册 null 服务：{typeof(T).Name}"); return; }
            if (_services.ContainsKey(typeof(T)))
                Log.Warn(Log.Tag.Bootstrap, $"重复注册服务：{typeof(T).Name}（覆盖）");
            _services[typeof(T)] = service;
        }

        public static void Unregister<T>() where T : class => _services.Remove(typeof(T));

        public static bool TryGet<T>(out T service) where T : class
        {
            if (_services.TryGetValue(typeof(T), out var o)) { service = o as T; return service != null; }
            service = null;
            return false;
        }

        public static T Get<T>(string reason = null) where T : class
        {
            if (TryGet<T>(out var s)) return s;
            Log.Error(Log.Tag.Bootstrap,
                $"服务缺失：{typeof(T).Name}" + (string.IsNullOrEmpty(reason) ? "" : $"（{reason}）"));
            return null;
        }

        public static void Clear() => _services.Clear();
    }
}

using System;
using UnityEngine;

namespace DarwinPark.Core
{
    // ★ 修复（防Bug回归）：先更新统一时钟，实体本帧才能读取相同的模拟步长。
    [DefaultExecutionOrder(-1000)]
    public class SimulationClock : MonoBehaviour
    {
        [SerializeField] private bool _startRunning = true;
        [SerializeField] private float _timeScale = 1f;
        [Tooltip("单帧最多推进的模拟秒数；多余时间继续排队，防止卡顿后无限补算")]
        public float maximumGameDelta=.5f;
        [Tooltip("负载恢复后补算速度最多为所选倍率的倍数，避免切回1倍却突然快进几十倍")]
        public float maximumCatchUpMultiplier=1.5f;
        private readonly SimulationStepBudget _budget=new SimulationStepBudget();
        private bool _budgetedFrame;
        public double PendingGameTime=>_budget.Pending;
        // ★ 适配：过载帧的物理行动也按实际交付时间缩放，避免日历限速而实体仍全速移动。
        public float MotionTimeScale=>!IsRunning?0:WorldAuthority.IsReplica||!_budgetedFrame?_timeScale:GameDeltaTime/Mathf.Max(.0001f,Time.unscaledDeltaTime);

        public bool IsRunning { get; private set; }
        public float GameTime { get; private set; }

        // ★ 核心：全局统一受控的 DeltaTime，所有实体和系统都用这个
        public float GameDeltaTime { get; private set; }
        public float TimeScale => IsRunning ? _timeScale : 0f;
        public float ConfiguredTimeScale => _timeScale;
        private int _resumeFrame=-1;

        public event Action<bool> OnRunningChanged;

        private void Awake()
        {
            if (ServiceLocator.TryGet<SimulationClock>(out _))
            {
                Destroy(this);
                return;
            }
            ServiceLocator.Register(this);
            IsRunning = _startRunning;
            GameTime = 0f; // 确保从 0 开始
        }

        private void Start()
        {
            ApplyTimeScale();
            OnRunningChanged?.Invoke(IsRunning);
        }

        private void Update()
        {
            // ★ 适配：联机副本只显示房主下发的时间，不能独立推进第二份世界。
            if(WorldAuthority.IsReplica){GameDeltaTime=0;return;}
            // ★ 修复（防Bug回归）：加载屏完成前不累计日期，模拟仍沿用统一时钟。
            if (IsRunning && Time.frameCount>_resumeFrame && (!WorldRuntimeGate.Managed || WorldRuntimeGate.Ready))
            {
                // GameDeltaTime = 真实时间 * 时间流速
                // ★ 适配：补算设上限，日历只累计实际完成的统一模拟步长；暂停不新增积压。
                float incoming=Time.unscaledDeltaTime*_timeScale;
                // ★ 修复（防Bug回归）：恢复负载或降低倍率后渐进补算，物理与日历一起按交付倍率推进，不能突然几十倍追赶。
                float limit=Mathf.Min(Mathf.Max(.1f,maximumGameDelta),incoming*Mathf.Max(1,maximumCatchUpMultiplier));
                GameDeltaTime = incoming>0?_budget.Consume(Time.unscaledDeltaTime,_timeScale,limit):0;
                _budgetedFrame=true;
                GameTime += GameDeltaTime;
            }
            else
            {
                GameDeltaTime = 0f;
            }
        }

        // ★ 适配：存档恢复总时间和倍率，加载过程始终保持暂停。
        public void RestoreState(float time,float scale){_budget.Clear();_budgetedFrame=false;GameTime=Mathf.Max(0,time);_timeScale=Mathf.Max(0,scale);IsRunning=false;GameDeltaTime=0;ApplyTimeScale();OnRunningChanged?.Invoke(false);}
        // ★ 适配：只读网络时钟不经本地启停请求，避免收到同步时再次向服务端发包。
        public void ApplyRemoteState(float time,float scale,bool running){GameTime=time;_timeScale=scale;GameDeltaTime=0;bool changed=IsRunning!=running;IsRunning=running;if(changed)OnRunningChanged?.Invoke(running);}
        // ★ 修复（防Bug回归）：加载结束的当前帧 delta 仍包含磁盘/上传等待，下一帧才开始玩家时间。
        public void Play() { if(WorldAuthority.InterceptTime(true,_timeScale))return;if(!IsRunning){_resumeFrame=Time.frameCount;_budgetedFrame=false;}IsRunning = true; ApplyTimeScale(); OnRunningChanged?.Invoke(true); }
        public void Pause() { if(WorldAuthority.InterceptTime(false,_timeScale))return;IsRunning = false; GameDeltaTime = 0f; ApplyTimeScale(); OnRunningChanged?.Invoke(false); }
        public void Toggle() { if (IsRunning) Pause(); else Play(); }
        public void SetTimeScale(float s){if(WorldAuthority.InterceptTime(IsRunning,s))return;_timeScale=Mathf.Max(0,s);_budgetedFrame=false;}

        private void ApplyTimeScale()
        {
            // 我们不使用 Time.timeScale = 0，因为那会影响 UI 动画。
            // 所有逻辑冻结完全靠 GameDeltaTime 为 0 来控制。
        }

        private void OnDisable() => ServiceLocator.Unregister<SimulationClock>();
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace DarwinPark.Core
{
    /// <summary>
    /// 空格键暂停/继续。
    /// ★ 新增：独立输入组件，挂到 GameRoot；不把热键逻辑塞进 SimulationClock，
    /// 便于后续改键或按场景禁用。输入框获得焦点时跳过，避免输入基因数值被误暂停。
    /// </summary>
    public class SimulationPauseHotkey : MonoBehaviour
    {
        [Header("热键")]
        // ★ 适配：世界暂停与通用暂停分开绑定，实体跳跃不会同时暂停。
        public KeyCode pauseKey=>ControlBindings.Get(ControlAction.WorldPause);
        public KeyCode viewPauseKey=>ControlBindings.Get(ControlAction.Pause);

        private SimulationClock _clock;

        private void Start()
        {
            _clock = ServiceLocator.Get<SimulationClock>("SimulationPauseHotkey 需要 SimulationClock");
        }

        private void Update()
        {
            // ★ 适配：覆盖菜单拥有输入时不处理世界操作。
            if (DarwinPark.Core.GameInputGate.Blocked) return;
            if (_clock == null) return;
            // ★ 修复（防Bug回归）：操控视角空格留给跳跃，P 仍能启动/暂停，不能把全部时间控制一起禁掉。
            bool view=Camera.main!=null&&Camera.main.GetComponent<OrbitCamera>() is OrbitCamera orbit&&orbit.EntityViewActive;
            if(Input.GetKeyDown(viewPauseKey))HandlePauseKey(viewPauseKey,view,IsTypingInInputField());
            else if(Input.GetKeyDown(pauseKey))HandlePauseKey(pauseKey,view,IsTypingInInputField());
        }

        public bool HandlePauseKey(KeyCode key,bool entityView,bool typing)
        {
            if(GameInputGate.Blocked||!WorldAuthority.CanEdit||typing||key!=viewPauseKey&&(entityView||key!=pauseKey))return false;
            if(_clock==null&&!ServiceLocator.TryGet<SimulationClock>(out _clock))return false;
            _clock.Toggle();return true;
        }

        private bool IsTypingInInputField()
        {
            var eventSystem = EventSystem.current;
            if (eventSystem == null) return false;

            var selected = eventSystem.currentSelectedGameObject;
            if (selected == null) return false;

            var input = selected.GetComponentInParent<InputField>();
            return input != null && input.isFocused;
        }
    }
}

using System;

namespace DarwinPark.Core
{
    // ★ 新增：限制单帧补算工作量，尚未完成的时间排队；禁止丢弃积压或让日历提前跳过实体模拟。
    public sealed class SimulationStepBudget
    {
        public double Pending {get;private set;}
        public float Consume(float elapsed,float scale,float maximumStep)
        {
            if(float.IsNaN(elapsed)||float.IsInfinity(elapsed)||elapsed<0||float.IsNaN(scale)||float.IsInfinity(scale)||scale<0||float.IsNaN(maximumStep)||float.IsInfinity(maximumStep)||maximumStep<=0)
                throw new ArgumentOutOfRangeException(nameof(maximumStep),"时间与倍率须有限且非负，单帧预算须大于零");
            Pending+=(double)elapsed*scale;
            float delivered=(float)Math.Min(Pending,maximumStep);Pending=Math.Max(0,Pending-delivered);return delivered;
        }
        public void Clear()=>Pending=0;
    }
}

using System;
using UnityEngine;
using UnityEngine.UI;

namespace DarwinPark.Core
{
    /// <summary>
    /// UI 元素工厂。
    /// ★ 新增：统一字体/样式，消除各 UI 脚本重复建 Rect/Text/Button/Slider 代码。
    /// 字体带 fallback（LegacyRuntime.ttf → Arial.ttf），兼容不同 Unity 版本。
    /// </summary>
    public static class UIFactory
    {
        private static Font _font;
        public static Font DefaultFont
        {
            get
            {
                if (_font != null) return _font;
                // ★ 适配：中文界面优先使用系统无衬线字体，避免默认字体缺字和图标字符兜底。
                var installed=Font.GetOSInstalledFontNames();
                foreach(var name in UIVisualTheme.Data.fontNames)
                    if(Array.Exists(installed,f=>string.Equals(f,name,StringComparison.OrdinalIgnoreCase)))
                    {_font=Font.CreateDynamicFontFromOSFont(name,16);break;}
                if (_font != null) return _font;
                _font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
                if (_font == null) _font = Resources.GetBuiltinResource<Font>("Arial.ttf");
                if (_font == null) Log.Error(Log.Tag.UI, "找不到内置字体，UI 文本将不可见");
                return _font;
            }
        }

        public static GameObject NewRect(string name, Transform parent, params Type[] extra)
        {
            var go = new GameObject(name, typeof(RectTransform));
            if (extra != null && extra.Length > 0)
            {
                var all = new Type[1 + extra.Length];
                all[0] = typeof(RectTransform);
                Array.Copy(extra, 0, all, 1, extra.Length);
                DestroySafely(go); // 先建好再补组件，避免重复 RectTransform
                go = new GameObject(name, all);
            }
            go.transform.SetParent(parent, false);
            // ★ 适配：默认按钮与输入背景统一主题，业务脚本仍拥有原有位置和大小。
            if(go.TryGetComponent<Button>(out var button)) UIVisualTheme.StyleButton(button);
            else if(go.GetComponent<InputField>()!=null) UIVisualTheme.Paint(go.GetComponent<Image>(),"field");
            return go;
        }

        private static void DestroySafely(GameObject go)
        {
            if (Application.isPlaying) UnityEngine.Object.Destroy(go);
            else UnityEngine.Object.DestroyImmediate(go);
        }

        public static Text NewText(string name, Transform parent, string content,
            int fontSize = 16, TextAnchor align = TextAnchor.MiddleLeft)
        {
            var go = NewRect(name, parent, typeof(Text));
            var t = go.GetComponent<Text>();
            t.font = DefaultFont;
            t.fontSize = fontSize;
            t.text = content;
            t.alignment = align;
            t.color = UIVisualTheme.Text;
            t.raycastTarget = false; // 规则附录：文本默认不参与射线
            t.horizontalOverflow = HorizontalWrapMode.Wrap;
            t.verticalOverflow = VerticalWrapMode.Truncate;
            return t;
        }

        public static Button NewButton(string name, Transform parent, string label,
            Action onClick, Vector2 size)
        {
            var go = NewRect(name, parent, typeof(Image), typeof(Button));
            var rt = go.GetComponent<RectTransform>();
            rt.sizeDelta = size;

            var btn = go.GetComponent<Button>();
            if (onClick != null) btn.onClick.AddListener(() => onClick());

            if (!string.IsNullOrEmpty(label))
            {
                var txt = NewText("Label", go.transform, label, 18, TextAnchor.MiddleCenter);
                Stretch(txt.rectTransform);
            }
            UIVisualTheme.StyleButton(btn);
            return btn;
        }

        public static Slider NewSlider(string name, Transform parent, string label,
            float min, float max, float value, float width, out Text labelText)
        {
            var row = NewRect(name + "Row", parent);
            var rrt = row.GetComponent<RectTransform>();
            rrt.sizeDelta = new Vector2(width, 32);

            labelText = NewText(name + "Label", row.transform, label, 14);
            var lrt = labelText.rectTransform;
            lrt.anchorMin = new Vector2(0, 0);
            lrt.anchorMax = new Vector2(0, 1);
            lrt.pivot = new Vector2(0, 0.5f);
            lrt.sizeDelta = new Vector2(60, 0);
            lrt.anchoredPosition = Vector2.zero;

            var sliderGO = NewRect(name + "Slider", row.transform, typeof(Slider));
            var srt = sliderGO.GetComponent<RectTransform>();
            srt.anchorMin = new Vector2(0, 0);
            srt.anchorMax = new Vector2(1, 1);
            srt.pivot = new Vector2(0, 0.5f);
            srt.offsetMin = new Vector2(64, 4);
            srt.offsetMax = new Vector2(-4, -4);

            var slider = sliderGO.GetComponent<Slider>();
            slider.minValue = min;
            slider.maxValue = max;
            slider.value = value;
            BuildSliderVisuals(sliderGO.transform, slider);
            return slider;
        }

        private static void BuildSliderVisuals(Transform parent, Slider slider)
        {
            var bg = NewRect("Background", parent, typeof(Image));
            var bgRect=bg.GetComponent<RectTransform>();
            bgRect.anchorMin=new Vector2(0,.5f);bgRect.anchorMax=new Vector2(1,.5f);bgRect.sizeDelta=new Vector2(0,8);
            UIVisualTheme.Paint(bg.GetComponent<Image>(),"track");
            bg.GetComponent<Image>().raycastTarget=false;

            var fillArea = NewRect("FillArea", parent);
            var areaRect=fillArea.GetComponent<RectTransform>();
            areaRect.anchorMin=new Vector2(0,.5f);areaRect.anchorMax=new Vector2(1,.5f);areaRect.sizeDelta=new Vector2(-16,8);

            var fill = NewRect("Fill", fillArea.transform, typeof(Image));
            Stretch(fill.GetComponent<RectTransform>());
            UIVisualTheme.Paint(fill.GetComponent<Image>(),"fill");fill.GetComponent<Image>().raycastTarget=false;

            var handle = NewRect("Handle", parent, typeof(Image));
            UIVisualTheme.Paint(handle.GetComponent<Image>(),"thumb");
            handle.GetComponent<RectTransform>().anchorMin=handle.GetComponent<RectTransform>().anchorMax=new Vector2(.5f,.5f);
            handle.GetComponent<RectTransform>().sizeDelta = new Vector2(16, 16);

            slider.fillRect = fill.GetComponent<RectTransform>();
            slider.handleRect = handle.GetComponent<RectTransform>();
            slider.targetGraphic = handle.GetComponent<Image>();
            slider.direction = Slider.Direction.LeftToRight;
        }

        public static void Stretch(RectTransform rt, float padX = 0, float padY = 0)
        {
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.offsetMin = new Vector2(padX, padY);
            rt.offsetMax = new Vector2(-padX, -padY);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Core
{
    /// <summary>
    /// UI 图标自动注册表。
    /// ★ 新增：扫描 Resources/UI/Icons 下的所有 Sprite，用文件名作为 ID 注册。
    /// 遵循数据驱动，新增图标无需修改代码。
    /// </summary>
    public static class UIIconRegistry
    {
        private static Dictionary<string, Sprite> _icons;
        private static bool _initialized = false;

        public static void Init()
        {
            if (_initialized) return;
            _icons = new Dictionary<string, Sprite>();

            // 扫描所有图标
            var sprites = Resources.LoadAll<Sprite>("UI/Icons");
            foreach (var sprite in sprites)
            {
                if (!_icons.ContainsKey(sprite.name))
                {
                    _icons.Add(sprite.name, sprite);
                }
                else
                {
                    Debug.LogWarning($"[UIIconRegistry] 发现重复图标 ID: {sprite.name}");
                }
            }

            _initialized = true;
        }

        public static Sprite Get(string id)
        {
            if (!_initialized) Init();
            if (string.IsNullOrEmpty(id)) return null;

            if (_icons.TryGetValue(id, out var sprite))
            {
                return sprite;
            }

            // 不输出报错，允许静默返回 null 以便 UI 显示纯色块兜底
            return null;
        }

        public static IEnumerable<string> GetAllIds()
        {
            if (!_initialized) Init();
            return _icons.Keys;
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace DarwinPark.Core
{
    /// <summary>
    /// 全局 UI 根节点。
    /// ★ 新增：全场景唯一 Canvas + GraphicRaycaster，所有业务 UI 都挂到 MainCanvas 下，
    /// 消除多个 Canvas 的射线/层级冲突（规则3.5）。
    /// </summary>
    public class UIRoot : MonoBehaviour
    {
        public Canvas MainCanvas { get; private set; }
        public Canvas WorldCanvas { get; private set; }

        private void Awake()
        {
            if (ServiceLocator.TryGet<UIRoot>(out _))
            {
                Log.Warn(Log.Tag.UI, "重复 UIRoot，销毁多余实例");
                Destroy(this);
                return;
            }
            ServiceLocator.Register(this);

            MainCanvas = EnsureCanvas("MainCanvas", RenderMode.ScreenSpaceOverlay);
            WorldCanvas = EnsureCanvas("WorldCanvas", RenderMode.ScreenSpaceCamera);
            WorldCanvas.sortingOrder = 10;

            EnsureEventSystem();
        }

        private Canvas EnsureCanvas(string name, RenderMode mode)
        {
            var child = transform.Find(name);
            if (child == null)
            {
                var go = new GameObject(name, typeof(Canvas), typeof(GraphicRaycaster), typeof(CanvasScaler));
                go.transform.SetParent(transform, false);
                child = go.transform;
            }
            // ★ 修复（防Bug回归）：同名场景节点未必已有完整 UI 组件，逐项补齐以免初始化中途抛异常。
            var canvas = child.GetComponent<Canvas>() ?? child.gameObject.AddComponent<Canvas>();
            if (child.GetComponent<CanvasScaler>() == null) child.gameObject.AddComponent<CanvasScaler>();
            canvas.renderMode = mode;

            if (canvas.GetComponent<GraphicRaycaster>() == null)
                canvas.gameObject.AddComponent<GraphicRaycaster>();

            if (mode == RenderMode.ScreenSpaceOverlay)
            {
                // ★ 修复：明确主 HUD 排序，避免 WorldCanvas/其他全屏 UI 遮住底部控制栏。
                // 底部栏在 SimulationControlPanel 里还会再抬到 200，这里给一个足够高的基线。
                canvas.sortingOrder = 200;
                var scaler = canvas.GetComponent<CanvasScaler>();
                scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
                scaler.referenceResolution = new Vector2(1920, 1080);
                scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
                scaler.matchWidthOrHeight = 0.5f;
            }
            return canvas;
        }

        private void EnsureEventSystem()
        {
            if (FindFirstObjectByType<EventSystem>() != null) return; // ★ 适配 Unity 6 新 API
            var go = new GameObject("EventSystem", typeof(EventSystem), typeof(StandaloneInputModule));
            go.transform.SetParent(transform, false);
            Log.Info(Log.Tag.UI, "UIRoot 自动补建 EventSystem");
        }

        // ★ 修复（防Bug回归）：禁用再启用必须重新注册；重复根节点销毁时不能注销真正的根。
        private void OnEnable()
        {
            if (MainCanvas != null && (!ServiceLocator.TryGet<UIRoot>(out var root) || root != this))
                ServiceLocator.Register(this);
        }

        private void OnDisable()
        {
            if (ServiceLocator.TryGet<UIRoot>(out var root) && root == this)
                ServiceLocator.Unregister<UIRoot>();
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace DarwinPark.Core
{
    // ★ 新增：两套 UI 共用资源与颜色；仅设置 Graphic，不触碰已有布局、锚点或射线规则。
    public static class UIVisualTheme
    {
        [Serializable] public sealed class IconEntry { public string id, icon; }
        [Serializable] public sealed class StatEntry { public string id, label, format;public bool bar; }
        [Serializable] public sealed class LayerEntry { public string id, label; }
        [Serializable] public sealed class ThemeData
        {
            public string[] fontNames;
            public string accent, text, muted, ink, border, panel, surface, danger, favorite;
            public IconEntry[] geneIcons;
            public StatEntry[] summaryStats;
            public LayerEntry[] layerButtons;
        }
        private static ThemeData _data;
        private static readonly Dictionary<string, Sprite> Surfaces = new Dictionary<string, Sprite>();
        public static ThemeData Data
        {
            get
            {
                if (_data != null) return _data;
                var asset = Resources.Load<TextAsset>("UI/theme");
                if (asset == null) throw new InvalidOperationException("缺少 UI/theme.json 主题配置");
                _data = JsonUtility.FromJson<ThemeData>(asset.text);
                return _data;
            }
        }
        private static Color Parse(string hex) => ColorUtility.TryParseHtmlString(hex, out var c) ? c : Color.white;
        public static Color Accent => Parse(Data.accent);
        public static Color Text => Parse(Data.text);
        public static Color Muted => Parse(Data.muted);
        public static Color Ink => Parse(Data.ink);
        public static Color Border => Parse(Data.border);
        public static Color Panel => Parse(Data.panel);
        public static Color Surface => Parse(Data.surface);
        public static Color Danger => Parse(Data.danger);
        public static Color Favorite => Parse(Data.favorite);
        public static Sprite SurfaceSprite(string name)
        {
            if (Surfaces.TryGetValue(name, out var sprite)) return sprite;
            sprite = Resources.Load<Sprite>("UI/Surfaces/" + name);
            if (sprite == null) Debug.LogWarning("[UI主题] 缺少表面资源：" + name);
            Surfaces[name] = sprite;
            return sprite;
        }
        public static string GeneIcon(string id)
        {
            foreach (var entry in Data.geneIcons) if (entry.id == id) return entry.icon;
            return "dna";
        }
        public static void Paint(Image image, string surface = "panel")
        {
            if (image == null) return;
            image.sprite = SurfaceSprite(surface);
            image.type = Image.Type.Sliced;
            image.color = Color.white;
            // ★ 适配：九宫格边角按 UI 像素显示，保留所有原始点击范围。
            image.pixelsPerUnitMultiplier = 1;
        }
        public static void StyleButton(Button button, bool primary = false)
        {
            Paint(button.image, primary ? "primary" : "button");
            button.transition = Selectable.Transition.SpriteSwap;
            var states = button.spriteState;
            states.highlightedSprite = SurfaceSprite(primary ? "primary_hover" : "hover");
            states.pressedSprite = SurfaceSprite(primary ? "primary_pressed" : "pressed");
            states.selectedSprite = states.highlightedSprite;
            states.disabledSprite = SurfaceSprite("button");
            button.spriteState = states;
            foreach (var label in button.GetComponentsInChildren<Text>(true)) label.color = primary ? Ink : Text;
        }
        public static Image AddIcon(Transform parent, string id, Vector2 size, Vector2 position, Vector2 anchor)
        {
            var go = UIFactory.NewRect("ThemeIcon", parent, typeof(Image), typeof(LayoutElement));
            go.GetComponent<LayoutElement>().ignoreLayout = true;
            var rt = go.GetComponent<RectTransform>();
            rt.anchorMin = rt.anchorMax = anchor; rt.sizeDelta = size; rt.anchoredPosition = position;
            var image = go.GetComponent<Image>(); image.sprite = UIIconRegistry.Get(id);
            image.color = Accent; image.preserveAspect = true; image.raycastTarget = false;
            return image;
        }
    }
}

