            check(GeneDatabase.Get(target).ParentGeneId==parent&&GeneTreeStorage.Active.nodes.Single(n=>n.id==target).error&&GeneTreeStorage.Active.edges.Any(e=>e.from==parent&&e.to==target&&e.kind=="error"),"营养利用为储存基因的菱形出错分支");
