            var watch=Stopwatch.StartNew();foreach(var e in EntityRegistry.All.ToArray())e.Genes.AdvanceSimulation(.1f);watch.Stop();Results.Add("800 genes 0.1s all: "+watch.Elapsed.TotalMilliseconds.ToString("F3")+"ms");
