        // ★ 关键修改 1：定义一个静态委托，让上层（GameBootstrap）把生成逻辑注入进来
        public static Action<Genome, Vector3, string> Spawner;

        private void Awake()
        {
            Genes = GetComponent<EntityGeneController>();
        }

        private void OnEnable() => EntityRegistry.Register(this);
        private void OnDisable() => EntityRegistry.Unregister(this);

        public void EnableTrait(string id) { if (!string.IsNullOrEmpty(id)) _traits.Add(id); }
        public void DisableTrait(string id) { if (!string.IsNullOrEmpty(id)) _traits.Remove(id); }
        public bool HasTrait(string id) => _traits.Contains(id);

        public void AddEnergy(float amount) => _energy += amount;
        public float Energy => _energy;

        public void RequestReproduction(DarwinEntity partner, Genome offspringGenome)
        {
            if (OnOffspringReady == null)
            {
                SpawnOffspring(offspringGenome, name + "_child");
                return;
            }
            OnOffspringReady.Invoke(partner, offspringGenome);
        }

        public void SpawnOffspring(Genome genome, string childName)
        {
            if (genome == null)
            {
                Log.Warn(Log.Tag.Entity, $"{name} 子代基因组为空，跳过");
                return;
            }

            // ★ 关键修改 2：删掉原有的 EntityFactory 调用，改为通过委托触发
            if (Spawner != null)
            {
                Spawner.Invoke(genome, transform.position + UnityEngine.Random.insideUnitSphere * 1.5f, childName);
            }
            else
            {
                Log.Error(Log.Tag.Entity, "尚未注入实体生成器 (Spawner)，请检查 GameBootstrap 是否初始化");
            }
        }
    }
}

using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    // ★ 新增：最终伤害入口执行同群识别和分工限制，玩家攻击也不能绕过工匠/王后的零战斗能力。
    public static class AntColonyCombat
    {
        public static bool CanAttack(DarwinEntity attacker,DarwinEntity target)
        {
            if(attacker==null||target==null)return true;
            if(attacker.GetComponent<PopulationBehavior>()?.SameGroup(target)==true)return false;
            var member=attacker.GetComponent<AntColonyMember>();
            return member==null||!member.Active||member.Role==AntRole.None||member.Role==AntRole.Soldier&&!member.Young;
        }
        public static bool SettleSoldierAttack(EntityGeneController genes,DarwinEntity target,bool killed)
        {
            var member=genes.GetComponent<AntColonyMember>();if(member==null||!member.Active||member.Role!=AntRole.Soldier)return false;
            // ★ 修复（防Bug回归）：尸体由死亡入口统一生成，士兵只更新巡逻状态，不能再生成第二具。
            if(killed)member.AfterKill();
            return true;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using DarwinPark.Genetics;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    [Serializable] public sealed class AntColonyMemberSave
    {
        public string role,lockedGenome,resourceTarget,livingTarget,carriedResource,carriedLiving;
        public float scan,patrolRemaining,restRemaining,circleAngle,reproductionTimer,reproductionCooldown;
        // ★ 适配：王后无配偶等待和孤雌孕育状态与已有蚁群快照一起持久化。
        public float mateWait,maintenanceWait;public bool parthenogenetic;
        public bool founding,deliveryNursery,originalKinematic,originalDetect;
        public Vector3 foundingPoint,deliveryPoint;
        public List<Vector3> supplyPoints=new List<Vector3>();
        public Genome partnerGenome;
        public bool HasData=>!string.IsNullOrEmpty(role);
    }
    public enum ColonyActivity { Rest,Patrol,Hunt,Collect,Transport,Feed,Reproduce,Founding,Young,Mate }
    // ★ 新增：固定出生分工与可持久化工作状态独立于基因倾向，不给原种群脚本堆叠蚁群流程。
    public sealed class AntColonyMember : MonoBehaviour
    {
        private static readonly List<AntColonyMember> Members=new List<AntColonyMember>();
        public static IEnumerable<AntColonyMember> All=>Members.Where(m=>m!=null&&m.Active);
        public AntColonyMemberSave State {get;private set;}=new AntColonyMemberSave();
        public EntityGeneController Genes {get;private set;}
        public DarwinEntity Entity {get;private set;}
        public PopulationBehavior Population {get;private set;}
        private string _roleText;private AntRole _role;
        // ★ 修复（防Bug回归）：固定分工的文本只在变化时解析，不能每次读取移动属性都重新解析枚举。
        public AntRole Role {get{if(_roleText!=State.role){_roleText=State.role;_role=Enum.TryParse<AntRole>(State.role,out var role)?role:AntRole.None;}return _role;}}
        public bool Active=>Population!=null&&Population.Active&&Population.Mode==EcologySettings.Load().antState;
        public bool Young=>Genes.CurrentAge==AgeState.Infant||GetComponent<EggIncubation>()?.Incubating==true;
        public string GroupId=>Population.GroupId;
        public string Id=>EcologyIdentity.Of(Entity);
        public IEnumerable<AntColonyMember> Group=>Population.GroupMembers.Select(p=>p.GetComponent<AntColonyMember>()).Where(m=>m!=null&&m.Active);
        public AntColonyMember Queen=>PopulationGroupIndex.Queen(Population);
        public Vector3 Center {get{var queen=Queen;return queen!=null?queen.transform.position:transform.position;}}
        public float Radius=>Mathf.Max(AntColonySettings.Current.minimumColonyRadius,Genes.GetAttribute("territory_radius"),AntColonySettings.Current.colonyRadius)*DarwinPark.Core.GameplayTuning.Current.colonyActivityRadiusMultiplier;
        public bool Frozen=>Active&&Role!=AntRole.None&&AntColonySettings.Current.Rule(Role).frozenGenome;
        public ColonyActivity Activity {get;internal set;}
        internal DarwinEntity HuntTarget;
        private readonly Dictionary<string,float> _suppression=new Dictionary<string,float>();
        private string _suppressionRole;
        private void Awake(){Genes=GetComponent<EntityGeneController>();Entity=GetComponent<DarwinEntity>();Population=GetComponent<PopulationBehavior>();}
        private void OnEnable(){if(!Members.Contains(this))Members.Add(this);}
        private void OnDisable(){AntColonyWorker.Release(this);Members.Remove(this);}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)] private static void Reset()=>Members.Clear();
        public static AntColonyMember Ensure(PopulationBehavior pop)=>pop.GetComponent<AntColonyMember>()??pop.gameObject.AddComponent<AntColonyMember>();
        public static AntColonyMember QueenFor(PopulationBehavior pop)=>pop.GetComponent<AntColonyMember>()?.Queen;
        public static bool IsManaged(EntityGeneController genes)=>genes!=null&&genes.GetComponent<AntColonyMember>()?.Active==true;
        public void Assign(AntRole role,string group=null)
        {
            if(group!=null)Population.JoinColony(group,role==AntRole.Queen);
            State.role=role.ToString();State.lockedGenome=AntColonySettings.Current.Rule(role).frozenGenome?JsonUtility.ToJson(Genes.Genome):null;
            PopulationGroupIndex.Invalidate();
            Genes.IsGestating=false;_suppressionRole=null;Genes.Recalculate();
            if(GetComponent<ColonyMemberMarker>()==null)gameObject.AddComponent<ColonyMemberMarker>();
            if(role==AntRole.Queen)EnsureSupplyPoints();
        }
        public static void OnBirth(EntityGeneController parent,DarwinEntity child)
        {
            var source=parent.GetComponent<AntColonyMember>();if(source==null||!source.Active||child==null)return;
            var pop=child.GetComponent<PopulationBehavior>();if(pop==null)return;
            var member=Ensure(pop);member.Assign(source.ChooseBirthRole(),source.GroupId);
        }
        public AntRole ChooseBirthRole()
        {
            var settings=AntColonySettings.Current;
            if(Group.Count()>=settings.reproductivePopulationThreshold&&Group.Count(m=>m.Role==AntRole.Reproductive)<settings.minimumReproductives)return AntRole.Reproductive;
            var choices=settings.roles.Where(r=>r.birthWeight>0&&(r.Role!=AntRole.Reproductive||Group.Count(m=>m.Role==AntRole.Reproductive)<settings.maximumReproductives)).ToArray();
            float roll=UnityEngine.Random.value*choices.Sum(r=>r.birthWeight);
            foreach(var rule in choices){roll-=rule.birthWeight;if(roll<=0)return rule.Role;}return choices[choices.Length-1].Role;
        }
        public void Advance(float dt)
        {
            if(!Active||dt<=0)return;
            if(Role==AntRole.None)Assign(Population.LeaderFlag?AntRole.Queen:ChooseBirthRole());
            State.scan-=dt;State.reproductionCooldown=Mathf.Max(0,State.reproductionCooldown-dt);
            ColonyResource.Feed(this,dt);
            if(GetComponent<EggIncubation>()?.Incubating==true)return;
            if(Young){Activity=ColonyActivity.Young;return;}
            if(Role==AntRole.Reproductive){BeginFounding();return;}
            if(State.founding)
            {
                Activity=ColonyActivity.Founding;
                if(EcologyQueries.Distance(transform.position,EcologyQueries.ToWorld(State.foundingPoint))<=AntColonySettings.Current.arrivalDistance)
                {State.founding=false;EnsureSupplyPoints();GetComponent<TerritoryBehavior>()?.Restore(EcologyQueries.ToLocal(transform.position),true,0,Vector3.zero);}
                return;
            }
            if(Role==AntRole.Queen){Activity=ColonyActivity.Reproduce;AntColonyReproduction.Advance(this,dt);return;}
            if(Role==AntRole.Worker){AntColonyWorker.Advance(this,dt);return;}
            if(Role==AntRole.Mate){Activity=ColonyActivity.Mate;return;}
            AdvanceSoldier(dt);
        }
        private void BeginFounding()
        {
            string parentGroup=GroupId;
            Vector3 center=Center,up=EcologyQueries.Up(center);var tangent=Vector3.ProjectOnPlane(UnityEngine.Random.onUnitSphere,up).normalized;
            State.foundingPoint=EcologyQueries.ToLocal(EcologyQueries.Surface(center+tangent*Radius*AntColonySettings.Current.foundingDistanceRatio));
            State.founding=true;State.supplyPoints.Clear();Assign(AntRole.Queen,Guid.NewGuid().ToString("N"));State.supplyPoints.Clear();
            // ★ 新增：在种群标识变化的真实建群入口记录来源，而不是按地理接近猜测谱系。
            PopulationArchive.RecordFounding(parentGroup,GroupId,Population.Mode,Entity.DisplayName);
            Activity=ColonyActivity.Founding;
        }
        private void AdvanceSoldier(float dt)
        {
            // ★ 修复（防Bug回归）：持续可见的猎物不能永久占据饥饿士兵的补给优先级。
            if(ColonyFeeding.Destination(this,out _))return;
            if(!EcologyQueries.Alive(HuntTarget)||!EcologyMotion.CanHunt(Genes,HuntTarget)||!EcologyMotion.Detectable(HuntTarget,transform.position,Genes.GetAttribute("senseRange"),Entity))HuntTarget=null;
            if(State.scan<=0)
            {
                State.scan=AntColonySettings.Current.scanInterval;
                float range=Genes.GetAttribute("senseRange");Vector3 position=transform.position;
                // ★ 修复（防Bug回归）：先筛感知距离，再执行体型、同群和领地判断，分散的其他种群不消耗完整捕猎判定。
                HuntTarget=EntityRegistry.All.Where(e=>e!=Entity&&(e.transform.position-position).sqrMagnitude<=range*range&&EcologyQueries.Alive(e)&&EcologyMotion.CanHunt(Genes,e)&&EcologyMotion.Detectable(e,position,range,Entity))
                    .OrderBy(e=>(e.transform.position-transform.position).sqrMagnitude).FirstOrDefault();
            }
            if(HuntTarget!=null){Activity=ColonyActivity.Hunt;return;}
            var settings=AntColonySettings.Current;
            if(State.patrolRemaining>0)
            {
                State.patrolRemaining=Mathf.Max(0,State.patrolRemaining-dt);
                float circumference=2*Mathf.PI*ColonyActivityRange.PatrolCircle(this).Radius*settings.soldierPatrolRadiusRatio;
                State.circleAngle+=360*Genes.GetAttribute("moveSpeed")*dt/Mathf.Max(settings.arrivalDistance,circumference);
                Activity=ColonyActivity.Patrol;if(State.patrolRemaining<=0)State.restRemaining=settings.soldierRestSeconds;
            }
            else
            {State.restRemaining=Mathf.Max(0,State.restRemaining-dt);Activity=ColonyActivity.Rest;if(State.restRemaining<=0)State.patrolRemaining=settings.soldierPatrolSeconds;}
        }
        public void AfterKill(){HuntTarget=null;State.scan=AntColonySettings.Current.soldierPatrolSeconds;State.patrolRemaining=AntColonySettings.Current.soldierPatrolSeconds;State.restRemaining=0;Activity=ColonyActivity.Patrol;}
        public bool Destination(out Vector3 point,out DarwinEntity target,out float multiplier)
        {
            point=transform.position;target=null;multiplier=1;if(!Active||Role==AntRole.None)return false;
            if(State.founding){point=EcologyQueries.ToWorld(State.foundingPoint);return true;}
            // ★ 修复（防Bug回归）：所有已定居分工先寻可用补给，王后/幼体前往育幼能量块，成年成员前往普通补给。
            if(ColonyFeeding.Destination(this,out point))return true;
            // ★ 修复（防Bug回归）：跟随终点是各自站位，不能让同群成员持续向王后的身体中心挤压。
            if(Young||Role==AntRole.Mate){point=ColonyFormation.Home(this,Center,AntColonySettings.Current.feedRadius*.8f);return true;}
            if(Role==AntRole.Worker){point=AntColonyWorker.Destination(this);return true;}
            if(Role==AntRole.Soldier&&EcologyQueries.Alive(HuntTarget)){target=HuntTarget;point=target.transform.position;return true;}
            if(Role==AntRole.Soldier&&State.patrolRemaining>0)
            {
                // ★ 适配：巡逻路径与捕猎、图层使用同一批王后和补给活动中心。
                var circle=ColonyActivityRange.PatrolCircle(this);
                point=ColonyActivityRange.Boundary(circle,State.circleAngle,AntColonySettings.Current.soldierPatrolRadiusRatio);
            }
            else if(Role==AntRole.Soldier)point=ColonyFormation.Home(this,Center,Radius*.75f);
            return true;
        }
        public bool TrySupplyDestination(out Vector3 point)
        {
            return ColonyFeeding.Destination(this,out point);
        }
        public void EnsureSupplyPoints()
        {
            // ★ 修复（防Bug回归）：王后出生不预建空检查点；只保留当前确有剩余能量的成年补给位置。
            State.supplyPoints.Clear();
            foreach(var resource in ColonyResource.All)if(resource.State.group==GroupId&&resource.State.kind==ColonyResourceKind.Supply)
                State.supplyPoints.Add(EcologyQueries.ToLocal(resource.transform.position));
        }
        public void EnforceGenome()
        {
            if(Frozen&&!string.IsNullOrEmpty(State.lockedGenome)&&JsonUtility.ToJson(Genes.Genome)!=State.lockedGenome)
                Genes.Genome=JsonUtility.FromJson<Genome>(State.lockedGenome);
        }
        public static IReadOnlyDictionary<string,float> ExpressionSuppression(EntityGeneController genes)
        {
            var member=genes.GetComponent<AntColonyMember>();if(member==null||!member.Active||member.Role==AntRole.None)return null;
            if(member._suppressionRole!=member.State.role)
            {
                member._suppression.Clear();foreach(var id in AntColonySettings.Current.Rule(member.Role).suppressedGenes)member._suppression[id]=AntColonySettings.Current.geneSuppression;
                // ★ 适配：旧角色配置已禁用有性繁殖时，其新增出错分支也应禁用，避免工匠/配偶显示可繁殖能力。
                if(member._suppression.ContainsKey(ParthenogenesisEvolutionUpgrade.SourceGeneId))member._suppression[ParthenogenesisEvolutionUpgrade.GeneId]=AntColonySettings.Current.geneSuppression;
                member._suppressionRole=member.State.role;
            }
            return member._suppression;
        }
        public static float Attribute(EntityGeneController genes,string id,float value)
        {
            var member=genes.GetComponent<AntColonyMember>();if(member==null||!member.Active||member.Role==AntRole.None)return value;
            var rule=AntColonySettings.Current.Rule(member.Role);
            if(id=="attack")return member.Young?0:value*rule.attackMultiplier;
            if(id=="moveSpeed")return value*(member.State.founding?1:rule.moveMultiplier);
            return value;
        }
        public AntColonyMemberSave Capture()=>JsonUtility.FromJson<AntColonyMemberSave>(JsonUtility.ToJson(State));
        public void Suspend(){AntColonyWorker.Release(this);HuntTarget=null;}
        public void Restore(AntColonyMemberSave state){if(state==null||!state.HasData)return;State=JsonUtility.FromJson<AntColonyMemberSave>(JsonUtility.ToJson(state));if(State.partnerGenome?.Genes?.Count==0)State.partnerGenome=null;_suppressionRole=null;PopulationGroupIndex.Invalidate();Genes.Recalculate();Population.EnsureMembership();if(GetComponent<ColonyMemberMarker>()==null)gameObject.AddComponent<ColonyMemberMarker>();}
    }
}

using System.Linq;
using DarwinPark.Entities.Logic;
using DarwinPark.Entities.Stats;
using DarwinPark.Genetics;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    // ★ 新增：王后独占繁殖流程，有性蚁群只维持一名不可自主繁殖的配偶，孕育进度随分工状态保存。
    public static class AntColonyReproduction
    {
        public static bool BlocksOrdinary(EntityGeneController genes)=>AntColonyMember.IsManaged(genes);
        private static Genome Copy(Genome genome)
        {
            var result=new Genome();
            foreach(var gene in genome.Genes)
            {var copy=GeneInstance.Create(gene.DefinitionId,gene.Value,gene.Tier);copy.Enabled=gene.Enabled;copy.CopyStrength=gene.CopyStrength;copy.MissingStateIds=new System.Collections.Generic.List<string>(gene.MissingStateIds);copy.OriginInstanceId=gene.InstanceId;result.Add(copy);}
            return result;
        }
        private static DarwinEntity Spawn(Genome genome,Vector3 point)
        {
            if(!EntityPopulationLimit.CanSpawn)return null;
            var before=EntityRegistry.All.ToArray();DarwinEntity.Spawner?.Invoke(genome,point,"");return EntityRegistry.All.FirstOrDefault(e=>!before.Contains(e));
        }
        public static void Advance(AntColonyMember queen,float dt)
        {
            if(queen.Role!=AntRole.Queen||queen.Young||queen.State.founding||queen.Genes.CurrentAge!=AgeState.Adult){queen.State.mateWait=0;return;}
            if(dt<=0||DarwinPark.Core.WorldAuthority.IsReplica)return;
            var genes=queen.Genes;var state=queen.State;var settings=AntColonySettings.Current;var stats=queen.GetComponent<EntityStats>();
            var reproduction=genes.Evaluation.Genes.Where(g=>g.IsActive&&genes.GetLogic(g.Gene) is ReproductionGeneLogic).OrderByDescending(g=>g.Definition.Tier).FirstOrDefault();
            if(reproduction==null)
            {state.mateWait=0;if(genes.IsGestating){genes.IsGestating=false;state.reproductionTimer=0;genes.Recalculate();}return;}
            bool sexual=reproduction.State?.StateId=="sexual";
            var mates=queen.Group.Where(m=>m.Role==AntRole.Mate).OrderBy(m=>m.Population.JoinOrder).ToArray();
            // 配偶不来自出生随机池；损失后由王后花费实际储备补充，并立即锁定为同群成年配偶。
            // ★ 适配：带孤雌分支的王后等待真实配偶，不再凭空复制一个配偶绕过等待机制；其他有性王后保持既有补配偶流程。
            if(EntityPopulationLimit.CanSpawn&&sexual&&!ParthenogenesisCondition.Enabled(genes)&&mates.Length==0&&stats.TryGet("storedNutrient",out var mateReserve)&&mateReserve>=settings.mateCost&&DarwinEntity.Spawner!=null)
            {
                var mate=ColonyFormation.TryBirthPosition(queen,out var matePoint)?Spawn(Copy(genes.Genome),matePoint):null;
                if(mate!=null)
                {
                    AntColonyMember.Ensure(mate.GetComponent<PopulationBehavior>()).Assign(AntRole.Mate,queen.GroupId);
                    mate.GetComponent<EntityLifeCycle>().RestoreProgress(LifeCycleSettings.Load().adultProgress);
                    int mask=(1<<(int)AgeState.Infant)|(1<<(int)AgeState.Adult);mate.Genes.RestoreStageState(AgeState.Adult,mask,2);mate.Genes.Recalculate();
                    stats.Modify("storedNutrient",-settings.mateCost);mates=new[]{mate.GetComponent<AntColonyMember>()};
                }
            }
            if(genes.IsGestating)
            {
                state.mateWait=0;
                state.reproductionTimer=Mathf.Max(0,state.reproductionTimer-dt);
                if(state.reproductionTimer>0||DarwinEntity.Spawner==null)return;
                // ★ 修复（防Bug回归）：只在育幼范围空位出生；拥挤时保留孕育，不继续向已有身体上方堆叠后代。
                if(!ColonyFormation.TryBirthPosition(queen,out var point))return;
                var child=Copy(genes.Genome);
                if(state.partnerGenome!=null)
                    foreach(var gene in child.Genes){var partner=state.partnerGenome.Genes.FirstOrDefault(g=>g.DefinitionId==gene.DefinitionId);if(partner!=null)gene.Value=(gene.Value+partner.Value)*.5f;}
                // 使用原出生入口，卵生/孵化和分工继承仍由同一个入口处理。
                if(!EcologyReproduction.Spawn(genes,child,point))return;genes.IsGestating=false;state.partnerGenome=null;state.parthenogenetic=false;state.reproductionCooldown=settings.queenCooldownSeconds;genes.Recalculate();return;
            }
            if(state.reproductionCooldown>0){state.mateWait=0;return;}
            var eligibleMate=mates.FirstOrDefault(m=>EcologyQueries.Distance(queen.transform.position,m.transform.position)<=settings.feedRadius);
            bool parthenogenetic=ParthenogenesisCondition.Advance(genes,ref state.mateWait,!sexual||eligibleMate!=null,dt);
            if(!EntityPopulationLimit.CanSpawn||sexual&&eligibleMate==null&&!parthenogenetic)return;
            if(!stats.TryGet("storedNutrient",out float reserve)||reserve<settings.queenBirthCost)return;
            // ★ 适配：维持比例超量时延长王后的新孕育间隔，不中断已开始的孕育。
            if(!PopulationMaintenance.BreedingReady(genes,ref state.maintenanceWait,dt))return;state.maintenanceWait=0;
            stats.Modify("storedNutrient",-settings.queenBirthCost);state.partnerGenome=sexual&&!parthenogenetic?Copy(eligibleMate.Genes.Genome):null;state.parthenogenetic=parthenogenetic;state.mateWait=0;state.reproductionTimer=settings.queenGestationSeconds;genes.IsGestating=true;genes.Recalculate();
        }
    }
}

using System;
using System.IO;
using System.Linq;
using DarwinPark.Core;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    public enum AntRole { None, Soldier, Worker, Reproductive, Queen, Mate }
    [Serializable] public sealed class AntRoleRule
    {
        public string role,label;public float birthWeight,attackMultiplier,moveMultiplier;
        public bool frozenGenome;public string[] suppressedGenes;
        public AntRole Role=>(AntRole)Enum.Parse(typeof(AntRole),role);
    }
    // ★ 新增：蚁群规则随世界快照保存；角色比例、巡逻与运输参数均由配置控制。
    [Serializable] public sealed class AntColonySettings
    {
        public int version,supplyPointCount,maximumReproductives,minimumReproductives,reproductivePopulationThreshold,circleSegments;
        public AntRoleRule[] roles;
        public bool patrolRetaliationOnly=true;
        public float patrolDuration,patrolRestMin,patrolRestMax,retaliationSeconds,scanInterval;
        public float colonyRadius,minimumColonyRadius,soldierPatrolRadiusRatio,soldierPatrolSeconds,soldierRestSeconds;
        public float arrivalDistance,transportSearchRadius,transportReach,transportOffset,nurseryDeliveryFraction;
        public float biomassPerSize,minimumBiomass,queenFeedThreshold,memberFeedThreshold,feedRate,feedRadius,queenReserveTarget;
        public float queenGestationSeconds,queenCooldownSeconds,queenBirthCost,mateCost,foundingDistanceRatio;
        public float energyBlockSize,glowIntensity,glowRange,overlayWidth;
        public float geneSuppression;
        public string energyColor;
        private static AntColonySettings _current;private static string _json;
        public static AntColonySettings Current {get{if(_current==null)UseSnapshot(null);return _current;}}
        public static string CurrentJson {get{_=Current;return _json;}}
        public static string ReadConfiguredJson()
        {
            string path=Path.Combine(GamePaths.Mods,"Default","ant_colony.json");
            if(File.Exists(path))return File.ReadAllText(path);
            var text=Resources.Load<TextAsset>("Entities/ant_colony");
            if(text==null)throw new InvalidDataException("缺少 Entities/ant_colony");return text.text;
        }
        public static AntColonySettings Parse(string json)
        {
            var value=JsonUtility.FromJson<AntColonySettings>(json);
            if(value==null||value.version!=1||value.roles==null||value.roles.Length!=5)throw new InvalidDataException("蚁群配置版本或分工无效");
            var ids=value.roles.Select(r=>r.Role).ToArray();
            if(ids.Distinct().Count()!=5||ids.Contains(AntRole.None)||ids.Any(id=>!Enum.IsDefined(typeof(AntRole),id)))throw new InvalidDataException("蚁群角色重复或缺失");
            foreach(var rule in value.roles)
                if(string.IsNullOrWhiteSpace(rule.label)||rule.suppressedGenes==null||new[]{rule.birthWeight,rule.attackMultiplier,rule.moveMultiplier}.Any(n=>float.IsNaN(n)||float.IsInfinity(n)||n<0))
                    throw new InvalidDataException("蚁群角色参数无效："+rule.role);
            foreach(var field in typeof(AntColonySettings).GetFields().Where(f=>f.FieldType==typeof(float)))
            {float number=(float)field.GetValue(value);if(float.IsNaN(number)||float.IsInfinity(number)||number<0)throw new InvalidDataException("蚁群参数必须为非负有限值："+field.Name);}
            if(value.supplyPointCount<1||value.minimumReproductives<0||value.maximumReproductives<value.minimumReproductives||value.reproductivePopulationThreshold<1||value.geneSuppression<=0||value.circleSegments<12||value.scanInterval<=0||value.arrivalDistance<=0||value.colonyRadius<=0||value.minimumColonyRadius<=0||value.queenGestationSeconds<=0||value.feedRate<=0||value.feedRadius<=0||value.patrolRestMax<value.patrolRestMin||value.nurseryDeliveryFraction>1||value.foundingDistanceRatio<=1||value.roles.Where(r=>r.Role==AntRole.Soldier||r.Role==AntRole.Worker).Sum(r=>r.birthWeight)<=0||!ColorUtility.TryParseHtmlString(value.energyColor,out _))
                throw new InvalidDataException("蚁群半径、计时、比例、分工权重或颜色配置无效");
            return value;
        }
        private System.Collections.Generic.Dictionary<AntRole,AntRoleRule> _roleRules;
        public AntRoleRule Rule(AntRole role)
        {
            // ★ 修复（防Bug回归）：角色倍率是属性热路径，配置加载后只构建一次索引，不反复解析角色文本和枚举数组。
            if(_roleRules==null){_roleRules=new System.Collections.Generic.Dictionary<AntRole,AntRoleRule>();foreach(var rule in roles)_roleRules.Add(rule.Role,rule);}
            return _roleRules[role];
        }
        public static void UseSnapshot(string raw){raw=string.IsNullOrWhiteSpace(raw)?ReadConfiguredJson():raw;var parsed=Parse(raw);_current=parsed;_json=raw;}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)] public static void Clear(){_current=null;_json=null;}
    }
}

using System.Linq;
using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    // ★ 新增：单个工匠独占运输任务；活植株仍为原实体，读档/搬运中断都能恢复其刚体。
    public static class AntColonyWorker
    {
        private static readonly Dictionary<DarwinEntity,AntColonyMember> Carriers=new Dictionary<DarwinEntity,AntColonyMember>();
        private static readonly Dictionary<AntColonyMember,DarwinEntity> Cargo=new Dictionary<AntColonyMember,DarwinEntity>();
        private static readonly Dictionary<string,AntColonyMember> Claims=new Dictionary<string,AntColonyMember>();
        private static readonly Dictionary<AntColonyMember,string> Targets=new Dictionary<AntColonyMember,string>();
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)] private static void Reset(){Carriers.Clear();Cargo.Clear();Claims.Clear();Targets.Clear();}
        private static DarwinEntity Entity(string id)=>EcologyIdentity.Find(id);
        // ★ 修复（防Bug回归）：移动属性只需判定是否被搬运，不应每次扫描所有蚁群并重算每名成员的表达。
        private static void TrackCargo(AntColonyMember worker,DarwinEntity entity)
        {
            // ★ 修复（防Bug回归）：Unity 已销毁对象会与 null 比较相等，必须比较托管引用，否则途中死亡的运载物会永久留在索引中。
            if(Cargo.TryGetValue(worker,out var previous)&&!ReferenceEquals(previous,entity)){Carriers.Remove(previous);Cargo.Remove(worker);}
            if(entity!=null){Cargo[worker]=entity;Carriers[entity]=worker;}
        }
        private static void TrackTarget(AntColonyMember worker)
        {
            string id=worker.State.livingTarget;
            if(Targets.TryGetValue(worker,out var previous)&&previous!=id){if(Claims.TryGetValue(previous,out var owner)&&owner==worker)Claims.Remove(previous);Targets.Remove(worker);}
            if(string.IsNullOrEmpty(id))return;
            Targets[worker]=id;if(!Claims.TryGetValue(id,out var current)||current==worker||current==null||!current.Active)Claims[id]=worker;
        }
        private static bool Claimed(DarwinEntity entity,AntColonyMember worker)
        {
            string id=EcologyIdentity.Of(entity);
            if(!Claims.TryGetValue(id,out var owner)||owner==worker)return false;
            if(owner!=null&&owner.Active&&(owner.State.livingTarget==id||owner.State.carriedLiving==id))return true;
            Claims.Remove(id);return false;
        }
        // ★ 适配：体内隐藏的寄生幼体不是可搬运植株；不能把被宿主带到附近的幼体当作零速食物。
        private static bool Valid(DarwinEntity entity,AntColonyMember worker)=>EcologyQueries.Alive(entity)&&ColonyActivityRange.Contains(worker.Population,entity.transform.position)&&entity.GetComponent<NutritionParasite>()?.Host==null&&!worker.Population.SameGroup(entity)&&entity.Genes.GetAttribute("moveSpeed")<=0&&entity.GetComponent<EntityManualControl>()?.IsControlled!=true;
        public static void Advance(AntColonyMember worker,float dt)
        {
            var state=worker.State;var settings=AntColonySettings.Current;
            var carried=ColonyResource.Find(state.carriedResource);var live=Entity(state.carriedLiving);
            TrackTarget(worker);TrackCargo(worker,live);
            if(carried!=null||live!=null)
            {
                worker.Activity=ColonyActivity.Transport;
                Vector3 held=worker.transform.position+EcologyQueries.Up(worker.transform.position)*settings.transportOffset;
                if(carried!=null)carried.CarryTo(held);
                // ★ 适配：搬运会在目标自己的Update之后传送位置，同帧更新邻域，避免食物与竞争还停留在旧格子。
                if(live!=null){live.transform.position=held;EntityNeighborhood.ObservePosition(live.Genes);}
                // ★ 修复（防Bug回归）：运输中允许先补给但保留独占货物，不能无限执行运输直到饿死，也不能中断后复制货物。
                if(ColonyFeeding.Destination(worker,out _))return;
                // ★ 修复（防Bug回归）：王后移动后育幼送达点必须随之更新，避免永远送往旧位置。
                if(state.deliveryNursery&&worker.Queen!=null)state.deliveryPoint=EcologyQueries.ToLocal(worker.Queen.transform.position);
                var destination=EcologyQueries.ToWorld(state.deliveryPoint);
                if(EcologyQueries.Distance(worker.transform.position,destination)>settings.arrivalDistance)return;
                float energy=carried!=null?carried.State.energy:ColonyResource.Biomass(live);
                if(carried!=null)carried.Remove();
                if(live!=null){live.gameObject.SetActive(false);Object.Destroy(live.gameObject);}
                ColonyResource.Convert(worker.GroupId,destination,energy,state.deliveryNursery);
                state.carriedResource=state.carriedLiving=state.resourceTarget=state.livingTarget=null;TrackCargo(worker,null);TrackTarget(worker);return;
            }
            state.carriedResource=state.carriedLiving=null;
            // ★ 修复（防Bug回归）：未取货时同样先解决饥饿，原任务保留，吃饱后继续执行。
            if(ColonyFeeding.Destination(worker,out _))return;
            var resource=ColonyResource.Find(state.resourceTarget);var plant=Entity(state.livingTarget);
            if(resource!=null&&(!ColonyActivityRange.Contains(worker.Population,resource.transform.position)||!resource.Claim(worker)))
            {resource.Release(worker.Id);state.resourceTarget=null;resource=null;}
            if(plant!=null&&(!Valid(plant,worker)||Claimed(plant,worker))){state.livingTarget=null;plant=null;}
            if(resource==null&&plant==null&&state.scan<=0)
            {
                state.scan=settings.scanInterval;
                // ★ 适配：活动圆决定采集边界，搜索距离仍决定单次感知；二者不能被个人出生领地替代。
                foreach(var body in ColonyResource.All.Where(r=>ColonyCorpseAccess.Available(r,worker)&&ColonyActivityRange.Contains(worker.Population,r.transform.position)&&EcologyQueries.Distance(worker.transform.position,r.transform.position)<=settings.transportSearchRadius).OrderBy(r=>(r.transform.position-worker.transform.position).sqrMagnitude))
                    if(body.Claim(worker)){resource=body;state.resourceTarget=body.State.id;break;}
                if(resource==null)
                {
                    // ★ 适配：先筛廉价距离再读基因属性，远处种群不参与运输能力与占用判定。
                    plant=EntityRegistry.All.Where(e=>(e.transform.position-worker.transform.position).sqrMagnitude<=settings.transportSearchRadius*settings.transportSearchRadius&&Valid(e,worker)&&!Claimed(e,worker)&&EcologyQueries.Distance(worker.transform.position,e.transform.position)<=settings.transportSearchRadius).OrderBy(e=>(e.transform.position-worker.transform.position).sqrMagnitude).FirstOrDefault();
                    state.livingTarget=plant!=null?EcologyIdentity.Of(plant):null;
                    TrackTarget(worker);
                }
            }
            if(resource==null&&plant==null){worker.Activity=ColonyActivity.Rest;return;}
            worker.Activity=ColonyActivity.Collect;Vector3 point=resource!=null?resource.transform.position:plant.transform.position;
            if(EcologyQueries.Distance(worker.transform.position,point)>settings.transportReach)return;
            if(resource!=null)state.carriedResource=resource.State.id;
            else
            {
                state.carriedLiving=EcologyIdentity.Of(plant);var body=plant.GetComponent<Rigidbody>();
                TrackCargo(worker,plant);
                // ★ 修复（防Bug回归）：静止活体也可能原本就是运动学刚体，不能向这种刚体写速度；释放时仍恢复原始模式。
                if(body!=null){state.originalKinematic=body.isKinematic;state.originalDetect=body.detectCollisions;if(!body.isKinematic)body.linearVelocity=Vector3.zero;body.isKinematic=true;body.detectCollisions=false;}
            }
            var queen=worker.Queen;
            state.deliveryNursery=UnityEngine.Random.value<settings.nurseryDeliveryFraction;
            if(queen==null){state.deliveryPoint=EcologyQueries.ToLocal(worker.Center);state.deliveryNursery=true;}
            else
            {
                queen.EnsureSupplyPoints();
                // ★ 适配：优先补足当前不存在的两类补给，再按配置分配后续货物，避免随机连抽使王后永久断粮。
                if(!ColonyResource.All.Any(r=>r.State.group==worker.GroupId&&r.State.kind==ColonyResourceKind.Nursery))state.deliveryNursery=true;
                else if(!ColonyResource.All.Any(r=>r.State.group==worker.GroupId&&r.State.kind==ColonyResourceKind.Supply))state.deliveryNursery=false;
                if(state.deliveryNursery)state.deliveryPoint=EcologyQueries.ToLocal(queen.transform.position);
                else if(queen.State.supplyPoints.Count>=settings.supplyPointCount)state.deliveryPoint=queen.State.supplyPoints[UnityEngine.Random.Range(0,queen.State.supplyPoints.Count)];
                else
                {
                    // ★ 适配：已有实际货物才计划新存放位置；抵达转换前不把计划点计入活动区。
                    var tangent=Vector3.ProjectOnPlane(UnityEngine.Random.onUnitSphere,EcologyQueries.Up(queen.transform.position)).normalized;
                    state.deliveryPoint=EcologyQueries.ToLocal(EcologyQueries.Surface(queen.transform.position+tangent*UnityEngine.Random.Range(Mathf.Min(settings.feedRadius,queen.Radius),queen.Radius)));
                }
            }
        }
        public static Vector3 Destination(AntColonyMember worker)
        {
            var state=worker.State;
            if(!string.IsNullOrEmpty(state.carriedResource)||!string.IsNullOrEmpty(state.carriedLiving))return EcologyQueries.ToWorld(state.deliveryPoint);
            var resource=ColonyResource.Find(state.resourceTarget);if(resource!=null)return resource.transform.position;
            var plant=Entity(state.livingTarget);if(plant!=null)return plant.transform.position;
            // 工匠休息时靠近群内补给点，避免饥饿时被无效运输目标锁住。
            var supply=ColonyResource.All.Where(r=>r.State.group==worker.GroupId&&r.State.kind==ColonyResourceKind.Supply).OrderBy(r=>(r.transform.position-worker.transform.position).sqrMagnitude).FirstOrDefault();
            // ★ 修复（防Bug回归）：空闲工匠在活动区分散休息，不能全部返回同一个王后中心坐标。
            return ColonyFormation.Home(worker,supply!=null?supply.transform.position:worker.Center,supply!=null?AntColonySettings.Current.feedRadius:worker.Radius*.75f);
        }
        public static void Release(AntColonyMember worker)
        {
            if(worker==null||worker.Entity==null)return;var state=worker.State;
            ColonyResource.Find(state.resourceTarget)?.Release(worker.Id);ColonyResource.Find(state.carriedResource)?.Release(worker.Id);
            var live=Entity(state.carriedLiving);
            if(live!=null)
            {var body=live.GetComponent<Rigidbody>();if(body!=null){body.isKinematic=state.originalKinematic;body.detectCollisions=state.originalDetect;}live.transform.position=EcologyQueries.Surface(worker.transform.position);EntityNeighborhood.ObservePosition(live.Genes);}
            state.carriedResource=state.carriedLiving=state.resourceTarget=state.livingTarget=null;
            TrackCargo(worker,null);TrackTarget(worker);
        }
        public static void Resolve(AntColonyMember worker)
        {
            TrackTarget(worker);var live=Entity(worker.State.carriedLiving);TrackCargo(worker,live);if(live==null)return;
            var body=live.GetComponent<Rigidbody>();if(body!=null){body.isKinematic=true;body.detectCollisions=false;}
        }
        public static bool IsCarried(DarwinEntity entity)=>entity!=null&&Carriers.TryGetValue(entity,out var worker)&&worker!=null&&worker.Active&&worker.State.carriedLiving==EcologyIdentity.Of(entity);
    }
}

using System.Collections.Generic;
using DarwinPark.Core;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    public readonly struct ActivityCircle
    {
        public readonly string Id;public readonly Vector3 Center;public readonly float Radius;
        public ActivityCircle(string id,Vector3 center,float radius){Id=id;Center=center;Radius=radius;}
    }
    // ★ 修复（防Bug回归）：活动范围使用王后及补给点球面圆的并集，巡猎、领地和图层共用同一判定。
    public static class ColonyActivityRange
    {
        public static IEnumerable<ActivityCircle> Circles(PopulationBehavior population)
        {
            if(population==null||!population.Active)yield break;
            var queen=AntColonyMember.QueenFor(population);
            var leader=queen!=null?queen.Population:population.Leader;
            if(leader==null)yield break;
            float radius=queen!=null?queen.Radius:Mathf.Max(AntColonySettings.Current.minimumColonyRadius,leader.GetComponent<EntityGeneController>().GetAttribute("territory_radius"))*GameplayTuning.Current.colonyActivityRadiusMultiplier;
            yield return new ActivityCircle("leader",leader.transform.position,radius);
            if(queen==null)yield break;
            float supplyRadius=radius*GameplayTuning.Current.supplyActivityRadiusRatio;
            // ★ 修复（防Bug回归）：旧档里预先生成的空点不再扩张范围，耗尽的补给也立即失去活动圆。
            foreach(var resource in ColonyResource.All)
            {
                if(resource.State.group!=population.GroupId||resource.State.kind!=ColonyResourceKind.Supply&&resource.State.kind!=ColonyResourceKind.Nursery)continue;
                bool duplicate=Mathf.Approximately(radius,supplyRadius)&&Vector3.Distance(resource.transform.position,queen.transform.position)<.01f;
                if(!duplicate)yield return new ActivityCircle("resource-"+resource.State.id,resource.transform.position,supplyRadius);
            }
        }
        public static bool Contains(PopulationBehavior population,Vector3 position)
        {
            foreach(var circle in Circles(population))if(EcologyQueries.Distance(circle.Center,position)<=circle.Radius)return true;
            return false;
        }
        public static Vector3 Boundary(ActivityCircle circle,float angle,float ratio=1)
        {
            var up=EcologyQueries.Up(circle.Center);var axis=Vector3.Cross(up,Vector3.forward).normalized;if(axis.sqrMagnitude<.1f)axis=Vector3.Cross(up,Vector3.right).normalized;
            var tangent=Quaternion.AngleAxis(angle,up)*axis;var planet=EcologyQueries.Planet;
            if(planet==null)return circle.Center+tangent*circle.Radius*ratio;
            float radians=circle.Radius*ratio/Mathf.Max(planet.radius,planet.WaterRadius);
            return EcologyQueries.Surface(planet.transform.position+(up*Mathf.Cos(radians)+tangent*Mathf.Sin(radians))*Vector3.Distance(circle.Center,planet.transform.position));
        }
        public static Vector3 NearestCenter(PopulationBehavior population,Vector3 position)
        {
            float best=float.PositiveInfinity;Vector3 result=position;
            foreach(var circle in Circles(population)){float gap=EcologyQueries.Distance(circle.Center,position)-circle.Radius;if(gap<best){best=gap;result=circle.Center;}}
            return result;
        }
        public static ActivityCircle PatrolCircle(AntColonyMember member)
        {
            // 固定出生顺序分配巡逻中心，补给点不再全部无人巡逻。
            var circles=new List<ActivityCircle>(Circles(member.Population));
            return circles.Count==0?new ActivityCircle("leader",member.Center,member.Radius):circles[(int)(member.Population.JoinOrder%circles.Count)];
        }
    }
}

