            if(!string.IsNullOrEmpty(nutritionParasite?.host)&&entities.TryGetValue(nutritionParasite.host,out var feedingHost))entity.GetComponent<NutritionParasite>()?.TryAttach(feedingHost,nutritionParasite);
        }
    }
