namespace DarwinPark.Entities.Ecology
{
    // ★ 新增：在清场前校验外来基因与计时，坏档不能先破坏当前世界，也不能把宿主的基因当作默认后代。
    public static class NutritionSaveValidation
    {
        public static void Validate(EcologySaveState state,ICollection<string> catalog)
        {
            if(state==null)return;
            if(state.nutritionParasiteCount<0||!string.IsNullOrEmpty(state.nutritionParasite?.host)&&(!Guid.TryParseExact(state.nutritionParasite.host,"N",out _)||state.nutritionParasite.host==state.id))throw new InvalidDataException("营养寄生宿主标识或数量无效");
            if(state.foreignEggs==null)return;
            foreach(var egg in state.foreignEggs)
                if(egg==null||!float.IsFinite(egg.remaining)||egg.remaining<0||!Guid.TryParseExact(egg.parent,"N",out _)||egg.genome?.Genes==null||egg.genome.Genes.Count==0||egg.genome.Genes.Any(g=>g==null||!catalog.Contains(g.DefinitionId)||!float.IsFinite(g.Value)||g.MissingStateIds==null))throw new InvalidDataException("卵寄生载荷的亲本、计时或基因组无效");
        }
    }
}

using System.Linq;
using DarwinPark.Entities.Stats;
using DarwinPark.Entities.Logic;
using DarwinPark.Genetics;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    // ★ 新增：吸收只扣实际增加的营养，满仓、部分消化及群体分配不能凭空吞掉剩余尸体。
    public static class NutritionTransfer
    {
        public static float Room(EntityStats stats)=>stats==null?0:stats.CapacityRemaining("nutrient")+stats.CapacityRemaining("storedNutrient");
        public static float Feed(EntityStats stats,float amount)
        {
            float accepted=Mathf.Min(Mathf.Max(0,amount),Room(stats));if(accepted>0)stats.Feed(accepted);return accepted;
        }
        public static bool CanDigest(EntityGeneController genes)
        {
            if(genes==null)return false;
            var settings=NutritionEcologySettings.Current;
            // ★ 适配：食腐替代正常异养消化，攻击能力仍由行动基因授权，攻击本身不再产生额外营养。
            if(EcologyQueries.Active(genes,settings.scavengerGene)!=null)return false;
            var state=EcologyQueries.Active(genes,settings.heterotrophyGene)?.State?.StateId;
            return state==settings.digestState||settings.adultParasitesDigest&&state==settings.parasiteState&&genes.CurrentAge!=AgeState.Infant;
        }
        public static bool CanHuntForFood(EntityGeneController genes)
        {
            var ant=genes.GetComponent<AntColonyMember>();return ant!=null&&ant.Active&&ant.Role==AntRole.Soldier||CanDigest(genes);
        }
        // ★ 适配：行动的食草倾向只挑静止实体，捕猎倾向可挑移动实体；两者都必须有消化食性才能自主猎食。
        public static bool FoodTargetAllowed(EntityGeneController genes,DarwinEntity target)
        {
            if(!CanHuntForFood(genes)||!EcologyQueries.Alive(target))return false;
            var movement=genes.Evaluation?.Genes.FirstOrDefault(g=>g.IsActive&&genes.GetLogic(g.Gene) is LocomotionGeneLogic&&GeneBehaviorAuthority.IsPrimary<LocomotionGeneLogic>(genes,g.Gene));
            return movement?.State?.StateId!="herbivore"||target.Genes.GetAttribute("moveSpeed")<=0;
        }
        public static float Digest(DarwinEntity attacker,float available)
        {
            if(!EcologyQueries.Alive(attacker)||!CanDigest(attacker.Genes))return 0;
            var soldier=attacker.GetComponent<AntColonyMember>();if(soldier!=null&&soldier.Active&&soldier.Role==AntRole.Soldier)return 0;
            float budget=available*Mathf.Clamp01(attacker.Genes.GetAttribute(NutritionEcologySettings.Current.digestionAttribute));
            var population=attacker.GetComponent<PopulationBehavior>();float absorbed=0;
            if(population!=null&&population.Active)
            {
                var recipients=population.GroupMembers.Where(m=>m!=population&&EcologyQueries.Distance(attacker.transform.position,m.transform.position)<=population.Aura).ToArray();
                if(recipients.Length>0)
                {
                    float share=budget*Mathf.Clamp01(EcologySettings.Load().shareFraction)/recipients.Length;
                    foreach(var recipient in recipients)absorbed+=Feed(recipient.GetComponent<EntityStats>(),share);
                }
            }
            return absorbed+Feed(attacker.GetComponent<EntityStats>(),budget-absorbed);
        }
    }
}

using System.Collections.Generic;
using DarwinPark.Core;
using DarwinPark.Entities.Stats;
using UnityEngine;
namespace DarwinPark.Entities.Ecology
{
    // ★ 新增：寄生以独立物体跟随宿主并只忽略宿主碰撞；宿主销毁不会连带销毁寄生体。
    [DefaultExecutionOrder(-180)]
    public sealed class ParasiteBehavior : MonoBehaviour
    {
        private EntityGeneController _genes;private DarwinEntity _entity,_candidate;private EcologySettings _settings;
        private Rigidbody _body;private bool _kinematic,_attached,_attachedInternal;private Vector3 _offset;private float _search;
        private bool _detectedByHost;private float _detectionRemaining;
        private readonly List<(Collider parasite,Collider host)> _ignored=new List<(Collider,Collider)>();
        private readonly Dictionary<Renderer,bool> _renderers=new Dictionary<Renderer,bool>();
        public DarwinEntity Host {get;private set;}
        public Vector3 Offset=>_offset;
        public bool DetectedByHost=>_detectedByHost;
        public float DetectionRemaining=>_detectionRemaining;
        public bool VisibleTo(DarwinEntity observer)=>observer!=Host||_detectedByHost;
        public void RestoreDetection(bool detected,float remaining){_detectedByHost=detected;_detectionRemaining=remaining;}
        // ★ 修复（防Bug回归）：热更新或旧组件残留时，新卵寄生逻辑不能继续触发旧的吸血/跟随行为。
        public bool Active=>EcologyQueries.Active(_genes,_settings.parasiticGene)?.Definition.LogicScriptId==DarwinPark.Genetics.NutritionEcologySettings.Current.legacyEggLogic;
        public bool Internal=>EcologyQueries.Active(_genes,_settings.parasiticGene)?.State?.StateId==_settings.internalState;
        public bool OriginalKinematic=>Host!=null?_kinematic:_body!=null&&_body.isKinematic;
        private void Awake(){_genes=GetComponent<EntityGeneController>();_entity=GetComponent<DarwinEntity>();_settings=EcologySettings.Load();EcologyIdentity.Ensure(gameObject);}
        private void Update(){Advance(ServiceLocator.TryGet<SimulationClock>(out var clock)?clock.GameDeltaTime:Time.deltaTime);}
        private void OnDisable(){Detach();}
        public void Advance(float dt)
        {
            if(!Active){Detach();return;}if(dt<=0)return;
            if(_body==null)_body=GetComponent<Rigidbody>();
            if(_attached&&(!EcologyQueries.Alive(Host)||_attachedInternal!=Internal))Detach();
            if(Host!=null)
            {
                // ★ 新增：宿主发现按模拟周期抽样并缓存，不能每个 AI 子步重复掷骰而必然发现寄生体。
                _detectionRemaining-=dt;
                while(_detectionRemaining<=0){_detectionRemaining+=Mathf.Max(.01f,_settings.hostSearchInterval);_detectedByHost=Random.value>=Mathf.Clamp01(_genes.GetAttribute("hide_from_host"));}
                var stats=Host.GetComponent<EntityStats>();float requested=Mathf.Max(0,_genes.GetAttribute("host_drain_rate"))*dt;
                stats.TryGet("nutrient",out var food);float drained=Mathf.Min(food,requested);stats.Modify("nutrient",-drained);
                stats.TryGet("storedNutrient",out var stored);float extra=Mathf.Min(stored,requested-drained);stats.Modify("storedNutrient",-extra);
                _entity.GetComponent<EntityStats>().Feed(drained+extra);Follow();return;
            }
            _search-=dt;
            if(_search<=0){_search=_settings.hostSearchInterval;_candidate=FindHost();}
            if(!CanHost(_candidate))return;
            if(Vector3.Distance(transform.position,_candidate.transform.position)<=_settings.attachReach+HostRadius(_candidate)){TryAttach(_candidate);return;}
            if(_body==null||_body.isKinematic)return;
            Vector3 up=EcologyQueries.Up(transform.position),direction=Vector3.ProjectOnPlane(_candidate.transform.position-transform.position,up).normalized;
            /* ★ 适配：与实际交付模拟时间一致。 */ float scale=ServiceLocator.TryGet<SimulationClock>(out var clock)?clock.MotionTimeScale:1;
            _body.linearVelocity=direction*_settings.parasiteSeekSpeed*scale+up*Mathf.Min(0,Vector3.Dot(_body.linearVelocity,up));
        }
        private DarwinEntity FindHost()
        {
            DarwinEntity best=null;float distance=_settings.hostSearchRadius*_settings.hostSearchRadius;
            foreach(var entity in EntityRegistry.All)
            {if(!CanHost(entity))continue;float d=(entity.transform.position-transform.position).sqrMagnitude;if(d<distance){best=entity;distance=d;}}
            return best;
        }
        private bool CanHost(DarwinEntity entity)
        {
            if(!EcologyQueries.Alive(entity)||entity==_entity)return false;
            _entity.GetComponent<EntityStats>().TryGet("size",out var own);entity.GetComponent<EntityStats>().TryGet("size",out var size);
            if(size<Mathf.Max(.01f,own)*_settings.minimumHostSizeRatio)return false;
            var seen=new HashSet<DarwinEntity>();var current=entity;
            while(current!=null){if(current==_entity||!seen.Add(current))return false;current=current.GetComponent<ParasiteBehavior>()?.Host;}
            return true;
        }
        private static float HostRadius(DarwinEntity entity)=>entity.GetComponent<Collider>()?.bounds.extents.magnitude??0;
        public bool TryAttach(DarwinEntity host,bool restoring=false,Vector3 savedOffset=default,bool originalKinematic=false)
        {
            if(!Active||!CanHost(host))return false;
            if(!restoring&&Vector3.Distance(transform.position,host.transform.position)>_settings.attachReach+HostRadius(host))return false;
            Detach();Host=host;_attached=true;_attachedInternal=Internal;_body=GetComponent<Rigidbody>();
            _detectedByHost=!restoring&&Random.value>=Mathf.Clamp01(_genes.GetAttribute("hide_from_host"));_detectionRemaining=_settings.hostSearchInterval;
            if(_body!=null){_kinematic=restoring?originalKinematic:_body.isKinematic;if(!_body.isKinematic){_body.linearVelocity=Vector3.zero;_body.angularVelocity=Vector3.zero;}_body.isKinematic=true;}
            _offset=restoring?savedOffset:host.transform.InverseTransformVector(Internal?Vector3.zero:EcologyQueries.Up(host.transform.position)*(HostRadius(host)+.1f));
            foreach(var parasite in GetComponentsInChildren<Collider>())foreach(var collider in host.GetComponentsInChildren<Collider>())
            {if(parasite==collider)continue;Physics.IgnoreCollision(parasite,collider,true);_ignored.Add((parasite,collider));}
            if(Internal)foreach(var renderer in GetComponentsInChildren<Renderer>()){_renderers[renderer]=renderer.enabled;renderer.enabled=false;}
            Follow();return true;
        }
        private void LateUpdate(){if(Host!=null)Follow();}
        // ★ 适配：宿主跟随可能发生在基因模拟之后，及时同步空间索引。
        private void Follow(){if(Host!=null){transform.position=Host.transform.position+Host.transform.TransformVector(_offset);EntityNeighborhood.ObservePosition(GetComponent<EntityGeneController>());}}
        public void Detach()
        {
            // Host 可能已变成 Unity 的假 null，清理以缓存集合为准，不能只检查 Host != null。
            foreach(var pair in _ignored)if(pair.parasite!=null&&pair.host!=null)Physics.IgnoreCollision(pair.parasite,pair.host,false);
            _ignored.Clear();foreach(var pair in _renderers)if(pair.Key!=null)pair.Key.enabled=pair.Value;_renderers.Clear();
            if(_body!=null&&_attached){_body.isKinematic=_kinematic;if(!_body.isKinematic)_body.linearVelocity=Vector3.zero;}
            _attached=false;Host=null;_candidate=null;_search=0;
        }
    }
}

using System;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    [Serializable] public sealed class PatrolRhythmSave {public float rest,active;}
    // ★ 新增：巡逻具有明确休息期，抵达一个巡逻点不会立即刷新下一段无限巡逻。
    public sealed class PatrolRhythm : MonoBehaviour
    {
        private float _rest,_active;
        private void Awake(){_rest=UnityEngine.Random.Range(AntColonySettings.Current.patrolRestMin,AntColonySettings.Current.patrolRestMax);}
        public bool Patrolling=>_active>0;
        public static PatrolRhythm Ensure(GameObject obj)=>obj.GetComponent<PatrolRhythm>()??obj.AddComponent<PatrolRhythm>();
        public void Advance(float dt)
        {
            if(dt<=0)return;
            var settings=AntColonySettings.Current;
            if(_active>0){_active=Mathf.Max(0,_active-dt);if(_active<=0)_rest=UnityEngine.Random.Range(settings.patrolRestMin,settings.patrolRestMax);}
            else{_rest=Mathf.Max(0,_rest-dt);if(_rest<=0)_active=settings.patrolDuration;}
        }
        public static bool Allows(EntityGeneController genes)=>Ensure(genes.gameObject).Patrolling;
        // ★ 修复（防Bug回归）：普通领地巡逻仅受击反击，附近捕猎倾向和饥饿状态不能自行授予攻击目标；群体仍执行自己的分工。
        public static bool Defensive(EntityGeneController genes)=>AntColonySettings.Current.patrolRetaliationOnly&&genes.GetComponent<TerritoryBehavior>()?.Active==true&&genes.GetComponent<PopulationBehavior>()?.Active!=true;
        public static bool Eligible(EntityGeneController genes,Genetics.EntityStateDefinition state)
        {
            if(state.Behavior==Genetics.EntityStateBehavior.Hunt&&Defensive(genes))return false;
            return state.Behavior!=Genetics.EntityStateBehavior.TerritoryPatrol||Allows(genes);
        }
        public static bool Resting(EntityGeneController genes)
        {
            if(genes.GetComponent<TerritoryBehavior>()?.Active!=true||Allows(genes)||genes.GetComponent<EntityStateController>()?.Current.Behavior==Genetics.EntityStateBehavior.Hunt)return false;
            var stats=genes.GetComponent<Stats.EntityStats>();return stats!=null&&!EcologyEnergyBudget.WantsFood(genes,stats,AntColonySettings.Current.memberFeedThreshold);
        }
        public PatrolRhythmSave Capture()=>new PatrolRhythmSave{rest=_rest,active=_active};
        public void Restore(PatrolRhythmSave state){if(state!=null){_rest=state.rest;_active=state.active;}}
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using DarwinPark.Core;
using DarwinPark.Genetics;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    [Serializable] public sealed class PopulationSample {public float time;public int members,infants,adults,elders;}
    [Serializable] public sealed class PopulationEvent {public float time;public string text;}
    [Serializable] public sealed class PopulationGeneCount {public string id;public int carried,expressed;}
    [Serializable] public sealed class PopulationRecord
    {
        // ★ 新增：实体配色默认独立；旧存档缺少该字段时维持原本外观。
        public string id,name,mode,parentId,color;public bool originKnown,visible=true,syncEntityColor;
        // ★ 新增：-1表示沿用外部全局默认值，旧档不因缺少字段而变成完全透明。
        public float rangeOpacity=-1;
        public float firstSeen,lastSeen;public int current,peak,lastLiving,increases,decreases;
        public int infants,adults,elders;
        public List<PopulationSample> samples=new List<PopulationSample>();
        public List<PopulationEvent> events=new List<PopulationEvent>();
        public List<PopulationGeneCount> genes=new List<PopulationGeneCount>();
    }
    [Serializable] public sealed class PopulationArchiveState {public int version=1;public List<PopulationRecord> groups=new List<PopulationRecord>();}
    [Serializable] public sealed class PopulationArchiveSettings
    {
        public float refreshSeconds=.5f,sampleGameSeconds=10;public int maximumSamples=512,maximumEvents=256;
        private static PopulationArchiveSettings _current;
        public static PopulationArchiveSettings Current
        {
            get
            {
                if(_current!=null)return _current;var asset=Resources.Load<TextAsset>("Entities/population_archive");if(asset==null)throw new InvalidDataException("缺少 Entities/population_archive");
                var value=JsonUtility.FromJson<PopulationArchiveSettings>(asset.text);
                if(value==null||!float.IsFinite(value.refreshSeconds)||value.refreshSeconds<=0||!float.IsFinite(value.sampleGameSeconds)||value.sampleGameSeconds<=0||value.maximumSamples<4||value.maximumEvents<4)throw new InvalidDataException("种群历史记录配置无效");return _current=value;
            }
        }
    }
    // ★ 新增：档案独立于存活实体；灭绝后保留历史，旧档从首次观察建档，不编造之前的出生或谱系。
    public static class PopulationArchive
    {
        private static readonly Dictionary<string,PopulationRecord> Records=new Dictionary<string,PopulationRecord>();
        public static long Revision {get;private set;}
        public static long DisplayRevision {get;private set;}
        public static IEnumerable<PopulationRecord> All=>Records.Values;
        public static float Now=>ServiceLocator.TryGet<SimulationClock>(out var clock)?clock.GameTime:0;
        public static PopulationRecord Find(string id)=>id!=null&&Records.TryGetValue(id,out var record)?record:null;
        public static PopulationRecord Register(string id,string mode,string name,bool known=false)
        {
            if(string.IsNullOrEmpty(id))return null;if(Records.TryGetValue(id,out var record))return record;
            record=new PopulationRecord{id=id,mode=mode??"",name=string.IsNullOrWhiteSpace(name)?"种群 "+id.Substring(0,Math.Min(6,id.Length)):name,firstSeen=Now,lastSeen=Now,originKnown=known};Records.Add(id,record);
            Event(record,known?"种群成立":"首次观察；此前历史未记录");Revision++;return record;
        }
        private static void Event(PopulationRecord record,string text)
        {
            record.events.Add(new PopulationEvent{time=Now,text=text});while(record.events.Count>PopulationArchiveSettings.Current.maximumEvents)record.events.RemoveAt(0);
        }
        public static void RecordFounding(string parent,string child,string mode,string name,string reason="繁殖个体离群建立新种群")
        {
            if(WorldAuthority.IsReplica||string.IsNullOrEmpty(parent)||string.IsNullOrEmpty(child)||parent==child)return;
            var source=Register(parent,mode,"原种群");var result=Register(child,mode,name,true);
            if(!string.IsNullOrEmpty(result.parentId))return;result.parentId=parent;result.originKnown=true;
            Event(source,reason+"："+result.name);Event(result,"由种群「"+source.name+"」衍生建立");Revision++;
        }
        public static List<DarwinEntity> Members(string id)=>EntityRegistry.All.Where(EcologyQueries.Alive).Where(e=>e.GetComponent<PopulationBehavior>() is PopulationBehavior p&&p.Active&&p.GroupId==id).ToList();
        public static void Observe()
        {
            if(WorldAuthority.IsReplica||WorldRuntimeGate.Loading)return;
            var groups=EntityRegistry.All.Where(EcologyQueries.Alive).Select(e=>e.GetComponent<PopulationBehavior>()).Where(p=>p!=null&&p.Active&&!string.IsNullOrEmpty(p.GroupId)).GroupBy(p=>p.GroupId).ToArray();var seen=new HashSet<string>();
            foreach(var group in groups)
            {
                seen.Add(group.Key);var first=group.First();var entities=group.Select(p=>p.GetComponent<DarwinEntity>()).ToList();
                var record=Register(group.Key,first.Mode,(first.Leader??first).GetComponent<DarwinEntity>().DisplayName);
                int count=entities.Count;bool changed=count!=record.current;
                if(changed){int delta=count-record.current;if(record.samples.Count>0){record.increases+=Mathf.Max(0,delta);record.decreases+=Mathf.Max(0,-delta);Event(record,"成员数 "+record.current+" → "+count+"（含出生、死亡及迁移）");}record.current=count;Revision++;}
                record.lastSeen=Now;record.peak=Mathf.Max(record.peak,count);record.mode=first.Mode;
                if(changed||record.samples.Count==0||Now-record.samples[record.samples.Count-1].time>=PopulationArchiveSettings.Current.sampleGameSeconds)
                {
                    record.infants=entities.Count(e=>e.Genes.CurrentAge==AgeState.Infant);record.adults=entities.Count(e=>e.Genes.CurrentAge==AgeState.Adult);record.elders=count-record.infants-record.adults;record.lastLiving=count;
                    var genes=new Dictionary<string,PopulationGeneCount>();foreach(var entity in entities)
                    {
                        var active=new HashSet<string>(entity.Genes.Evaluation.Genes.Where(g=>g.IsActive).Select(g=>g.Definition.Id));
                        foreach(string id in entity.Genes.Genome.Genes.Select(g=>g.DefinitionId).Distinct()){if(!genes.TryGetValue(id,out var value))genes[id]=value=new PopulationGeneCount{id=id};value.carried++;if(active.Contains(id))value.expressed++;}
                    }
                    record.genes=genes.Values.OrderBy(g=>g.id).ToList();Sample(record,count);Revision++;
                }
            }
            foreach(var record in Records.Values.Where(r=>r.current>0&&!seen.Contains(r.id)).ToArray())
            {record.decreases+=record.current;record.current=0;Event(record,"种群灭绝或全部成员离开");Sample(record,0);Revision++;}
        }
        private static void Sample(PopulationRecord record,int count)
        {
            record.samples.Add(new PopulationSample{time=Now,members=count,infants=count==0?0:record.infants,adults=count==0?0:record.adults,elders=count==0?0:record.elders});
            if(record.samples.Count>PopulationArchiveSettings.Current.maximumSamples)
            {
                // ★ 适配：保留首尾并压缩中间采样，长期世界不会无限增长；时间跨度不因容量限制消失。
                var compact=new List<PopulationSample>{record.samples[0]};for(int i=2;i<record.samples.Count-1;i+=2)compact.Add(record.samples[i]);compact.Add(record.samples[record.samples.Count-1]);record.samples=compact;
            }
        }
        public static bool SetDisplay(string id,string color,bool visible,bool? syncEntityColor=null,float? rangeOpacity=null)
        {
            if(WorldAuthority.IsReplica||!WorldAuthority.CanEdit||Find(id) is not PopulationRecord record||!ColorUtility.TryParseHtmlString(color,out var parsed)||rangeOpacity.HasValue&&(!float.IsFinite(rangeOpacity.Value)||rangeOpacity<0||rangeOpacity>1))return false;
            record.color="#"+ColorUtility.ToHtmlStringRGB(parsed);record.visible=visible;if(syncEntityColor.HasValue)record.syncEntityColor=syncEntityColor.Value;if(rangeOpacity.HasValue)record.rangeOpacity=rangeOpacity.Value;Revision++;DisplayRevision++;return true;
        }
        public static float OpacityFor(string id)=>Find(id) is PopulationRecord record&&record.rangeOpacity>=0?record.rangeOpacity:GameplayTuning.Current.populationFillOpacity;
        public static bool TryColor(string id,out Color color){color=default;return Find(id) is PopulationRecord record&&!string.IsNullOrEmpty(record.color)&&ColorUtility.TryParseHtmlString(record.color,out color);}
        public static bool IsVisible(string id)=>Find(id)?.visible??true;
        public static PopulationArchiveState Capture(){if(WorldRuntimeGate.Ready&&!WorldAuthority.IsReplica)Observe();return JsonUtility.FromJson<PopulationArchiveState>(JsonUtility.ToJson(new PopulationArchiveState{groups=Records.Values.OrderBy(r=>r.id).ToList()}));}
        public static void Validate(PopulationArchiveState state)
        {
            if(state==null)return;if(state.version!=1||state.groups==null)throw new InvalidDataException("种群档案版本无效");var ids=new HashSet<string>();
            foreach(var r in state.groups)
            {
                if(r!=null&&(!float.IsFinite(r.rangeOpacity)||r.rangeOpacity!= -1&&(r.rangeOpacity<0||r.rangeOpacity>1)))throw new InvalidDataException("种群范围不透明度无效");
                if(r==null||!Guid.TryParseExact(r.id,"N",out _)||!ids.Add(r.id)||string.IsNullOrWhiteSpace(r.name)||r.current<0||r.lastLiving<0||r.peak<r.current||!float.IsFinite(r.firstSeen)||r.firstSeen<0||!float.IsFinite(r.lastSeen)||r.lastSeen<r.firstSeen||r.samples==null||r.events==null||r.genes==null||!string.IsNullOrEmpty(r.color)&&!ColorUtility.TryParseHtmlString(r.color,out _))throw new InvalidDataException("种群档案内容无效");
                float last=-1;foreach(var s in r.samples){if(s==null||!float.IsFinite(s.time)||s.time<last||s.time<0||s.members<0||s.infants<0||s.adults<0||s.elders<0||s.infants+s.adults+s.elders!=s.members)throw new InvalidDataException("种群历史采样无效");last=s.time;}
                if(r.events.Any(e=>e==null||!float.IsFinite(e.time)||e.time<0||string.IsNullOrWhiteSpace(e.text))||r.genes.Any(g=>g==null||string.IsNullOrWhiteSpace(g.id)||g.carried<0||g.expressed<0||g.expressed>g.carried||g.carried>r.lastLiving))throw new InvalidDataException("种群事件或基因计数无效");
            }
            var byId=state.groups.ToDictionary(r=>r.id);foreach(var record in state.groups){var path=new HashSet<string>{record.id};var current=record;while(!string.IsNullOrEmpty(current.parentId)){if(!path.Add(current.parentId)||!byId.TryGetValue(current.parentId,out current))throw new InvalidDataException("种群谱系有循环或缺失来源");}}
        }
        public static void Restore(PopulationArchiveState state)
        {
            Validate(state);Records.Clear();if(state!=null)foreach(var record in JsonUtility.FromJson<PopulationArchiveState>(JsonUtility.ToJson(state)).groups)Records.Add(record.id,record);Revision++;DisplayRevision++;
        }
        public static void Clear(){Records.Clear();Revision++;DisplayRevision++;}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)] private static void Reset()=>Clear();
    }
    // ★ 新增：记录不依赖第二页或详情窗口是否打开，暂停不生成重复历史点。
    public sealed class PopulationArchiveObserver:MonoBehaviour
    {
        private float _next;
        public static void Ensure(){if(UnityEngine.Object.FindFirstObjectByType<PopulationArchiveObserver>()==null)new GameObject("种群档案记录").AddComponent<PopulationArchiveObserver>();}
        private void Update(){if(!WorldRuntimeGate.Ready||WorldRuntimeGate.Loading||Time.unscaledTime<_next)return;_next=Time.unscaledTime+PopulationArchiveSettings.Current.refreshSeconds;PopulationArchive.Observe();}
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using DarwinPark.Core;
using DarwinPark.Entities.Stats;
using UnityEngine;
namespace DarwinPark.Entities.Ecology
{
    public enum PopulationCommand {None,Hunt,Gather,Rally,Defend}
    // ★ 新增：群体消息只在同一持久化群体内直接分发；没有持有死亡实体的全局静态事件。
    [DefaultExecutionOrder(-190)]
    public sealed class PopulationBehavior : MonoBehaviour
    {
        private static readonly List<PopulationBehavior> Members=new List<PopulationBehavior>();
        private static long _serial;
        internal static IReadOnlyList<PopulationBehavior> RegisteredMembers=>Members;
        private EntityGeneController _genes;private DarwinEntity _entity;private EcologySettings _settings;
        private EntityStats _stats;
        private string _mode;private float _scan,_manualRemaining,_duelRemaining;
        public string GroupId {get;private set;}="";
        public long JoinOrder {get;private set;}
        public bool LeaderFlag {get;private set;}
        public PopulationCommand Command {get;private set;}
        public float CommandRemaining {get;private set;}
        public Vector3 CommandPointLocal {get;private set;}
        public DarwinEntity Target {get;private set;}
        public float DuelRemaining=>_duelRemaining;
        // ★ 修复（防Bug回归）：孵化限制的是行动而非血缘，卵必须保留同群标记，避免下一帧退群、被士兵误伤或读档后随机入群。
        private Genetics.GenomeEvaluation _populationEvaluation;
        private Genetics.GeneEvaluation _populationGene;
        private Genetics.GeneEvaluation PopulationGene
        {
            get
            {
                // ★ 修复（防Bug回归）：一次表达只选一次种群基因，属性读取不能不断分配 LINQ 迭代器和排序数组。
                if(!ReferenceEquals(_populationEvaluation,_genes.Evaluation))
                {
                    _populationEvaluation=_genes.Evaluation;_populationGene=null;
                    if(_populationEvaluation!=null)foreach(var gene in _populationEvaluation.Genes)
                        if(gene.IsActive&&gene.Definition.Id==_settings.populationGene&&(_populationGene==null||gene.EffectiveStrength>_populationGene.EffectiveStrength))_populationGene=gene;
                    PopulationGroupIndex.Invalidate();
                }
                return _populationGene;
            }
        }
        public string Mode=>PopulationGene?.State?.StateId??"";
        // ★ 适配：缓存属性组件但实时读取生命值，同帧死亡立即生效，不用每次关系查询都查找相同组件。
        private bool Alive {get{if(_stats==null)_stats=GetComponent<EntityStats>();return _entity!=null&&_entity.isActiveAndEnabled&&_stats!=null&&_stats.TryGet("health",out float hp)&&hp>0;}}
        public bool Active=>PopulationGene!=null&&Alive&&
            (GetComponent<EggIncubation>()?.Incubating!=true||
             Mode==_settings.antState&&!string.IsNullOrEmpty(GroupId)&&GetComponent<AntColonyMember>()?.Role is AntRole role&&role!=AntRole.None);
        // ★ 适配：蚁群领袖由王后分工确定，狼群仍沿用原有决斗与加入顺序。
        public PopulationBehavior Leader=>PopulationGroupIndex.Leader(this);
        public bool IsLeader=>Active&&Leader==this;
        public IEnumerable<PopulationBehavior> GroupMembers=>PopulationGroupIndex.Members(this);
        public int MemberCount=>GroupMembers.Count();
        public float Aura=>Mathf.Max(_settings.arrivalDistance,_genes.GetAttribute("leadership_aura"));
        public bool InAura=>Leader is PopulationBehavior leader&&EcologyQueries.Distance(transform.position,leader.transform.position)<=leader.Aura;
        public float MoveMultiplier=>!Active?1:Mode==_settings.antState?_settings.antBodyMultiplier*(InAura?1+_settings.antSpeedBonus*_genes.GetAttribute("coordination"):1):1;
        public float AttackMultiplier
        {
            get
            {
                if(!Active)return 1;if(Mode==_settings.antState)return _settings.antBodyMultiplier;if(!InAura)return 1;
                // ★ 适配：狼群协同由真实附近同群成员贡献，独狼不凭空获得群攻加成，贡献上限由配置控制。
                int helpers=Mathf.Min(_settings.maximumCoordinators,GroupMembers.Count(m=>m!=this&&EcologyQueries.Distance(transform.position,m.transform.position)<=Aura));
                return 1+_settings.wolfAttackBonus*_genes.GetAttribute("coordination")*helpers;
            }
        }
        private void Awake(){_genes=GetComponent<EntityGeneController>();_entity=GetComponent<DarwinEntity>();_settings=EcologySettings.Load();EcologyIdentity.Ensure(gameObject);_genes.OnEvaluationChanged+=OnGenesChanged;}
        // ★ 修复（防Bug回归）：表达变更必须立即使关系缓存失效，不能等下一帧才移除同帧禁用/变为其他模式的成员。
        private void OnGenesChanged(Genetics.GenomeEvaluation evaluation){_populationEvaluation=null;_populationGene=null;PopulationGroupIndex.Invalidate();}
        private void OnDestroy(){if(_genes!=null)_genes.OnEvaluationChanged-=OnGenesChanged;}
        private void OnDisable(){Members.Remove(this);PopulationGroupIndex.Invalidate();}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void Reset(){Members.Clear();_serial=0;}
        private void Update(){Advance(ServiceLocator.TryGet<SimulationClock>(out var clock)?clock.GameDeltaTime:Time.deltaTime);}
        public void Advance(float dt)
        {
            // ★ 适配：副本保留读档的身份与分工，只由房主计算成员变化。
            if(WorldAuthority.IsReplica)return;
            if(!Active){GetComponent<AntColonyMember>()?.Suspend();if(Members.Remove(this)||!string.IsNullOrEmpty(GroupId))PopulationGroupIndex.Invalidate();GroupId="";LeaderFlag=false;Command=PopulationCommand.None;return;}
            if(dt<=0)return;
            string previousGroup=_mode!=null&&_mode!=Mode?GroupId:null;
            if(_mode!=null&&_mode!=Mode){GetComponent<AntColonyMember>()?.Suspend();Members.Remove(this);PopulationGroupIndex.Invalidate();GroupId="";LeaderFlag=false;Command=PopulationCommand.None;}
            _mode=Mode;EnsureMembership();
            // ★ 适配：种群状态改变后独立成群也记录真实来源；加入既有种群不会改写其谱系。
            if(!string.IsNullOrEmpty(previousGroup)&&previousGroup!=GroupId&&LeaderFlag)PopulationArchive.RecordFounding(previousGroup,GroupId,Mode,_entity.DisplayName,"种群状态变化形成新种群");
            if(GetComponent<EggIncubation>()?.Incubating==true)return;
            // ★ 适配：固定分工独立推进，旧全群采集与决斗不能覆盖蚁群角色。
            if(Mode==_settings.antState){AntColonyMember.Ensure(this).Advance(dt);return;}
            _duelRemaining=Mathf.Max(0,_duelRemaining-dt);_manualRemaining=Mathf.Max(0,_manualRemaining-dt);
            CommandRemaining=Mathf.Max(0,CommandRemaining-dt);
            if(CommandRemaining<=0||Command==PopulationCommand.Hunt&&(!EcologyQueries.Alive(Target)||SameGroup(Target))){Command=PopulationCommand.None;Target=null;}
            var leader=Leader;if(leader!=null&&!leader.LeaderFlag)leader.LeaderFlag=true;
            if(!IsLeader&&leader!=null&&_duelRemaining<=0&&leader._duelRemaining<=0&&EcologyQueries.Distance(transform.position,leader.transform.position)<=_settings.arrivalDistance&&Score()>leader.Score()*_settings.duelAdvantage)
                ChallengeLeadership(out _);
            _scan-=dt;
            if(IsLeader&&_scan<=0&&_manualRemaining<=0){_scan=_settings.scanInterval;AutoCommand();}
            if(Mode==_settings.antState&&Command==PopulationCommand.Gather&&EcologyQueries.Distance(transform.position,EcologyQueries.ToWorld(CommandPointLocal))<=_settings.arrivalDistance&&Planet.PlanetOreSystem.Instance!=null)
            {
                float auraBonus=InAura?1+_settings.antGatherBonus:1;
                float extracted=Planet.PlanetOreSystem.Instance.ConsumeOre(transform.position,_settings.antGatherRate*Mathf.Max(0,_genes.GetAttribute("coordination"))*auraBonus*dt);
                _entity.GetComponent<EntityStats>().Feed(extracted);
            }
        }
        public void EnsureMembership()
        {
            if(!Active)return;
            if(string.IsNullOrEmpty(GroupId))
            {
                var neighbor=Members.Where(m=>m!=null&&m!=this&&m.Active&&m.Mode==Mode&&EcologyQueries.Distance(transform.position,m.transform.position)<=_settings.joinRadius)
                    .OrderBy(m=>m.JoinOrder).FirstOrDefault();
                GroupId=neighbor?.GroupId??Guid.NewGuid().ToString("N");JoinOrder=++_serial;LeaderFlag=neighbor==null;
                // ★ 新增：新建种群记录真实成立时间；读档期间不把首次观察误写成出生。
                if(neighbor==null&&WorldRuntimeGate.Ready&&!WorldRuntimeGate.Loading&&!WorldAuthority.IsReplica)PopulationArchive.Register(GroupId,Mode,_entity.DisplayName,true);
            }
            _serial=Math.Max(_serial,JoinOrder);if(!Members.Contains(this)){Members.Add(this);PopulationGroupIndex.Invalidate();}
        }
        // ★ 适配：出生继承和新王后建群通过此接口写入持久标识，不重新按距离随机入群。
        public void JoinColony(string group,bool queen)
        {PopulationGroupIndex.Invalidate();GroupId=group;JoinOrder=++_serial;LeaderFlag=queen;Command=PopulationCommand.None;Target=null;CommandRemaining=0;EnsureMembership();}
        public bool SameGroup(DarwinEntity other)=>Active&&other!=null&&other.GetComponent<PopulationBehavior>() is PopulationBehavior pop&&pop.Active&&pop.Mode==Mode&&!string.IsNullOrEmpty(GroupId)&&pop.GroupId==GroupId;
        private float Score(){_entity.GetComponent<EntityStats>().TryGet("health",out var health);return _genes.GetAttribute("attack")+health*_settings.duelHealthWeight;}
        public bool ChallengeLeadership(out string message)
        {
            // ★ 修复（防Bug回归）：王后身份由出生分工确定，任何调用入口都不能用狼群决斗改写蚁群领袖，隐藏按钮不足以保证此约束。
            if(Mode==_settings.antState){message="蚁群王后不能被挑战";return false;}
            EnsureMembership();var leader=Leader;
            if(!Active||leader==null||leader==this){message="当前没有可挑战的领袖";return false;}
            if(_duelRemaining>0||leader._duelRemaining>0){message="决斗仍在冷却";return false;}
            if(EcologyQueries.Distance(transform.position,leader.transform.position)>_settings.joinRadius){message="请先靠近领袖";return false;}
            _duelRemaining=leader._duelRemaining=_settings.duelCooldown;
            bool won=Score()>leader.Score()*_settings.duelAdvantage;
            if(won){foreach(var member in GroupMembers)member.LeaderFlag=false;LeaderFlag=true;PopulationGroupIndex.Invalidate();}
            message=won?"决斗获胜，成为领袖":"决斗失败，原领袖留任";return won;
        }
        public bool Issue(PopulationCommand command,DarwinEntity target,Vector3 point,bool manual,out string message)
        {
            EnsureMembership();if(!IsLeader){message="只有领袖可以下令";return false;}
            // ★ 适配：领袖选择目标也服从体型判定，成员执行时仍须独立检查自己的体型。
            if(command==PopulationCommand.Hunt&&(!EcologyQueries.Alive(target)||SameGroup(target)||!PredationSizePolicy.Allows(_genes,target)||EcologyQueries.Distance(transform.position,target.transform.position)>_settings.maximumCommandRange))
            {message="需要范围内的非同群存活猎物";return false;}
            foreach(var member in GroupMembers)
            {
                member.Command=command;member.Target=target;member.CommandPointLocal=EcologyQueries.ToLocal(point);member.CommandRemaining=_settings.commandLifetime;
                member._manualRemaining=manual?_settings.commandLifetime:0;
            }
            message="已下令："+CommandLabel(command);return true;
        }
        private void AutoCommand()
        {
            // ★ 适配：自动群猎尊重食性，手动下令仍可指挥防御攻击；食腐/幼年寄生不会因狼群模式被迫捕猎。
            if(Mode==_settings.wolfState&&NutritionTransfer.CanHuntForFood(_genes))
            {
                var prey=EntityRegistry.All.Where(e=>EcologyQueries.Alive(e)&&e!=_entity&&!SameGroup(e)&&NutritionTransfer.FoodTargetAllowed(_genes,e)&&PredationSizePolicy.Allows(_genes,e)&&EcologyMotion.Detectable(e,transform.position,_genes.GetAttribute("senseRange"),_entity))
                    .OrderBy(e=>(e.transform.position-transform.position).sqrMagnitude).FirstOrDefault();
                if(prey!=null){Issue(PopulationCommand.Hunt,prey,prey.transform.position,false,out _);return;}
            }
            if(Mode==_settings.antState&&FindOre(out var ore)){Issue(PopulationCommand.Gather,null,ore,false,out _);return;}
            var territory=GetComponent<TerritoryBehavior>();Issue(PopulationCommand.Rally,null,territory!=null?territory.Center:transform.position,false,out _);
        }
        public bool FindOre(out Vector3 point)
        {
            point=transform.position;var ore=Planet.PlanetOreSystem.Instance;if(ore==null)return false;
            float best=ore.GetOreAmount(point);Vector3 up=EcologyQueries.Up(point),axis=Vector3.Cross(up,Vector3.forward).normalized;
            if(axis.sqrMagnitude<.5f)axis=Vector3.Cross(up,Vector3.right).normalized;
            for(int i=0;i<_settings.oreSearchSamples;i++)
            {
                Vector3 candidate=EcologyQueries.Surface(transform.position+Quaternion.AngleAxis(i*137.50776f,up)*axis*Aura*Mathf.Sqrt((i+1f)/_settings.oreSearchSamples));
                float value=ore.GetOreAmount(candidate);if(value>best){best=value;point=candidate;}
            }
            return best>0;
        }
        public bool Destination(out Vector3 point,out DarwinEntity target)
        {
            point=transform.position;target=null;if(!Active||Command==PopulationCommand.None||CommandRemaining<=0)return false;
            if(Command==PopulationCommand.Hunt)
            {
                if(_manualRemaining<=0&&!NutritionTransfer.FoodTargetAllowed(_genes,Target))return false;
                if(!EcologyQueries.Alive(Target)||SameGroup(Target)||!PredationSizePolicy.Allows(_genes,Target))return false;
                target=Target;point=Target.transform.position;
                var peers=GroupMembers.OrderBy(m=>m.JoinOrder).ToList();int index=Mathf.Max(0,peers.IndexOf(this));
                if(EcologyQueries.Distance(transform.position,point)>_settings.formationSpacing*2)
                {
                    Vector3 up=EcologyQueries.Up(point),side=Vector3.Cross(up,transform.position-point).normalized;
                    point=EcologyQueries.Surface(point+Quaternion.AngleAxis(index*360f/Mathf.Max(1,peers.Count),up)*side*_settings.formationSpacing);
                }
                return true;
            }
            point=EcologyQueries.ToWorld(CommandPointLocal);return true;
        }
        public void ShareReward(float amount)
        {
            var others=GroupMembers.Where(m=>m!=this&&EcologyQueries.Distance(transform.position,m.transform.position)<=Aura).ToArray();
            float shared=others.Length>0?amount*Mathf.Clamp01(_settings.shareFraction):0;
            _entity.GetComponent<EntityStats>().Feed(amount-shared);
            foreach(var member in others)member._entity.GetComponent<EntityStats>().Feed(shared/others.Length);
        }
        public void Restore(EcologySaveState state)
        {
            Members.Remove(this);PopulationGroupIndex.Invalidate();GroupId=state.groupId??"";JoinOrder=state.joinOrder;LeaderFlag=state.leader;_mode=state.mode;
            Command=state.command;CommandRemaining=state.commandRemaining;CommandPointLocal=state.commandPoint;_manualRemaining=state.manualRemaining;_duelRemaining=state.duelRemaining;
            EnsureMembership();
        }
        public float ManualRemaining=>_manualRemaining;
        public void RestoreTarget(DarwinEntity target){Target=target;if(Command==PopulationCommand.Hunt&&!EcologyQueries.Alive(target))Command=PopulationCommand.None;}
        public static string CommandLabel(PopulationCommand command)=>command switch {PopulationCommand.Hunt=>"捕猎",PopulationCommand.Gather=>"采集",PopulationCommand.Rally=>"集结",PopulationCommand.Defend=>"守卫",_=>"自由活动"};
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    // ★ 修复（防Bug回归）：移动属性会高频询问领袖和王后，不能每次排序全世界成员；关系仅在成员、表达或角色变化时重建。
    public static class PopulationGroupIndex
    {
        private sealed class Group
        {
            public readonly List<PopulationBehavior> members=new List<PopulationBehavior>();
            public PopulationBehavior leader;
            public AntColonyMember queen;
        }
        private static readonly Dictionary<(string,string),Group> Groups=new Dictionary<(string,string),Group>();
        private static readonly List<PopulationBehavior> Empty=new List<PopulationBehavior>();
        public static long BuildCount {get;private set;}
        // ★ 适配：资源归属索引同步成员变化，不能用上一帧的“已灭绝”结果回收仍有主人的补给。
        public static long Revision {get;private set;}
        public static void Invalidate(){Groups.Clear();Revision++;}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void Reset(){Groups.Clear();BuildCount=0;Revision=0;}
        private static bool Earlier(PopulationBehavior a,PopulationBehavior b)=>b==null||a.JoinOrder<b.JoinOrder||a.JoinOrder==b.JoinOrder&&string.CompareOrdinal(EcologyIdentity.Of(a.GetComponent<DarwinEntity>()),EcologyIdentity.Of(b.GetComponent<DarwinEntity>()))<0;
        private static Group Get(PopulationBehavior owner)
        {
            var key=(owner.GroupId,owner.Mode);
            if(Groups.TryGetValue(key,out var group))return group;
            group=new Group();BuildCount++;
            foreach(var member in PopulationBehavior.RegisteredMembers)
            {
                if(member==null||member.GroupId!=key.Item1||member.Mode!=key.Item2||!member.Active)continue;
                group.members.Add(member);
                if(group.leader==null||member.LeaderFlag&&!group.leader.LeaderFlag||member.LeaderFlag==group.leader.LeaderFlag&&Earlier(member,group.leader))group.leader=member;
                var ant=member.GetComponent<AntColonyMember>();
                if(key.Item2==EcologySettings.Load().antState&&ant!=null&&ant.Role==AntRole.Queen&&Earlier(member,group.queen!=null?group.queen.Population:null))group.queen=ant;
            }
            Groups[key]=group;return group;
        }
        public static IEnumerable<PopulationBehavior> Members(PopulationBehavior owner)
        {
            if(string.IsNullOrEmpty(owner.GroupId))return Empty;
            return AliveMembers(Get(owner).members,owner.GroupId,owner.Mode);
        }
        private static IEnumerable<PopulationBehavior> AliveMembers(List<PopulationBehavior> members,string id,string mode)
        {foreach(var member in members)if(member!=null&&member.GroupId==id&&member.Mode==mode&&member.Active)yield return member;}
        public static AntColonyMember Queen(PopulationBehavior owner)
        {
            if(string.IsNullOrEmpty(owner.GroupId)||owner.Mode!=EcologySettings.Load().antState)return null;
            var group=Get(owner);
            if(group.queen!=null&&(!group.queen.Active||group.queen.Role!=AntRole.Queen)){Invalidate();group=Get(owner);}
            return group.queen;
        }
        public static PopulationBehavior Leader(PopulationBehavior owner)
        {
            if(string.IsNullOrEmpty(owner.GroupId))return null;
            var group=Get(owner);
            if(group.leader!=null&&!group.leader.Active){Invalidate();group=Get(owner);}
            return owner.Mode==EcologySettings.Load().antState&&group.queen!=null&&group.queen.Active?group.queen.Population:group.leader;
        }
    }
}

using DarwinPark.Entities.Stats;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    // ★ 新增：捕食比较实际 size 数值；选目标和最终咬合都检查，猎物长大后旧目标也不能绕过限制。
    public static class PredationSizePolicy
    {
        public static bool Allows(EntityGeneController predator,DarwinEntity prey)
        {
            if(predator==null||prey==null||predator.gameObject==prey.gameObject)return false;
            var settings=EcologyBalanceSettings.Current;
            var a=predator.GetComponent<EntityStats>();var b=prey.GetComponent<EntityStats>();
            if(a==null||b==null||!a.TryGet(settings.sizeAttribute,out float own)||!b.TryGet(settings.sizeAttribute,out float other))return false;
            return AllowsValues(own,other,settings);
        }
        public static bool AllowsValues(float predatorSize,float preySize,EcologyBalanceSettings settings=null)
        {
            settings=settings??EcologyBalanceSettings.Current;
            if(float.IsNaN(predatorSize)||float.IsInfinity(predatorSize)||float.IsNaN(preySize)||float.IsInfinity(preySize)||predatorSize<settings.minimumSize||preySize<settings.minimumSize)return false;
            return preySize<=predatorSize*settings.maximumPreySizeRatio;
        }
    }
}

using System;
using System.Linq;
using DarwinPark.Core;
using UnityEngine;

namespace DarwinPark.Entities.Ecology
{
    public enum RtsOrderKind { Move,Attack,Collect,Guard,Stop }
    [Serializable] public sealed class RtsOrderSave
    {public bool active;public RtsOrderKind kind;public Vector3 point;public string target;}
    // ★ 新增：RTS只改变行动意图，实际移动、战斗、搬运仍使用原有基因和体型判定；命令随世界保存。
    public sealed class RtsOrderController : MonoBehaviour
    {
        public float arrivalDistance=2;
        public RtsOrderSave State {get;private set;}=new RtsOrderSave();
        private EntityGeneController _genes;
        private void Awake(){_genes=GetComponent<EntityGeneController>();}
        public static RtsOrderController Ensure(DarwinEntity entity)=>entity.GetComponent<RtsOrderController>()??entity.gameObject.AddComponent<RtsOrderController>();
        public static bool Supports(DarwinEntity entity,RtsOrderKind kind)
        {
            if(!EcologyQueries.Alive(entity)||EcologyMotion.Immobilized(entity.Genes))return false;
            if(kind==RtsOrderKind.Stop)return true;
            if(entity.Genes.GetAttribute("moveSpeed")<=0)return false;
            if(kind==RtsOrderKind.Attack)return entity.Genes.GetAttribute("attack")>0;
            if(kind==RtsOrderKind.Collect)return entity.GetComponent<AntColonyMember>() is AntColonyMember ant&&ant.Active&&!ant.Young&&ant.Role==AntRole.Worker;
            return true;
        }
        public bool Issue(RtsOrderKind kind,Vector3 worldPoint,DarwinEntity target=null,ColonyResource resource=null)
        {
            var entity=GetComponent<DarwinEntity>();if(!Supports(entity,kind))return false;
            if(kind==RtsOrderKind.Attack&&(!EcologyQueries.Alive(target)||!EcologyMotion.CanHunt(_genes,target)))return false;
            if(kind==RtsOrderKind.Collect)
            {
                var worker=GetComponent<AntColonyMember>();
                // ★ 适配：RTS与工匠自主领取使用同一尸体资格，允许收集自然死亡尸体。
                if(resource!=null&&ColonyCorpseAccess.Available(resource,worker))
                {AntColonyWorker.Release(worker);worker.State.resourceTarget=resource.State.id;worker.State.scan=1;}
                else if(target!=null&&!worker.Population.SameGroup(target)&&target.Genes.GetAttribute("moveSpeed")<=0)
                {AntColonyWorker.Release(worker);worker.State.livingTarget=EcologyIdentity.Of(target);worker.State.scan=1;}
                else return false;
            }
            State=new RtsOrderSave{active=true,kind=kind,point=EcologyQueries.ToLocal(worldPoint),target=target!=null?EcologyIdentity.Of(target):resource?.State.id};return true;
        }
        public bool Destination(out Vector3 point,out DarwinEntity target)
        {
            point=transform.position;target=null;if(!State.active||WorldAuthority.IsReplica)return false;
            if(State.kind==RtsOrderKind.Stop)return true;
            if(!Supports(GetComponent<DarwinEntity>(),State.kind)){State.active=false;return false;}
            if(State.kind==RtsOrderKind.Collect)
            {var worker=GetComponent<AntColonyMember>();if(ColonyResource.Find(State.target)==null&&EcologyIdentity.Find(State.target)==null&&string.IsNullOrEmpty(worker.State.carriedResource)&&string.IsNullOrEmpty(worker.State.carriedLiving))State.active=false;return false;}
            point=EcologyQueries.ToWorld(State.point);
            if(State.kind==RtsOrderKind.Attack)
            {target=EcologyIdentity.Find(State.target);if(!EcologyQueries.Alive(target)||!EcologyMotion.CanHunt(_genes,target)){State.active=false;target=null;return false;}point=target.transform.position;return true;}
            if(State.kind==RtsOrderKind.Guard&&_genes.GetAttribute("attack")>0)
            {
                float range=_genes.GetAttribute("senseRange");
                var guardPoint=point;target=EntityRegistry.All.FirstOrDefault(e=>e!=GetComponent<DarwinEntity>()&&(e.transform.position-guardPoint).sqrMagnitude<=range*range&&EcologyQueries.Alive(e)&&EcologyMotion.CanHunt(_genes,e));
                if(target!=null)point=target.transform.position;
            }
            if(State.kind==RtsOrderKind.Move&&EcologyQueries.Distance(transform.position,point)<=arrivalDistance){State.active=false;return true;}
            return true;
        }
        public RtsOrderSave Capture()=>JsonUtility.FromJson<RtsOrderSave>(JsonUtility.ToJson(State));
        public void Restore(RtsOrderSave state){if(state!=null)State=JsonUtility.FromJson<RtsOrderSave>(JsonUtility.ToJson(state));}
    }
}

using DarwinPark.Core;
using UnityEngine;
namespace DarwinPark.Entities.Ecology
{
    // ★ 新增：领地中心以星球本地坐标保存；遇袭脱离边界，安全期后在新位置定居，不再返回旧领地。
    [DefaultExecutionOrder(-200)]
    public sealed class TerritoryBehavior : MonoBehaviour
    {
        public Vector3 CenterLocal {get;private set;}
        public bool HasCenter {get;private set;}
        public float EvictionRemaining {get;private set;}
        public Vector3 ThreatLocal {get;private set;}
        private EntityGeneController _genes;private EntityCombat _combat;private EcologySettings _settings;
        private float _patrolTimer;private Vector3 _destination;
        public bool Active=>EcologyQueries.Active(_genes,_settings.territoryGene)!=null||EcologyQueries.Active(_genes,_settings.populationGene)!=null;
        public Vector3 Center=>EcologyQueries.ToWorld(CenterLocal);
        public float Radius=>Mathf.Max(_settings.arrivalDistance,_genes.GetAttribute("territory_radius"));
        public float Defense=>Active&&EvictionRemaining<=0&&AllowsTarget(transform.position)?_genes.GetAttribute("defend_bonus"):0;
        private void Awake(){_genes=GetComponent<EntityGeneController>();_settings=EcologySettings.Load();}
        private void OnEnable(){_combat=EntityCombat.Ensure(gameObject);_combat.Attacked+=OnAttacked;}
        private void OnDisable(){if(_combat!=null)_combat.Attacked-=OnAttacked;}
        private void Update(){float dt=ServiceLocator.TryGet<SimulationClock>(out var clock)?clock.GameDeltaTime:Time.deltaTime;Advance(dt);}
        public void Advance(float dt)
        {
            if(!Active||dt<=0)return;
            // ★ 适配：巡逻休息期独立保存，不靠抵达刷新巡逻点维持无限巡逻。
            PatrolRhythm.Ensure(gameObject).Advance(dt);
            if(!HasCenter){CenterLocal=EcologyQueries.ToLocal(transform.position);HasCenter=true;}
            if(EvictionRemaining>0)
            {
                EvictionRemaining=Mathf.Max(0,EvictionRemaining-dt);
                if(EvictionRemaining<=0){CenterLocal=EcologyQueries.ToLocal(transform.position);_patrolTimer=0;}
            }
            _patrolTimer-=dt;
        }
        private void OnAttacked(DarwinEntity attacker,float damage)
        {
            if(!Active||attacker==null||damage<=0)return;
            // ★ 修复（防Bug回归）：可反击的实体不再一律驱逐；无法对抗时保留原逃离逻辑。
            if(CombatIntent.CanRetaliate(_genes,attacker))return;
            ThreatLocal=EcologyQueries.ToLocal(attacker.transform.position);EvictionRemaining=_settings.settleDelay;
        }
        public bool AllowsTarget(Vector3 position)
        {
            // ★ 适配：种群成员共享活动区，普通领地仍使用自身领地圆。
            if(!Active||EvictionRemaining>0)return true;
            var population=GetComponent<PopulationBehavior>();
            return population!=null&&population.Active?ColonyActivityRange.Contains(population,position):EcologyQueries.Distance(Center,position)<=Radius;
        }
        public bool Destination(out Vector3 point,out float speed)
        {
            point=transform.position;speed=1;if(!Active)return false;
            if(!HasCenter){CenterLocal=EcologyQueries.ToLocal(transform.position);HasCenter=true;}
            if(EvictionRemaining>0)
            {
                Vector3 away=Vector3.ProjectOnPlane(transform.position-EcologyQueries.ToWorld(ThreatLocal),EcologyQueries.Up(transform.position));
                if(away.sqrMagnitude<.01f)away=Vector3.Cross(EcologyQueries.Up(transform.position),Vector3.right);
                point=EcologyQueries.Surface(transform.position+away.normalized*_settings.fleeDistance);speed=_settings.fleeSpeedMultiplier;return true;
            }
            if(!AllowsTarget(transform.position)){var pop=GetComponent<PopulationBehavior>();point=pop!=null&&pop.Active?ColonyActivityRange.NearestCenter(pop,transform.position):Center;return true;}
            // ★ 修复（防Bug回归）：领地只约束边界与驱逐，不能永远返回巡逻意图并阻断饥饿捕猎。
            return false;
        }
        // ★ 适配：仅由注册表中 TerritoryPatrol 行为调用，保留基因状态与独立实体状态。
        public bool PatrolDestination(out Vector3 point)
        {
            point=transform.position;if(!Active||!PatrolRhythm.Allows(_genes))return false;
            if(!HasCenter){CenterLocal=EcologyQueries.ToLocal(transform.position);HasCenter=true;}
            if(_patrolTimer<=0||EcologyQueries.Distance(transform.position,EcologyQueries.ToWorld(_destination))<_settings.arrivalDistance)
            {
                var tangent=Vector3.ProjectOnPlane(Random.onUnitSphere,EcologyQueries.Up(Center));
                _destination=EcologyQueries.ToLocal(EcologyQueries.Surface(Center+tangent.normalized*Random.Range(0,Radius)));_patrolTimer=_settings.patrolInterval;
            }
            point=EcologyQueries.ToWorld(_destination);return true;
        }
        public void Restore(Vector3 center,bool hasCenter,float eviction,Vector3 threat)
        {CenterLocal=center;HasCenter=hasCenter;EvictionRemaining=eviction;ThreatLocal=threat;_patrolTimer=0;}
    }
}

using DarwinPark.Core;
using DarwinPark.Entities.Ecology;
using UnityEngine;

namespace DarwinPark.Entities
{
    // ★ 修复（防Bug回归）：仅扩展攻击选择框，不改变物理碰撞体；扩大球形扫掠会先碰地面，让近身实体反而无法选中。
    public static class EntityAttackAim
    {
        public static DarwinEntity Pick(GameObject self,Ray ray,float distance,float radius=0)
        {
            DarwinEntity best=null;float nearest=distance;
            foreach(var entity in EntityRegistry.All)
            {
                if(entity==null||entity.gameObject==self||!EcologyQueries.Alive(entity))continue;
                foreach(var collider in entity.GetComponentsInChildren<Collider>())
                {
                    if(!collider.enabled||collider.isTrigger||!collider.gameObject.activeInHierarchy)continue;
                    // ★ 修复（防Bug回归）：相机落在扩大的选择框内时，朝反方向也会相交；先排除准星后方实体。
                    if(Vector3.Dot(collider.bounds.center-ray.origin,ray.direction)<=0)continue;
                    var bounds=collider.bounds;
                    bounds.extents=bounds.extents*GameplayTuning.Current.manualHitboxScale+Vector3.one*Mathf.Max(0,radius);
                    if(!bounds.IntersectRay(ray,out float along)||along>nearest)continue;
                    // 对真实表面检查视线，仍禁止穿过地形、墙壁或其他实体攻击。
                    Vector3 point=collider.ClosestPoint(ray.GetPoint(Mathf.Max(0,along)));
                    Vector3 toward=point-ray.origin;bool blocked=false;
                    if(toward.sqrMagnitude>.0001f)foreach(var hit in Physics.RaycastAll(ray.origin,toward.normalized,toward.magnitude,~0,QueryTriggerInteraction.Ignore))
                    {
                        var owner=hit.collider.GetComponentInParent<DarwinEntity>();
                        if(owner==entity||owner!=null&&owner.gameObject==self)continue;
                        blocked=true;break;
                    }
                    if(blocked)continue;nearest=along;best=entity;
                }
            }
            return best;
        }
    }
}

using DarwinPark.Core;
using DarwinPark.Entities.Logic;
using DarwinPark.Entities.Stats;
using DarwinPark.Genetics;
using DarwinPark.Genetics.Mutation;
using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Entities
{
    // ★ 核心修复：新增实体自带生命阶段枚举
    public enum AgeState { Infant, Adult, Elder }

    public class EntityGeneController : MonoBehaviour
    {
        public Genome Genome = new();
        public GenomeEvaluation Evaluation { get; private set; }
        public int LogicRevision {get;private set;}
        public event Action<GenomeEvaluation> OnEvaluationChanged;

        [Header("成长设置")]
        public float growthInterval = 5f;
        public float mutationChance = 0.3f;
        [HideInInspector] public bool IsGestating = false;

        [Header("环境选择压力（由 EntityEnvironmentHazard 写入）")]
        [HideInInspector] public float EnvironmentGeneSuppression = 0f;
        [HideInInspector] public float EnvironmentMutationChance = 0f;
        [HideInInspector] public string EnvironmentGeneId = "gene_environment";
        [HideInInspector] public float EnvironmentAdaptationTarget = -1f;

        // ★ 核心修复：新增 CurrentAge 属性，供繁殖和生长逻辑调用
        public AgeState CurrentAge { get; set; } = AgeState.Infant;

        private Dictionary<GeneInstance, IGeneLogic> _activeLogics = new();
        private readonly List<IGeneLogic> _simulationLogics=new List<IGeneLogic>();
        private bool _isRecalculating = false;
        private EntityLifeCycle _life;private Ecology.CombatIntent _combat;private Ecology.EntityStateController _state;
        private int _mutatedStages;
        public int StageMutationChecks {get;private set;}
        // ★ 适配：恢复已抽过的阶段，读档不能重抽出生/成年变异。
        public int MutatedStageMask=>_mutatedStages;
        public void RestoreStageState(AgeState age,int mask,int checks){CurrentAge=age;_mutatedStages=mask;StageMutationChecks=checks;}

        private void Awake()
        {
            LoadGenesFromJson("entity_default");
            Recalculate();
        }

        private void Update()
        {
            // ★ 修复（防Bug回归）：基因逻辑、成长及突变共用模拟时间，不能只让日历加速。
            float dt = ServiceLocator.TryGet<SimulationClock>(out var clock) ? clock.GameDeltaTime : Time.deltaTime;
            AdvanceSimulation(dt);
        }

        public void AdvanceSimulation(float dt)
        {
            // ★ 适配：联机生态只在管理员进程推进，副本不能发生独立变异或出生。
            if (dt <= 0f||WorldAuthority.IsReplica) return;
            // ★ 适配：物理/搬运改变位置后更新已存在的邻居快照，不在每个小步重建索引。
            Ecology.EntityNeighborhood.ObservePosition(this);
            // ★ 适配：卵孵化前不执行出生变异和普通基因行为，孵化后从幼年开始。
            var egg=GetComponent<Ecology.EggIncubation>();if(egg!=null&&egg.Incubating){egg.Advance(dt);return;}
            if (_isRecalculating) return;
            // ★ 修复（防Bug回归）：生命与反击组件在实体生命周期内复用，不能每个模拟子步重复GetComponent。
            if(_life==null){_life=GetComponent<EntityLifeCycle>();if(_life==null&&GetComponent<EntityStats>()!=null)_life=gameObject.AddComponent<EntityLifeCycle>();}
            if(_combat==null)_combat=GetComponent<Ecology.CombatIntent>()??gameObject.AddComponent<Ecology.CombatIntent>();
            // ★ 修复（防Bug回归）：按整数步数结算，避免0.5反复减0.1留下浮点残差、额外跑第六轮全部行为。
            int steps=Mathf.CeilToInt(dt/.1f);
            for(int index=0;index<steps;index++)
            {
                float step=index==steps-1?dt-index*.1f:.1f;
                // ★ 适配：寿命由单一组件推进，基因复制/失效/重新挂载不会重置或重复推进年龄。
                _life?.Advance(step);
                if(_life!=null && _life.HasDied)return;
                // ★ 适配：反击记忆随模拟步长推进，暂停或倍率切换不会消耗真实秒数。
                _combat.Advance(step);
                // ★ 适配：独立状态机先按配置选择意图，所有复制行动基因随后共用一个行为写入者。
                _state?.Advance(step);
                // ★ 修复（防Bug回归）：仍使用逻辑快照防止重算时修改集合，但复用缓冲区，避免每个实体每个子步分配新列表。
                _simulationLogics.Clear();_simulationLogics.AddRange(_activeLogics.Values);
                foreach (var logic in _simulationLogics) logic.OnUpdate(step);
            }
        }

        public void Recalculate()
        {
            if (_isRecalculating) return;
            // ★ 适配：固定分工先还原出生遗传快照，编辑和阶段变异不能改写士兵/工匠基因。
            GetComponent<Ecology.AntColonyMember>()?.EnforceGenome();
            _isRecalculating = true;

            var currentGenes = new HashSet<GeneInstance>(Genome.Genes);

            // ★ 修复（防Bug回归）：环境不适应时所有基因受抑；突变作用于遗传值，表达受抑仍可变异。
            Evaluation = GeneValueResolver.Resolve(Genome, IsGestating, EnvironmentGeneSuppression,additionalSuppression:Ecology.AntColonyMember.ExpressionSuppression(this));

            var stats = GetComponent<EntityStats>();
            float size = 1f;
            if (stats != null && stats.TryGet("size", out float s)) size = s;

            Evaluation.Attributes = EntityAttributeProcessor.Process(
                Evaluation.Attributes,
                Evaluation.Genes,
                CurrentAge,
                size,
                IsGestating
            );

            // ★ 2. 清理旧逻辑：如果基因被移除、被禁用，或者因为被抑制而失效，就删掉它的逻辑
            var toRemove = new List<GeneInstance>();
            foreach (var kvp in _activeLogics)
            {
                var eval = Evaluation.Genes.Find(g => g.Gene.InstanceId == kvp.Key.InstanceId);

                // 如果基因不在了，或者未启用，或者被抑制到失效 (!eval.IsActive)
                if (!currentGenes.Contains(kvp.Key) || !kvp.Key.Enabled || eval == null || !eval.IsActive ||
                    kvp.Value.GetType().Name != eval.Definition.LogicScriptId)
                {
                    toRemove.Add(kvp.Key);
                }
            }
            // ★ 修复（防Bug回归）：出错变异会原地更换 DefinitionId，旧逻辑必须释放并重建，不能继续执行旧行动/旧事件。
            foreach (var g in toRemove){if(_activeLogics[g] is IDisposable disposable)disposable.Dispose();_activeLogics.Remove(g);}

            OnEvaluationChanged?.Invoke(Evaluation);

            // 3. 挂载新逻辑：只挂载有效且还未挂载的基因
            foreach (var gene in Genome.Genes)
            {
                if (!gene.Enabled) continue;

                var eval = Evaluation.Genes.Find(g => g.Gene.InstanceId == gene.InstanceId);
                if (eval == null || !eval.IsActive) continue; // 被抑制失效，不挂载

                if (_activeLogics.ContainsKey(gene)) continue;

                var def = GeneDatabase.Get(gene.DefinitionId);
                if (def == null || string.IsNullOrEmpty(def.LogicScriptId)) continue;

                var logic = GeneLogicRegistry.CreateLogic(def.LogicScriptId);
                if (logic != null)
                {
                    logic.Initialize(this, gene);
                    _activeLogics[gene] = logic;
                }
            }

            _isRecalculating = false;
            // ★ 适配：标签新增/移除、出错换基因或受抑后同步更新实体状态授权。
            Ecology.EntityStateController.Rebind(this);
            _state=GetComponent<Ecology.EntityStateController>();LogicRevision++;
            // ★ 适配：必须在新逻辑挂载和状态授权完成后刷新生产者分类，避免使用旧表达。
            Ecology.EntityNeighborhood.Changed(this);
        }

        /// <summary>
        /// ★ 新增：环境压力写入。压力变化较大时才重算，避免每帧重建评估。
        /// </summary>
        public void ApplyEnvironmentPressure(float suppression, float mutationChance, string adaptationGeneId, float targetValue)
        {
            EnvironmentMutationChance = Mathf.Clamp01(mutationChance);
            EnvironmentGeneId = string.IsNullOrEmpty(adaptationGeneId) ? "gene_environment" : adaptationGeneId;
            EnvironmentAdaptationTarget = targetValue;

            suppression = Mathf.Max(0f, suppression);

            // ★ 修复（防Bug回归）：旧版只比较 `_lastAppliedSuppression` 且阈值 0.75，
            // 当压力从 0.4 回到 0 时差值不足 0.75，抑制值会永久残留。
            // 现在始终用当前生效值做比较，并保证“压力归零”一定能触发恢复。
            float delta = Mathf.Abs(suppression - EnvironmentGeneSuppression);
            bool mustReset = suppression <= 0.01f && EnvironmentGeneSuppression > 0.01f;
            if (delta > 0.3f || mustReset)
            {
                EnvironmentGeneSuppression = suppression;
                Recalculate();
            }
        }

        public IGeneLogic GetLogic(GeneInstance gene)
        {
            if (gene != null && _activeLogics.TryGetValue(gene, out var logic)) return logic;
            return null;
        }

        private void OnDestroy()
        {
            // ★ 适配：纯 C# 逻辑在移除/销毁时释放；仅停用控制器冻结测试时仍保留可查询的评估与逻辑。
            foreach(var logic in _activeLogics.Values)if(logic is IDisposable disposable)disposable.Dispose();
            _activeLogics.Clear();
        }

        public void LoadGenesFromJson(string jsonId)
        {
            var asset = Resources.Load<TextAsset>($"Entities/{jsonId}");
            if (asset == null)
            {
                Genome = GeneMutator.CreateBaseGenome();
                return;
            }

            var data = JsonUtility.FromJson<EntityGeneData>(asset.text);
            Genome = new Genome();
            foreach (var g in data.genes)
            {
                Genome.Add(GeneInstance.Create(g.definitionId, g.value, g.tier));
            }
        }

        public string GetRandomName()
        {
            var nameAsset = Resources.Load<TextAsset>("Names/name_pool");
            if (nameAsset == null) return $"未知生物-{UnityEngine.Random.Range(100, 999)}";
            var pool = JsonUtility.FromJson<NamePoolJson>(nameAsset.text);
            if (pool == null || pool.familyNames == null || pool.familyNames.Count == 0) return "无名生物";
            string f = pool.familyNames[UnityEngine.Random.Range(0, pool.familyNames.Count)];
            string g = pool.givenNames[UnityEngine.Random.Range(0, pool.givenNames.Count)];
            return $"{f}·{g}";
        }

        public float GetAttribute(string id)
        {
            if (Evaluation != null && Evaluation.Attributes.TryGetValue(id, out var v)) return Ecology.EcologyMotion.ResolveAttribute(this,id,v);
            return 0f;
        }

        public void TryStageMutation(AgeState stage)
        {
                // ★ 修复（防Bug回归）：只在出生/成年/老年首次进入时抽一次，普通帧和定时刷新不能变异。
                int bit=1<<(int)stage;if((_mutatedStages&bit)!=0)return;
                _mutatedStages|=bit;StageMutationChecks++;
                // 基因变异与刷新。
                // ★ 修复：环境压力不仅提高“定向选择”概率，也提高本次变异的总体发生率
                //（最高 +25%），否则玩家很难观察到适应基因被优先突变。
                float effectiveMutationChance = Mathf.Clamp01(
                    mutationChance + EnvironmentMutationChance * 0.25f);
                if (GetComponent<Ecology.AntColonyMember>()?.Frozen!=true&&UnityEngine.Random.value < effectiveMutationChance)
                {
                    var settings = GeneMutationSettings.CreateDefault();
                    settings.AdaptationGeneId = EnvironmentGeneId;
                    settings.AdaptationMutationChance = EnvironmentMutationChance;
                    settings.AdaptationTargetValue = EnvironmentAdaptationTarget;
                    GeneMutator.Mutate(Genome, settings);
                }
                Recalculate();
        }
    }
}

using DarwinPark.Core;
using UnityEngine;

namespace DarwinPark.Entities
{
    /// <summary>★ 新增：只允许真实地形接地时跳跃，独立管理合法的向外速度，避免旧防飞天约束截断跳跃。</summary>
    [RequireComponent(typeof(Rigidbody), typeof(Collider))]
    [DefaultExecutionOrder(60)]
    public sealed class EntityJumpMotor : MonoBehaviour
    {
        public float jumpSpeed = 6f, groundTolerance = .18f;
        [Range(0f, 1f)] public float minimumGroundDot = .45f;
        public bool IsJumping { get; private set; }
        private Rigidbody _body;
        private Collider _collider;
        private Transform _planet;
        private MeshCollider _ground;
        private EntityManualControl _manual;
        private void Awake() { _body = GetComponent<Rigidbody>(); _collider = GetComponent<Collider>(); _manual = GetComponent<EntityManualControl>(); }
        public void Bind(Transform planet)
        { _planet = planet; _ground = planet != null ? planet.GetComponent<MeshCollider>() : null; IsJumping = false; }
        public bool TryJump(bool allowed)
        {
            if (!allowed || IsJumping || _body.isKinematic || _planet == null || _ground == null) return false;
            // ★ 修复（防Bug回归）：海底接地不能成为陆地跳跃/连续上浮的发力点。
            if(GetComponent<DarwinPark.Entities.Vitals.EntityEnvironmentHazard>()?.IsSubmerged == true) return false;
            // ★ 适配：行动使用时钟实际交付倍率，过载补算限速不造成物理时间分离。
            float scale = ServiceLocator.TryGet<SimulationClock>(out var clock) ? clock.MotionTimeScale : 1;
            if (scale <= 0) return false;
            Vector3 up = (transform.position - _planet.position).normalized;
            var bounds = _collider.bounds;
            float support = Vector3.Dot(bounds.extents, new Vector3(Mathf.Abs(up.x), Mathf.Abs(up.y), Mathf.Abs(up.z)));
            // 只检测星球碰撞体，实体或触发器不能成为空中二段跳的落脚点。
            if (!_ground.Raycast(new Ray(bounds.center, -up), out var hit, support + groundTolerance) ||
                Vector3.Dot(hit.normal, up) < minimumGroundDot) return false;
            // ★ 修复（防Bug回归）：现有星球重力使用物理秒，跳跃冲量保持同一单位，倍率不能把小人射过高空约束。
            // ★ 修复（防Bug回归）：旧跳跃使用固定冲量，完全绕过跳跃基因与体型；实际起跳也执行与面板相同的能力上限。
            var genes=GetComponent<EntityGeneController>();float ability=genes!=null?genes.GetAttribute("jumpAbility"):0;
            float launch=Mathf.Min(jumpSpeed,ability);if(launch<=0)return false;
            _body.linearVelocity = Vector3.ProjectOnPlane(_body.linearVelocity, up) + up * launch;
            IsJumping = true;
            return true;
        }
        public float RadialVelocity(Vector3 up, float velocity)
        {
            if (IsJumping && velocity <= 0) IsJumping = false;
            return IsJumping ? velocity : Mathf.Min(0, velocity);
        }
        public void Cancel() { IsJumping = false; }
        private void FixedUpdate()
        {
            if (_manual == null || !_manual.IsControlled || _body.isKinematic) return;
            if (ServiceLocator.TryGet<SimulationClock>(out var clock) && !clock.IsRunning) return;
            ResolveGroundContact();
        }
        // ★ 修复（防Bug回归）：密集曲面上的切向速度控制可能覆盖接触解算，用真实碰撞表面兜底防止操控实体穿地溺水。
        public bool ResolveGroundContact()
        {
            if (_planet == null || _ground == null) return false;
            Vector3 up = (_body.position - _planet.position).normalized;
            float outer = _ground.bounds.extents.magnitude + groundTolerance;
            if (!_ground.Raycast(new Ray(_planet.position + up * outer, -up), out var hit, outer * 2)) return false;
            var bounds = _collider.bounds;
            float support = Vector3.Dot(bounds.extents, new Vector3(Mathf.Abs(up.x), Mathf.Abs(up.y), Mathf.Abs(up.z)));
            float gap = Vector3.Dot(bounds.center-hit.point,up)-support;
            if (gap >= 0) return false;
            _body.position += up * (-gap + Physics.defaultContactOffset);
            float radial = Vector3.Dot(_body.linearVelocity,up);
            if (radial < 0) { _body.linearVelocity -= up * radial; IsJumping = false; }
            return true;
        }
        private void OnDisable() => Cancel();
    }
}

using DarwinPark.Entities.Stats;
using UnityEngine;

namespace DarwinPark.Entities
{
    /// <summary>★ 新增：寿命进度独立于可被抑制/复制的生长基因逻辑，避免重挂基因重置年龄或永远不死。</summary>
    [RequireComponent(typeof(EntityGeneController),typeof(EntityStats))]
    public sealed class EntityLifeCycle : MonoBehaviour
    {
        public float Progress { get; private set; }
        public bool HasDied { get; private set; }
        private bool _born;
        private EntityGeneController _genes;
        private EntityStats _stats;
        private void Awake(){_genes=GetComponent<EntityGeneController>();_stats=GetComponent<EntityStats>();}
        private void Start()=>InitializeBirth();
        public void InitializeBirth()
        {
            // ★ 适配：卵未孵化时不消耗出生阶段抽签，也不提前衰老。
            if(GetComponent<Ecology.EggIncubation>()?.Incubating==true)return;
            if(_born)return;_born=true;
            _genes.CurrentAge=AgeState.Infant;
            _genes.TryStageMutation(AgeState.Infant);_genes.Recalculate();
        }
        public void Advance(float dt)
        {
            if(dt<=0 || HasDied)return;
            InitializeBirth();
            if(_stats.TryGet("health",out float hp) && hp<=0)return;
            var settings=LifeCycleSettings.Load();
            // 孕育仍可抑制幼年成长；老化不能因为基因失效而无限暂停。
            float speed=_genes.CurrentAge==AgeState.Elder
                ?Mathf.Max(settings.minimumAgingSpeed,_genes.GetAttribute("agingSpeed"))*settings.agingProgressScale
                :Mathf.Max(0,_genes.GetAttribute("growthSpeed"))*settings.growthProgressScale;
            Progress=Mathf.Min(settings.deathProgress,Progress+speed*dt);
            if(Progress>=settings.adultProgress && _genes.CurrentAge==AgeState.Infant)EnterStage(AgeState.Adult);
            if(Progress>=settings.elderProgress && _genes.CurrentAge==AgeState.Adult)EnterStage(AgeState.Elder);
            if(Progress>=settings.deathProgress)
            {
                // ★ 修复（防Bug回归）：寿命终点直接结算死亡，不能靠缓慢扣血与修复互相抵消。
                HasDied=true;_stats.TryGet("health",out hp);_stats.Modify("health",-Mathf.Max(0,hp),false);
                GetComponent<EntityManualControl>()?.Release();
                // ★ 适配：寿终也留下尚未被吸收的营养；清场仍走原有显式销毁路径。
                Ecology.EntityDeathSettlement.Die(GetComponent<DarwinEntity>());
            }
        }
        // ★ 适配：读档直接恢复寿命，不运行出生初始化。
        public void RestoreProgress(float progress){Progress=progress;HasDied=false;_born=true;}
        // ★ 适配：读档的卵尚未出生，孵化时仍应执行一次出生阶段初始化。
        public void WaitForHatch(){_born=false;}
        private void EnterStage(AgeState stage)
        {_genes.CurrentAge=stage;_genes.TryStageMutation(stage);_genes.Recalculate();}
    }
}

