        {
            switch (scriptId)
            {
                case "GrowthGeneLogic": return new GrowthGeneLogic();
                case "RepairGeneLogic": return new RepairGeneLogic();
                case "NutritionGeneLogic": return new NutritionGeneLogic(); // ★ 这里
