    // ★ 新增：规则是世界数据；只在不足时补充，超量用额外繁殖间隔降低出生率，不删除实体或改动正在孕育的后代。
    public static class PopulationMaintenance
    {
        private static readonly List<PopulationMaintenanceRule> Items=new();private static readonly Dictionary<string,int> Counts=new();private static HashSet<string> RoundedPartitions=new();private static int _frame=-1,_registered=-1;
        public static IReadOnlyList<PopulationMaintenanceRule> Rules=>Items;public static int Total {get;private set;}
        public static void Refresh()
        {
            if(_frame==Time.frameCount&&_registered==EntityRegistry.All.Count)return;_frame=Time.frameCount;_registered=EntityRegistry.All.Count;Total=0;Counts.Clear();foreach(var rule in Items)Counts[rule.id]=0;
            foreach(var entity in EntityRegistry.All)if(EcologyQueries.Alive(entity)){Total++;foreach(var rule in Items)if(rule.source.Matches(entity.Genes.Genome))Counts[rule.id]++;}
        }
        public static int Count(PopulationMaintenanceRule rule){Refresh();return Counts.TryGetValue(rule.id,out int count)?count:0;}
        public static int Needed(PopulationMaintenanceRule rule)
        {
            int count=Count(rule);if(!rule.enabled||rule.ratio<=0)return 0;if(Total==0)return Math.Min(PopulationMaintenanceSettings.Current.emptyWorldSeedCount,PopulationMaintenanceSettings.Current.maximumRefillPerCycle);if(count>=Total*rule.ratio)return 0;
            // 新实体同时增加分子和分母，不能用ratio*当前总数直接补差。
            return (int)Math.Min(PopulationMaintenanceSettings.Current.maximumRefillPerCycle,Math.Max(0,Math.Ceiling(((double)rule.ratio*Total-count)/(1d-rule.ratio))));
        }
        private static bool Disjoint(RandomSpawnRecipe a,RandomSpawnRecipe b)
        {
            if(a.method==RandomSpawnMethod.Template)return !b.Matches(a.template);
            if(b.method==RandomSpawnMethod.Template)return !a.Matches(b.template);
            return a.included.Any(b.excluded.Contains)||b.included.Any(a.excluded.Contains);
        }
        public static bool RequiresRefill(PopulationMaintenanceRule rule)
        {
            if(Needed(rule)==0)return false;int count=Count(rule);if(count==0)return true;
            // ★ 修复（防Bug回归）：完整互斥分区按一个实体的精度维持，避免33.3%/66.7%为追逐分母而交替无限补充。
            return !RoundedPartitions.Contains(rule.id)||rule.ratio*Total-count>=1;
        }
        public static float BreedingScale(EntityGeneController genes)
        {
            if(Items.Count==0)return 1;Refresh();float factor=1;
            foreach(var rule in Items)if(rule.enabled&&rule.source.Matches(genes.Genome)&&Total>0){float share=Counts[rule.id]/(float)Total;if(share>rule.ratio)factor=Mathf.Min(factor,rule.ratio/share);}return factor;
        }
        public static bool BreedingReady(EntityGeneController genes,ref float waited,float dt)
        {
            float scale=BreedingScale(genes);if(scale>=1){waited=0;return true;}if(scale<=0){waited=0;return false;}
            float delay=PopulationMaintenanceSettings.Current.extraBreedingDelaySeconds*(1/scale-1);waited=Mathf.Min(delay,waited+Mathf.Max(0,dt));return waited>=delay;
        }
        public static bool Set(PopulationMaintenanceRule rule)
        {
            if(WorldAuthority.IsReplica||!WorldAuthority.CanEdit||rule==null)return false;
            var next=Capture();int index=next.rules.FindIndex(r=>r.id==rule.id);if(index<0)next.rules.Add(rule);else next.rules[index]=rule;
            try{Validate(next,GeneDatabase.All.Select(d=>d.Id).ToArray());}catch(InvalidDataException){return false;}Restore(next);return true;
        }
        public static bool Remove(string id){if(WorldAuthority.IsReplica||!WorldAuthority.CanEdit)return false;int removed=Items.RemoveAll(r=>r.id==id);RoundedPartitions=CheckPartitions(Items);_frame=-1;return removed>0;}
        public static void SuspendAll(){foreach(var rule in Items)rule.enabled=false;RoundedPartitions.Clear();_frame=-1;}
        public static PopulationMaintenanceState Capture()=>JsonUtility.FromJson<PopulationMaintenanceState>(JsonUtility.ToJson(new PopulationMaintenanceState{rules=Items.ToList()}));
        public static void Validate(PopulationMaintenanceState state,ICollection<string> catalog)
        {
            if(state==null||state.version==0&&(state.rules==null||state.rules.Count==0))return;
            if(state.version!=1||state.rules==null||state.rules.Count>PopulationMaintenanceSettings.Current.maximumRules)throw new InvalidDataException("数量维持规则版本或数量无效");var ids=new HashSet<string>();
            foreach(var rule in state.rules){if(rule==null||!Guid.TryParseExact(rule.id,"N",out _)||!ids.Add(rule.id)||!float.IsFinite(rule.ratio)||rule.ratio<0||rule.ratio>=1||rule.source==null)throw new InvalidDataException("数量维持比例或来源无效（比例须小于100%）");rule.source.Validate(catalog);}
            // ★ 修复（防Bug回归）：互斥条件的目标总和超过100%无解，必须在写盘/启动生成前拒绝，而非一直补到世界上限。
            CheckPartitions(state.rules);
        }
        private static HashSet<string> CheckPartitions(IEnumerable<PopulationMaintenanceRule> rules)
        {
            var result=new HashSet<string>();var enabled=rules.Where(r=>r.enabled).ToArray();var apart=new bool[enabled.Length,enabled.Length];for(int i=0;i<enabled.Length;i++)for(int j=0;j<i;j++)apart[i,j]=Disjoint(enabled[i].source,enabled[j].source);
            for(int mask=1;mask<(1<<enabled.Length);mask++){double sum=0;bool clique=true;for(int i=0;i<enabled.Length&&clique;i++)if((mask&(1<<i))!=0){sum+=enabled[i].ratio;for(int j=0;j<i;j++)if((mask&(1<<j))!=0&&!apart[i,j]){clique=false;break;}}if(!clique)continue;if(sum>1.000001)throw new InvalidDataException("互斥维持规则的目标比例总和不能超过100%");if(Math.Abs(sum-1)<.000001)for(int i=0;i<enabled.Length;i++)if((mask&(1<<i))!=0)result.Add(enabled[i].id);}
            return result;
        }
        public static void Restore(PopulationMaintenanceState state)
        {var incoming=state?.rules!=null?JsonUtility.FromJson<PopulationMaintenanceState>(JsonUtility.ToJson(state)).rules:new List<PopulationMaintenanceRule>();var partitions=CheckPartitions(incoming);Items.Clear();Items.AddRange(incoming);RoundedPartitions=partitions;_frame=-1;Counts.Clear();Total=0;}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)] private static void Reset()=>Restore(null);
    }
}

using DarwinPark.Entities.Ecology;
using System.Collections.Generic;
using DarwinPark.Planet;
using UnityEngine;

namespace DarwinPark.Entities
{
    // ★ 新增：只让已落地且无移动能力的动态刚体休眠，保留碰撞、被击退、搬运和基因获得行动后的唤醒能力。
    public static class StationaryBodyRest
    {
        private sealed class Contact {public Vector3 position,planetPosition;public Quaternion rotation;public Transform planet;public PlanetTerrainMeshBuilder builder;public PlanetTerrainData data;public float radius,heightScale;}
        private static readonly Dictionary<Rigidbody,Contact> Contacts=new Dictionary<Rigidbody,Contact>();
        public static bool IsResting(Rigidbody body)
        {
            if(!body.IsSleeping()||!Contacts.TryGetValue(body,out var contact))return false;
            // ★ 修复（防Bug回归）：外部休眠、存档传送和星球移动不能绕过地表救援；只跳过经过接触验证且位置未变的休眠。
            return contact.planet!=null&&contact.builder!=null&&ReferenceEquals(contact.data,contact.builder.Data)&&contact.radius==contact.builder.radius&&contact.heightScale==contact.builder.heightScale&&body.position==contact.position&&contact.planet.position==contact.planetPosition&&contact.planet.rotation==contact.rotation;
        }
        public static bool RemainsAsleep(Rigidbody body,EntityGeneController genes)
        {
            if(EcologyPerformanceSettings.Current.stationarySleep&&IsResting(body)&&genes!=null&&genes.GetAttribute("moveSpeed")<=0)return true;
            Contacts.Remove(body);if(body.IsSleeping())body.WakeUp();return false;
        }
        public static void TryRest(Rigidbody body,EntityGeneController genes,Collider collider,RaycastHit hit,Transform planet)
        {
            var config=EcologyPerformanceSettings.Current;
            if(!config.stationarySleep||genes==null||collider==null||hit.collider==null||hit.collider.transform!=planet||genes.GetAttribute("moveSpeed")>0)return;
            // ★ 修复（防Bug回归）：只在真正接触星球地面时休眠；不能把出生下落或站在移动实体上误当成静止植物。
            Vector3 contact=collider.ClosestPoint(hit.point);
            if((contact-hit.point).sqrMagnitude>config.restContactSlack*config.restContactSlack||body.linearVelocity.sqrMagnitude>config.restSpeed*config.restSpeed)return;
            var builder=planet.GetComponent<PlanetTerrainMeshBuilder>();if(builder==null||builder.Data==null)return;
            if(!Contacts.TryGetValue(body,out var record)){record=new Contact();Contacts.Add(body,record);}
            // ★ 适配：地形重建或星球参数变化后也须唤醒，不能让旧休眠实体悬在新地表上方。
            record.builder=builder;record.data=builder.Data;record.radius=builder.radius;record.heightScale=builder.heightScale;
            record.position=body.position;record.planet=planet;record.planetPosition=planet.position;record.rotation=planet.rotation;body.Sleep();
        }
        public static void Remove(Rigidbody body){if(body!=null)Contacts.Remove(body);}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)] public static void Clear()=>Contacts.Clear();
    }
}

using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using DarwinPark.Genetics;

namespace DarwinPark.Entities.Stats
{
    public static class EntityAttributeProcessor
    {
        public static Dictionary<string, float> Process(
            Dictionary<string, float> baseAttributes,
            List<GeneEvaluation> activeGenes,
            AgeState ageState,
            float size,
            bool isGestating)
        {
            var finalAttrs = new Dictionary<string, float>(baseAttributes);

            // ================= 1. 注入系统级虚拟属性 =================
            float ageMult = ageState switch
            {
                AgeState.Infant => 0.5f,
                AgeState.Adult => 1.2f,
                AgeState.Elder => 0.8f,
                _ => 1.0f
            };
            finalAttrs["sys_age_mult"] = ageMult;
            finalAttrs["sys_size"] = size;
            finalAttrs["sys_gestating"] = isGestating ? 1f : 0f;

            // 将所有激活的基因ID注入，值为 1，供 JSON 引用
            foreach (var eval in activeGenes)
            {
                if (eval.IsActive && !string.IsNullOrEmpty(eval.Definition.Id))
                {
                    finalAttrs[eval.Definition.Id] = 1f;
                    if(GeneAttributeInheritance.Applies(eval.Definition))foreach(var ancestor in GeneAttributeInheritance.Lineage(eval.Definition))finalAttrs[ancestor.Id]=1;
                }
            }

            // ================= 2. 收集所有联动规则 =================
            var activeLinkages = new List<AttributeLinkage>();
            foreach (var eval in activeGenes)
            {
                if (!eval.IsActive || eval.Definition.Linkages == null) continue;
                if(!GeneAttributeInheritance.Applies(eval.Definition))activeLinkages.AddRange(eval.Definition.Linkages);
            }
            // ★ 修复（防Bug回归）：行动谱系继承的体型联动只执行一次，不能因行动、领地、种群共存反复除体型或叠加攻击。
            activeLinkages.AddRange(activeGenes.Where(g=>g.IsActive&&GeneAttributeInheritance.Applies(g.Definition)).SelectMany(g=>GeneAttributeInheritance.Lineage(g.Definition)).GroupBy(d=>d.Id).SelectMany(g=>g.First().Linkages).Distinct());

            // ================= 3. 按优先级执行联动 =================
            // 优先级：Add (加算) -> Multiply/Divide (乘除) -> Override (覆盖归零/锁定)

            // 3.1 先执行所有加算
            foreach (var link in activeLinkages.Where(l => l.mode == "Add"))
            {
                if (!finalAttrs.TryGetValue(link.sourceAttributeId, out float sourceVal)) continue;
                if (!finalAttrs.ContainsKey(link.targetAttributeId)) finalAttrs[link.targetAttributeId] = 0f;

                float effectVal = sourceVal * link.factor;
                finalAttrs[link.targetAttributeId] += effectVal;
            }

            // 3.2 再执行所有乘除算
            foreach (var link in activeLinkages.Where(l => l.mode == "Multiply" || l.mode == "Divide"))
            {
                if (!finalAttrs.TryGetValue(link.sourceAttributeId, out float sourceVal)) continue;
                if (!finalAttrs.ContainsKey(link.targetAttributeId)) continue;

                float effectVal = sourceVal * link.factor;

                if (link.mode == "Multiply")
                {
                    // ★ 修复：允许乘数为 0
                    finalAttrs[link.targetAttributeId] *= effectVal;
                }
                else
                {
                    if (effectVal > 0.01f) finalAttrs[link.targetAttributeId] /= effectVal;
                }
            }

            // 3.3 ★ 核心修复：最后执行所有覆盖（强制归零/改变）
            foreach (var link in activeLinkages.Where(l => l.mode == "Override"))
            {
                if (!finalAttrs.TryGetValue(link.sourceAttributeId, out float sourceVal)) continue;
                // 直接覆盖，完全无视前面加了多少
                finalAttrs[link.targetAttributeId] = sourceVal * link.factor;
            }

            return finalAttrs;
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Entities.Stats
{
    public class EntityStats : MonoBehaviour
    {
        private Dictionary<string, float> _stats = new();
        private Dictionary<string, float> _maxStats = new();

        // ★ 新增：用于控制受击闪烁的协程与颜色记录
        private Coroutine _flashCoroutine;
        private Dictionary<Renderer, Color[]> _rendererOriginalColors = new();
        private bool _isFlashing = false;
        private Ecology.PopulationBehavior _population;
        private bool _appliedSync,_appliedFlash;
        private Color _appliedColor;
        private MaterialPropertyBlock _colorBlock;

        private void Awake()
        {
            // ★ 修复（防Bug回归）：属性块包含原生资源，必须在主线程Awake创建，不能放进组件字段初始化。
            _colorBlock=new MaterialPropertyBlock();
            _stats["health"] = 100f; _maxStats["health"] = 100f;
            _stats["nutrient"] = 10f; _maxStats["nutrient"] = 10f;
            _stats["storedNutrient"] = 0f; _maxStats["storedNutrient"] = 100f;
            _stats["growth"] = 0f; _maxStats["growth"] = 100f;
            _stats["aging"] = 0f; _maxStats["aging"] = 100f;
            _stats["size"] = 1.0f; _maxStats["size"] = 10.0f;
        }

        private void Start()
        {
            // ★ 记录实体原本的材质颜色
            var renderers = GetComponentsInChildren<Renderer>(true);
            foreach (var r in renderers)
            {
                // ★ 修复（防Bug回归）：成员环、收藏线及资源标记有自己的颜色，不属于实体身体。
                if(r is not MeshRenderer&&r is not SkinnedMeshRenderer)continue;
                // ★ 修复（防Bug回归）：记录颜色无需实例化材质；数百静止个体原来在Start就破坏了材质共享。
                var materials=r.sharedMaterials;
                if (materials.Length>0&&materials[0]!=null)
                {
                    // 受击时才创建独立材质，静止且未受击的个体继续共享资源
                    Color[] colors = new Color[materials.Length];
                    for (int i = 0; i < materials.Length; i++)
                    {
                        r.GetPropertyBlock(_colorBlock,i);if(_colorBlock.isEmpty)r.GetPropertyBlock(_colorBlock);
                        colors[i] = _colorBlock.HasColor("_BaseColor")?_colorBlock.GetColor("_BaseColor"):_colorBlock.HasColor("_Color")?_colorBlock.GetColor("_Color"):materials[i]!=null?materials[i].color:Color.white;
                    }
                    _rendererOriginalColors[r] = colors;
                }
            }
            RefreshAppearance();
        }

        // ★ 新增：在最后渲染前组合受击色和种群配色；出生、读档、换群和暂停时的配置修改都能生效。
        private void LateUpdate()=>RefreshAppearance();
        private void RefreshAppearance()
        {
            if(_population==null)_population=GetComponent<Ecology.PopulationBehavior>();
            bool sync=_population!=null&&_population.Active&&Ecology.PopulationArchive.Find(_population.GroupId)?.syncEntityColor==true;
            Color color=sync?Ecology.ColonyAppearance.ColorFor(_population.GroupId):Color.white;
            if(sync==_appliedSync&&_isFlashing==_appliedFlash&&(!sync||color==_appliedColor))return;
            _appliedSync=sync;_appliedFlash=_isFlashing;_appliedColor=color;
            foreach(var pair in _rendererOriginalColors)
            {
                if(pair.Key==null)continue;
                for(int i=0;i<pair.Value.Length;i++)
                {
                    Color body=_isFlashing?Color.red:sync?color:pair.Value[i];body.a=pair.Value[i].a;
                    // ★ 修复（防Bug回归）：逐实体/材质槽属性块保留其他属性，避免改写共享材质或每次受击实例化材质。
                    pair.Key.GetPropertyBlock(_colorBlock,i);if(_colorBlock.isEmpty)pair.Key.GetPropertyBlock(_colorBlock);
                    _colorBlock.SetColor("_BaseColor",body);_colorBlock.SetColor("_Color",body);pair.Key.SetPropertyBlock(_colorBlock,i);
                }
            }
        }
        private void OnDisable()
        {
            if(_flashCoroutine!=null)StopCoroutine(_flashCoroutine);_flashCoroutine=null;_isFlashing=false;
            RestoreColor();
        }

        // ★ 适配：数值与上限成对持久化，恢复时不触发受击闪烁或进食副作用。
        public List<DarwinPark.Entities.StatSaveValue> CaptureValues()
        {var values=new List<DarwinPark.Entities.StatSaveValue>();foreach(var pair in _stats)values.Add(new DarwinPark.Entities.StatSaveValue{id=pair.Key,value=pair.Value,max=_maxStats.TryGetValue(pair.Key,out var max)?max:100});return values;}
        public void RestoreValues(List<DarwinPark.Entities.StatSaveValue> values)
        {foreach(var value in values){_stats[value.id]=value.value;_maxStats[value.id]=value.max;}Ecology.EntityNeighborhood.Changed(GetComponent<EntityGeneController>());}
        public bool TryGet(string id, out float value) => _stats.TryGetValue(id, out value);
        // ★ 适配：营养转移只需当前空位，不应每帧构造整份存档数值列表。
        public float CapacityRemaining(string id)=>_stats.TryGetValue(id,out float value)&&_maxStats.TryGetValue(id,out float maximum)?Mathf.Max(0,maximum-value):0;

        /// <summary>★ 新增：进食先补饱食度，溢出进入储存；猎食收益不因饱食度上限而丢失。</summary>
        public void Feed(float amount)
        {
            if (amount <= 0 || !TryGet("nutrient", out float before)) return;
            Modify("nutrient", amount);
            TryGet("nutrient", out float after);
            float overflow = Mathf.Max(0, amount - (after - before));
            if (overflow > 0) Modify("storedNutrient", overflow);
        }

        public void Modify(string id, float delta)
        {
            Modify(id, delta, true);
        }

        // ★ 适配：环境持续伤害每帧都会调用，关闭闪烁避免实体长期变红；
        // 捕食/饥饿等瞬时伤害仍走原来的闪烁路径。
        public void Modify(string id, float delta, bool playHitFlash)
        {
            if (_stats.ContainsKey(id))
            {
                float max = _maxStats.ContainsKey(id) ? _maxStats[id] : 100f;
                float before=_stats[id];_stats[id] = Mathf.Clamp(before + delta, 0f, max);
                // ★ 适配：同帧死亡或恢复立刻失效邻居计数；普通扣血不重建空间数据。
                if(id=="health"&&(before>0)!=(_stats[id]>0))Ecology.EntityNeighborhood.Changed(GetComponent<EntityGeneController>());

                // ★ 核心修改：如果是扣血，触发变红闪烁
                if (playHitFlash && id == "health" && delta < 0)
                {
                    PlayHitFlash();
                }
            }
        }

        public void SetMax(string id, float max)
        {
            if (_maxStats.ContainsKey(id)) _maxStats[id] = max;
        }

        /// <summary>
        /// 触发受击变红闪烁
        /// </summary>
        private void PlayHitFlash()
        {
            if (_isFlashing)
            {
                // 如果正在闪烁，刷新持续时间
                if (_flashCoroutine != null) StopCoroutine(_flashCoroutine);
            }

            _flashCoroutine = StartCoroutine(FlashRoutine());
        }

        private IEnumerator FlashRoutine()
        {
            _isFlashing = true;
            RefreshAppearance(); // 变红
            yield return new WaitForSeconds(0.15f); // 红0.15秒
            RestoreColor(); // 恢复
            _isFlashing = false;
            _flashCoroutine = null;
        }

        private void RestoreColor()
        {
            _isFlashing=false;RefreshAppearance();
        }
    }
}

