using System;
using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Genetics
{
    public static class GeneDatabase
    {
        private static Dictionary<string, GeneDefinition> _definitions;
        private static bool _initialized = false;

        public static void EnsureLoaded()
        {
            if (_initialized) return;
            _definitions = new Dictionary<string, GeneDefinition>();

            // ★ 适配：自定义工具配置覆盖内置同 id 基因，失败明确告警并回退。
            var assets = System.Linq.Enumerable.ToArray(GeneTreeStorage.RuntimeAssets());
            if (assets == null || assets.Length == 0)
            {
                Debug.LogError("[GeneDatabase] 致命错误：Resources/Genes 下找不到任何 JSON 文件！");
                return;
            }

            foreach (var asset in assets)
            {
                try
                {
                    var json = JsonUtility.FromJson<GeneDefinitionJson>(asset.text);
                    if (json == null || string.IsNullOrEmpty(json.id))
                    {
                        Debug.LogError($"[GeneDatabase] JSON 解析为空或缺少 id：{asset.name}");
                        continue;
                    }

                    var def = new GeneDefinition
                    {
                        Id = json.id,
                        DisplayName = json.displayName,
                        Category = (GeneCategory)Enum.Parse(typeof(GeneCategory), json.category, true),
                        ParentGeneId = json.parentGeneId,
                        BaseGeneId = json.baseGeneId,
                        IsBaseGene = json.isBaseGene,
                        Tier = json.tier,
                        LogicScriptId = json.logicScriptId,
                        AiModuleId = json.aiModuleId,
                        // ★ 适配：统一迁移和校验标签后交给独立状态组件使用。
                        EntityStateTags = GeneEntityStateTags.Read(asset.text),
                        AttributeCurves = new List<AttributeCurve>(),
                        Linkages = new List<AttributeLinkage>(), // ★ 确保这里初始化了
                        States = new List<GeneStateDefinition>(),
                        SuppressionRules = new List<GeneSuppressionRule>()
                    };

                    // 映射属性曲线
                    if (json.attributeCurves != null)
                    {
                        foreach (var c in json.attributeCurves)
                        {
                            def.AttributeCurves.Add(new AttributeCurve
                            {
                                attributeId = c.attributeId,
                                minValue = c.minValue,
                                maxValue = c.maxValue
                            });
                        }
                    }

                    // 映射状态
                    if (json.states != null)
                    {
                        foreach (var s in json.states)
                        {
                            def.States.Add(new GeneStateDefinition
                            {
                                StateId = s.stateId,
                                DisplayName = s.displayName,
                                Center = s.center,
                                Color = (s.color != null && s.color.Length >= 3) ? new Color(s.color[0], s.color[1], s.color[2]) : Color.white,
                                Tier = s.tier,
                                BaseGeneId = s.baseGeneId,
                                AiModuleId = s.aiModuleId,
                                // ★ 修复：补齐状态迁移数据，旧版只读 stateId/displayName，基因树会丢失后继状态。
                                AllowedNextStates = s.allowedNextStates != null
                                    ? new List<string>(s.allowedNextStates)
                                    : new List<string>()
                            });
                        }
                    }

                    // 映射抑制规则
                    if (json.suppressionRules != null)
                    {
                        foreach (var r in json.suppressionRules)
                        {
                            def.SuppressionRules.Add(new GeneSuppressionRule
                            {
                                TargetGeneId = r.targetGeneId,
                                Coefficient = r.coefficient
                            });
                        }
                    }

                    // ★ 核心插入位置：映射基因联动规则
                    if (json.attributeLinkages != null)
                    {
                        def.Linkages.AddRange(json.attributeLinkages);
                    }

                    // ★ 适配：红/绿关系转为运行中的抑制/促进系数。
                    GeneTreeStorage.ApplyInfluences(def);
                    _definitions[json.id] = def;
                }
                catch (Exception e)
                {
                    Debug.LogError($"[GeneDatabase] 加载 {asset.name} 失败：{e.Message}");
                }
            }

            _initialized = true;
            // ★ 适配：定义全部装载后再解析谱系，旧世界中的重复行动曲线也使用同一继承规则。
            GeneAttributeInheritance.Prepare(_definitions);
            Debug.Log($"[GeneDatabase] 初始化完成，共加载 {_definitions.Count} 个基因。");
        }

        public static IEnumerable<GeneDefinition> All
        {
            get
            {
                EnsureLoaded();
                return _definitions.Values;
            }
        }

        public static GeneDefinition Get(string id)
        {
            EnsureLoaded();
            if (_definitions.TryGetValue(id, out var def))
                return def;

            Debug.LogWarning($"[GeneDatabase] 找不到基因 ID: {id}");
            return null;
        }

        public static void Reload() { _initialized = false; EntityStateRegistry.ReloadConfigured(); }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Genetics
{
    public enum GeneCategory { Reproduction = 0, Nutrition = 1, Locomotion = 2, Custom = 99 }
    public enum AttributeApplyMode { Add = 0, Multiply = 1, Override = 2 }

    [System.Serializable]
    public struct AttributeEffect
    {
        public string attributeId;
        public AttributeApplyMode mode;
        public float value;
    }

    [System.Serializable]
    public struct GeneSuppressionRule
    {
        public string TargetGeneId;
        public float Coefficient;
    }

    // ★ 新增：数据驱动的联动规则
    [System.Serializable]
    public struct AttributeLinkage
    {
        public string sourceAttributeId; // 来源属性 (可以是基因属性，也可以是系统虚拟属性)
        public string targetAttributeId; // 目标属性
        public string mode;              // 运算模式："Add" (加算), "Multiply" (乘算)
        public float factor;             // 影响系数
    }

    // ★ 核心修复：新增属性曲线结构体
    [System.Serializable]
    public struct AttributeCurve
    {
        public string attributeId;
        public float minValue; // 基因值为 0 时的属性
        public float maxValue; // 基因值为 100 时的属性
    }

    [System.Serializable]
    public class GeneStateDefinition
    {
        public string StateId;
        public string DisplayName;
        public float Center;
        public Color Color = Color.white;
        public int Tier;
        public string BaseGeneId;
        public string AiModuleId;
        public List<string> AllowedNextStates = new List<string>();

        public Color GetDisplayColor(float geneValue)
        {
            Color.RGBToHSV(Color, out var h, out var s, out _);
            float v = Mathf.Lerp(0.30f, 1f, Mathf.Clamp01(geneValue / 100f));
            return Color.HSVToRGB(h, s, v);
        }
    }

    public class GeneDefinition
    {
        public string Id;
        public string DisplayName;
        public GeneCategory Category;
        public string ParentGeneId;
        public string BaseGeneId;
        public bool IsBaseGene;
        public int Tier;
        public string LogicScriptId; // ★ 新增：标识要挂载的逻辑脚本
        public string AiModuleId;

        // ★ 核心：属性曲线列表
        // ★ 适配：标签授予实体可用状态，不替换基因自身的食性/倾向状态。
        public List<string> EntityStateTags = new List<string>();
        public List<AttributeCurve> AttributeCurves = new List<AttributeCurve>();
        public List<AttributeLinkage> Linkages = new List<AttributeLinkage>(); // ★ 新增
        public List<GeneStateDefinition> States = new List<GeneStateDefinition>();
        public List<GeneSuppressionRule> SuppressionRules = new List<GeneSuppressionRule>();

        public GeneStateDefinition ResolveState(float value, ICollection<string> missingStates)
        {
            GeneStateDefinition best = null;
            float bestDist = float.MaxValue;
            foreach (var s in States)
            {
                if (missingStates != null && missingStates.Contains(s.StateId)) continue;
                float d = Mathf.Abs(s.Center - value);
                if (d < bestDist) { bestDist = d; best = s; }
            }
            return best;
        }
    }
}

