        public string defaultStateId;
        public List<EntityStateDefinition> states=new List<EntityStateDefinition>();
        public EntityStateDefinition Get(string id)=>states.FirstOrDefault(s=>s.id==id);
    }
    public static class EntityStateRegistry
    {
        private static string _snapshot,_json;
        private static EntityStateDocument _current;
        public static string ConfiguredPath=>Path.Combine(GeneTreeStorage.Folder,"entity_states.json");
        public static EntityStateDocument Current
        {
            get {if(_current==null){_json=_snapshot??ReadConfiguredJson();_current=Parse(_json);}return _current;}
        }
        public static string CurrentJson {get {_=Current;return _json;}}
        public static string ReadConfiguredJson()
        {
            if(File.Exists(ConfiguredPath))return File.ReadAllText(ConfiguredPath);
            var asset=Resources.Load<TextAsset>("Genetics/entity_states");
            if(asset==null)throw new InvalidDataException("缺少实体状态注册表 Genetics/entity_states");
            return asset.text;
        }
        // ★ 适配：存档使用自己的注册表快照；缺少该字段的旧档使用当前配置，异常必须明确阻止加载。
        public static void UseSnapshot(string json)
        {_snapshot=string.IsNullOrWhiteSpace(json)?null:json;_current=null;_json=null;}
        public static void ReloadConfigured(){if(_snapshot==null){_current=null;_json=null;}}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        public static void Clear()=>UseSnapshot(null);
        public static EntityStateDocument Parse(string json)
        {
            var doc=JsonUtility.FromJson<EntityStateDocument>(json);
            if(doc==null||doc.version!=1||doc.states==null||doc.states.Count==0)throw new InvalidDataException("实体状态注册表版本或内容无效");
            var ids=new HashSet<string>();
            foreach(var state in doc.states)
            {
                if(state==null||!System.Text.RegularExpressions.Regex.IsMatch(state.id??"","^[A-Za-z0-9_-]+$")||!ids.Add(state.id)||string.IsNullOrWhiteSpace(state.displayName)||!Enum.TryParse<EntityStateBehavior>(state.behavior,out var behavior)||!Enum.IsDefined(typeof(EntityStateBehavior),behavior)||state.transitions==null)
                    throw new InvalidDataException("实体状态缺失、重复或行为未注册："+state?.id);
                ValidateRules(state.entryAny);
                if(behavior==EntityStateBehavior.Hunt&&string.IsNullOrEmpty(state.targetRangeAttributeId))throw new InvalidDataException("捕猎状态缺少目标感知属性："+state.id);
                foreach(var transition in state.transitions){if(transition==null)throw new InvalidDataException("实体状态迁移为空");ValidateRules(transition.any);}
            }
            if(!ids.Contains(doc.defaultStateId))throw new InvalidDataException("实体默认状态未注册");
            foreach(var state in doc.states)foreach(var transition in state.transitions)if(!ids.Contains(transition.to))throw new InvalidDataException("实体迁移目标未注册："+transition.to);
            return doc;
        }
        private static void ValidateRules(List<EntityStateRule> rules)
        {
            if(rules==null)throw new InvalidDataException("实体状态条件列表为空");
            foreach(var rule in rules)
            {
                if(rule?.all==null||rule.all.Count==0)throw new InvalidDataException("实体状态条件组不能为空");
                foreach(var condition in rule.all)
                {
                    if(condition==null)throw new InvalidDataException("实体状态条件为空");
                    bool valid=condition.kind=="stat"&&!string.IsNullOrEmpty(condition.attributeId)&&new[]{"gt","lte"}.Contains(condition.comparison)&&!float.IsNaN(condition.value)&&!float.IsInfinity(condition.value)||
                        condition.kind=="nearby_gene_state"&&!string.IsNullOrEmpty(condition.geneId)&&!string.IsNullOrEmpty(condition.geneStateId)&&!string.IsNullOrEmpty(condition.rangeAttributeId)&&new[]{"present","absent"}.Contains(condition.comparison);
                    if(!valid)throw new InvalidDataException("实体状态条件类型、比较方式或参数无效："+condition.kind);
                }
            }
        }
        public static HashSet<string> ExpandTags(IEnumerable<string> tags,EntityStateDocument doc)
        {
            var result=new HashSet<string>();var pending=new Queue<string>(tags);
            while(pending.Count>0)
            {
                string id=pending.Dequeue();var definition=doc.Get(id);
                if(definition==null)throw new InvalidDataException("实体状态标签未注册："+id);
                if(!result.Add(id))continue;
                foreach(var transition in definition.transitions)pending.Enqueue(transition.to);
            }
            result.Add(doc.defaultStateId);return result;
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Genetics
{
    // ★ 修复：补回丢失的数据类
    public class GeneEvaluation
    {
        public GeneInstance Gene;
        public GeneDefinition Definition;
        public GeneStateDefinition State;
        public float SuppressionAmount;
        public float EffectiveStrength;
        public Dictionary<string,float> AttributeContributions=new Dictionary<string,float>();
        public bool IsActive => EffectiveStrength >= 10f; // 生效阈值改为 10
    }

    public class GenomeEvaluation
    {
        public List<GeneEvaluation> Genes = new List<GeneEvaluation>();
        public Dictionary<string, float> Attributes = new Dictionary<string, float>();
    }

    public static class GeneValueResolver
    {
        /// <summary>
        /// ★ 修复（防Bug回归）：默认把环境压力施加给所有基因；遗传值不受影响，
        /// 环境适应突变仍可发生。可选豁免参数仅供显式需要豁免的调用使用。
        /// </summary>
        public static GenomeEvaluation Resolve(Genome genome, bool isGestating = false,
            float globalSuppression = 0f, string suppressExemptGeneId = null,IReadOnlyDictionary<string,float> additionalSuppression=null)
        {
            var result = new GenomeEvaluation();
            if (genome == null) return result;

            // 1. 处理抑制关系
            var suppressions = new Dictionary<GeneInstance, float>();
            foreach (var gene in genome.Genes)
            {
                if (!gene.Enabled) continue;
                var def = GeneDatabase.Get(gene.DefinitionId);
                if (def == null || def.SuppressionRules == null) continue;

                // 如果是繁殖基因，且不在孕育期，则不产生抑制
                if (gene.DefinitionId == "gene_reproduction" && !isGestating)
                    continue;

                foreach (var rule in def.SuppressionRules)
                {
                    foreach (var target in genome.FindByDefinition(rule.TargetGeneId))
                    {
                        if (!target.Enabled) continue;
                        suppressions.TryGetValue(target, out var cur);
                        suppressions[target] = cur + gene.Value * rule.Coefficient / 1000f;
                    }
                }
            }

            // 2. 逐基因计算属性

            foreach (var gene in genome.Genes)
            {
                if (!gene.Enabled) continue;
                var def = GeneDatabase.Get(gene.DefinitionId);
                if (def == null) continue;

                suppressions.TryGetValue(gene, out var sup);
                // ★ 适配：角色表达抑制只影响有效值与属性，不改写遗传值。
                if(additionalSuppression!=null&&additionalSuppression.TryGetValue(gene.DefinitionId,out float extra))sup+=Mathf.Max(0,extra);
                bool exempt = !string.IsNullOrEmpty(suppressExemptGeneId)
                    && gene.DefinitionId == suppressExemptGeneId;
                float global = exempt ? 0f : Mathf.Max(0f, globalSuppression);
                float effectiveValue = Mathf.Max(0f, gene.Value - sup - global);

                var eval = new GeneEvaluation
                {
                    Gene = gene,
                    Definition = def,
                    State = def.ResolveState(gene.Value, gene.MissingStateIds),
                    // ★ 修复（防Bug回归）：面板同时显示环境抑制，保证有效值与抑制值一致。
                    SuppressionAmount = sup + global,
                    EffectiveStrength = effectiveValue
                };
                result.Genes.Add(eval);

            }

            // ★ 修复（防Bug回归）：同时记录每个表达真正贡献的属性，失效基因和被同谱系替代的共有属性不能冒用实体总值。
            result.Attributes = GeneAttributeInheritance.Accumulate(result.Genes);
            return result;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace DarwinPark.Genetics
{
    // ★ 修复（防Bug回归）：行动谱系的共有能力只表达一次；进化基因保留专属属性，单独存在时仍继承基础行动能力。
    public static class GeneAttributeInheritance
    {
        private static readonly Dictionary<string,List<GeneDefinition>> Chains=new Dictionary<string,List<GeneDefinition>>();
        private static readonly Dictionary<string,List<AttributeCurve>> Curves=new Dictionary<string,List<AttributeCurve>>();
        public static bool Applies(GeneDefinition definition)=>definition.Category==GeneCategory.Locomotion;
        public static IEnumerable<GeneDefinition> Lineage(GeneDefinition definition)=>Chains.TryGetValue(definition.Id,out var chain)?chain:new[]{definition}.AsEnumerable();
        public static void Prepare(IReadOnlyDictionary<string,GeneDefinition> definitions)
        {
            Chains.Clear();Curves.Clear();
            foreach(var definition in definitions.Values.Where(Applies))
            {
                var chain=new List<GeneDefinition>();var seen=new HashSet<string>();var current=definition;
                while(current!=null&&seen.Add(current.Id))
                {
                    chain.Add(current);string parent=!string.IsNullOrEmpty(current.ParentGeneId)?current.ParentGeneId:current.BaseGeneId;
                    current=!string.IsNullOrEmpty(parent)&&definitions.TryGetValue(parent,out var ancestor)&&Applies(ancestor)?ancestor:null;
                }
                Chains[definition.Id]=chain;
            }
            // 兼容旧世界的重复曲线，仅规范运行定义，不覆盖存档和用户的原始配置文件。
            foreach(var pair in Chains.OrderBy(p=>p.Value.Count))
            {
                var definition=pair.Value[0];var inherited=new Dictionary<string,AttributeCurve>();
                foreach(var ancestor in pair.Value.Skip(1).Reverse())foreach(var curve in ancestor.AttributeCurves)inherited[curve.attributeId]=curve;
                definition.AttributeCurves.RemoveAll(c=>inherited.ContainsKey(c.attributeId));
                foreach(var curve in definition.AttributeCurves)inherited[curve.attributeId]=curve;
                Curves[definition.Id]=inherited.Values.ToList();
            }
        }
        private static IEnumerable<AttributeCurve> Effective(GeneDefinition definition)=>Curves.TryGetValue(definition.Id,out var curves)?curves:definition.AttributeCurves;
        public static Dictionary<string,float> Accumulate(List<GeneEvaluation> genes)
        {
            var result=new Dictionary<string,float>();
            void Add(GeneEvaluation gene,AttributeCurve curve)
            {
                float value=Mathf.Lerp(curve.minValue,curve.maxValue,Mathf.Clamp01(gene.EffectiveStrength/100f))*gene.Gene.CopyStrength;
                gene.AttributeContributions[curve.attributeId]=value;
                result.TryGetValue(curve.attributeId,out float prior);result[curve.attributeId]=prior+value;
            }
            foreach(var gene in genes.Where(g=>g.IsActive&&!Applies(g.Definition)))foreach(var curve in gene.Definition.AttributeCurves)Add(gene,curve);
            foreach(var family in genes.Where(g=>g.IsActive&&Applies(g.Definition)).GroupBy(g=>Lineage(g.Definition).Last().Id))
            {
                foreach(string attribute in family.SelectMany(g=>Effective(g.Definition)).Select(c=>c.attributeId).Distinct())
                {
                    var owner=family.Where(g=>g.Definition.AttributeCurves.Any(c=>c.attributeId==attribute)).OrderBy(g=>g.Definition.Tier).ThenBy(g=>g.Definition.Id,StringComparer.Ordinal).FirstOrDefault()
                        ??family.Where(g=>Effective(g.Definition).Any(c=>c.attributeId==attribute)).OrderByDescending(g=>g.Definition.Tier).ThenBy(g=>g.Definition.Id,StringComparer.Ordinal).First();
                    // 同一种基因的复制仍保留 CopyStrength；不同进化类型不重复叠加共有属性。
                    foreach(var gene in family.Where(g=>g.Definition.Id==owner.Definition.Id))Add(gene,Effective(gene.Definition).First(c=>c.attributeId==attribute));
                }
            }
            return result;
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace DarwinPark.Genetics
{
    // ★ 修复（防Bug回归）：旧世界快照只有旧基因，增量补库使新增基因可用，同时保留已有基因数值与自定义关系。
    public static class GeneCatalogExpansion
    {
        public static int Expand(Dictionary<string,string> catalog,GeneTreeDocument tree)
        {
            var available=GeneTreeStorage.ReadCatalog();
            var missing=new HashSet<string>(available.Keys.Where(id=>!catalog.ContainsKey(id)));
            if(missing.Count==0)return 0;
            var merged=new Dictionary<string,string>(catalog);
            foreach(var id in missing)merged.Add(id,available[id]);
            var result=JsonUtility.FromJson<GeneTreeDocument>(JsonUtility.ToJson(tree));
            var builtin=Resources.Load<TextAsset>("Genetics/default_tree");
            if(builtin==null)throw new System.IO.InvalidDataException("缺少 Genetics/default_tree，无法补齐基因关系");
            var defaults=JsonUtility.FromJson<GeneTreeDocument>(builtin.text);
            var nodes=new HashSet<string>(result.nodes.Select(n=>n.id));
            var newEdges=defaults.edges.Where(e=>(missing.Contains(e.from)||missing.Contains(e.to))&&merged.ContainsKey(e.from)&&merged.ContainsKey(e.to)).ToList();
            var required=new HashSet<string>(missing.Concat(newEdges.SelectMany(e=>new[]{e.from,e.to})));
            foreach(var node in defaults.nodes)if(required.Contains(node.id)&&nodes.Add(node.id))result.nodes.Add(node);
            foreach(var edge in newEdges)if(!result.edges.Any(e=>e.from==edge.from&&e.to==edge.to&&e.kind==edge.kind))result.edges.Add(edge);
            GeneTreeStorage.Validate(result,merged);
            // ★ 修复（防Bug回归）：校验时迁移了旧卵寄生定义，既有条目也要成对写回，不能只保存新增ID。
            foreach(var entry in merged)catalog[entry.Key]=entry.Value;
            tree.nodes=result.nodes;tree.edges=result.edges;tree.nutritionVersion=result.nutritionVersion;
            return missing.Count;
        }
    }
}

