namespace DarwinPark.Planet
{
    /// <summary>FBM 噪声（实例持有 ImprovedNoise）。★ 适配：构造时注入 seed，不再依赖静态 Init。</summary>
    public class FBMNoise
    {
        private readonly ImprovedNoise _noise;
        public int Octaves, Seed;
        public float Frequency, Amplitude, Lacunarity, Gain, WarpStrength;

        public FBMNoise(FBMConfig cfg, int seed)
        {
            _noise = new ImprovedNoise(seed);
            Octaves = cfg.octaves;
            Frequency = cfg.frequency;
            Amplitude = cfg.amplitude;
            Lacunarity = cfg.lacunarity;
            Gain = cfg.gain;
            WarpStrength = cfg.warpStrength;
            Seed = seed;
        }

        public float Sample(Vector3 unitDir)
        {
            float amp = Amplitude, freq = Frequency, sum = 0f, norm = 0f;
            // ★ 修复（防Bug回归）：种子已进入置换表；大种子叠加后逐层倍频会丢失小数精度，造成地形/气候台阶。
            var p = unitDir * freq;
            for (int i = 0; i < Octaves; i++)
            {
                float n = WarpStrength > 0f
                    ? _noise.WarpedNoise(p, WarpStrength, (Seed & 255) + i * 17)
                    : _noise.Noise(p);
                sum += n * amp;
                norm += amp;
                p *= Lacunarity;
                amp *= Gain;
            }
            return norm > 0f ? sum / norm : 0f;
        }
    }
}

using UnityEngine;

namespace DarwinPark.Planet
{
    /// <summary>
    /// 3D 改进 Perlin 噪声（实例化）。
    /// ★ 适配：从静态 Perm 数组改为实例持有，消除多行星并发生成的竞态（规则3.6）。
    /// </summary>
    public class ImprovedNoise
    {
        private readonly int[] _perm = new int[512];

        public ImprovedNoise(int seed)
        {
            // ★ 修复：改用跨平台确定性随机，避免不同运行时的 System.Random 算法差异
            // 导致同一种子在 Editor 与打包版本生成不同地形（山脉位置漂移）。
            var rng = new DeterministicRandom(seed);
            var p = new int[256];
            for (int i = 0; i < 256; i++) p[i] = i;
            for (int i = 255; i > 0; i--)
            {
                int j = rng.Next(i + 1);
                (p[i], p[j]) = (p[j], p[i]);
            }
            for (int i = 0; i < 512; i++) _perm[i] = p[i & 255];
        }

        private static float Fade(float t) => t * t * t * (t * (t * 6 - 15) + 10);
        private static float Lerp(float a, float b, float t) => a + t * (b - a);

        private float Grad(int hash, float x, float y, float z)
        {
            int h = hash & 15;
            float u = h < 8 ? x : y;
            float v = h < 4 ? y : (h == 12 || h == 14 ? x : z);
            return ((h & 1) == 0 ? u : -u) + ((h & 2) == 0 ? v : -v);
        }

        public float Noise(Vector3 p)
        {
            int X = Mathf.FloorToInt(p.x) & 255;
            int Y = Mathf.FloorToInt(p.y) & 255;
            int Z = Mathf.FloorToInt(p.z) & 255;
            float x = p.x - Mathf.Floor(p.x);
            float y = p.y - Mathf.Floor(p.y);
            float z = p.z - Mathf.Floor(p.z);
            float u = Fade(x), v = Fade(y), w = Fade(z);
            int A = _perm[X] + Y, AA = _perm[A] + Z, AB = _perm[A + 1] + Z;
            int B = _perm[X + 1] + Y, BA = _perm[B] + Z, BB = _perm[B + 1] + Z;
            return Lerp(
                Lerp(Lerp(Grad(_perm[AA], x, y, z), Grad(_perm[BA], x - 1, y, z), u),
                     Lerp(Grad(_perm[AB], x, y - 1, z), Grad(_perm[BB], x - 1, y - 1, z), u), v),
                Lerp(Lerp(Grad(_perm[AA + 1], x, y, z - 1), Grad(_perm[BA + 1], x - 1, y, z - 1), u),
                     Lerp(Grad(_perm[AB + 1], x, y - 1, z - 1), Grad(_perm[BB + 1], x - 1, y - 1, z - 1), u), v),
                w);
        }

        public float WarpedNoise(Vector3 p, float warpStrength, int seedOffset)
        {
            var offset = new Vector3(
                Noise(p + Vector3.one * seedOffset),
                Noise(p + Vector3.one * (seedOffset + 31.4f)),
                Noise(p + Vector3.one * (seedOffset + 61.8f))
            ) * warpStrength;
            return Noise(p + offset);
        }
    }
}

using UnityEngine;
using System.Collections;
using System.Collections.Generic;

namespace DarwinPark.Planet
{
    public class OreGenerator : MonoBehaviour
    {
        [Header("生成设置")]
        public int maxOreCount = 150;
        public float minSize = 1.5f;
        public float maxSize = 4f;
        public Material oreMaterial;

        [Header("刷新设置")]
        public float refreshInterval = 10f;
        public int refreshAmount = 5;

        private float _planetRadius = 300f;
        private float _timer;
        private List<GameObject> _activeOres = new List<GameObject>();
        private bool _isReady = false;

        private IEnumerator Start()
        {
            var builder = GetComponent<PlanetTerrainMeshBuilder>();
            if (builder != null) _planetRadius = builder.radius;

            // ★ 核心修复：等待 1 帧，确保 PlanetTerrainMeshBuilder 的 MeshCollider 已经挂载完成
            yield return null;

            _isReady = true;
            for (int i = 0; i < maxOreCount / 2; i++)
            {
                GenerateSingleOre();
            }
            Debug.Log($"[OreGen] 初始生成了一半矿石 (共 {maxOreCount / 2} 块)");
        }

        private void Update()
        {
            if (!_isReady) return;

            _timer += Time.deltaTime;
            if (_timer >= refreshInterval)
            {
                _timer = 0;
                RefreshOres();
            }
        }

        private void RefreshOres()
        {
            _activeOres.RemoveAll(ore => ore == null);

            if (_activeOres.Count < maxOreCount)
            {
                int countToSpawn = Mathf.Min(refreshAmount, maxOreCount - _activeOres.Count);
                for (int i = 0; i < countToSpawn; i++)
                {
                    GenerateSingleOre();
                }
            }
        }

        private void GenerateSingleOre()
        {
            Vector3 randomDir = Random.onUnitSphere;
            Ray ray = new Ray(transform.position, randomDir);

            // 射线检测地形
            if (Physics.Raycast(ray, out RaycastHit hit, _planetRadius * 2f))
            {
                if (hit.collider is MeshCollider)
                {
                    CreateOre(hit.point, hit.normal);
                }
            }
        }

        private void CreateOre(Vector3 position, Vector3 normal)
        {
            GameObject ore = GameObject.CreatePrimitive(PrimitiveType.Cube);
            ore.name = "OreNode";
            ore.transform.position = position;
            ore.transform.rotation = Quaternion.FromToRotation(Vector3.up, normal) * Quaternion.Euler(Random.Range(-15, 15), Random.Range(0, 360), Random.Range(-15, 15));
            ore.transform.localScale = Vector3.one * Random.Range(minSize, maxSize);

            var renderer = ore.GetComponent<Renderer>();
            if (oreMaterial != null) renderer.material = oreMaterial;
            else
            {
                var mat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
                Color defaultColor = Random.value > 0.5f ? new Color(0.6f, 0.5f, 0.2f) : new Color(0.3f, 0.6f, 0.6f);
                if (mat.HasProperty("_BaseColor")) mat.SetColor("_BaseColor", defaultColor);
                else mat.color = defaultColor;
                renderer.material = mat;
            }

            var node = ore.AddComponent<OreNode>();
            node.maxNutrient = Random.Range(50f, 150f);
            node.currentNutrient = node.maxNutrient;

            _activeOres.Add(ore);
        }
    }
}

using UnityEngine;

namespace DarwinPark.Planet // ★ 改为 Planet
{
    public class OreNode : MonoBehaviour
    {
        public float maxNutrient = 100f;
        public float currentNutrient = 100f;
        public float nutrientDensity = 1.0f; // 密度倍率

        public float Extract(float amount)
        {
            if (currentNutrient <= 0) return 0f;

            float actualExtract = Mathf.Min(amount, currentNutrient);
            currentNutrient -= actualExtract;

            // 根据剩余量调整模型大小（视觉反馈）
            float scale = Mathf.Max(0.1f, currentNutrient / maxNutrient);
            transform.localScale = Vector3.one * scale;

            if (currentNutrient <= 0.1f)
            {
                Destroy(gameObject); // 被吸干了就销毁
            }
            return actualExtract;
        }
    }
}

