        public float polarIceTemp = -22f;
        public float tundraTemp = -12f;
        public float tropicalTemp = 23f;
        public float desertTemp = 12f;
        public float desertHumidity = 32f;
        public float forestHumidity = 56f;
        public float tropicalHumidity = 74f;

        [Header("气候图层颜色（直接烘焙到纹理，避免硬分类断层）")]
        public Color oceanWarm = new Color(0.10f, 0.32f, 0.55f);
        public Color oceanCold = new Color(0.20f, 0.42f, 0.62f);
        public Color polarIce = new Color(0.91f, 0.93f, 0.97f);
        public Color tundra = new Color(0.47f, 0.50f, 0.43f);
        public Color desert = new Color(0.79f, 0.68f, 0.44f);
        public Color savanna = new Color(0.49f, 0.54f, 0.29f);
        public Color grassland = new Color(0.38f, 0.53f, 0.27f);
        public Color forest = new Color(0.15f, 0.35f, 0.18f);
        public Color rainforest = new Color(0.05f, 0.25f, 0.10f);
        public Color beach = new Color(0.72f, 0.67f, 0.49f);
        public Color rock = new Color(0.36f, 0.33f, 0.29f);

        public Vector3 GetWindDirection()
        {
            float lon = prevailingWindLongitudeDeg * Mathf.Deg2Rad;
            float lat = prevailingWindLatitudeDeg * Mathf.Deg2Rad;
            return new Vector3(
                Mathf.Cos(lat) * Mathf.Sin(lon),
                Mathf.Sin(lat),
                Mathf.Cos(lat) * Mathf.Cos(lon)).normalized;
        }

        /// <summary>
        /// 用于玩法（环境伤害）的离散气候分类。
        /// 图层颜色走连续混色，不依赖这里的硬阈值，因此不会产生色块断层。
        /// </summary>
        public ClimateType Classify(float temperature, float humidity, bool isOcean)
        {
            if (isOcean) return ClimateType.Ocean;
            if (temperature <= polarIceTemp) return ClimateType.PolarIce;
            if (temperature <= tundraTemp) return ClimateType.Tundra;
            if (temperature >= desertTemp && humidity <= desertHumidity) return ClimateType.Desert;
            if (temperature >= tropicalTemp && humidity >= tropicalHumidity) return ClimateType.TropicalRain;
            if (humidity >= forestHumidity) return ClimateType.Forest;
            return ClimateType.Grassland;
        }
    }
}

using UnityEngine;
using DarwinPark.Core;

namespace DarwinPark.Planet
{
    /// <summary>
    /// 预计算全球气候图。
    /// ★ 修复：气候生成逻辑已抽到 <see cref="PlanetClimateModel"/>（纯数据、可单测）。
    /// 本组件只负责：取地形数据 → 调模型 → 上传纹理 → 绑定到星球材质。
    ///
    /// 图层不再由纬度湿度带或 Shader 硬分类生成：温度、湿度、降水全部是连续场，
    /// 颜色在 CPU 端连续混色后写入 sRGB 纹理，因此不会出现色块/等距断层。
    /// </summary>
    public class PlanetClimateMap : MonoBehaviour
    {
        public static PlanetClimateMap Instance { get; private set; }

        [Header("气候图")]
        [Tooltip("气候纹理分辨率。越高越清晰，但生成耗时按平方增长")]
        // ★ 修复（防Bug回归）：近距离观察需要更密集的气候采样，避免 512 图在地面视角被放大成色块。
        public int mapResolution = 1024;

        public Texture2D ClimateTexture { get; private set; }
        public bool IsReady { get; private set; }

        private PlanetTerrainMeshBuilder _terrainBuilder;
        private PlanetClimateSystem _climateSystem;
        private Color[] _pixels;
        private float[] _heightMap;
        private float[] _temperatureMap;
        private float[] _humidityMap;
        private float[] _precipitationMap;
        private bool[] _oceanMap;
        private bool _isDirty;
        private int _generatedResolution;
        private float _lastLogTime = -10f;
        private float _lastGenerateTime = -10f;
        private const float MinRegenerateInterval = 0.6f;

        private void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(this); return; }
            Instance = this;
        }

        private void OnDestroy()
        {
            if (Instance == this) Instance = null;
        }

        private void Start()
        {
            _terrainBuilder = GetComponent<PlanetTerrainMeshBuilder>();
            _climateSystem = GetComponent<PlanetClimateSystem>();

            if (_terrainBuilder == null)
                Log.Error(Log.Tag.Planet, "PlanetClimateMap 需要同一星球上的 PlanetTerrainMeshBuilder");
            if (_climateSystem == null)
                Log.Error(Log.Tag.Planet, "PlanetClimateMap 需要同一星球上的 PlanetClimateSystem，气候参数将使用默认值");

            Invoke(nameof(InitialGenerate), 0.25f);
        }

        private void InitialGenerate(){if(!WorldRuntimeGate.Managed || WorldRuntimeGate.Ready)GenerateClimateMap();}
        public void MarkDirty() => _isDirty = true;

        private void Update()
        {
            if(WorldRuntimeGate.Managed&&!WorldRuntimeGate.Ready)return;
            if (!_isDirty) return;
            // ★ 修复：滑条拖动时限制重建频率。气候生成包含风程步进，比旧版更重，
            // 因此间隔提高到 0.6s，避免拖滑条时每帧卡顿。
            if (Time.unscaledTime - _lastGenerateTime < MinRegenerateInterval) return;
            _isDirty = false;
            GenerateClimateMap();
        }

        public void GenerateClimateMap()
        {
            _lastGenerateTime = Time.unscaledTime;

            if (_terrainBuilder == null || _terrainBuilder.Data == null)
            {
                // 地形可能比气候图晚一帧就绪；保持 dirty，下一帧重试而不是永久失败。
                _isDirty = true;
                if (Time.unscaledTime - _lastLogTime >= 1f)
                {
                    _lastLogTime = Time.unscaledTime;
                    Log.Warn(Log.Tag.Planet, "气候图生成跳过：地形数据尚未就绪");
                }
                return;
            }

            int res = Mathf.Clamp(mapResolution, 64, 1024);
            mapResolution = res;
            var data = _terrainBuilder.Data;
            var cfg = _climateSystem != null && _climateSystem.config != null
                ? _climateSystem.config
                : new PlanetClimateConfig();
            if (_climateSystem == null)
                Log.Warn(Log.Tag.Planet, "PlanetClimateSystem 缺失，气候图使用默认配置");

            // 纹理只烘焙“基准温湿度”，季节偏移在 SampleClimate 时实时叠加，
            // 避免实体感知与图层显示出现两份偏移。
            float baseTempOffset = ClimateDataHub.BaseTemperature - cfg.baseTemperatureReference;
            float baseHumidityOffset = ClimateDataHub.BaseHumidity - cfg.baseHumidityReference;

            var model = new PlanetClimateModel(data, cfg, _terrainBuilder.seed);
            var result = model.Generate(res, baseTempOffset, baseHumidityOffset);

            ApplyGeneratedClimate(result);
        }
        // ★ 适配：气候纯数据可后台计算，纹理与材质必须主线程上传。
        public void ApplyGeneratedClimate(PlanetClimateResult result)
        {
            int res=result.Resolution;_isDirty=false;_lastGenerateTime=Time.unscaledTime;
            _pixels = result.Pixels;
            _heightMap = result.Height;
            _temperatureMap = result.Temperature;
            _humidityMap = result.Humidity;
            _precipitationMap = result.Precipitation;
            _oceanMap = result.Ocean;
            _generatedResolution = res;

            if (ClimateTexture == null || ClimateTexture.width != res)
            {
                // 颜色贴图使用 sRGB，避免把手工调好的气候颜色当成线性数据而洗白。
                ClimateTexture = new Texture2D(res, res, TextureFormat.RGBA32, false, false)
                {
                    name = "PlanetClimateMap",
                    filterMode = FilterMode.Bilinear
                };
            }
            // ★ 修复：经度方向必须 Repeat、纬度方向 Clamp。
            // 旧版整体 Clamp，接缝处双线性采样会跨到错误边界，表现为一条经线断层。
            ClimateTexture.wrapModeU = TextureWrapMode.Repeat;
            ClimateTexture.wrapModeV = TextureWrapMode.Clamp;

            ClimateTexture.SetPixels(_pixels);
            ClimateTexture.Apply(false, false);
            IsReady = true;
            BindToPlanet();

            if (Time.unscaledTime - _lastLogTime >= 1f)
            {
                _lastLogTime = Time.unscaledTime;
                float landPercent = result.LandCells / Mathf.Max(1f, res * res) * 100f;
                float desertPercent = result.DesertCells / Mathf.Max(1f, result.LandCells) * 100f;
                float snowPercent = result.SnowCells / Mathf.Max(1f, result.LandCells) * 100f;
                Log.Info(Log.Tag.Planet,
                    $"气候图生成完成：{res}x{res}，温度[{result.MinTemperature:F1},{result.MaxTemperature:F1}]°C，" +
                    $"湿度[{result.MinHumidity:F1},{result.MaxHumidity:F1}]%，陆地{landPercent:F1}%，" +
                    $"沙漠/陆地{desertPercent:F1}%，雪地/陆地{snowPercent:F1}%");
            }
        }

        /// <summary>★ 适配：把气候贴图写入指定 MaterialPropertyBlock，供图层按钮复用。</summary>
        public void ApplyToBlock(MaterialPropertyBlock block)
        {
            if (block == null) return;
            if (ClimateTexture != null) block.SetTexture("_ClimateMap", ClimateTexture);
            block.SetFloat("_ClimateReady", IsReady && ClimateTexture != null ? 1f : 0f);
        }

        private void BindToPlanet()
        {
            var mr = GetComponent<MeshRenderer>();
            if (mr == null) return;

            var block = new MaterialPropertyBlock();
            mr.GetPropertyBlock(block);
            block.SetTexture("_ClimateMap", ClimateTexture);
            block.SetFloat("_ClimateReady", 1f);
            mr.SetPropertyBlock(block);
        }

        /// <summary>
        /// 世界坐标采样气候。气候系统和 UI 共用，保证“看到的图层”和“实体感受到的气候”一致。
        /// </summary>
        public bool SampleClimate(Vector3 worldPos, float tempOffset, float humidityOffset, out ClimateData data)
        {
            data = default;
            if (!IsReady || _temperatureMap == null) return false;

            Vector3 dir = transform.InverseTransformDirection(worldPos - transform.position).normalized;
            if (dir.sqrMagnitude < 1e-6f) return false;

            int res = _generatedResolution > 0 ? _generatedResolution : mapResolution;
            Vector2 uv = PlanetTerrainSampler.DirectionToUV(dir);
            float fx = uv.x * res - 0.5f;
            float fy = uv.y * res - 0.5f;
            int x0 = Mathf.FloorToInt(fx);
            int y0 = Mathf.FloorToInt(fy);
            float tx = fx - x0;
            float ty = fy - y0;

            int x1 = WrapIndex(x0 + 1, res);
            int y1 = Mathf.Clamp(y0 + 1, 0, res - 1);
            x0 = WrapIndex(x0, res);
            y0 = Mathf.Clamp(y0, 0, res - 1);

            int i00 = y0 * res + x0;
            int i10 = y0 * res + x1;
            int i01 = y1 * res + x0;
            int i11 = y1 * res + x1;

            float temp = Bilerp(_temperatureMap[i00], _temperatureMap[i10], _temperatureMap[i01], _temperatureMap[i11], tx, ty);
            float humidity = Bilerp(_humidityMap[i00], _humidityMap[i10], _humidityMap[i01], _humidityMap[i11], tx, ty);
            float precipitation = Bilerp(_precipitationMap[i00], _precipitationMap[i10], _precipitationMap[i01], _precipitationMap[i11], tx, ty);
            bool isOcean = _oceanMap[i00] && _oceanMap[i10] && _oceanMap[i01] && _oceanMap[i11];

            var cfg = _climateSystem != null && _climateSystem.config != null
                ? _climateSystem.config
                : new PlanetClimateConfig();
            temp = Mathf.Clamp(temp + tempOffset, -60f, 70f);
            humidity = Mathf.Clamp(humidity + humidityOffset, 0f, 100f);
            precipitation = Mathf.Clamp(precipitation, 0f, 100f);

            data = new ClimateData
            {
                Temperature = temp,
                Humidity = humidity,
                Precipitation = precipitation,
                Type = cfg.Classify(temp, humidity, isOcean)
            };
            return true;
        }

        private static float Bilerp(float v00, float v10, float v01, float v11, float tx, float ty)
        {
            return Mathf.Lerp(Mathf.Lerp(v00, v10, tx), Mathf.Lerp(v01, v11, tx), ty);
        }

        private static int WrapIndex(int index, int size)
        {
            int wrapped = index % size;
            return wrapped < 0 ? wrapped + size : wrapped;
        }
    }
}

using System;
using UnityEngine;

namespace DarwinPark.Planet
{
    /// <summary>气候图的一次生成结果（纯数据，方便在编辑器/测试中复用与验证）。</summary>
    public sealed class PlanetClimateResult
    {
        public int Resolution;
        public float SeaLevel;

        public float[] Height;
        public float[] Temperature;
        public float[] Humidity;
        public float[] Precipitation;
        public float[] CoastProximity;
        public float[] WindFetch;
        public float[] Continentality;
        public float[] Relief;
        public bool[] Ocean;
        public Color[] Pixels;
        public ClimateType[] Types;

        public int LandCells;
        public int DesertCells;
        public int SnowCells;
        public float MinTemperature = float.MaxValue;
        public float MaxTemperature = float.MinValue;
        public float MinHumidity = float.MaxValue;
        public float MaxHumidity = float.MinValue;
    }

    /// <summary>
    /// ★ 新增：星球气候模型（纯 C#，不依赖场景对象）。
    /// 为什么独立：气候生成涉及“太阳辐射 + 海拔 + 海洋热惯性 + 洋流 + 风程 +
    /// 海岸距离 + 迎风坡 + 雨影 + 地形起伏 + 噪声”多个条件，放在 MonoBehaviour
    /// 里既难调参也难验证。这里只负责算数据，PlanetClimateMap 只负责上传纹理。
    ///
    /// 所有输入都是连续的场，颜色在 CPU 端连续混色；没有任何“if 湿度小于 X 就
    /// 变成沙漠”的硬分类，因此图层不会出现色块断层。
    /// </summary>
    public sealed class PlanetClimateModel
    {
        private readonly PlanetTerrainData _data;
        private readonly PlanetClimateConfig _cfg;
        private readonly int _seed;

        public PlanetClimateModel(PlanetTerrainData data, PlanetClimateConfig cfg, int seed)
        {
            _data = data ?? throw new ArgumentNullException(nameof(data));
            _cfg = cfg ?? new PlanetClimateConfig();
            _seed = seed;
        }

        /// <summary>
        /// 生成气候图。tempOffset/humidityOffset 来自环境系统滑条与季节偏移，
        /// 每次重生成都叠加，保证“看到的图层”和“实体感受到的气候”一致。
        /// </summary>
        public PlanetClimateResult Generate(int resolution, float tempOffset, float humidityOffset)
        {
            int res = Mathf.Clamp(resolution, 64, 2048);
            int count = res * res;
            var result = new PlanetClimateResult
            {
                Resolution = res,
                SeaLevel = _data.SeaLevel,
                Height = new float[count],
                Temperature = new float[count],
                Humidity = new float[count],
                Precipitation = new float[count],
                CoastProximity = new float[count],
                WindFetch = new float[count],
                Continentality = new float[count],
                Relief = new float[count],
                Ocean = new bool[count],
                Pixels = new Color[count],
                Types = new ClimateType[count]
            };

            // ---------- 1. 采样高度 / 海洋，并计算海岸距离 ----------
            for (int y = 0; y < res; y++)
            {
                float v = (y + 0.5f) / res;
                for (int x = 0; x < res; x++)
                {
                    float u = (x + 0.5f) / res;
                    Vector3 dir = PlanetTerrainSampler.DirectionFromUV(u, v);
                    int i = y * res + x;
                    float h = PlanetTerrainSampler.SampleHeight(_data, dir);
                    result.Height[i] = h;
                    result.Ocean[i] = h < _data.SeaLevel;
                }
            }

            int[] coastDistance = BuildCoastDistance(result.Ocean, res);
            float coastScale = Mathf.Max(1f, res * Mathf.Max(0.01f, _cfg.coastFalloffFraction));

            // ---------- 2. 盛行风“上风方海洋距离”（风程）----------
            // 在 1/4 分辨率上做球面步进，再双线性插值到全分辨率：
            // 风程是连续场，不会像“最近海洋方向”那样在等距边界产生扇形断层。
            int coarseResolution = Mathf.Clamp(res / 4, 48, 256);
            float[] coarseFetch = BuildCoarseWindFetch(coarseResolution);

            // ---------- 3. 温度/湿度噪声 ----------
            var temperatureNoise = new FBMNoise(new FBMConfig
            {
                octaves = 3,
                frequency = _cfg.temperatureNoiseFrequency,
                amplitude = 1f,
                lacunarity = 2f,
                gain = 0.5f,
                warpStrength = 0.35f
            }, _seed + 1701);

            var currentNoise = new FBMNoise(new FBMConfig
            {
                octaves = 2,
                frequency = _cfg.oceanCurrentFrequency,
                amplitude = 1f,
                lacunarity = 2f,
                gain = 0.5f,
                warpStrength = 0.5f
            }, _seed + 2303);

            var moistureNoise = new FBMNoise(new FBMConfig
            {
                octaves = 3,
                frequency = _cfg.moistureNoiseFrequency,
                amplitude = 1f,
                lacunarity = 2f,
                gain = 0.5f,
                warpStrength = 0.25f
            }, _seed + 9001);

            Vector3 windDir = _cfg.GetWindDirection();
            float maxHeight = PlanetTerrainData.MaxNormalizedHeight;
            float altitudeRange = Mathf.Max(0.01f, maxHeight - _data.SeaLevel);

            for (int y = 0; y < res; y++)
            {
                float v = (y + 0.5f) / res;
                float lat = (v - 0.5f) * Mathf.PI;
                float solar = Mathf.Pow(Mathf.Cos(lat), Mathf.Max(0.1f, _cfg.latitudeTempExponent));
                // ★ 修复（防Bug回归）：降低纬向辐射支配，温度由区域、海洋、海拔和水分共同决定。
                float regionalBase = _cfg.regionalTemperature;

                for (int x = 0; x < res; x++)
                {
                    int i = y * res + x;
                    float u = (x + 0.5f) / res;
                    Vector3 dir = PlanetTerrainSampler.DirectionFromUV(u, v);
                    bool isOcean = result.Ocean[i];
                    float height = result.Height[i];
                    float altitudeNorm = Mathf.Clamp01((height - _data.SeaLevel) / altitudeRange);
                    float coastProximity = Mathf.Exp(-coastDistance[i] / coastScale);
                    float continentality = 1f - coastProximity;
                    float fetch = SampleCoarseBilinear(coarseFetch, coarseResolution, u, v);

                    result.CoastProximity[i] = coastProximity;
                    result.Continentality[i] = continentality;
                    result.WindFetch[i] = fetch;

                    // ---------- 温度：太阳辐射是基准，但不是唯一条件 ----------
                    float oceanTemperature = Mathf.Lerp(regionalBase, Mathf.Lerp(_cfg.oceanPoleTemp, _cfg.oceanEquatorTemp, solar), _cfg.solarTemperatureWeight)
                        + currentNoise.Sample(dir) * _cfg.oceanCurrentAmplitude + tempOffset;

                    float temperature = Mathf.Lerp(regionalBase, Mathf.Lerp(_cfg.poleTemp, _cfg.equatorTemp, solar), _cfg.solarTemperatureWeight)
                        + tempOffset
                        - altitudeNorm * _cfg.altitudeTempDrop
                        + temperatureNoise.Sample(dir) * _cfg.temperatureNoiseAmplitude
                            * (0.45f + 0.55f * continentality);

                    if (isOcean)
                    {
                        temperature = Mathf.Lerp(temperature, oceanTemperature, _cfg.oceanTempModeration);
                    }
                    else
                    {
                        // 近海被海水热惯性拉平，内陆温差更大。
                        temperature = Mathf.Lerp(temperature, oceanTemperature,
                            _cfg.coastalTempModeration * Mathf.Pow(coastProximity, 1.5f));
                    }

                    // ---------- 湿度：风程 + 海岸 + 迎风坡 + 雨影 + 起伏 ----------
                    float humidity;
                    float relief = 0f;
                    float windLift = 0f;
                    if (isOcean)
                    {
                        humidity = 100f;
                    }
                    else
                    {
                        SampleNeighbourhood(dir, height, out relief, out float coldPool);
                        result.Relief[i] = relief;
                        temperature -= coldPool * _cfg.basinColdPoolDrop;
                        float fetchMoisture = Mathf.Exp(-fetch / Mathf.Max(0.05f, _cfg.windFetchScale));
                        ComputeWindExposure(dir, height, windDir, out windLift, out float rainShadow01);
                        // windwardMoistureBonus / leewardDryness 继续作为迎风/背风的调参倍率，
                        // 与 orographic/rainShadow 的绝对幅度配合使用。
                        float orographic = windLift * _cfg.orographicMoistureBonus
                            * (1f + Mathf.Max(0f, _cfg.windwardMoistureBonus));
                        float rainShadow = rainShadow01 * _cfg.rainShadowDryness
                            * (1f + Mathf.Max(0f, _cfg.leewardDryness));

                        humidity = _cfg.baseHumidityReference + humidityOffset
                            + _cfg.windFetchMoisture * fetchMoisture
                            + _cfg.coastInfluence * coastProximity
                            - _cfg.inlandDryness * continentality
                            - relief * _cfg.terrainReliefMoisturePenalty
                            + orographic
                            - rainShadow
                            + moistureNoise.Sample(dir) * _cfg.moistureNoiseAmplitude;

                        // ★ 平滑海岸下限：用连续权重把海岸附近“托”到目标湿度，
                        // 代替旧版 `if (coastProximity >= threshold) humidity = max(...)`
                        // 的硬阈值——那条硬阈值正是气候图出现等距断层的根因之一。
                        float coastWeight = Mathf.SmoothStep(0f, 1f,
                            Mathf.InverseLerp(_cfg.coastProximityThreshold * 0.45f,
                                _cfg.coastProximityThreshold + 0.25f, coastProximity));
                        float coastTarget = _cfg.minCoastHumidity + humidityOffset * 0.5f;
                        humidity = Mathf.Lerp(humidity, Mathf.Max(humidity, coastTarget), coastWeight * 0.85f);
                    }

                    float precipitation = isOcean
                        ? 100f
                        : Mathf.Clamp(humidity - altitudeNorm * _cfg.altitudePrecipitationPenalty
                            + windLift * _cfg.orographicMoistureBonus * 0.3f, 0f, 100f);

                    // 干旱区增温：放在湿度之后，让“缺水 + 高温”形成正反馈，
                    // 同时不引入任何离散分支（连续权重）。
                    if (!isOcean)
                    {
                        float dryHeat = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(55f, 15f, humidity));
                        temperature += dryHeat * _cfg.aridHeatBonus * Mathf.Max(0f, solar);
                    }

                    result.Temperature[i] = Mathf.Clamp(temperature, -60f, 60f);
                    result.Humidity[i] = Mathf.Clamp(humidity, 4f, 100f);
                    result.Precipitation[i] = precipitation;
                }
            }

            // ★ 新增：对陆地温湿度做两次小范围平滑。
            // 迎风/背风在真实山脊上本来就是突变；低分辨率纹理若逐像素保留，
            // 会被玩家看成“气候断层”。扩散几像素后既保留雨影，又消除刀切边。
            SmoothLandField(result, res, result.Temperature, 3);
            SmoothLandField(result, res, result.Humidity, 3);

            BuildColorsAndStats(result, res, altitudeRange);

            // ★ 球面首尾经线一致 + 两极收敛为同一颜色，消除纹理接缝/极点 pinch 断层。
            // ★ 修复（防Bug回归）：像元中心不在经线/极点上，强行复制边界行列会制造一圈不连续。
            // 球面方向采样本身连续，纹理 U Repeat / V Clamp 负责边界插值。

            return result;
        }

        /// <summary>只对陆地像元做 3x3 平均，避免把海洋 100% 湿度扩散到海岸。</summary>
        private static void SmoothLandField(PlanetClimateResult result, int res, float[] field, int iterations)
        {
            var buffer = new float[field.Length];
            for (int pass = 0; pass < iterations; pass++)
            {
                for (int y = 0; y < res; y++)
                {
                    for (int x = 0; x < res; x++)
                    {
                        int i = y * res + x;
                        if (result.Ocean[i]) { buffer[i] = field[i]; continue; }

                        float sum = 0f;
                        int n = 0;
                        for (int dy = -1; dy <= 1; dy++)
                        {
                            int ny = Mathf.Clamp(y + dy, 0, res - 1);
                            for (int dx = -1; dx <= 1; dx++)
                            {
                                int nx = (x + dx + res) % res;
                                int ni = ny * res + nx;
                                if (result.Ocean[ni]) continue;
                                sum += field[ni];
                                n++;
                            }
                        }
                        buffer[i] = n > 0 ? sum / n : field[i];
                    }
                }
                System.Array.Copy(buffer, field, field.Length);
            }
        }

        private void BuildColorsAndStats(PlanetClimateResult result, int res, float altitudeRange)
        {
            for (int y = 0; y < res; y++)
            {
                for (int x = 0; x < res; x++)
                {
                    int i = y * res + x;
                    bool isOcean = result.Ocean[i];
                    float temperature = result.Temperature[i];
                    float humidity = result.Humidity[i];
                    float altitudeNorm = isOcean
                        ? 0f
                        : Mathf.Clamp01((result.Height[i] - _data.SeaLevel) / altitudeRange);

                    var type = _cfg.Classify(temperature, humidity, isOcean);
                    result.Types[i] = type;
                    result.Pixels[i] = EvaluateBiomeColor(temperature, humidity, altitudeNorm,
                        result.CoastProximity[i], result.Relief[i], isOcean);

                    if (isOcean) continue;
                    result.LandCells++;
                    if (type == ClimateType.Desert) result.DesertCells++;
                    else if (type == ClimateType.PolarIce || type == ClimateType.Tundra) result.SnowCells++;
                    if (temperature < result.MinTemperature) result.MinTemperature = temperature;
                    if (temperature > result.MaxTemperature) result.MaxTemperature = temperature;
                    if (humidity < result.MinHumidity) result.MinHumidity = humidity;
                    if (humidity > result.MaxHumidity) result.MaxHumidity = humidity;
                }
            }
        }

        /// <summary>多源 BFS 求到最近海洋的像素距离（x 方向环绕）。</summary>
        private static int[] BuildCoastDistance(bool[] ocean, int res)
        {
            int count = res * res;
            var distance = new int[count];
            var queue = new System.Collections.Generic.Queue<int>(count / 4);

            for (int i = 0; i < count; i++)
            {
                if (ocean[i]) { distance[i] = 0; queue.Enqueue(i); }
                else distance[i] = -1;
            }

            while (queue.Count > 0)
            {
                int index = queue.Dequeue();
                int x = index % res;
                int y = index / res;
                int next = distance[index] + 1;

                Try(x == 0 ? res - 1 : x - 1, y);
                Try(x == res - 1 ? 0 : x + 1, y);
                Try(x, y - 1);
                Try(x, y + 1);

                void Try(int nx, int ny)
                {
                    if (ny < 0 || ny >= res) return;
                    int ni = ny * res + nx;
                    if (distance[ni] >= 0) return;
                    distance[ni] = next;
                    queue.Enqueue(ni);
                }
            }

            for (int i = 0; i < count; i++)
                if (distance[i] < 0) distance[i] = res;

            return distance;
        }

        /// <summary>
        /// 在 coarse 分辨率上，从每个陆地格沿上风方向步进，找到海洋为止。
        /// 返回值 0=紧邻海洋，1=上风方向一直是陆地（最干燥）。
        /// </summary>
        private float[] BuildCoarseWindFetch(int coarse)
        {
            int count = coarse * coarse;
            var fetch = new float[count];
            Vector3 windDir = _cfg.GetWindDirection();
            int steps = Mathf.Clamp(_cfg.windFetchSteps, 16, 160);
            float stepAngle = 2.0f / coarse;

            var heights = new float[count];
            var ocean = new bool[count];
            for (int y = 0; y < coarse; y++)
            {
                float v = (y + 0.5f) / coarse;
                for (int x = 0; x < coarse; x++)
                {
                    int i = y * coarse + x;
                    Vector3 dir = PlanetTerrainSampler.DirectionFromUV((x + 0.5f) / coarse, v);
                    heights[i] = PlanetTerrainSampler.SampleHeight(_data, dir);
                    ocean[i] = heights[i] < _data.SeaLevel;
                }
            }

            for (int y = 0; y < coarse; y++)
            {
                float v = (y + 0.5f) / coarse;
                for (int x = 0; x < coarse; x++)
                {
                    int i = y * coarse + x;
                    if (ocean[i]) { fetch[i] = 0f; continue; }

                    Vector3 p = PlanetTerrainSampler.DirectionFromUV((x + 0.5f) / coarse, v);
                    float found = 1f;
                    for (int step = 1; step <= steps; step++)
                    {
                        // 沿球面逆风走：把风向量投影到切平面，再向反方向旋转。
                        Vector3 tangent = Vector3.ProjectOnPlane(windDir, p);
                        if (tangent.sqrMagnitude < 1e-8f) break;
                        tangent.Normalize();
                        p = (p * Mathf.Cos(stepAngle) - tangent * Mathf.Sin(stepAngle)).normalized;

                        if (PlanetTerrainSampler.SampleHeight(_data, p) < _data.SeaLevel)
                        {
                            found = (float)step / steps;
                            break;
                        }
                    }
                    fetch[i] = found;
                }
            }

            // 轻量平滑，避免 coarse 格点插值后出现网格感。
            var smoothed = new float[count];
            for (int y = 0; y < coarse; y++)
            {
                for (int x = 0; x < coarse; x++)
                {
                    float sum = 0f;
                    int n = 0;
                    for (int dy = -1; dy <= 1; dy++)
                    {
                        int ny = Mathf.Clamp(y + dy, 0, coarse - 1);
                        int row = ny * coarse;
                        for (int dx = -1; dx <= 1; dx++)
                        {
                            int nx = (x + dx + coarse) % coarse;
                            sum += fetch[row + nx];
                            n++;
                        }
                    }
                    smoothed[y * coarse + x] = sum / n;
                }
            }
            return smoothed;
        }

        private static float SampleCoarseBilinear(float[] data, int coarse, float u, float v)
        {
            float fx = u * coarse - 0.5f;
            float fy = Mathf.Clamp(v * coarse - 0.5f, 0f, coarse - 1.001f);
            int x0 = Mathf.FloorToInt(fx);
            int y0 = Mathf.FloorToInt(fy);
            float tx = fx - x0;
            float ty = fy - y0;
            int x1 = (x0 + 1) % coarse;
            x0 = (x0 % coarse + coarse) % coarse;
            int y1 = Mathf.Clamp(y0 + 1, 0, coarse - 1);
            y0 = Mathf.Clamp(y0, 0, coarse - 1);

            float a = Mathf.Lerp(data[y0 * coarse + x0], data[y0 * coarse + x1], tx);
            float b = Mathf.Lerp(data[y1 * coarse + x0], data[y1 * coarse + x1], tx);
            return Mathf.Lerp(a, b, ty);
        }

        /// <summary>
        /// 迎风抬升 / 背风雨影，都写成连续权重 0~1。
        /// 旧版用 max(0, ±局部坡度) 在 1 像素内从 +26 翻到 -24，正是山区
        /// 湿度图出现狭长“断层”的原因；这里改为在上风方 8~30 像素窗口内
        /// 采样，让过渡自然铺开。
        /// </summary>
        private void ComputeWindExposure(Vector3 dir, float height, Vector3 windDir,
            out float lift01, out float rainShadow01)
        {
            lift01 = 0f;
            rainShadow01 = 0f;

            Vector3 tangent = Vector3.ProjectOnPlane(windDir, dir);
            if (tangent.sqrMagnitude < 1e-8f) return;
            tangent.Normalize();

            // 上风方三个距离：近处判断抬升，远处判断是否被山体挡住了水汽。
            float upNear = PlanetTerrainSampler.SampleHeight(_data, (dir - tangent * 0.015f).normalized);
            float upMid = PlanetTerrainSampler.SampleHeight(_data, (dir - tangent * 0.035f).normalized);
            float upFar = PlanetTerrainSampler.SampleHeight(_data, (dir - tangent * 0.065f).normalized);

            float rise = height - upNear;
            lift01 = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.01f, 0.12f, rise));

            float blocked = Mathf.Max(upMid, upFar) - height;
            float shadow = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.02f, 0.14f, blocked));
            rainShadow01 = shadow * (1f - lift01);
        }

        /// <summary>
        /// 一次采样四邻域，同时得到局部起伏（山地更干）和盆地冷空气堆积。
        /// ★ 优化：旧版把这两件事拆成两次四邻域采样，气候图每像元多跑 4 次高度插值。
        /// </summary>
        private void SampleNeighbourhood(Vector3 dir, float centerHeight,
            out float relief01, out float coldPool01)
        {
            Vector3 axis = Mathf.Abs(Vector3.Dot(dir, Vector3.up)) > 0.99f ? Vector3.right : Vector3.up;
            Vector3 tangent = Vector3.Cross(dir, axis).normalized;
            Vector3 bitangent = Vector3.Cross(dir, tangent).normalized;
            const float reliefStep = 0.006f;
            const float basinStep = 0.018f;

            float h1 = PlanetTerrainSampler.SampleHeight(_data, (dir + tangent * reliefStep).normalized);
            float h2 = PlanetTerrainSampler.SampleHeight(_data, (dir - tangent * reliefStep).normalized);
            float h3 = PlanetTerrainSampler.SampleHeight(_data, (dir + bitangent * reliefStep).normalized);
            float h4 = PlanetTerrainSampler.SampleHeight(_data, (dir - bitangent * reliefStep).normalized);

            float maxDiff = Mathf.Max(
                Mathf.Max(Mathf.Abs(h1 - centerHeight), Mathf.Abs(h2 - centerHeight)),
                Mathf.Max(Mathf.Abs(h3 - centerHeight), Mathf.Abs(h4 - centerHeight)));
            relief01 = Mathf.Clamp01(maxDiff * 12f);

            // 用较远一圈的四个方向估计周围地势，避免把山峰本身当成盆地。
            float b1 = PlanetTerrainSampler.SampleHeight(_data, (dir + tangent * basinStep).normalized);
            float b2 = PlanetTerrainSampler.SampleHeight(_data, (dir - tangent * basinStep).normalized);
            float b3 = PlanetTerrainSampler.SampleHeight(_data, (dir + bitangent * basinStep).normalized);
            float b4 = PlanetTerrainSampler.SampleHeight(_data, (dir - bitangent * basinStep).normalized);
            float avg = (b1 + b2 + b3 + b4) * 0.25f;
            coldPool01 = Mathf.Clamp01((avg - centerHeight) * 8f);
        }

        /// <summary>连续混色：所有生态色都按权重叠加，没有离散 if/else。</summary>
        private Color EvaluateBiomeColor(float temperature, float humidity, float altitudeNorm,
            float coastProximity, float relief, bool isOcean)
        {
            if (isOcean)
            {
                float oceanWarmT = Mathf.InverseLerp(-5f, 30f, temperature);
                return Color.Lerp(_cfg.oceanCold, _cfg.oceanWarm, oceanWarmT);
            }

            float wet = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(18f, 85f, humidity));
            float warm = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(4f, 30f, temperature));
            // 干旱权重直接由湿度决定，和 Classify 的沙漠阈值保持一致，
            // 避免“分类是草原、颜色却是沙漠黄”的观感错位。
            float arid = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(38f, 14f, humidity))
                * Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(4f, 18f, temperature));
            float cold = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(_cfg.tundraTemp + 6f, _cfg.tundraTemp - 6f, temperature));
            float ice = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(_cfg.polarIceTemp + 6f, _cfg.polarIceTemp - 6f, temperature));

            Color color = Color.Lerp(_cfg.savanna, _cfg.grassland, Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.25f, 0.55f, wet)));
            color = Color.Lerp(color, _cfg.forest, Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.45f, 0.72f, wet)));
            color = Color.Lerp(color, _cfg.rainforest, Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.65f, 0.92f, wet)) * warm);
            color = Color.Lerp(color, _cfg.desert, arid * (1f - cold));
            color = Color.Lerp(color, _cfg.tundra, cold);
            color = Color.Lerp(color, _cfg.polarIce, ice);

            // 高山岩石与雪线：只影响真正的高海拔区域，避免整片大陆变白。
            float rock = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.35f, 0.75f, altitudeNorm))
                * Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.1f, 0.5f, relief));
            color = Color.Lerp(color, _cfg.rock, rock * 0.75f);

            float snowLine = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.55f, 0.85f, altitudeNorm))
                * Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(2f, -8f, temperature));
            color = Color.Lerp(color, _cfg.polarIce, snowLine * 0.85f);

            // 低海拔海岸沙滩，只影响很窄的一圈，让海岸线更自然。
            float beach = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.5f, 0.9f, coastProximity))
                * Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(0.06f, 0.005f, altitudeNorm))
                * (1f - cold) * 0.55f;
            color = Color.Lerp(color, _cfg.beach, beach);

            return color;
        }

    }
}

using UnityEngine;
using DarwinPark.Core;

namespace DarwinPark.Planet
{
    public enum ClimateType
    {
        Ocean,          // 海洋
        TropicalRain,   // 热带雨林
        Desert,         // 沙漠
        Grassland,      // 草原
        Forest,         // 温带森林
        Tundra,         // 苔原
        PolarIce        // 极地冰盖
    }

    public struct ClimateData
    {
        public float Temperature;   // 温度 (-50 ~ 50)
        public float Humidity;      // 湿度 (0 ~ 100)
        public float Precipitation; // 降雨量 (0 ~ 100)
        public ClimateType Type;    // 气候类型
    }

    /// <summary>
    /// 星球气候系统。提供接口给实体查询当前气候。
    /// ★ 修复：气候图生成与实体查询共用同一气候模型；实体查询优先读取预计算气候图，
    /// 避免旧版“两张气候表”导致的沿海沙漠、温湿度不一致。
    /// </summary>
    public class PlanetClimateSystem : MonoBehaviour
    {
        public static PlanetClimateSystem Instance { get; private set; }

        [Header("星球基准")]
        public float planetRadius = 300f;

        [Header("气候模型（数据驱动）")]
        public PlanetClimateConfig config = new PlanetClimateConfig();

        private PlanetTerrainMeshBuilder _builder;

        private void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(this); return; }
            Instance = this;

            if (config == null)
            {
                Log.Error(Log.Tag.Planet, "PlanetClimateConfig 为空，使用代码默认气候参数");
                config = new PlanetClimateConfig();
            }
        }

        private void OnDestroy()
        {
            if (Instance == this) Instance = null;
        }

        private void Start()
        {
            _builder = GetComponent<PlanetTerrainMeshBuilder>();
            if (_builder == null)
                Log.Error(Log.Tag.Planet, "PlanetClimateSystem 找不到 PlanetTerrainMeshBuilder，海陆判断将回退为球面半径");
        }

        /// <summary>
        /// 获取世界坐标处的气候数据。
        /// </summary>
        public ClimateData GetClimateAt(Vector3 worldPos)
        {
            // ★ 修复：通过 Core 的 ClimateDataHub 读取季节偏移，
            // 避免 Planet 引用 Environment 而 Environment 又引用 Planet 的循环依赖。
            float seasonalTempOffset = ClimateDataHub.SeasonalTemperatureOffset;
            float seasonalHumidityOffset = ClimateDataHub.SeasonalHumidityOffset;

            // ★ 修复：优先使用气候图预计算值，实体感知与图层显示保持一致。
            if (PlanetClimateMap.Instance != null &&
                PlanetClimateMap.Instance.SampleClimate(worldPos, seasonalTempOffset, seasonalHumidityOffset, out var mapped))
            {
                return mapped;
            }

            return ComputeFallback(worldPos, seasonalTempOffset, seasonalHumidityOffset);
        }

        private ClimateData ComputeFallback(Vector3 worldPos, float tempOffset, float humidityOffset)
        {
            if (_builder == null) _builder = GetComponent<PlanetTerrainMeshBuilder>();
            if (_builder == null) _builder = FindFirstObjectByType<PlanetTerrainMeshBuilder>();

            Vector3 localPos = worldPos - transform.position;
            float distance = localPos.magnitude;
            // ★ 修复：地形数据在星球本地空间；星球被旋转时不能直接用世界方向采样，
            // 否则海陆/海拔判断会随星球自转而漂移。
            Vector3 unitDir = transform.InverseTransformDirection(localPos).normalized;
            // ★ 修复：0°=赤道、90°=极地；旧代码用 Acos(y) 会把极地当成赤道。
            float latDeg = Mathf.Asin(Mathf.Clamp(Mathf.Abs(unitDir.y), 0f, 1f)) * Mathf.Rad2Deg;

            float seaLevel = _builder != null && _builder.Data != null ? _builder.Data.SeaLevel : 0.45f;
            float height = 0f;
            float waterRadius = _builder != null ? _builder.WaterRadius : planetRadius;
            bool isOcean = distance < waterRadius;

            if (_builder != null && _builder.Data != null)
            {
                height = PlanetTerrainSampler.SampleHeight(_builder.Data, unitDir);
            }

            float altitudeNorm = Mathf.Clamp01(
                (height - seaLevel) / Mathf.Max(0.01f, PlanetTerrainData.MaxNormalizedHeight - seaLevel));
            var cfg = config ?? new PlanetClimateConfig();
            float latCurve = Mathf.Pow(Mathf.Cos(latDeg * Mathf.Deg2Rad), Mathf.Max(0.1f, cfg.latitudeTempExponent));


            // ★ 适配：初始化回退也必须遵循辐射权重，避免前后出现完全不同的纬度气候带。
            float temp = Mathf.Lerp(cfg.regionalTemperature, Mathf.Lerp(cfg.poleTemp, cfg.equatorTemp, latCurve), cfg.solarTemperatureWeight);
            temp += ClimateDataHub.BaseTemperature - cfg.baseTemperatureReference;
            temp -= altitudeNorm * cfg.altitudeTempDrop;

            // 气候图未就绪时的最小回退：只代表“高空/内陆更干”，不参与正式气候生成。
            float humidity = 55f
                + ClimateDataHub.BaseHumidity - cfg.baseHumidityReference
                - altitudeNorm * 18f;

            if (isOcean)
            {
                float oceanTarget = Mathf.Lerp(cfg.regionalTemperature, Mathf.Lerp(cfg.oceanPoleTemp, cfg.oceanEquatorTemp, latCurve), cfg.solarTemperatureWeight);
                temp = Mathf.Lerp(temp, oceanTarget, cfg.oceanTempModeration);
                humidity = 100f;
            }

            temp = Mathf.Clamp(temp + tempOffset, -60f, 70f);
            humidity = Mathf.Clamp(humidity + humidityOffset, 0f, 100f);
            float precipitation = Mathf.Clamp(humidity - altitudeNorm * cfg.altitudePrecipitationPenalty, 0f, 100f);

            return new ClimateData
            {
                Temperature = temp,
                Humidity = humidity,
                Precipitation = precipitation,
                Type = cfg.Classify(temp, humidity, isOcean)
            };
        }
    }
}

using UnityEngine;
using DarwinPark.Core;

namespace DarwinPark.Planet
{
    public class PlanetOreSystem : MonoBehaviour
    {
        public static PlanetOreSystem Instance { get; private set; }

        [Header("矿石分布设置")]
        public int mapResolution = 512;
        public float baseOreChance = 0.4f; // 稍微增加一点覆盖率
        public float noiseScale = 20f; // ★ 核心修复：把频率调高，矿脉就会变碎变自然
        public float maxOreAmount = 100f;
        public float regenRate = 0.5f;

        public Texture2D OreMapTexture { get; private set; }

        private Color[] _oreMapPixels;
        private float _regenTimer;

        private void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(this); return; }
            Instance = this;
        }

        // ★ 修复（防Bug回归）：重进场景后不能沿用已经销毁的静态实例与纹理。
        private void OnDestroy()
        {
            if (Instance == this) Instance = null;
            if (OreMapTexture != null) Destroy(OreMapTexture);
        }

        private void Start()
        {
            GenerateOreMap();
        }

        private void GenerateOreMap()
        {
            OreMapTexture = new Texture2D(mapResolution, mapResolution, TextureFormat.RGBA32, false, true);
            // ★ 修复（防Bug回归）：矿量属于线性数据；经度环绕，纬度不能从北极跨到南极。
            OreMapTexture.wrapModeU = TextureWrapMode.Repeat;
            OreMapTexture.wrapModeV = TextureWrapMode.Clamp;
            OreMapTexture.filterMode = FilterMode.Bilinear;
            _oreMapPixels = new Color[mapResolution * mapResolution];

            for (int y = 0; y < mapResolution; y++)
            {
                for (int x = 0; x < mapResolution; x++)
                {
                    // ★ 修改：使用分形噪声生成更碎的矿斑
                    float nx = (float)x / mapResolution * noiseScale;
                    float ny = (float)y / mapResolution * noiseScale;
                    float noise1 = Mathf.PerlinNoise(nx + 100f, ny + 100f);
                    float noise2 = Mathf.PerlinNoise(nx * 3f + 50f, ny * 3f + 50f) * 0.4f;

                    float finalNoise = (noise1 + noise2) / 1.4f;

                    // ★ 修改：降低阈值，增加分布面积，并将对比度拉高
                    // ★ 修复（防Bug回归）：采用 Inspector 的分布参数，避免配置字段被硬编码覆盖。
                    float threshold = 1f - Mathf.Clamp01(baseOreChance); // 越低矿越多
                    float amount = 0f;
                    if (finalNoise > threshold)
                    {
                        // 用 Lerp 让从边缘到中心有从 0 到 1 的平滑过渡
                        amount = Mathf.Clamp01((finalNoise - threshold) / (1f - threshold));
                        amount = Mathf.Pow(amount, 1.5f); // 强化中心亮度
                    }

                    // ★ 强制提高 R 通道的存储亮度
                    _oreMapPixels[y * mapResolution + x] = new Color(amount, 0, 0, 1);
                }
            }
            OreMapTexture.SetPixels(_oreMapPixels);
            OreMapTexture.Apply();
            Debug.Log("[OreSystem] 矿石分布图生成完毕。");
        }

        private void Update()
        {
            // ★ 修复（防Bug回归）：新矿脉系统启用后须遵循模拟暂停，且纹理未就绪时不能刷新。
            if (_oreMapPixels == null || OreMapTexture == null) return;
            float dt = Time.deltaTime;
            if (ServiceLocator.TryGet<SimulationClock>(out var clock))
            {
                if (!clock.IsRunning) return;
                dt = clock.GameDeltaTime;
            }
            _regenTimer += dt;
            if (_regenTimer >= 1f)
            {
                _regenTimer = 0;
                for (int i = 0; i < _oreMapPixels.Length; i++)
                {
                    if (_oreMapPixels[i].r < 1f && _oreMapPixels[i].r > 0f)
                    {
                        float r = _oreMapPixels[i].r + (regenRate / maxOreAmount);
                        _oreMapPixels[i] = new Color(Mathf.Min(1f, r), 0, 0, 1);
                    }
                }
                OreMapTexture.SetPixels(_oreMapPixels);
                OreMapTexture.Apply();
            }
        }

        // ★ 适配：矿脉消耗与再生状态必须存档，不能只按种子重建资源。
        public float[] CaptureAmounts(){if(_oreMapPixels==null)return null;var values=new float[_oreMapPixels.Length];for(int i=0;i<values.Length;i++)values[i]=_oreMapPixels[i].r;return values;}
        public float RegenTimer {get=>_regenTimer;set=>_regenTimer=value;}
        public void RestoreAmounts(float[] values,int resolution)
        {
            if(values==null||values.Length!=resolution*resolution)throw new System.IO.InvalidDataException("矿脉存档尺寸无效");
            if(OreMapTexture!=null)Destroy(OreMapTexture);mapResolution=resolution;
            OreMapTexture=new Texture2D(resolution,resolution,TextureFormat.RGBA32,false,true){wrapModeU=TextureWrapMode.Repeat,wrapModeV=TextureWrapMode.Clamp,filterMode=FilterMode.Bilinear};
            _oreMapPixels=new Color[values.Length];for(int i=0;i<values.Length;i++)_oreMapPixels[i]=new Color(values[i],0,0,1);
            OreMapTexture.SetPixels(_oreMapPixels);OreMapTexture.Apply();
        }
        public void ResetWorld(){if(OreMapTexture!=null)Destroy(OreMapTexture);_regenTimer=0;GenerateOreMap();}
        /// <summary>
        /// 世界坐标转 UV
        /// </summary>
        private Vector2 WorldToUV(Vector3 worldPos)
        {
            Vector3 localPos = transform.InverseTransformPoint(worldPos).normalized;
            float u = (Mathf.Atan2(localPos.x, localPos.z) / (2f * Mathf.PI)) + 0.5f;
            float v = (Mathf.Asin(localPos.y) / Mathf.PI) + 0.5f;
            return new Vector2(u, v);
        }

        public float GetOreAmount(Vector3 worldPos)
        {
            if (OreMapTexture == null) return 0f;
            Vector2 uv = WorldToUV(worldPos);
            int x = Mathf.Clamp((int)(uv.x * mapResolution), 0, mapResolution - 1);
            int y = Mathf.Clamp((int)(uv.y * mapResolution), 0, mapResolution - 1);
            return _oreMapPixels[y * mapResolution + x].r * maxOreAmount;
        }

        public float ConsumeOre(Vector3 worldPos, float amount)
        {
            if (OreMapTexture == null) return 0f;
            Vector2 uv = WorldToUV(worldPos);
            int x = Mathf.Clamp((int)(uv.x * mapResolution), 0, mapResolution - 1);
            int y = Mathf.Clamp((int)(uv.y * mapResolution), 0, mapResolution - 1);

            int index = y * mapResolution + x;
            float current = _oreMapPixels[index].r * maxOreAmount;
            float actualConsume = Mathf.Min(amount, current);

            if (actualConsume > 0)
            {
                float newValue = (current - actualConsume) / maxOreAmount;
                _oreMapPixels[index] = new Color(newValue, 0, 0, 1);
                OreMapTexture.SetPixels(_oreMapPixels);
                OreMapTexture.Apply();
            }
            return actualConsume;
        }
    }
}

using UnityEngine;

namespace DarwinPark.Planet
{
    /// <summary>让星球缓慢自转。</summary>
    public class PlanetRotator : MonoBehaviour
    {
        public float rotationSpeed = 10f;

        private void Update()
        {
            // ★ 修复（防Bug回归）：暂停与加载期间星球不推进；菜单背景另用预录视频。
            float dt=DarwinPark.Core.ServiceLocator.TryGet<DarwinPark.Core.SimulationClock>(out var clock)?clock.GameDeltaTime:Time.deltaTime;
            transform.Rotate(Vector3.up, rotationSpeed * dt);
        }
    }
}

using UnityEngine;

namespace DarwinPark.Planet
{
    public class PlanetVisuals : MonoBehaviour
    {
        public float starRadius = 2500f;
        public int starCount = 1800;
        // ★ 修复（防Bug回归）：原来 8 米的白色方块星星遮挡画面，改为可调的小型静态星点。
        public float starSize = 1.2f;

        void Start()
        {
            // ★ 适配：海面、大气和体积云由场景上的 PlanetWeatherVisuals 独立管理。
            SetupStars();
        }

        private void SetupStars()
        {
            if (GameObject.Find("Starfield") != null) return;

            GameObject starfield = new GameObject("Starfield");
            var ps = starfield.AddComponent<ParticleSystem>();

            var main = ps.main;
            main.startColor = Color.white;
            main.startSize = starSize;
            main.startLifetime = float.MaxValue;
            main.loop = false;
            main.startSpeed = 0f;
            main.maxParticles = starCount;
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.playOnAwake = false;

            var emission = ps.emission;
            emission.rateOverTime = 0;
            emission.SetBursts(new ParticleSystem.Burst[] { new ParticleSystem.Burst(0, (short)starCount) });

            var shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = starRadius;
            shape.radiusThickness = 0f;

            var renderer = ps.GetComponent<ParticleSystemRenderer>();
            renderer.material = new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));
            renderer.material.color = Color.white;

            starfield.transform.position = transform.position;
            ps.Play();
        }
    }
}

using UnityEngine;
using UnityEngine.Rendering;
using DarwinPark.Core;

namespace DarwinPark.Planet
{
    /// <summary>★ 新增：独立海面、体积云和薄大气层；不改变地形碰撞及气候数据。</summary>
    [RequireComponent(typeof(PlanetTerrainMeshBuilder))]
    public sealed class PlanetWeatherVisuals : MonoBehaviour
    {
        public Shader oceanShader, cloudShader, atmosphereShader;
        [Header("海洋")]
        public Color shallowWater = new Color(0.12f, 0.62f, 0.82f);
        public Color deepWater = new Color(0.015f, 0.13f, 0.32f);
        public float shelfDepth = 3f;
        [Header("云层（海平面以上高度，山峰可穿出云层）")]
        public bool showClouds = true;
        [Tooltip("相机距海平面低于此高度时隐藏体积云，便于观察地面实体")]
        public float hideCloudsBelowAltitude = 100f;
        public float cloudClearance = 3f;
        public float cloudThickness = 5f;
        [Range(0f, 1f)] public float cloudCoverage = 0.48f;
        public float cloudFrequency = 9f;
        public float cloudDetail = 80f;
        public float cloudSpeed = 0.3f;
        public float cloudDensity = 3.5f;
        [Range(6, 24)] public int cloudSteps = 8;
        [Header("大气")]
        public float atmosphereThickness = 12f;
        public float atmosphereDensity = 0.08f;
        public Color atmosphereColor = new Color(0.2f, 0.52f, 1f);
        private Mesh _oceanMesh, _cloudMesh, _atmosphereMesh;
        private Material _oceanMaterial, _cloudMaterial, _atmosphereMaterial;
        private GameObject _ocean, _clouds, _atmosphere;
        private PlanetTerrainMeshBuilder _builder;
        private MaterialPropertyBlock _sourceBlock;

        public void Rebuild()
        {
            _builder = GetComponent<PlanetTerrainMeshBuilder>();
            var data = _builder.Data;
            if (data == null) return;
            Release();
            float sea = _builder.WaterRadius;
            // ★ 适配：轨道相机必须停在海面以上，不能只靠海底碰撞体限制拉近。
            var orbit=Camera.main != null ? Camera.main.GetComponent<OrbitCamera>() : null;
            if(orbit != null) orbit.minimumSurfaceRadius=sea;
            // ★ 修复（防Bug回归）：云层以海平面为基准，否则一座山会将全球云层撑成远离地表的空心壳。
            float cloudBottom = sea + cloudClearance;
            float cloudTop = cloudBottom + cloudThickness;
            float atmosphereTop = cloudTop + atmosphereThickness;
            _ocean = CreateShell("OceanSurface", data, sea, oceanShader, ref _oceanMesh, out _oceanMaterial);
            if (_oceanMaterial != null)
            {
                var depth = new Color[data.Vertices.Length];
                for (int i = 0; i < depth.Length; i++)
                {
                    float h = PlanetTerrainSampler.SampleHeight(data, data.Vertices[i].normalized);
                    depth[i] = new Color(Mathf.Clamp01((data.SeaLevel - h) * data.HeightScale / Mathf.Max(0.1f, shelfDepth)), 0, 0, 1);
                }
                _oceanMesh.colors = depth;
                _oceanMaterial.SetColor("_ShallowColor", shallowWater);
                _oceanMaterial.SetColor("_DeepColor", deepWater);
            }
            _clouds = CreateShell("CloudVolume", data, cloudTop, cloudShader, ref _cloudMesh, out _cloudMaterial);
            if (_cloudMaterial != null)
            {
                _cloudMaterial.SetFloat("_BottomRadius", cloudBottom);
                _cloudMaterial.SetFloat("_TopRadius", cloudTop);
                _cloudMaterial.SetFloat("_Coverage", cloudCoverage);
                _cloudMaterial.SetFloat("_Frequency", cloudFrequency);
                _cloudMaterial.SetFloat("_Detail", cloudDetail);
                _cloudMaterial.SetFloat("_Density", cloudDensity);
                _cloudMaterial.SetFloat("_Steps", cloudSteps);
            }
            _atmosphere = CreateShell("AtmosphericScattering", data, atmosphereTop, atmosphereShader,
                ref _atmosphereMesh, out _atmosphereMaterial);
            if (_atmosphereMaterial != null)
            {
                _atmosphereMaterial.SetFloat("_SurfaceRadius", sea);
                _atmosphereMaterial.SetFloat("_OuterRadius", atmosphereTop);
                _atmosphereMaterial.SetFloat("_Density", atmosphereDensity);
                _atmosphereMaterial.SetColor("_ScatterColor", atmosphereColor);
            }
            _sourceBlock = new MaterialPropertyBlock();
        }

        private GameObject CreateShell(string name, PlanetTerrainData data, float radius, Shader shader,
            ref Mesh mesh, out Material material)
        {
            material = null;
            if (shader == null || !shader.isSupported)
            {
                Debug.LogError($"[PlanetWeather] {name} 缺少可用 Shader，请检查场景引用。", this);
                return null;
            }
            var vertices = new Vector3[data.Vertices.Length];
            var normals = new Vector3[vertices.Length];
            for (int i = 0; i < vertices.Length; i++)
            {
                normals[i] = data.Vertices[i].normalized;
                vertices[i] = normals[i] * radius;
            }
            mesh = new Mesh { name = name, indexFormat = IndexFormat.UInt32 };
            // ★ 修复（防Bug回归）：壳层按自身球面校正每个三角形绕序，不能沿用受陡坡影响的面剔除结果。
            var triangles = (int[])data.Triangles.Clone();
            for (int i = 0; i < triangles.Length; i += 3)
            {
                Vector3 a = vertices[triangles[i]], b = vertices[triangles[i+1]], c = vertices[triangles[i+2]];
                if (Vector3.Dot(Vector3.Cross(b-a,c-a), a+b+c) < 0)
                { int t = triangles[i+1]; triangles[i+1] = triangles[i+2]; triangles[i+2] = t; }
            }
            mesh.vertices = vertices; mesh.normals = normals; mesh.triangles = triangles;
            mesh.RecalculateBounds();
            var go = new GameObject(name, typeof(MeshFilter), typeof(MeshRenderer));
            go.layer = gameObject.layer;
            go.transform.SetParent(transform, false);
            go.GetComponent<MeshFilter>().sharedMesh = mesh;
            var renderer = go.GetComponent<MeshRenderer>();
            material = new Material(shader) { name = name + " (Runtime)" };
            renderer.sharedMaterial = material;
            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;
            return go;
        }

        private void LateUpdate()
        {
            if (_builder == null || _sourceBlock == null) return;
            GetComponent<MeshRenderer>().GetPropertyBlock(_sourceBlock);
            float layer = _sourceBlock.GetFloat("_LayerMode");
            // 数据图层关闭天气遮挡，海面延续同一气候/矿石图，保持图层切换完整。
            // ★ 修复（防Bug回归）：靠近地表自动隐藏云层；拉远恢复，独立保留用户总开关与数据层规则。
            var camera = Camera.main;
            float altitude = camera != null ? transform.InverseTransformPoint(camera.transform.position).magnitude - _builder.WaterRadius : float.MaxValue;
            if (_clouds != null) _clouds.SetActive(showClouds && layer < 0.5f && altitude > hideCloudsBelowAltitude);
            if (_oceanMaterial != null)
            {
                _oceanMaterial.SetFloat("_LayerMode", layer);
                _oceanMaterial.SetFloat("_ClimateReady", _sourceBlock.GetFloat("_ClimateReady"));
                _oceanMaterial.SetTexture("_ClimateMap", _sourceBlock.GetTexture("_ClimateMap"));
                _oceanMaterial.SetTexture("_OreMap", _sourceBlock.GetTexture("_OreMap"));
            }
            if (_clouds != null && _clouds.activeSelf)
                _clouds.transform.Rotate(Vector3.up, cloudSpeed * Time.deltaTime, Space.Self);
        }

        private void Release()
        {
            // 重建先停用旧壳，避免延迟销毁造成两层共面闪烁。
            foreach (var go in new[] { _ocean, _clouds, _atmosphere })
                if (go != null) { go.SetActive(false); Destroy(go); }
            foreach (var mesh in new[] { _oceanMesh, _cloudMesh, _atmosphereMesh })
                if (mesh != null) Destroy(mesh);
            foreach (var mat in new[] { _oceanMaterial, _cloudMaterial, _atmosphereMaterial })
                if (mat != null) Destroy(mat);
        }
        private void OnDestroy() => Release();
    }
}

using UnityEngine;
using DarwinPark.Core; // ★ 确保引入 Core 命名空间

namespace DarwinPark.Planet
{
    public class SunSystem : MonoBehaviour
    {
        [Header("公转设置")]
        public Transform planet;
        public float distanceToPlanet = 800f;

        [Header("光照强度配置")]
        [Range(0f, 5f)] public float sunLightIntensity = 1.5f;
        [Range(0f, 5f)] public float ambientLightIntensity = 1.0f;

        [Header("环境光颜色配置 (受控)")]
        public Color ambientSkyColor = new Color(0.4f, 0.5f, 0.7f);
        public Color ambientEquatorColor = new Color(0.3f, 0.3f, 0.3f);
        public Color ambientGroundColor = new Color(0.1f, 0.1f, 0.1f);

        private Light _sunLight;
        private Transform _sunVisual;

        // ★ 修复：确保这里是带下划线的 _angle
        private float _angle = 45f;
        // ★ 适配：太阳公转相位成对保存/恢复，避免读档昼夜跳变。
        public float OrbitAngle {get=>_angle;set=>_angle=Mathf.Repeat(value,360); }

        void Start()
        {
            if (planet == null) planet = GameObject.Find("Planet")?.transform;

            _sunLight = GetComponent<Light>();
            if (_sunLight == null) _sunLight = gameObject.AddComponent<Light>();
            _sunLight.type = LightType.Directional;
            _sunLight.color = Color.white;
            _sunLight.shadows = LightShadows.Soft;

            GameObject sunGO = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            sunGO.name = "Sun_Visual_Model";
            Destroy(sunGO.GetComponent<Collider>());
            _sunVisual = sunGO.transform;
            var renderer = sunGO.GetComponent<Renderer>();
            var mat = new Material(Shader.Find("Universal Render Pipeline/Unlit"));
            mat.color = new Color(1f, 0.95f, 0.8f);
            renderer.material = mat;
            sunGO.transform.localScale = Vector3.one * 60f;

            ApplyLighting();
        }

        void Update()
        {
            if (planet == null) return;

            float dt = 0f;
            if (ServiceLocator.TryGet<SimulationClock>(out var clock))
            {
                dt = clock.GameDeltaTime;
            }

            if (dt > 0)
            {
                // ★ 修复：全部改为带下划线的 _angle
                _angle += (360f / 10f) * dt; // 10秒转一圈
                if (_angle >= 360f) _angle -= 360f;
            }

            // ★ 修复：改用 _angle
            Quaternion rot = Quaternion.Euler(23.5f, _angle, 0);
            transform.position = planet.position + rot * (Vector3.back * distanceToPlanet);
            transform.LookAt(planet.position);

            if (_sunVisual != null) _sunVisual.position = transform.position + transform.forward * 300f;

            ApplyLighting();
        }

        private void ApplyLighting()
        {
            if (_sunLight != null) _sunLight.intensity = sunLightIntensity;

            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Trilight;
            RenderSettings.ambientSkyColor = ambientSkyColor;
            RenderSettings.ambientEquatorColor = ambientEquatorColor;
            RenderSettings.ambientGroundColor = ambientGroundColor;
            RenderSettings.ambientIntensity = ambientLightIntensity;
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace DarwinPark.Planet
{
    /// <summary>★ 新增：按球面方向焊接六面重复顶点，让几何和法线使用同一拓扑。</summary>
    public static class PlanetMeshTopology
    {
        public static void Weld(PlanetTerrainData data)
        {
            var lookup = new Dictionary<Vector3Int, int>();
            var vertices = new List<Vector3>();
            var remap = new int[data.Vertices.Length];
            for (int i = 0; i < remap.Length; i++)
            {
                Vector3 p = data.Vertices[i];
                Vector3 d = p.normalized;
                var key = new Vector3Int(Mathf.RoundToInt(d.x * 100000f),
                    Mathf.RoundToInt(d.y * 100000f), Mathf.RoundToInt(d.z * 100000f));
                if (!lookup.TryGetValue(key, out int index))
                {
                    index = vertices.Count;
                    lookup.Add(key, index);
                    vertices.Add(p);
                }
                remap[i] = index;
            }
            for (int i = 0; i < data.Triangles.Length; i++)
                data.Triangles[i] = remap[data.Triangles[i]];
            data.Vertices = vertices.ToArray();
        }
    }
}

using UnityEngine;

namespace DarwinPark.Planet
{
    /// <summary>★ 新增：低频连续造山带，细分支只修饰山脊，避免整个大陆长满等高圆丘。</summary>
    public sealed class PlanetMountainField
    {
        private readonly FBMNoise _belt;
        private readonly FBMNoise _detail;
        private readonly PlanetTerrainConfig _config;
        public PlanetMountainField(PlanetTerrainConfig config)
        {
            _config = config;
            _belt = new FBMNoise(new FBMConfig { frequency = config.mountainFrequency,
                octaves = config.mountainOctaves, warpStrength = config.mountainWarp }, config.seed + 500);
            _detail = new FBMNoise(new FBMConfig { frequency = config.mountainFrequency * 18f,
                octaves = 4, warpStrength = config.mountainWarp }, config.seed + 733);
        }
        public float Sample(Vector3 direction)
        {
            // ★ 修复（防Bug回归）：细节既侵蚀山顶也扭曲脊线，避免生成光滑的封闭“火山口”。
            float fine = _detail.Sample(direction);
            float distance = Mathf.Abs(_belt.Sample(direction) + fine * 0.06f);
            float belt = 1f - Mathf.SmoothStep(0f, 1f,
                Mathf.InverseLerp(_config.mountainCoreWidth, _config.mountainBeltWidth, distance));
            float ridge = Mathf.Pow(belt, _config.mountainSharpness);
            float detail = Mathf.Clamp01(1f - Mathf.Abs(fine) * 3f);
            return ridge * Mathf.Lerp(1f - _config.mountainDetailStrength, 1f, detail);
        }
    }
}

using DarwinPark.Core;
using UnityEngine;

namespace DarwinPark.Planet
{
    /// <summary>★ 新增：在球面邻域平滑六面交界坡度；只焊接边缘高度仍会留下侵蚀缓冲带的直线折痕。</summary>
    public static class PlanetSeamContinuity
    {
        public static void Smooth(PlanetTerrainData data, ErosionConfig config)
        {
            if(config==null || config.seamSmoothIterations<=0 || config.seamSmoothCells<=0)return;
            float before=MeanCurvature(data);
            int sub=data.Subdivisions, stride=sub+1;
            float step=2f/sub;
            for(int pass=0;pass<config.seamSmoothIterations;pass++)
            {
                var next=new float[6][];
                for(int face=0;face<6;face++)
                {
                    next[face]=(float[])data.FaceHeights[face].Clone();
                    for(int y=0;y<=sub;y++)for(int x=0;x<=sub;x++)
                    {
                        float edge=Mathf.Min(Mathf.Min(x,y),Mathf.Min(sub-x,sub-y));
                        if(edge>=config.seamSmoothCells)continue;
                        var dir=Direction(face,x,y,sub);
                        var a=Vector3.Cross(dir,Mathf.Abs(dir.y)>.95f?Vector3.right:Vector3.up).normalized*step;
                        var b=Vector3.Cross(dir,a).normalized*step;
                        float average=(PlanetTerrainSampler.SampleHeight(data,(dir+a).normalized)+PlanetTerrainSampler.SampleHeight(data,(dir-a).normalized)
                            +PlanetTerrainSampler.SampleHeight(data,(dir+b).normalized)+PlanetTerrainSampler.SampleHeight(data,(dir-b).normalized))*.25f;
                        float weight=1-Mathf.SmoothStep(0,1,edge/config.seamSmoothCells);
                        int i=y*stride+x;
                        next[face][i]=Mathf.Lerp(data.FaceHeights[face][i],average,Mathf.Clamp01(config.seamSmoothStrength)*weight);
                    }
                }
                // 所有面都读上一轮快照，不能先改一面再让相邻面读取修改后的边缘。
                data.FaceHeights=next;
            }
            Log.Info(Log.Tag.Planet,$"跨面坡度平滑：接缝曲率 {before:F6} → {MeanCurvature(data):F6}");
        }
        public static Vector3 Direction(int face,int x,int y,int sub)
        {
            float u=2f*x/sub-1,v=2f*y/sub-1;
            return (face==0?new Vector3(1,v,u):face==1?new Vector3(-1,v,u):face==2?new Vector3(u,1,v)
                :face==3?new Vector3(u,-1,v):face==4?new Vector3(u,v,1):new Vector3(u,v,-1)).normalized;
        }
        public static float MeanCurvature(PlanetTerrainData data)
        {
            float sum=0,step=2f/data.Subdivisions;int count=0;
            for(int face=0;face<6;face++)for(int edge=0;edge<4;edge++)for(int i=1;i<data.Subdivisions;i++)
            {
                int x=edge==0?0:edge==1?data.Subdivisions:i;
                int y=edge==2?0:edge==3?data.Subdivisions:i;
                var d=Direction(face,x,y,data.Subdivisions);
                var inside=Direction(face,Mathf.Clamp(x+(edge==0?1:edge==1?-1:0),0,data.Subdivisions),
                    Mathf.Clamp(y+(edge==2?1:edge==3?-1:0),0,data.Subdivisions),data.Subdivisions);
                var t=Vector3.ProjectOnPlane(inside-d,d).normalized*step;
                sum+=Mathf.Abs(PlanetTerrainSampler.SampleHeight(data,(d+t).normalized)+PlanetTerrainSampler.SampleHeight(data,(d-t).normalized)-2*PlanetTerrainSampler.SampleHeight(data,d));count++;
            }
            return sum/Mathf.Max(1,count);
        }
    }
}

