namespace DarwinPark.Planet
{
    /// <summary>地形配置加载。★ 适配：继承 JsonResourceDatabase 消除重复加载逻辑。</summary>
    public class PlanetTerrainConfigDatabase : JsonResourceDatabase<PlanetTerrainConfig>
    {
        public PlanetTerrainConfigDatabase() : base(Log.Tag.Planet) { }

        protected override string ResourceFolder => "Terrain";
        protected override string GetId(PlanetTerrainConfig item) => item.id;

        protected override PlanetTerrainConfig ConvertFromJson(string jsonText, string assetName)
        {
            var cfg = JsonUtility.FromJson<PlanetTerrainConfig>(jsonText);
            if (cfg != null && cfg.subdivisions < 1)
            {
                Log.Error(Log.Tag.Planet, $"{assetName} subdivisions 必须≥1");
                return null;
            }
            return cfg;
        }

        public static readonly PlanetTerrainConfigDatabase Instance = new();
    }
}

using UnityEngine;

namespace DarwinPark.Planet
{
    /// <summary>地形数据（cube-sphere 6 面）。</summary>
    public class PlanetTerrainData
    {
        /// <summary>
        /// ★ 新增：归一化高度的上限。海平面、气候海拔、Shader 都引用该值，
        /// 避免各处分别写死 0.9 导致山脉被截断或雪线错位。
        /// </summary>
        public const float MaxNormalizedHeight = 1f;

        public int Subdivisions;
        public float Radius;
        public float HeightScale;

        // 6 个面，每个面包含 (subdivisions + 1)^2 个高度数据
        public float[][] FaceHeights;

        public Vector3[] Vertices;
        public int[] Triangles;
        public Color[] Colors;
        public Bounds Bounds;
        public float SeaLevel;
    }
}

using System.Collections.Generic;
using UnityEngine;
using DarwinPark.Planet.Erosion;

namespace DarwinPark.Planet
{
    /// <summary>
    /// Cube-Sphere 行星地形生成器。
    /// ★ 修复（防Bug回归）：旧实现的山脉使用“1-|2m-1|”折叠噪声，
    /// 负值会被平方放大，且盆地只有很窄的一条，实际几乎看不到山脉/盆地。
    /// 现在按“大陆基底 → 山脉带 → 盆地 → 峡谷 → 侵蚀”分层雕刻，所有幅度来自配置。
    /// </summary>
    public static class PlanetTerrainGenerator
    {
        private static readonly Vector3[] FaceNormals = { Vector3.right, Vector3.left, Vector3.up, Vector3.down, Vector3.forward, Vector3.back };

        // 用于把 6 个面接缝处的重复顶点合并，避免侵蚀后出现裂缝。
        private const float SeamQuantizeScale = 100000f;

        public static PlanetTerrainData Generate(PlanetTerrainConfig cfg, float seaLevelRatio, float continentRatio)
        {
            if (cfg == null) return null;

            int sub = Mathf.Max(2, cfg.subdivisions);
            int vertsPerFace = (sub + 1) * (sub + 1);
            var data = new PlanetTerrainData
            {
                Subdivisions = sub,
                Radius = cfg.radius,
                HeightScale = cfg.heightScale,
                FaceHeights = new float[6][]
            };

            // 每种地貌使用独立种子，避免山脉、盆地、峡谷全部叠在同一位置。
            var continentNoise = new FBMNoise(cfg.baseNoise, cfg.seed);
            var detailNoise = new FBMNoise(cfg.detailNoise, cfg.seed + 1337);

            // ★ 适配：由独立造山带模型提供连续山系。
            var mountains = new PlanetMountainField(cfg);

            var basinCfg = new FBMConfig
            {
                octaves = 3,
                frequency = cfg.basinFrequency,
                amplitude = 1f,
                lacunarity = 2f,
                gain = 0.5f,
                warpStrength = 0.15f
            };
            var basinNoise = new FBMNoise(basinCfg, cfg.seed + 1777);

            var valleyCfg = new FBMConfig
            {
                octaves = 4,
                frequency = cfg.valleyFrequency,
                amplitude = 1f,
                lacunarity = 2f,
                gain = 0.5f,
                warpStrength = 0.25f
            };
            var valleyNoise = new FBMNoise(valleyCfg, cfg.seed + 2663);

            // 1. 先采样“大陆/海洋”基底，并按目标陆地比例求海平面分位值。
            var rawHeights = new float[6][];
            var allHeights = new List<float>(6 * vertsPerFace);

            for (int face = 0; face < 6; face++)
            {
                var heights = new float[vertsPerFace];
                for (int y = 0; y <= sub; y++)
                {
                    for (int x = 0; x <= sub; x++)
                    {
                        float u = (float)x / sub * 2f - 1f;
                        float v = (float)y / sub * 2f - 1f;
                        Vector3 dir = FacePoint(FaceNormals[face], u, v).normalized;
                        float c = Noise01(continentNoise, dir);

                        heights[y * (sub + 1) + x] = c;
                        allHeights.Add(c);
                    }
                }
                rawHeights[face] = heights;
            }

            allHeights.Sort();
            float landFraction = Mathf.Clamp01(continentRatio);
            int seaIndex = Mathf.FloorToInt((1.0f - landFraction) * allHeights.Count);
            seaIndex = Mathf.Clamp(seaIndex, 0, allHeights.Count - 1);
            float seaLevelThreshold = allHeights[seaIndex];
            // ★ 修复（防Bug回归）：FBM 实际最大值远低于理论上限 1，旧归一化会压低整个大陆的山脉遮罩。
            float landRange = Mathf.Max(0.0001f, allHeights[allHeights.Count - 1] - seaLevelThreshold);
            data.SeaLevel = seaLevelThreshold;

            // 2. 分层雕刻：大陆架 → 山脉带 → 盆地 → 峡谷 → 细节。
            for (int face = 0; face < 6; face++)
            {
                var heights = new float[vertsPerFace];
                for (int y = 0; y <= sub; y++)
                {
                    for (int x = 0; x <= sub; x++)
                    {
                        int i = y * (sub + 1) + x;
                        float c = rawHeights[face][i];
                        float u = (float)x / sub * 2f - 1f;
                        float v = (float)y / sub * 2f - 1f;
                        Vector3 dir = FacePoint(FaceNormals[face], u, v).normalized;

                        float height;
                        if (c < seaLevelThreshold)
                        {
                            // 海洋：近岸平缓、深海下凹，避免整片海床高度相同。
                            float oceanT = seaLevelThreshold > 1e-5f
                                ? Mathf.Clamp01(c / seaLevelThreshold)
                                : 0f;
                            float floor = Mathf.Lerp(
                                seaLevelThreshold * cfg.oceanFloorRatio,
                                seaLevelThreshold,
                                Mathf.Pow(oceanT, 1.8f));
                            floor += detailNoise.Sample(dir) * cfg.detailStrength * 0.4f * (1f - oceanT);
                            height = floor;
                        }
                        else
                        {
                            float land = Mathf.Clamp01((c - seaLevelThreshold) / landRange);

                            // 大陆基底：海岸低平，向内陆逐渐抬升。
                            float baseHeight = seaLevelThreshold + cfg.coastalRise
                                + cfg.inlandRise * Mathf.Pow(land, Mathf.Max(0.1f, cfg.inlandCurve));

                            // 大尺度平原微起伏。
                            baseHeight += detailNoise.Sample(dir) * cfg.detailStrength
                                * (0.4f + land * 0.8f);

                            // ★ 适配：山系只占连续造山带，低地不再被大量等值线山脊淹没。
                            float mountainMask = Mathf.SmoothStep(0f, 1f,
                                Mathf.InverseLerp(cfg.mountainStart, cfg.mountainFull, land));
                            float headroom = Mathf.Max(0f, PlanetTerrainData.MaxNormalizedHeight - baseHeight);
                            baseHeight += mountains.Sample(dir) * cfg.mountainHeight * mountainMask * headroom;

                            // 盆地：宽而浅的碗状洼地，避免旧版只有一条窄带。
                            float basinNoiseValue = Noise01(basinNoise, dir);
                            float basinMask = Mathf.SmoothStep(0f, 1f,
                                Mathf.InverseLerp(cfg.basinThreshold, cfg.basinThreshold + cfg.basinWidth, basinNoiseValue));
                            baseHeight -= basinMask * cfg.basinDepth * (0.35f + land * 0.65f);

                            // 峡谷：脊状噪声的高值线作为河道下切，形成可见的谷地网络。
                            float valleyRaw = valleyNoise.Sample(dir);
                            float valley = Mathf.Pow(Mathf.Clamp01(1f - Mathf.Abs(valleyRaw)), Mathf.Max(0.5f, cfg.valleySharpness));
                            float valleyMask = Mathf.SmoothStep(0.04f, 0.55f, land);
                            baseHeight -= valley * cfg.valleyDepth * valleyMask;

                            // 陆地最低保持在海平面以上一点点，避免内陆盆地变成整片海洋。
                            // ★ 修复（防Bug回归）：盆地可形成湖泊，禁止将所有低地裁成同高度沙色平台。
                            height = baseHeight;
                        }

                        heights[i] = Mathf.Clamp(height, 0f, PlanetTerrainData.MaxNormalizedHeight);
                    }
                }
                data.FaceHeights[face] = heights;
            }

            // 3. 对每个面执行水力/热力侵蚀，再合并接缝顶点。
            ApplyErosion(cfg, data.FaceHeights, sub);
            MergeSeamVertices(data.FaceHeights, sub);

            // ★ 适配：跨面采样邻域平滑坡度，再合并边缘消除浮点误差；世界场与碰撞共用修正后的数据。
            PlanetSeamContinuity.Smooth(data,cfg.erosion);
            MergeSeamVertices(data.FaceHeights,sub);

            BuildMesh(data);
            // ★ 适配：焊接接缝共享索引，消除裂缝与两套法线。
            PlanetMeshTopology.Weld(data);
            return data;
        }

        private static float Noise01(FBMNoise noise, Vector3 dir)
        {
            return Mathf.Clamp01((noise.Sample(dir) + 1f) * 0.5f);
        }

        private static void ApplyErosion(PlanetTerrainConfig cfg, float[][] faceHeights, int sub)
        {
            if (cfg.erosion == null) return;

            for (int face = 0; face < 6; face++)
            {
                var grid = new float[sub + 1, sub + 1];
                for (int y = 0; y <= sub; y++)
                {
                    for (int x = 0; x <= sub; x++)
                    {
                        grid[x, y] = faceHeights[face][y * (sub + 1) + x];
                    }
                }

                // 每个面使用独立随机序列，保证同一种子生成结果可复现。
                var rng = new DeterministicRandom(cfg.seed + face * 7919 + 17);
                if (cfg.erosion.enableHydraulic && cfg.erosion.hydraulicIterations > 0)
                {
                    HydraulicErosion.Apply(grid, sub, cfg.erosion.hydraulicIterations,
                        cfg.erosion.hydraulicStrength, rng);
                }
                if (cfg.erosion.enableThermal && cfg.erosion.thermalIterations > 0)
                {
                    ThermalErosion.Apply(grid, sub, cfg.erosion.thermalIterations,
                        cfg.erosion.thermalTalusAngle, cfg.erosion.thermalStrength);
                }

                for (int y = 0; y <= sub; y++)
                {
                    for (int x = 0; x <= sub; x++)
                    {
                        float eroded = grid[x, y];
                        // ★ 修复：侵蚀算法一旦产生 NaN/Inf，会污染整张高度图并让山脉消失。
                        if (float.IsNaN(eroded) || float.IsInfinity(eroded))
                            eroded = 0f;
                        // ★ 修复（防Bug回归）：独立侵蚀在六面边界形成不同坡度，仅平均边缘一行仍会出现直线山崖。
                        // 边界缓冲带平滑退回原始球面场，保证两边的高度与一阶变化连续。
                        float edge = Mathf.Min(Mathf.Min(x, y), Mathf.Min(sub - x, sub - y));
                        float weight = Mathf.SmoothStep(0f, 1f, edge / Mathf.Max(1f, cfg.erosion.seamBlendCells));
                        int index = y * (sub + 1) + x;
                        faceHeights[face][index] = Mathf.Clamp(
                            Mathf.Lerp(faceHeights[face][index], eroded, weight), 0f, PlanetTerrainData.MaxNormalizedHeight);
                    }
                }
            }
        }

        /// <summary>
        /// 侵蚀会分别修改 6 个面；接缝处是重复顶点，如果不取平均会出现裂缝。
        /// </summary>
        private static void MergeSeamVertices(float[][] faceHeights, int sub)
        {
            int perFace = (sub + 1) * (sub + 1);
            var keys = new Vector3Int[6][];
            var sums = new Dictionary<Vector3Int, float>(6 * perFace);
            var counts = new Dictionary<Vector3Int, int>(6 * perFace);

            for (int face = 0; face < 6; face++)
            {
                keys[face] = new Vector3Int[perFace];
                for (int y = 0; y <= sub; y++)
                {
                    for (int x = 0; x <= sub; x++)
                    {
                        int i = y * (sub + 1) + x;
                        float u = (float)x / sub * 2f - 1f;
                        float v = (float)y / sub * 2f - 1f;
                        Vector3 dir = FacePoint(FaceNormals[face], u, v).normalized;
                        var key = new Vector3Int(
                            Mathf.RoundToInt(dir.x * SeamQuantizeScale),
                            Mathf.RoundToInt(dir.y * SeamQuantizeScale),
                            Mathf.RoundToInt(dir.z * SeamQuantizeScale));
                        keys[face][i] = key;

                        sums.TryGetValue(key, out float sum);
                        counts.TryGetValue(key, out int count);
                        sums[key] = sum + faceHeights[face][i];
                        counts[key] = count + 1;
                    }
                }
            }

            for (int face = 0; face < 6; face++)
            {
                for (int i = 0; i < perFace; i++)
                {
                    var key = keys[face][i];
                    faceHeights[face][i] = sums[key] / Mathf.Max(1, counts[key]);
                }
            }
        }

        private static void BuildMesh(PlanetTerrainData data)
        {
            int sub = data.Subdivisions;
            int perFace = (sub + 1) * (sub + 1);
            data.Vertices = new Vector3[perFace * 6];
            var tris = new List<int>(sub * sub * 36);

            for (int face = 0; face < 6; face++)
            {
                int baseIdx = face * perFace;
                for (int y = 0; y <= sub; y++)
                {
                    for (int x = 0; x <= sub; x++)
                    {
                        int i = baseIdx + y * (sub + 1) + x;
                        float u = (float)x / sub * 2f - 1f;
                        float v = (float)y / sub * 2f - 1f;
                        Vector3 dir = FacePoint(FaceNormals[face], u, v).normalized;
                        float h = data.FaceHeights[face][y * (sub + 1) + x];
                        // 乘上 HeightScale 之前，h 最大是 PlanetTerrainData.MaxNormalizedHeight
                        float r = data.Radius + h * data.HeightScale;
                        data.Vertices[i] = dir * r;
                    }
                }

                int first_i00 = baseIdx;
                int first_i10 = first_i00 + 1;
                int first_i11 = first_i00 + (sub + 1) + 1;
                // ★ 修复（防Bug回归）：用未变形球面判绕序；陡坡角点的法线不能代表整个立方体面。
                Vector3 p0 = data.Vertices[first_i00].normalized;
                Vector3 p1 = data.Vertices[first_i10].normalized;
                Vector3 p2 = data.Vertices[first_i11].normalized;
                // ★ 修复（防Bug回归）：高细分三角形叉积小于 Vector3.Normalize 的阈值，会归零并令三个面绕序反向。
                // 判正负无需单位化，保留原始叉积让碰撞射线和近景遮挡在六面都有效。
                Vector3 calcNormal = Vector3.Cross(p1 - p0, p2 - p0);
                bool flip = Vector3.Dot(calcNormal, FaceNormals[face]) < 0;

                for (int y = 0; y < sub; y++)
                {
                    for (int x = 0; x < sub; x++)
                    {
                        int i00 = baseIdx + y * (sub + 1) + x;
                        int i10 = i00 + 1;
                        int i01 = baseIdx + (y + 1) * (sub + 1) + x;
                        int i11 = i01 + 1;
                        if (!flip) { tris.Add(i00); tris.Add(i10); tris.Add(i11); tris.Add(i00); tris.Add(i11); tris.Add(i01); }
                        else { tris.Add(i00); tris.Add(i11); tris.Add(i10); tris.Add(i00); tris.Add(i01); tris.Add(i11); }
                    }
                }
            }
            data.Triangles = tris.ToArray();
        }

        private static Vector3 FacePoint(Vector3 n, float u, float v)
        {
            if (Mathf.Abs(n.x) > 0.5f) return new Vector3(n.x, v, u);
            if (Mathf.Abs(n.y) > 0.5f) return new Vector3(u, n.y, v);
            return new Vector3(u, v, n.z);
        }
    }
}

using UnityEngine;
using DarwinPark.Core;

namespace DarwinPark.Planet
{
    [RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
    public class PlanetTerrainMeshBuilder : MonoBehaviour
    {
        [Header("基础配置")]
        // ★ 修复（防Bug回归）：提高实体视角下的几何采样，配合近景片元细节而非只放大低频颜色。
        public int subdivisions = 320;
        public float radius = 300f;
        public int seed = 42;

        [Header("地形高度配置")]
        [Tooltip("归一化高度 0~1 对应的世界高度。★ 从 45 提到 90：45 时全星球最大起伏只有约 12 米，山脉在 300 半径的星球上几乎看不见")]
        public float heightScale = 90f;
        [Tooltip("历史参数：实际海平面由 continentRatio 的分位值决定；保留该字段仅为兼容旧场景")]
        [Range(0.3f, 0.7f)]
        public float seaLevelRatio = 0.45f;

        [Header("噪声配置 (FBM)")]
        public float baseFrequency = 0.8f; // 基础地形频率（越小大陆越连贯）
        public float baseAmplitude = 1.0f;
        public int baseOctaves = 4;

        public float detailFrequency = 3.0f; // 细节频率（增加起伏）
        public float detailAmplitude = 0.15f;
        public int detailOctaves = 3;

        [Header("地貌雕刻（数据驱动）")]
        [Tooltip("海岸相对海平面的抬升")]
        public float coastalRise = 0.012f;
        [Tooltip("大陆内部整体抬升，越大高原越明显")]
        public float inlandRise = 0.22f;
        [Tooltip("内陆抬升曲线，>1 时沿海更平坦")]
        public float inlandCurve = 1.35f;

        [Header("山脉")]
        [Tooltip("山脊相对大陆基底的最大抬升（归一化高度）")]
        public float mountainHeight = 0.72f;
        // ★ 适配：独立造山模型的可调参数。
        public float mountainCoreWidth = 0.015f;
        public float mountainBeltWidth = 0.16f;
        [Range(0f, 1f)] public float mountainDetailStrength = 0.65f;
        [Tooltip("山脉频率。方向向量是单位球，频率低于 2 时整个星球只有一两个鼓包，看不出山脉")]
        public float mountainFrequency = 1.65f;
        public int mountainOctaves = 2;
        [Range(0.5f, 6f)] public float mountainSharpness = 2.4f;
        [Range(0f, 1f)] public float mountainStart = 0.03f;
        [Range(0.01f, 1f)] public float mountainFull = 0.32f;
        public float mountainWarp = 0.45f;
        [Range(0f, 1f)] public float mountainBeltStrength = 0.75f;

        [Header("盆地与峡谷")]
        public float basinDepth = 0.10f;
        public float basinFrequency = 1.35f;
        [Range(0f, 1f)] public float basinThreshold = 0.28f;
        [Range(0.01f, 0.5f)] public float basinWidth = 0.30f;
        public float valleyDepth = 0.085f;
        public float valleyFrequency = 3.8f;
        [Range(0.5f, 6f)] public float valleySharpness = 3.2f;
        public float detailStrength = 0.02f;
        [Range(0.05f, 0.9f)] public float oceanFloorRatio = 0.22f;

        [Header("侵蚀（数据驱动）")]
        public ErosionConfig erosion = new ErosionConfig();

        [Header("渲染")]
        public Material TerrainMaterial;

        [Header("地形碰撞")]
        [Tooltip("普通网格使用快速碰撞结构；超过PhysX三角形上限时自动改用兼容结构，避免漏碰撞。")]
        public bool useFastMidphase = true;
        // ★ 修复（防Bug回归）：这是PhysX快速结构的索引上限，不是降低地形精度的游戏参数。
        public const int FastMidphaseTriangleLimit = 2_097_152;

        public PlanetTerrainData Data { get; private set; }
        private Mesh _mesh;

        // ★ 适配：有世界选择流程时延迟生成，避免菜单出现前阻塞。
        private void Start(){if(!WorldRuntimeGate.Managed)Build();}

        [Range(0.2f, 0.8f)]
        [Tooltip("陆地占比：0.2=海洋多，0.8=陆地多。海平面取大陆噪声的对应分位值")]
        public float continentRatio = 0.5f;

        /// <summary>
        /// ★ 适配：实体溺水/水下判断统一使用真实海平面，而不是 seaLevelRatio。
        /// 旧代码用 heightScale * seaLevelRatio 计算水位，会把整个大陆的低地误判成水下。
        /// </summary>
        public float WaterRadius
        {
            get
            {
                if (Data == null) return radius;
                return radius + Data.SeaLevel * heightScale;
            }
        }

        /// <summary>★ 适配：判断世界坐标是否位于海平面以下。</summary>
        public bool IsSubmerged(Vector3 worldPosition, float depthMargin = 0f)
        {
            return (worldPosition - transform.position).magnitude < WaterRadius - Mathf.Max(0f, depthMargin);
        }

        // ★ 适配：纯参数快照供后台计算；网格上传留在主线程。
        public PlanetTerrainConfig CaptureConfiguration()
        {
            // 1. 构建配置对象（所有地貌参数从 Inspector/配置传入，避免写死在生成器）
            var cfg = new PlanetTerrainConfig
            {
                id = "dynamic",
                subdivisions = this.subdivisions,
                radius = this.radius,
                heightScale = this.heightScale,
                seed = this.seed,

                coastalRise = this.coastalRise,
                inlandRise = this.inlandRise,
                inlandCurve = this.inlandCurve,

                mountainHeight = this.mountainHeight,
                mountainCoreWidth = this.mountainCoreWidth,
                mountainBeltWidth = this.mountainBeltWidth,
                mountainDetailStrength = this.mountainDetailStrength,
                mountainFrequency = this.mountainFrequency,
                mountainOctaves = this.mountainOctaves,
                mountainSharpness = this.mountainSharpness,
                mountainStart = this.mountainStart,
                mountainFull = this.mountainFull,
                mountainWarp = this.mountainWarp,
                mountainBeltStrength = this.mountainBeltStrength,

                basinDepth = this.basinDepth,
                basinFrequency = this.basinFrequency,
                basinThreshold = this.basinThreshold,
                basinWidth = this.basinWidth,
                valleyDepth = this.valleyDepth,
                valleyFrequency = this.valleyFrequency,
                valleySharpness = this.valleySharpness,
                detailStrength = this.detailStrength,
                oceanFloorRatio = this.oceanFloorRatio,
                erosion = this.erosion ?? new ErosionConfig()
            };

            // 填入噪声参数
            cfg.baseNoise.frequency = baseFrequency;
            cfg.baseNoise.amplitude = baseAmplitude;
            cfg.baseNoise.octaves = baseOctaves;

            cfg.detailNoise.frequency = detailFrequency;
            cfg.detailNoise.amplitude = detailAmplitude;
            cfg.detailNoise.octaves = detailOctaves;

            return cfg;
        }
        public void Build()=>ApplyGeneratedData(PlanetTerrainGenerator.Generate(CaptureConfiguration(),seaLevelRatio,continentRatio));
        // ★ 适配：后台计算完成后一次接入原网格/碰撞/天气装配链路。
        public void ApplyGeneratedData(PlanetTerrainData data)
        {
            Data=data;
            if (Data == null)
            {
                Log.Error(Log.Tag.Planet, "地形生成失败：生成器返回空数据");
                return;
            }

            // ★ 修复（防Bug回归）：先解绑旧碰撞网格，防止Clear/重新上传时沿用旧的快速结构提前烘焙超大网格。
            var mc = GetComponent<MeshCollider>();
            if (mc == null) mc = gameObject.AddComponent<MeshCollider>();
            mc.sharedMesh = null;

            // 3. 构建 Mesh 网格
            if (_mesh == null)
            {
                _mesh = new Mesh { name = "PlanetTerrain" };
                _mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
            }
            _mesh.Clear();
            _mesh.vertices = Data.Vertices;
            _mesh.triangles = Data.Triangles;
            _mesh.RecalculateNormals();
            // ★ 修复：Cube-Sphere 的 6 个面使用重复顶点，RecalculateNormals 会在接缝
            // 产生两套不同法线，气候/高程图层叠加阴影后会出现直线断层。这里按位置合并法线。
            SmoothSeamNormals(_mesh);
            _mesh.RecalculateBounds();

            GetComponent<MeshFilter>().mesh = _mesh;

            // 4. 配置渲染器并传递 Shader 参数
            var mr = GetComponent<MeshRenderer>();
            if (TerrainMaterial != null) mr.sharedMaterial = TerrainMaterial;

            // ★ 核心修复：把当前配置传给 Shader，防止 Shader 里写死
            var block = new MaterialPropertyBlock();
            mr.GetPropertyBlock(block);
            block.SetFloat("_PlanetRadius", radius);
            block.SetFloat("_HeightScale", heightScale);
            // ★ 核心修复：用动态算出来的海平面阈值，而不是输入的参数！
            block.SetFloat("_SeaLevel", Data.SeaLevel);
            // ★ 适配：Shader 的雪线/陆地归一化不再写死 0.9，统一从地形数据读取上限。
            block.SetFloat("_MaxHeight", PlanetTerrainData.MaxNormalizedHeight);
            mr.SetPropertyBlock(block);

            // 5. 配置碰撞体 (只获取一次，绝不重复)
            // ★ 修复（防Bug回归）：超过2,097,152三角形时禁用Fast Midphase，保留其余选项；小网格按Inspector偏好恢复。
            var cooking = mc.cookingOptions & ~MeshColliderCookingOptions.UseFastMidphase;
            if (useFastMidphase && Data.Triangles.Length / 3 <= FastMidphaseTriangleLimit)
                cooking |= MeshColliderCookingOptions.UseFastMidphase;
            mc.cookingOptions = cooking;
            mc.sharedMesh = _mesh;

            // ★ 适配：独立海面/云层复用本次生成的焊接网格，重建地形时同步刷新。
            GetComponent<PlanetWeatherVisuals>()?.Rebuild();

            // 6. 完成日志（同时输出高度范围，便于确认山脉/盆地是否真的生成）
            float minHeight = float.MaxValue;
            float maxHeight = float.MinValue;
            int mountainCells = 0;
            int totalCells = 0;
            for (int face = 0; face < 6; face++)
            {
                var hs = Data.FaceHeights[face];
                if (hs == null) continue;
                for (int i = 0; i < hs.Length; i++)
                {
                    float h = hs[i];
                    if (h < minHeight) minHeight = h;
                    if (h > maxHeight) maxHeight = h;
                    if (h > Data.SeaLevel + 0.10f) mountainCells++;
                    totalCells++;
                }
            }
            float peakAboveSea = (maxHeight - Data.SeaLevel) * heightScale;
            float oceanDepth = (Data.SeaLevel - minHeight) * heightScale;
            Log.Info(Log.Tag.Planet,
                $"地形生成完成：vert={Data.Vertices.Length}, seaLevel={Data.SeaLevel:F3}, waterRadius={WaterRadius:F1}, " +
                $"height=[{minHeight:F3},{maxHeight:F3}], peakAboveSea={peakAboveSea:F1}m, oceanDepth={oceanDepth:F1}m, " +
                $"highLandVertices={mountainCells}({100f * mountainCells / Mathf.Max(1, totalCells):F1}%)");
        }

        /// <summary>把同一位置（主要是 6 面接缝）的重复顶点法线取平均并归一化。</summary>
        private static void SmoothSeamNormals(Mesh mesh)
        {
            var vertices = mesh.vertices;
            var normals = mesh.normals;
            if (vertices == null || normals == null || vertices.Length != normals.Length) return;

            var sums = new System.Collections.Generic.Dictionary<Vector3Int, Vector3>(vertices.Length);
            var counts = new System.Collections.Generic.Dictionary<Vector3Int, int>(vertices.Length);
            var keys = new Vector3Int[vertices.Length];
            const float posScale = 10000f;

            for (int i = 0; i < vertices.Length; i++)
            {
                var p = vertices[i];
                var key = new Vector3Int(
                    Mathf.RoundToInt(p.x * posScale),
                    Mathf.RoundToInt(p.y * posScale),
                    Mathf.RoundToInt(p.z * posScale));
                keys[i] = key;

                sums.TryGetValue(key, out var sum);
                counts.TryGetValue(key, out var count);
                sums[key] = sum + normals[i];
                counts[key] = count + 1;
            }

            for (int i = 0; i < vertices.Length; i++)
            {
                var key = keys[i];
                if (counts[key] <= 1) continue;
                var normal = sums[key];
                if (normal.sqrMagnitude > 1e-8f) normals[i] = normal.normalized;
            }

            mesh.normals = normals;
        }
    }
}

using UnityEngine;

namespace DarwinPark.Planet
{
    /// <summary>
    /// ★ 新增：Cube-Sphere 数据采样工具。
    /// 气候图、环境回退、实体地表高度查询共用同一套 UV/六个面的映射，
    /// 避免各脚本各写一份导致接缝/错位（历史 Bug：气候图与网格面朝向不一致）。
    /// </summary>
    public static class PlanetTerrainSampler
    {
        /// <summary>等距柱状投影 UV → 球面单位方向。u=0/1 为同一条经线。</summary>
        public static Vector3 DirectionFromUV(float u, float v)
        {
            float lon = (u - 0.5f) * 2f * Mathf.PI;
            float lat = (v - 0.5f) * Mathf.PI;
            return new Vector3(
                Mathf.Cos(lat) * Mathf.Sin(lon),
                Mathf.Sin(lat),
                Mathf.Cos(lat) * Mathf.Cos(lon)).normalized;
        }

        /// <summary>球面单位方向 → 等距柱状投影 UV（与 Shader 的 sphereUV 对齐）。</summary>
        public static Vector2 DirectionToUV(Vector3 dir)
        {
            float u = Mathf.Atan2(dir.x, dir.z) / (2f * Mathf.PI) + 0.5f;
            float v = Mathf.Asin(Mathf.Clamp(dir.y, -1f, 1f)) / Mathf.PI + 0.5f;
            return new Vector2(Mathf.Repeat(u, 1f), Mathf.Clamp01(v));
        }

        /// <summary>按世界方向双线性采样 Cube-Sphere 高度。</summary>
        public static float SampleHeight(PlanetTerrainData data, Vector3 dir)
        {
            if (data == null || data.FaceHeights == null) return 0f;

            // ★ 优化：六个面法线就是 ±轴，主面 = 绝对值最大的轴分量。
            // 旧版每次采样做 6 次点乘，气候图每个像元要调用十几次，属于纯浪费。
            float ax = Mathf.Abs(dir.x);
            float ay = Mathf.Abs(dir.y);
            float az = Mathf.Abs(dir.z);
            int face;
            float maxDot;
            if (ax >= ay && ax >= az) { maxDot = ax; face = dir.x >= 0f ? 0 : 1; }
            else if (ay >= az) { maxDot = ay; face = dir.y >= 0f ? 2 : 3; }
            else { maxDot = az; face = dir.z >= 0f ? 4 : 5; }
            if (maxDot <= 0.001f) return 0f;

            Vector3 local = dir * (1f / maxDot);
            float u, v;
            if (face <= 1) { u = local.z; v = local.y; }        // ±X 面
            else if (face <= 3) { u = local.x; v = local.z; }   // ±Y 面
            else { u = local.x; v = local.y; }                   // ±Z 面

            int sub = data.Subdivisions;
            float fx = (u + 1f) * 0.5f * sub;
            float fy = (v + 1f) * 0.5f * sub;

            int ix = Mathf.Clamp(Mathf.FloorToInt(fx), 0, sub - 1);
            int iy = Mathf.Clamp(Mathf.FloorToInt(fy), 0, sub - 1);
            float tx = Mathf.Clamp01(fx - ix);
            float ty = Mathf.Clamp01(fy - iy);

            var heights = data.FaceHeights[face];
            if (heights == null) return 0f;

            int stride = sub + 1;
            float h00 = heights[iy * stride + ix];
            float h10 = heights[iy * stride + ix + 1];
            float h01 = heights[(iy + 1) * stride + ix];
            float h11 = heights[(iy + 1) * stride + ix + 1];

            return Mathf.Lerp(Mathf.Lerp(h00, h10, tx), Mathf.Lerp(h01, h11, tx), ty);
        }

        /// <summary>把世界坐标转成星球局部方向（兼容星球被旋转/移动）。</summary>
        public static Vector3 WorldToLocalDirection(Transform planet, Vector3 worldPos)
        {
            if (planet == null) return Vector3.up;
            return planet.InverseTransformDirection(worldPos - planet.position).normalized;
        }
    }
}

