    // ★ 新增：按键等待状态独立管理，Esc只取消改键，避免同时关闭设置或触发游戏操作。
    public sealed class ControlSettingsPage
    {
        public ControlAction? Waiting {get;private set;}
        private string _message="";
        private Vector2 _scroll;
        public void Cancel()=>Waiting=null;
        public void Begin(ControlAction action){Waiting=action;_message="请按键盘或鼠标按键；Esc 取消";}
        public bool HandleEvent(Event evt)
        {
            if(!Waiting.HasValue)return false;
            KeyCode key;
            if(evt.type==EventType.KeyDown)key=evt.keyCode;
            else if(evt.type==EventType.MouseDown)key=(KeyCode)((int)KeyCode.Mouse0+evt.button);
            else return false;
            if(key==KeyCode.Escape){Cancel();_message="已取消改键";}
            else if(ControlBindings.TryBind(Waiting.Value,key,out _message))Cancel();
            evt.Use();return true;
        }
        public void Draw()
        {
            GUILayout.Label("点击当前按键进行修改",RuntimeMenuTheme.Muted);
            // ★ 适配：长按键列表只滚动右侧内容，左侧分页和底部返回始终可见。
            _scroll=GUILayout.BeginScrollView(_scroll,GUILayout.Height(Mathf.Clamp(Screen.height-300,120,300)));
            foreach(ControlAction action in Enum.GetValues(typeof(ControlAction)))
            {
                GUILayout.BeginHorizontal();GUILayout.Label(ControlBindings.Labels[(int)action],GUILayout.Height(32));
                if(GUILayout.Button(Waiting==action?"等待按键…":ControlBindings.Display(action),GUILayout.Width(145),GUILayout.Height(30)))Begin(action);
                GUILayout.EndHorizontal();
            }
            GUILayout.Label("Esc 固定打开菜单。星球暂停和实体跳跃可共用按键。",new GUIStyle(RuntimeMenuTheme.Muted){wordWrap=true});
            if(!string.IsNullOrEmpty(_message))GUILayout.Label(_message,new GUIStyle(GUI.skin.label){wordWrap=true});
            if(RuntimeMenuTheme.Button("恢复默认按键",null,false,36)){Cancel();ControlBindings.RestoreDefaults();_message="已恢复默认并保存";}
            GUILayout.EndScrollView();
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using DarwinPark.Entities;
using DarwinPark.Entities.Ecology;
using DarwinPark.Entities.Logic;
using DarwinPark.Entities.Stats;
using UnityEngine;

namespace DarwinPark.UI
{
    // ★ 新增：旧长孕育和长休养必须随新表达规则一起迁移，避免恢复生长后先老死再到生产时间。
    public static class EcologyLegacySaveUpgrade
    {
        public static int Apply(WorldSaveData world,IEnumerable<DarwinEntity> entities)
        {
            if(!string.IsNullOrWhiteSpace(world.ecologyBalanceSettings))return 0;
            var settings=EcologyBalanceSettings.Current;
            var saved=world.entities.SelectMany(e=>e.reproduction).ToLookup(r=>r.gene);int changed=0;
            foreach(var entity in entities)
            {
                if(entity==null)continue;
                var genes=entity.Genes;var stats=entity.GetComponent<EntityStats>();
                if(stats==null||!stats.TryGet(settings.sizeAttribute,out float size))continue;
                size=Mathf.Max(settings.minimumReproductionSize,size);
                foreach(var gene in genes.Genome.Genes)
                {
                    if(!(genes.GetLogic(gene) is ReproductionGeneLogic logic))continue;
                    var state=logic.CaptureState();float priorGestation=state.gestation,priorCooldown=state.cooldown;
                    state.gestation=Mathf.Min(state.gestation,logic.CalculateGestationTime(size));
                    state.cooldown=Mathf.Min(state.cooldown,EcologyReproductionTiming.CooldownSeconds(genes));
                    if(state.gestation==priorGestation&&state.cooldown==priorCooldown)continue;
                    logic.RestoreState(state);changed++;
                    // ★ 适配：内存中的世界快照同步收纳，加载重试时不能重新使用旧长计时；磁盘仍只由正常保存链路写入。
                    foreach(var record in saved[state.gene]){record.gestation=state.gestation;record.cooldown=state.cooldown;}
                }
            }
            world.ecologyBalanceSettings=EcologyBalanceSettings.CurrentJson;
            if(changed>0)Debug.Log("[生态存档] 已收纳 "+changed+" 项旧孕育/休养计时，并登记世界规则快照。");
            return changed;
        }
    }
}

