            _empty.gameObject.SetActive(count==0);_pageLabel.text=(Page+1)+" / "+PageCount+" 页";
            float y=_rect.rect.height-34;Place(_previous.GetComponent<RectTransform>(),y,26,0,.31f);Place(_pageLabel.rectTransform,y,26,.31f,.69f);Place(_next.GetComponent<RectTransform>(),y,26,.69f,1);
            _previous.interactable=Page>0;_next.interactable=Page+1<PageCount;
        }
        private void LateUpdate(){if(_owner==null||!_owner.isActiveAndEnabled||!WorldRuntimeGate.Ready){Hide();return;}if(Reposition())Refresh();}
        private bool Reposition()
        {
            // ★ 新增：少量结果时缩短列表，避免只有一两个个体也留下整块空白。
            float height=Mathf.Min(_owner.resultWindowSize.y,Mathf.Max(_owner.minimumResultHeight,92+Mathf.Min(_owner.Matches.Count,_owner.resultsPerPage)*Mathf.Max(20,_owner.resultRowHeight)));
            var canvas=(RectTransform)transform.parent;var size=Vector2.Min(new Vector2(_owner.resultWindowSize.x,height),new Vector2(Mathf.Max(120,canvas.rect.width-24),Mathf.Max(120,canvas.rect.height-24)));
            var source=_owner.WideLayout&&_owner.Card!=null?_owner.Card:(RectTransform)_owner.transform;source.GetWorldCorners(_corners);
            var corner=(Vector2)canvas.InverseTransformPoint(_corners[1])-canvas.rect.min;
            var point=new Vector2(Mathf.Clamp(corner.x,12,Mathf.Max(12,canvas.rect.width-size.x-12)),Mathf.Clamp(corner.y+_owner.gap,12,Mathf.Max(12,canvas.rect.height-size.y-12)));
            bool changed=_rect.sizeDelta!=size;if(changed)_rect.sizeDelta=size;if(_rect.anchoredPosition!=point)_rect.anchoredPosition=point;return changed;
        }
    }
}

using UnityEngine;
using DarwinPark.Entities;

namespace DarwinPark.UI
{
    // ★ 新增：固定眼位与准星同源，隐藏自身但保留物理碰撞；退出恢复相机和模型。
    public sealed class EntityFirstPersonCamera : MonoBehaviour
    {
        public float eyeHeightRatio = .65f, nearClip = .03f;
        private Renderer[] _renderers;
        private bool[] _hidden;
        private Camera _camera;
        private float _oldNear;
        private DarwinEntity _target;
        public void Begin(DarwinEntity target, Camera camera)
        {
            End(); _target = target; _camera = camera; _oldNear = camera.nearClipPlane;
            camera.nearClipPlane = nearClip;
            _renderers = target.GetComponentsInChildren<Renderer>(); _hidden = new bool[_renderers.Length];
            for (int i=0;i<_renderers.Length;i++) { _hidden[i]=_renderers[i].forceRenderingOff; _renderers[i].forceRenderingOff=true; }
        }
        public void Apply(Vector3 up, Vector3 forward, float pitch, EntityManualControl manual)
        {
            if (_target == null || _camera == null) return;
            var collider = _target.GetComponent<Collider>();
            float radius = collider != null ? Mathf.Min(collider.bounds.extents.x, collider.bounds.extents.y, collider.bounds.extents.z) : .5f;
            Vector3 eye = _target.transform.position + up * radius * eyeHeightRatio;
            Vector3 direction = Quaternion.AngleAxis(pitch, Vector3.Cross(up,forward)) * forward;
            _camera.transform.SetPositionAndRotation(eye, Quaternion.LookRotation(direction,up));
            manual.SetAim(new Ray(eye,direction));
        }
        public void End()
        {
            if (_renderers != null) for(int i=0;i<_renderers.Length;i++) if(_renderers[i]!=null) _renderers[i].forceRenderingOff=_hidden[i];
            if(_camera!=null) _camera.nearClipPlane=_oldNear;
            _renderers=null; _camera=null; _target=null;
        }
        private void OnDisable()=>End();
    }
}

using System;
using System.Collections.Generic;
using DarwinPark.Entities;
using DarwinPark.Entities.Ecology;

namespace DarwinPark.UI
{
    // ★ 新增：包含条件全部满足、排除条件任一命中即排除；按携带判断，失效/抑制不等于没有基因。
    public sealed class EntityGeneFilter
    {
        private readonly HashSet<string> _included=new HashSet<string>(StringComparer.Ordinal);
        private readonly HashSet<string> _excluded=new HashSet<string>(StringComparer.Ordinal);
        private readonly HashSet<string> _seen=new HashSet<string>(StringComparer.Ordinal);
        public IReadOnlyCollection<string> Included=>_included;
        public IReadOnlyCollection<string> Excluded=>_excluded;
        public void Set(string id,bool include,bool enabled)
        {
            if(string.IsNullOrEmpty(id))return;
            var selected=include?_included:_excluded;var other=include?_excluded:_included;
            if(enabled){selected.Add(id);other.Remove(id);}else selected.Remove(id);
        }
        public void Clear(){_included.Clear();_excluded.Clear();}
        public void Clear(bool include){if(include)_included.Clear();else _excluded.Clear();}
        public void KeepKnown(HashSet<string> known){_included.RemoveWhere(id=>!known.Contains(id));_excluded.RemoveWhere(id=>!known.Contains(id));}
        public bool Contains(string id,bool include)=>include?_included.Contains(id):_excluded.Contains(id);
        // 只在UI主线程调用，复用去重集合，避免每个实体分配HashSet或复制完整基因组。
        public bool Matches(DarwinEntity entity)
        {
            if(!EcologyQueries.Alive(entity)||entity.Genes?.Genome==null)return false;
            if(_included.Count==0&&_excluded.Count==0)return true;
            int required=0;_seen.Clear();
            foreach(var gene in entity.Genes.Genome.Genes)
            {
                if(gene==null||string.IsNullOrEmpty(gene.DefinitionId))continue;
                if(_excluded.Contains(gene.DefinitionId))return false;
                if(_included.Contains(gene.DefinitionId)&&_seen.Add(gene.DefinitionId))required++;
            }
            return required==_included.Count;
        }
    }
}

using DarwinPark.Core;
using DarwinPark.Genetics;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace DarwinPark.UI
{
    /// <summary>★ 新增：点击槽位进入连续投放，每次地表左键生成一批，右键/ESC 取消；保留原拖拽入口。</summary>
    [DefaultExecutionOrder(100)]
    public sealed class EntityPlacementTool : MonoBehaviour
    {
        public static EntityPlacementTool Instance { get; private set; }
        public bool IsPlacing { get; private set; }
        public float spawnHeight = 8f;
        public float previewHeight = 3f;
        public Vector2 hintPosition = new Vector2(0, 225);
        public string placementHint = "选择地表：左键放置，右键或 ESC 取消";
        public int PlacementCount { get; private set; }=1;
        public float batchSpacing=2f;
        private Genome _genome;
        private GameObject _prefab;
        private GameObject _preview, _hint;
        private int _beginFrame;
        private void Awake() { Instance = this; }

        public void BeginPlacement(GameObject prefab, Genome genome, int count=1)
        {
            if(!WorldAuthority.CanEdit)return;
            // ★ 适配：再次点击同一槽位退出；切换模板直接进入新投放。
            if(IsPlacing && _prefab==prefab && ReferenceEquals(_genome,genome)){CancelPlacement();return;}
            // ★ 适配：开始投放时退出实体控制，避免两个模式争用键鼠与相机。
            EntityViewController.Instance?.ExitView();
            CancelPlacement();
            if (prefab == null) { Log.Error(Log.Tag.UI, "默认实体预制体未配置，无法投放"); return; }
            _genome = genome;_prefab=prefab; IsPlacing = true; OrbitCamera.IsDraggingUI = true; _beginFrame = Time.frameCount;
            PlacementCount=Mathf.Max(1,count);
            _preview = EntityPlacementUtility.CreatePreview(prefab);
            _preview?.SetActive(false);
            if (ServiceLocator.TryGet<UIRoot>(out var root) && root.MainCanvas != null)
            {
                var text = UIFactory.NewText("PlacementHint", root.MainCanvas.transform, $"{placementHint}（每次 {PlacementCount} 个）", 18, TextAnchor.MiddleCenter);
                text.raycastTarget=false;
                var rt = text.rectTransform;
                rt.anchorMin = rt.anchorMax = new Vector2(.5f, 0);
                rt.pivot = new Vector2(.5f, 0); rt.anchoredPosition = hintPosition;
                rt.sizeDelta = new Vector2(640, 35); _hint = text.gameObject;
            }
        }

        private void Update()
        {
            // ★ 适配：覆盖菜单拥有输入时不处理世界操作。
            if (DarwinPark.Core.GameInputGate.Blocked) return;
            if (!IsPlacing || Time.frameCount == _beginFrame) return;
            if (Input.GetKeyDown(KeyCode.Escape) || Input.GetMouseButtonDown(1)) { CancelPlacement(); return; }
            // ★ 适配：与拖拽共用实时坐标检测，避免上一帧 UI 命中阻断地表确认。
            bool overUI = EntityPlacementUtility.IsPointerOverUI(Input.mousePosition);
            bool valid = !overUI && EntityPlacementUtility.TryGetSurface(Camera.main, Input.mousePosition,
                out _, out _);
            if (_preview != null) _preview.SetActive(valid);
            if (!valid) return;
            EntityPlacementUtility.TryGetSurface(Camera.main, Input.mousePosition, out var point, out var outward);
            if (_preview != null)
            {
                _preview.transform.position = point + outward * previewHeight;
                _preview.transform.up = outward;
            }
            if (Input.GetMouseButtonDown(0)) TryPlaceAt(Input.mousePosition);
        }

        // ★ 修复（防Bug回归）：确认投放共用实时 UI/正面射线判定，失败可重新选位置，成功保持连续模式。
        public bool TryPlaceAt(Vector2 screen)
        {
            if(!WorldAuthority.CanEdit||!IsPlacing || EntityPlacementUtility.IsPointerOverUI(screen) ||
                !EntityPlacementUtility.TryGetSurface(Camera.main,screen,out var point,out var outward))return false;
            // ★ 新增：成功后保留当前模板与预览，支持连续点放；只有右键/Esc 取消。
            return EntityPlacementUtility.SpawnBatch(_genome,point,outward,spawnHeight,PlacementCount,batchSpacing)>0;
        }

        public void CancelPlacement()
        {
            if (IsPlacing) OrbitCamera.IsDraggingUI = false;
            IsPlacing = false; _genome = null;_prefab=null;
            EntityPlacementUtility.DestroyPreview(_preview); _preview = null;
            if (_hint != null) Destroy(_hint); _hint = null;
        }
        private void OnDisable() => CancelPlacement();
        private void OnDestroy() { if (Instance == this) Instance = null; }
    }
}

using System.Collections.Generic;
using DarwinPark.Core;
using DarwinPark.Entities;
using DarwinPark.Genetics;
using DarwinPark.Planet;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.EventSystems;

namespace DarwinPark.UI
{
    /// <summary>★ 新增：点击/拖拽共用的地表拾取、纯视觉预览及独立基因组投放。</summary>
    public static class EntityPlacementUtility
    {
        // ★ 修复（防Bug回归）：拖拽松手不能读取缓存的 pointerEnter，按释放坐标重做 UI 命中。
        public static bool IsPointerOverUI(Vector2 screen)
        {
            if(EventSystem.current==null)return false;
            var hits=new List<RaycastResult>();
            EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=screen},hits);
            return hits.Exists(h=>h.module is UnityEngine.UI.GraphicRaycaster);
        }
        public static bool TryGetSurface(Camera camera, Vector2 screen, out Vector3 point, out Vector3 outward)
        {
            point = default; outward = Vector3.up;
            if (camera == null) return false;
            var builder = Object.FindFirstObjectByType<PlanetTerrainMeshBuilder>();
            if (builder == null || builder.Data == null) return false;
            var collider = builder.GetComponent<MeshCollider>();
            var ray=camera.ScreenPointToRay(screen);
            if (collider == null || !collider.Raycast(ray, out var hit, camera.farClipPlane))
                return false;
            // ★ 修复（防Bug回归）：穿进星球后的背面不能作为可见的投放地面。
            if(Vector3.Dot(hit.normal,-ray.direction)<=0)return false;
            point = hit.point;
            outward = (point - builder.transform.position).normalized;
            return true;
        }

        // ★ 新增：批量投放按球面邻域散开，每个位置重新查询真实地面，避免重叠或落进山体。
        public static int SpawnBatch(Genome genome,Vector3 point,Vector3 outward,float height,int count,float spacing)
        {
            // ★ 适配：普通成员不能通过拖拽或调用放置入口绕过权限；作弊客户端交给房主生成。
            if(!WorldAuthority.CanEdit)return 0;
            if(LanSession.Instance?.IsClient==true)return LanEditActions.Submit(new LanCommand{kind="batch",genome=genome,point=point,value=height,count=count,scale=spacing})?count:0;
            var builder=Object.FindFirstObjectByType<PlanetTerrainMeshBuilder>();
            if(builder==null)return 0;
            var ground=builder.GetComponent<MeshCollider>();if(ground==null)return 0;
            var a=Vector3.Cross(outward,Mathf.Abs(outward.y)>.95f?Vector3.right:Vector3.up).normalized;
            var b=Vector3.Cross(outward,a);int spawned=0;
            float outer=ground.bounds.extents.magnitude+height;
            for(int i=0;i<count&&EntityPopulationLimit.CanSpawn;i++)
            {
                float radius=spacing*Mathf.Sqrt(i), angle=i*2.39996323f;
                var dir=(point-builder.transform.position+a*(Mathf.Cos(angle)*radius)+b*(Mathf.Sin(angle)*radius)).normalized;
                if(ground.Raycast(new Ray(builder.transform.position+dir*outer,-dir),out var hit,outer) &&
                    Spawn(genome,hit.point+dir*height))spawned++;
            }
            return spawned;
        }

        public static Genome CopyGenome(Genome source)
        {
            if (source == null) return null;
            var copy = new Genome();
            foreach (var gene in source.Genes)
            {
                var item = GeneInstance.Create(gene.DefinitionId, gene.Value, gene.Tier);
                item.Enabled = gene.Enabled; item.CopyStrength = gene.CopyStrength;
                item.OriginInstanceId = gene.OriginInstanceId;
                item.MissingStateIds = new List<string>(gene.MissingStateIds);
                copy.Add(item);
            }
            return copy;
        }

        public static bool Spawn(Genome genome, Vector3 position)
        {
            if(!WorldAuthority.CanEdit)return false;
            if (DarwinEntity.Spawner == null)
            {
                Debug.LogError("[EntityPlacement] 生成器未初始化，请检查 GameBootstrap。");
                return false;
            }
            // 同一模板的多次投放必须复制遗传数据，避免一个实体突变改写模板及同批个体。
            return LanEditActions.Spawn(genome,position);
        }

        public static GameObject CreatePreview(GameObject prefab)
        {
            if (prefab == null) return null;
            // 不 Instantiate 实体预制体：Awake/OnEnable 会先注册实体、计算基因，再 Destroy 无法撤销副作用。
            var preview = new GameObject("EntityPlacementPreview");
            preview.transform.localScale = prefab.transform.localScale;
            foreach (var source in prefab.GetComponentsInChildren<MeshFilter>(true))
            {
                if (source.sharedMesh == null) continue;
                var sourceRenderer = source.GetComponent<MeshRenderer>();
                if (sourceRenderer == null) continue;
                var child = new GameObject(source.name, typeof(MeshFilter), typeof(MeshRenderer));
                child.transform.SetParent(preview.transform, false);
                child.transform.localPosition = prefab.transform.InverseTransformPoint(source.transform.position);
                child.transform.localRotation = Quaternion.Inverse(prefab.transform.rotation) * source.transform.rotation;
                child.transform.localScale = new Vector3(
                    source.transform.lossyScale.x / prefab.transform.lossyScale.x,
                    source.transform.lossyScale.y / prefab.transform.lossyScale.y,
                    source.transform.lossyScale.z / prefab.transform.lossyScale.z);
                child.GetComponent<MeshFilter>().sharedMesh = source.sharedMesh;
                var renderer = child.GetComponent<MeshRenderer>();
                var materials = new Material[sourceRenderer.sharedMaterials.Length];
                for (int i = 0; i < materials.Length; i++)
                {
                    var sourceMaterial = sourceRenderer.sharedMaterials[i];
                    if (sourceMaterial == null) continue;
                    var material = new Material(sourceMaterial);
                    if (material.HasProperty("_BaseColor"))
                    {
                        Color color = material.GetColor("_BaseColor"); color.a = .45f;
                        material.SetColor("_BaseColor", color);
                    }
                    material.SetFloat("_Surface", 1f); material.SetFloat("_ZWrite", 0f);
                    material.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha);
                    material.SetFloat("_DstBlend", (float)BlendMode.OneMinusSrcAlpha);
                    material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
                    material.renderQueue = (int)RenderQueue.Transparent;
                    materials[i] = material;
                }
                renderer.sharedMaterials = materials;
                renderer.shadowCastingMode = ShadowCastingMode.Off;
            }
            return preview;
        }

        public static void DestroyPreview(GameObject preview)
        {
            if (preview == null) return;
            preview.SetActive(false);
            var materials = new HashSet<Material>();
            foreach (var renderer in preview.GetComponentsInChildren<Renderer>(true))
                foreach (var material in renderer.sharedMaterials)
                    if (material != null) materials.Add(material);
            foreach (var material in materials) Object.Destroy(material);
            Object.Destroy(preview);
        }
    }
}

using DarwinPark.Core;
using DarwinPark.Entities;
using UnityEngine;
using UnityEngine.UI;

namespace DarwinPark.UI
{
    /// <summary>★ 新增：实体视角专用锁鼠标、准星与按键；退出/失焦时成对释放输入。</summary>
    public sealed class EntityPossessionInput : MonoBehaviour
    {
        // ★ 适配：设置中的绑定直接用于输入，不保留另一套Inspector按键导致界面修改无效。
        public KeyCode forwardKey=>ControlBindings.Get(ControlAction.Forward);
        public KeyCode backKey=>ControlBindings.Get(ControlAction.Back);
        public KeyCode leftKey=>ControlBindings.Get(ControlAction.Left);
        public KeyCode rightKey=>ControlBindings.Get(ControlAction.Right);
        public KeyCode jumpKey=>ControlBindings.Get(ControlAction.Jump);
        public KeyCode cursorKey=>ControlBindings.Get(ControlAction.ReleaseCursor);
        public bool CursorReleased {get;private set;}
        public int attackMouseButton=>(int)ControlBindings.Get(ControlAction.Attack)-(int)KeyCode.Mouse0;
        public float lookSensitivity = 3, zoomSensitivity = 4, minPitch = -80, maxPitch = 80;
        public float crosshairSize = 18, crosshairThickness = 2;
        private CursorLockMode _savedLock;
        private bool _savedVisible, _active;
        private GameObject _crosshair;
        private EntityManualControl _manual;
        private EntityJumpMotor _jump;
        private float _pitch;
        public float Pitch => _pitch;
        private int _captureFrame;
        private bool _acceptAttack;
        public void Begin(EntityManualControl manual, Transform planet, float height, float distance)
        {
            _manual = manual;
            _jump = manual.GetComponent<EntityJumpMotor>() ?? manual.gameObject.AddComponent<EntityJumpMotor>();
            _jump.Bind(planet);
            _pitch = 0; // ★ 修复（防Bug回归）：第一人称进入时平视，滚轮不能改变眼位。
            _savedLock = Cursor.lockState; _savedVisible = Cursor.visible; _active = true;CursorReleased=false;
            SetCaptured(true);
            if (ServiceLocator.TryGet<UIRoot>(out var root) && root.MainCanvas != null)
            {
                _crosshair = UIFactory.NewRect("EntityCrosshair", root.MainCanvas.transform);
                var rt = _crosshair.GetComponent<RectTransform>();
                rt.anchorMin = rt.anchorMax = rt.pivot = new Vector2(.5f, .5f);
                rt.sizeDelta = new Vector2(crosshairSize, crosshairSize);
                AddLine("Horizontal", new Vector2(crosshairSize, crosshairThickness));
                AddLine("Vertical", new Vector2(crosshairThickness, crosshairSize));
            }
        }
        private void AddLine(string name, Vector2 size)
        {
            var line = UIFactory.NewRect(name, _crosshair.transform, typeof(Image));
            var rt = line.GetComponent<RectTransform>(); rt.anchorMin = rt.anchorMax = new Vector2(.5f,.5f); rt.sizeDelta = size;
            line.GetComponent<Image>().color = Color.white; line.GetComponent<Image>().raycastTarget = false;
        }
        public void Tick(bool blocked, Vector3 up, ref Vector3 forward, ref float height, ref float distance, float minDistance, float maxDistance)
        {
            if (!_active) return;
            // ★ 修复（防Bug回归）：Alt 是按住释放、松开恢复；不能沿用切换开关造成松键后仍无法操控。
            SetCursorReleased(ControlBindings.Held(ControlAction.ReleaseCursor));
            bool running=!ServiceLocator.TryGet<SimulationClock>(out var clock)||clock.IsRunning;
            blocked |= !Application.isFocused || GameInputGate.Blocked || CursorReleased;
            SetCaptured(!blocked);
            if (_crosshair != null) _crosshair.SetActive(!blocked&&running);
            _acceptAttack=!blocked&&running&&Time.frameCount>_captureFrame+1;
            if (blocked||!running) { _manual.SetInput(Vector3.zero, false);_manual.ClearAttack(); return; }
            // ★ 修复（防Bug回归）：刚锁鼠标时的居中位移不代表玩家转向，跳过捕获后的前两帧。
            if (Time.frameCount > _captureFrame + 1)
            {
                forward = Quaternion.AngleAxis(Input.GetAxis("Mouse X") * lookSensitivity, up) * forward;
                _pitch = Mathf.Clamp(_pitch - Input.GetAxis("Mouse Y") * lookSensitivity, minPitch, maxPitch);
            }
            // ★ 修复（防Bug回归）：锁定第一人称，禁用滚轮拉远。
            float y = (Input.GetKey(forwardKey) ? 1 : 0) - (Input.GetKey(backKey) ? 1 : 0);
            float x = (Input.GetKey(rightKey) ? 1 : 0) - (Input.GetKey(leftKey) ? 1 : 0);
            if(_acceptAttack && ControlBindings.Down(ControlAction.Attack))_manual.QueueAttack();
            if(!running)_manual.ClearAttack();
            // ★ 适配：准星始终对应真实相机中心射线，自身碰撞体由独立选取器排除。
            if(Camera.main!=null)_manual.SetAim(Camera.main.ViewportPointToRay(new Vector3(.5f,.5f,0)));
            _manual.SetInput(forward * y + Vector3.Cross(up, forward) * x, _acceptAttack && ControlBindings.Held(ControlAction.Attack));
            if (running && Input.GetKeyDown(jumpKey)) _jump.TryJump(_manual.CanMove);
        }
        public void SetCursorReleased(bool held){if(!_active||CursorReleased==held)return;CursorReleased=held;_manual?.SetInput(Vector3.zero,false);_manual?.ClearAttack();SetCaptured(!held);}
        private void OnGUI()
        {
            // ★ 修复（防Bug回归）：低帧率时按下/松开可能发生在同一帧，补收事件并锁存一次攻击。
            var evt=Event.current;var attack=ControlBindings.Get(ControlAction.Attack);
            if(_active && _acceptAttack && !GameInputGate.Blocked && Application.isFocused && (evt.type==EventType.MouseDown && evt.button==attackMouseButton || evt.type==EventType.KeyDown && evt.keyCode==attack))
                _manual?.QueueAttack();
        }
        private void SetCaptured(bool captured)
        {
            var desired = captured ? CursorLockMode.Locked : CursorLockMode.None;
            if (Cursor.lockState != desired)
            { Cursor.lockState = desired; if (captured) _captureFrame = Time.frameCount; }
            Cursor.visible = !captured;
        }
        // ★ 适配：暂停菜单释放鼠标但保留当前第一人称目标，返回时继续同一视角。
        public void Suspend(){_acceptAttack=false;_manual?.SetInput(Vector3.zero,false);_manual?.ClearAttack();SetCaptured(false);if(_crosshair!=null)_crosshair.SetActive(false);}
        public void End()
        {
            if (!_active) return;
            // ★ 修复（防Bug回归）：停用输入也清除待消费攻击，防止失焦/重新进入后补打一击。
            _active = false; _acceptAttack = false; _manual?.SetInput(Vector3.zero, false); _manual?.ClearAttack(); _jump?.Cancel();
            Cursor.lockState = _savedLock; Cursor.visible = _savedVisible;
            if (_crosshair != null) { _crosshair.SetActive(false); Destroy(_crosshair); _crosshair = null; }
        }
        private void OnApplicationFocus(bool focused)
        { if (_active && !focused) { SetCaptured(false); _acceptAttack = false; _manual?.SetInput(Vector3.zero, false); _manual?.ClearAttack(); } }
        private void OnDisable() => End();
    }
}

using UnityEngine;
using UnityEngine.UI;
using System.Collections.Generic;
using DarwinPark.Core;
using DarwinPark.Entities;
using DarwinPark.Genetics;

namespace DarwinPark.UI
{
    public class EntitySpawnPanel : MonoBehaviour
    {
        public GameObject DefaultEntityPrefab;

        private Transform _templateGridParent;

        private void Start()
        {
            BuildUI();
            EntityTemplateManager.OnTemplatesChanged += RefreshTemplates;
            RefreshTemplates();
        }

        private void OnDestroy()
        {
            EntityTemplateManager.OnTemplatesChanged -= RefreshTemplates;
        }

        private void BuildUI()
        {
            // ================= 左侧：生成与收藏 =================
            var leftSec = UIFactory.NewRect("LeftSec", transform);
            var lrt = leftSec.GetComponent<RectTransform>();
            lrt.anchorMin = new Vector2(0, 0);
            lrt.anchorMax = new Vector2(0, 1);
            lrt.offsetMin = new Vector2(10, 5);
            lrt.offsetMax = new Vector2(80, -5);    // 宽度 70

            var leftVlg = leftSec.AddComponent<VerticalLayoutGroup>();
            leftVlg.spacing = 10; // 两个按钮之间的间距
            leftVlg.childAlignment = TextAnchor.MiddleCenter;
            leftVlg.childControlHeight = false;
            leftVlg.childControlWidth = false; // 让按钮保持 70x70

            // 1. 默认生成槽 (70x70)
            CreateSpawnSlot(leftSec.transform, "默认生成\n点击或拖拽", DefaultEntityPrefab, null);

            // 2. 收藏列表按钮 (70x70)
            CreateFavoritesButton(leftSec.transform);

            // ================= 分隔线 1 =================
            CreateDivider(transform, 90);

            // ================= 中间：模板区域 (两行四列) =================
            var templateSec = UIFactory.NewRect("TemplateSec", transform);
            var trt = templateSec.GetComponent<RectTransform>();
            trt.anchorMin = new Vector2(0, 0);
            trt.anchorMax = new Vector2(0, 1);
            trt.offsetMin = new Vector2(100, 5);
            // 宽度 = 4列 * 70 + 3个间距 * 10 = 310
            trt.offsetMax = new Vector2(100 + 310, -5);

            var grid = templateSec.AddComponent<GridLayoutGroup>();
            grid.cellSize = new Vector2(70, 70); // ★ 模板 70x70
            grid.spacing = new Vector2(10, 10);
            grid.constraint = GridLayoutGroup.Constraint.FixedColumnCount;
            grid.constraintCount = 4;
            grid.childAlignment = TextAnchor.MiddleCenter;

            _templateGridParent = templateSec.transform;
            // ★ 适配：全星球随机投放由独立栏负责，保留原有默认、收藏与模板放置入口。
            RandomSpawnPanel.Attach(transform);
        }

        private void CreateSpawnSlot(Transform parent, string label, GameObject prefab, Genome customGenome)
        {
            var slotGO = UIFactory.NewRect("SpawnSlot", parent, typeof(Image), typeof(EntitySpawnerUI));
            var rt = slotGO.GetComponent<RectTransform>();
            rt.sizeDelta = new Vector2(70, 70);

            // ★ 适配：仅替换槽位表面，保留底栏第二页布局。
            UIVisualTheme.Paint(slotGO.GetComponent<Image>(),"button");
            var spawner = slotGO.GetComponent<EntitySpawnerUI>();
            spawner.entityPrefab = prefab;
            spawner.CustomGenome = customGenome;

            var txt = UIFactory.NewText("Txt", slotGO.transform, label, 12, TextAnchor.MiddleCenter); // 字号稍微小一点适应 70x70
            UIFactory.Stretch(txt.rectTransform);
        }

        private void CreateFavoritesButton(Transform parent)
        {
            var favBtnGO = UIFactory.NewRect("FavBtn", parent, typeof(Image), typeof(Button));
            var frt = favBtnGO.GetComponent<RectTransform>();
            frt.sizeDelta = new Vector2(70, 70);
            UIVisualTheme.StyleButton(favBtnGO.GetComponent<Button>());

            var favBtn = favBtnGO.GetComponent<Button>();
            favBtn.onClick.AddListener(() => {
                if (EntityFavoritesManager.Instance != null)
                {
                    EntityFavoritesManager.Instance.TogglePanel();
                }
                else Log.Error(Log.Tag.UI, "收藏列表不可用：场景缺少 EntityFavoritesManager");
            });

            var favTxt = UIFactory.NewText("Txt", favBtnGO.transform, "收藏列表", 12, TextAnchor.LowerCenter);
            UIFactory.Stretch(favTxt.rectTransform,2,6);
            UIVisualTheme.AddIcon(favBtnGO.transform,"star",new Vector2(28,28),new Vector2(0,9),new Vector2(.5f,.5f)).color=UIVisualTheme.Muted;
        }

        private void RefreshTemplates()
        {
            if (_templateGridParent == null) return;

            foreach (Transform child in _templateGridParent) Destroy(child.gameObject);

            for (int i = 0; i < 8; i++)
            {
                if (i < EntityTemplateManager.Templates.Count)
                {
                    CreateTemplateButton(EntityTemplateManager.Templates[i]);
                }
                else
                {
                    var emptyGO = UIFactory.NewRect("EmptyTpl", _templateGridParent, typeof(Image));
                    UIVisualTheme.Paint(emptyGO.GetComponent<Image>(),"button");
                    emptyGO.GetComponent<Image>().color=new Color(1,1,1,.4f);
                }
            }
        }

        private void CreateTemplateButton(EntityTemplateData tpl)
        {
            var btnGO = UIFactory.NewRect("Tpl_" + tpl.templateName, _templateGridParent, typeof(Image), typeof(Button), typeof(EntitySpawnerUI));
            var img = btnGO.GetComponent<Image>();
            UIVisualTheme.Paint(img,"button");

            var sprite = UIIconRegistry.Get(tpl.iconId);
            if (sprite != null)
            {
                // ★ 适配：模板图标不充当按钮底图，悬停皮肤切换不会覆盖或拉伸图标。
                UIVisualTheme.AddIcon(btnGO.transform,tpl.iconId,new Vector2(34,34),Vector2.zero,new Vector2(.5f,.5f));
            }

            var textGO = UIFactory.NewText("Tooltip", btnGO.transform, tpl.templateName, 12, TextAnchor.MiddleCenter);
            UIFactory.Stretch(textGO.rectTransform);
            textGO.gameObject.SetActive(false);

            var trigger = btnGO.AddComponent<UnityEngine.EventSystems.EventTrigger>();
            var enter = new UnityEngine.EventSystems.EventTrigger.Entry { eventID = UnityEngine.EventSystems.EventTriggerType.PointerEnter };
            enter.callback.AddListener((data) => { textGO.gameObject.SetActive(true); });
            trigger.triggers.Add(enter);

            var exit = new UnityEngine.EventSystems.EventTrigger.Entry { eventID = UnityEngine.EventSystems.EventTriggerType.PointerExit };
            exit.callback.AddListener((data) => { textGO.gameObject.SetActive(false); });
            trigger.triggers.Add(exit);

            var spawner = btnGO.GetComponent<EntitySpawnerUI>();
            spawner.entityPrefab = DefaultEntityPrefab;
            spawner.CustomGenome = ConvertToGenome(tpl.genes);
        }

        private Genome ConvertToGenome(List<GeneInstanceData> genes)
        {
            var genome = new Genome();
            foreach (var g in genes)
            {
                genome.Add(GeneInstance.Create(g.definitionId, g.value, g.tier));
            }
            return genome;
        }

        private void CreateDivider(Transform parent, float xOffset)
        {
            var div = UIFactory.NewRect("Divider", parent, typeof(Image));
            var rt = div.GetComponent<RectTransform>();
            rt.anchorMin = new Vector2(0, 0.1f);
            rt.anchorMax = new Vector2(0, 0.9f);
            rt.pivot = new Vector2(0, 0.5f);
            rt.offsetMin = new Vector2(xOffset, 0);
            rt.offsetMax = new Vector2(xOffset + 2, 0);
            div.GetComponent<Image>().color = UIVisualTheme.Border;
        }
    }
}

using UnityEngine;
using UnityEngine.EventSystems;
using DarwinPark.Genetics;
using DarwinPark.Core;

namespace DarwinPark.UI
{
    public class EntitySpawnerUI : MonoBehaviour, IBeginDragHandler, IDragHandler, IEndDragHandler, IPointerClickHandler
    {
        public GameObject entityPrefab;
        public float spawnHeight = 8f;
        public float ghostHeight = 3f;
        public int placementCount=1, maxPlacementCount=200;
        public float batchSpacing=2f;
        [HideInInspector] public Genome CustomGenome;
        private GameObject _ghostObj;
        private bool _dragging;

        // ★ 适配：单击原来没有处理器；把新点击投放交互交给独立工具，原拖拽继续有效。
        public void OnPointerClick(PointerEventData data)
        {
            if(!WorldAuthority.CanEdit)return;
            // ★ 新增：数量配置属于当前默认/模板槽位，右键设置后可连续左键投放。
            if(data.button==PointerEventData.InputButton.Right){PlacementQuantityPopup.Show(this);return;}
            if (data.button != PointerEventData.InputButton.Left || data.dragging) return;
            var tool = EntityPlacementTool.Instance;
            if (tool == null) { Log.Error(Log.Tag.UI, "场景缺少 EntityPlacementTool"); return; }
            tool.BeginPlacement(entityPrefab, CustomGenome,Mathf.Clamp(placementCount,1,maxPlacementCount));
        }
        public void OnBeginDrag(PointerEventData data)
        {
            if(!WorldAuthority.CanEdit)return;
            if (data.button != PointerEventData.InputButton.Left || entityPrefab == null) return;
            // ★ 适配：拖拽投放同样先释放手动控制。
            EntityViewController.Instance?.ExitView();
            EntityPlacementTool.Instance?.CancelPlacement();
            _dragging = true; OrbitCamera.IsDraggingUI = true;
            // ★ 修复（防Bug回归）：只复制网格外观，预览不运行实体脚本，不污染实体注册表。
            _ghostObj = EntityPlacementUtility.CreatePreview(entityPrefab);
            if (_ghostObj != null) _ghostObj.SetActive(false);
        }
        public void OnDrag(PointerEventData data)
        {
            if (!_dragging || _ghostObj == null) return;
            bool valid = !EntityPlacementUtility.IsPointerOverUI(data.position) && EntityPlacementUtility.TryGetSurface(Camera.main, data.position, out _, out _);
            _ghostObj.SetActive(valid);
            if (valid && EntityPlacementUtility.TryGetSurface(Camera.main,data.position,out var point,out var outward))
            { _ghostObj.transform.position = point + outward * ghostHeight; _ghostObj.transform.up = outward; }
        }
        public void OnEndDrag(PointerEventData data)
        {
            if (!_dragging) return;
            _dragging = false; OrbitCamera.IsDraggingUI = false;
            EntityPlacementUtility.DestroyPreview(_ghostObj); _ghostObj = null;
            // ★ 修复（防Bug回归）：松手仍在 UI/射线未命中指定星球时不能生成；距离使用相机裁剪面。
            if (EntityPlacementUtility.IsPointerOverUI(data.position)) return;
            if (EntityPlacementUtility.TryGetSurface(Camera.main, data.position, out var point, out var outward))
                EntityPlacementUtility.SpawnBatch(CustomGenome,point,outward,spawnHeight,Mathf.Clamp(placementCount,1,maxPlacementCount),batchSpacing);
        }
        private void OnDisable()
        {
            if (_dragging) OrbitCamera.IsDraggingUI = false;
            _dragging = false; EntityPlacementUtility.DestroyPreview(_ghostObj); _ghostObj = null;
        }
    }
}

using System.Linq;
using DarwinPark.Entities;
using DarwinPark.Entities.Ecology;
using DarwinPark.Genetics;

namespace DarwinPark.UI
{
    // ★ 新增：运行活动状态与基因倾向分别展示，注册表名称始终是唯一文案来源。
    public static class EntityStatePresentation
    {
        public static string Current(DarwinEntity entity)
        {
            // ★ 适配：蚁群优先显示实际分工活动，避免工匠运输仍被标为普通巡逻。
            if(ColonyStatusPresentation.TryCurrent(entity,out string colony))return NutritionStatusPresentation.Append(entity,colony);
            var controller=entity.GetComponent<EntityStateController>();
            return NutritionStatusPresentation.Append(entity,controller!=null?controller.Current.displayName:EntityStateRegistry.Current.Get(EntityStateRegistry.Current.defaultStateId).displayName);
        }
        public static string GeneTags(GeneDefinition gene)
        {
            if(gene.EntityStateTags.Count==0)return "";
            return "实体状态标签："+string.Join(" / ",gene.EntityStateTags.Select(id=>EntityStateRegistry.Current.Get(id).displayName));
        }
    }
}

using System.Collections.Generic;
using System.IO;
using System.Linq;
