namespace DarwinPark.UI
{
    [System.Serializable]
    public class EntityTemplateData
    {
        public string templateName;
        public string iconId;
        public string baseEntityJsonId; // 保留字段，如果以后有更高级的json生成
        public List<GeneInstanceData> genes = new List<GeneInstanceData>();
    }

    public static class EntityTemplateManager
    {
        // ★ 修复（防Bug回归）：进程/播放会话重启后首次访问从磁盘读取，不能只保留静态内存列表。
        private static List<EntityTemplateData> _templates = new List<EntityTemplateData>();
        private static bool _loaded;
        private static void EnsureLoaded(){if(_loaded)return;_templates=EntityTemplateStore.Load();_loaded=true;}
        public static IReadOnlyList<EntityTemplateData> Templates {get{EnsureLoaded();return _templates;}}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void Reset(){_templates=new List<EntityTemplateData>();_loaded=false;OnTemplatesChanged=null;}

        // 保存事件，通知 UI 刷新
        public static event System.Action OnTemplatesChanged;

        public static void SaveTemplate(DarwinEntity entity)
        {
            if(!DarwinPark.Core.WorldAuthority.CanEdit)return;
            EnsureLoaded();
            if(entity==null)return;
            var genes = entity.GetComponent<EntityGeneController>();
            if (genes == null || genes.Genome == null) return;

            var data = new EntityTemplateData
            {
                templateName = entity.DisplayName,
                iconId = "entity_template_default", // 默认图标ID，你可以根据基因判断赋予不同ID
                genes = new List<GeneInstanceData>()
            };

            foreach (var g in genes.Genome.Genes)
            {
                data.genes.Add(new GeneInstanceData
                {
                    definitionId = g.DefinitionId,
                    value = g.Value,
                    tier = g.Tier
                });
            }

            // ★ 修复（防Bug回归）：实际写盘成功后才更新列表/通知界面，失败不误报“保存成功”或丢掉原模板。
            var next=new List<EntityTemplateData>(_templates);
            int index=next.FindIndex(t=>t.templateName==data.templateName);
            if(index>=0)next[index]=data;else next.Add(data);
            try{EntityTemplateStore.Save(next);}
            catch(System.Exception ex) when(ex is System.IO.IOException||ex is System.UnauthorizedAccessException||ex is System.ArgumentException)
            {Debug.LogError("[Template] 模板保存失败，原模板保留："+ex.Message);return;}
            _templates=next;
            Debug.Log($"[Template] 已保存模板：{data.templateName}");

            OnTemplatesChanged?.Invoke();
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using DarwinPark.Core;
using UnityEngine;

namespace DarwinPark.UI
{
    // ★ 修复（防Bug回归）：模板属于跨世界资料，必须独立落盘；同目录原子替换和备份避免退出/写入中断丢失已有模板。
    public static class EntityTemplateStore
    {
        [Serializable] private sealed class Document
        {
            public int version;
            public List<EntityTemplateData> templates;
        }
        public static string FilePath=>Path.Combine(GamePaths.Root,"templates","entities.json");
        private static void Validate(Document document)
        {
            if(document==null||document.version!=1||document.templates==null)throw new InvalidDataException("模板格式或版本无效");
            var names=new HashSet<string>();
            foreach(var template in document.templates)
            {
                if(template==null||string.IsNullOrWhiteSpace(template.templateName)||!names.Add(template.templateName)||template.genes==null)throw new InvalidDataException("模板名称重复或数据缺失");
                foreach(var gene in template.genes)
                    if(gene==null||string.IsNullOrWhiteSpace(gene.definitionId)||float.IsNaN(gene.value)||float.IsInfinity(gene.value))throw new InvalidDataException("模板基因无效："+template.templateName);
            }
        }
        private static List<EntityTemplateData> Read(string path)
        {
            var document=JsonUtility.FromJson<Document>(File.ReadAllText(path,Encoding.UTF8));Validate(document);return document.templates;
        }
        public static List<EntityTemplateData> Load(string path=null)
        {
            path=path??FilePath;
            if(File.Exists(path))
            {
                try{return Read(path);}
                catch(Exception ex) when(ex is IOException||ex is UnauthorizedAccessException||ex is ArgumentException)
                {Debug.LogWarning("[Template] 模板读取失败，尝试备份："+path+"；"+ex.Message);}
            }
            if(File.Exists(path+".bak"))
            {
                try{return Read(path+".bak");}
                catch(Exception ex) when(ex is IOException||ex is UnauthorizedAccessException||ex is ArgumentException)
                {Debug.LogWarning("[Template] 备份读取失败，原文件已保留："+ex.Message);}
            }
            return new List<EntityTemplateData>();
        }
        public static void Save(List<EntityTemplateData> templates,string path=null)
        {
            var document=new Document{version=1,templates=templates};Validate(document);path=path??FilePath;
            // ★ 修复（防Bug回归）：主文件损坏而从备份恢复时，保存不能用损坏主文件覆盖最后一份有效备份。
            bool validPrimary=false;
            if(File.Exists(path))try{Read(path);validPrimary=true;}catch(Exception ex) when(ex is IOException||ex is UnauthorizedAccessException||ex is ArgumentException){Debug.LogWarning("[Template] 覆盖损坏主文件，保留备份："+ex.Message);}
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path)));string temporary=path+".tmp";
            using(var stream=new FileStream(temporary,FileMode.Create,FileAccess.Write,FileShare.None))
            using(var writer=new StreamWriter(stream,new UTF8Encoding(false))){writer.Write(JsonUtility.ToJson(document,true));writer.Flush();stream.Flush(true);}
            if(File.Exists(path))File.Replace(temporary,path,validPrimary?path+".bak":null);else File.Move(temporary,path);
        }
    }
}

using DarwinPark.Core;
using DarwinPark.Entities;
using DarwinPark.Entities.Stats;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace DarwinPark.UI
{
    /// <summary>★ 新增：双击实体进入锁定第一人称视角；输入、跟随和退出恢复独立于轨道相机。</summary>
    [DefaultExecutionOrder(200)]
    [RequireComponent(typeof(EntityPossessionInput))]
    public sealed class EntityViewController : MonoBehaviour
    {
        public static EntityViewController Instance { get; private set; }
        public DarwinEntity Target { get; private set; }
        public float doubleClickInterval = .35f;
        public float followDistance = 8, followHeight = 4, aimHeight = .5f;
        public float shoulderOffset=1.2f, aimForwardOffset=2f;
        public float minFollowDistance = 3, maxFollowDistance = 25, cameraClearance = .5f;
        public KeyCode exitKey = KeyCode.Escape;
        public LayerMask pickMask = ~0;
        private Camera _camera;
        private OrbitCamera _orbit;
        private EntityManualControl _manual;
        private Vector3 _savedPosition, _forward;
        private Quaternion _savedRotation;
        private Transform _planet;
        private MeshCollider _terrain;
        private float _distance, _height, _lastClickTime = -10;
        private DarwinEntity _lastClicked;
        private bool _active;
        private EntityPossessionInput _input;
        private EntityFirstPersonCamera _firstPerson;
        private void Awake() { Instance = this; _input = GetComponent<EntityPossessionInput>(); _firstPerson = gameObject.AddComponent<EntityFirstPersonCamera>();
            // ★ 适配：无界面的Q输入独立接入，不再安装免费生成补给的按钮工具。
            if(GetComponent<EnergyBlockInput>()==null)gameObject.AddComponent<EnergyBlockInput>(); }
        private void Update()
        {
            if (_active && (Target == null || !Target.isActiveAndEnabled ||
                (Target.GetComponent<EntityStats>() is EntityStats stats && stats.TryGet("health",out float hp) && hp <= 0)))
            { ExitView(); return; }
            if (GameInputGate.Blocked) return;
            bool typing = IsTyping();
            // ★ 适配：有暂停菜单时 Esc 专用于暂停，Tab 退出实体操控，防止锁鼠标后无法返回轨道视角。
            // ★ 适配：退出实体视角与设置页绑定一致，Esc继续专用于菜单。
            var viewExitKey = ControlBindings.Get(ControlAction.ExitView);
            if (_active && Input.GetKeyDown(viewExitKey)) { ExitView(); return; }
            bool overUI = EventSystem.current != null && EventSystem.current.IsPointerOverGameObject();
            bool placing = OrbitCamera.IsDraggingUI || (EntityPlacementTool.Instance != null && EntityPlacementTool.Instance.IsPlacing);
            if (!_active && !WorldAuthority.RtsMode && !typing && !overUI && !placing && Input.GetMouseButtonDown(0))
            {
                var camera = Camera.main;
                if (camera != null && Physics.Raycast(camera.ScreenPointToRay(Input.mousePosition),out var hit,camera.farClipPlane,pickMask,QueryTriggerInteraction.Ignore))
                    RegisterClick(hit.collider.GetComponentInParent<DarwinEntity>(),Time.unscaledTime);
                else RegisterClick(null,Time.unscaledTime);
            }
            if (!_active) return;
            // ★ 适配：捕获鼠标后左键只攻击，准星不参与 UI 射线，世界双击拾取不再抢占。
            bool blocked = typing || placing;
            Vector3 up = (Target.transform.position-_planet.position).normalized;
            _forward = Vector3.ProjectOnPlane(_forward,up).normalized;
            if (_forward.sqrMagnitude < .01f) _forward = Vector3.ProjectOnPlane(Vector3.forward,up).normalized;
            _input.Tick(blocked,up,ref _forward,ref _height,ref _distance,minFollowDistance,maxFollowDistance);
        }
        // ★ 新增：同一实体的双击才切换，UI/空白点击不会沿用上一次命中。
        public void RegisterClick(DarwinEntity entity, float time)
        {
            bool twice = entity != null && entity == _lastClicked && time-_lastClickTime <= doubleClickInterval && time >= _lastClickTime;
            _lastClicked = entity; _lastClickTime = time;
            if (twice) { _lastClicked = null; EnterView(entity); }
        }
        public bool EnterView(DarwinEntity entity)
        {
            if (entity == null || !entity.isActiveAndEnabled) return false;
            // ★ 适配：联机选择先经服务端分配，成员不能借双击切换到其他玩家实体。
            if(LanSession.Instance?.AllowView(entity)==false)return false;
            var camera = Camera.main; var orbit = camera != null ? camera.GetComponent<OrbitCamera>() : null;
            if (orbit == null || orbit.target == null) { Log.Error(Log.Tag.UI,"实体视角需要主相机与星球轨道目标"); return false; }
            if (entity.GetComponent<Rigidbody>() == null || entity.GetComponent<EntityGeneController>() == null) return false;
            if (_active) ExitView();
            EntityPlacementTool.Instance?.CancelPlacement();
            _camera = camera; _orbit = orbit; _planet = orbit.target; _terrain = _planet.GetComponent<MeshCollider>();
            _savedPosition = camera.transform.position; _savedRotation = camera.transform.rotation;
            _forward = Vector3.ProjectOnPlane(camera.transform.up,(entity.transform.position-_planet.position).normalized).normalized;
            _distance = followDistance; _height = followHeight;
            Target = entity; _manual = entity.GetComponent<EntityManualControl>() ?? entity.gameObject.AddComponent<EntityManualControl>();
            _manual.BeginControl(_planet); _active = true; _orbit.EntityViewActive = true;
            // ★ 适配：清理旧输入框焦点，进入时立即锁鼠标并生成准星。
            EventSystem.current?.SetSelectedGameObject(null);
            _input.Begin(_manual,_planet,_height,_distance);
            // ★ 适配：锁定眼位，不再用偏肩追随镜头。
            _firstPerson.Begin(entity, camera);
            // ★ 修复（防Bug回归）：按用户要求不创建操控提示栏或按钮，仅保留键盘操作。
            return true;
        }
        private void LateUpdate()
        {
            if (!_active || Target == null || _camera == null || _planet == null) return;
            Vector3 up = (Target.transform.position-_planet.position).normalized;
            Vector3 forward = Vector3.ProjectOnPlane(_forward,up).normalized;
            // ★ 适配：最终相机和攻击射线由同一个眼位/朝向生成。
            _firstPerson.Apply(up,forward,_input.Pitch,_manual);
        }
        public void ExitView()
        {
            if (!_active) return;
            _active = false;
            _input?.End();
            _firstPerson?.End();
            if (_manual != null) _manual.Release();
            if (_orbit != null) _orbit.EntityViewActive = false;
            // ★ 修复（防Bug回归）：操控后实体已经离开出生处，退出应对准其当前位置，不能恢复旧镜头而丢失实体。
            if (_orbit != null && Target != null) _orbit.ReturnToEntity(Target.transform.position);
            else if (_camera != null) _camera.transform.SetPositionAndRotation(_savedPosition,_savedRotation);
            Target = null; _manual = null; _lastClicked = null;
        }
        private static bool IsTyping()
        {
            var selected = EventSystem.current != null ? EventSystem.current.currentSelectedGameObject : null;
            return selected != null && selected.GetComponentInParent<InputField>() is InputField input && input.isFocused;
        }
        private void OnDisable() => ExitView();
        private void OnDestroy() { ExitView(); if (Instance == this) Instance = null; }
    }
}

using DarwinPark.Core;
using UnityEngine;

namespace DarwinPark.UI
{
    // ★ 新增：使用真实帧耗时采样，模拟倍率和暂停不改变FPS；只画标签，不拦截鼠标或生成逐帧日志。
    public sealed class FrameRateDisplay : MonoBehaviour
    {
        public Vector2 offset=new Vector2(12,10),size=new Vector2(190,28);
        public float sampleInterval=.5f,panelGap=8,simulationLineHeight=18;
        public int fontSize=16;
        [Range(0,1)] public float backgroundOpacity=.18f;
        public static FrameRateDisplay Instance {get;private set;}
        public float CurrentFps {get;private set;}
        public int SampleCount {get;private set;}
        public string DisplayText {get;private set;}="FPS —";
        private float _elapsed,_simulated;private int _frames;private GUIStyle _style,_fpsStyle,_simulationStyle;private string _simulationText;
        public Rect DisplayRect=>new Rect(offset,new Vector2(size.x,size.y+(string.IsNullOrEmpty(_simulationText)?0:simulationLineHeight)));
        private void Awake()=>Instance=this;
        private void Update()
        {
            ServiceLocator.TryGet<SimulationClock>(out var clock);_simulated+=clock!=null?clock.GameDeltaTime:0;
            _elapsed+=Time.unscaledDeltaTime;_frames++;if(_elapsed<Mathf.Max(.1f,sampleInterval))return;
            // ★ 修复（防Bug回归）：低于1帧时保留小数，避免长帧被四舍五入成FPS 0掩盖真实采样。
            CurrentFps=_frames/_elapsed;string fps=CurrentFps<1?CurrentFps.ToString("F2"):CurrentFps.ToString("F0");DisplayText=$"FPS {fps}  |  {_elapsed*1000/_frames:F1} ms";
            // ★ 适配：高倍率超出机器承载时显示实际完成倍率和待算时间，不能把限速后的画面误报为满速16倍。
            _simulationText=clock!=null&&clock.IsRunning&&clock.PendingGameTime>clock.maximumGameDelta?$"模拟 {_simulated/_elapsed:F1}× · 待算 {clock.PendingGameTime:F1}s":null;
            SampleCount++;_elapsed=0;_frames=0;_simulated=0;
        }
        private void OnApplicationFocus(bool focused){_elapsed=0;_frames=0;_simulated=0;}
        private void OnDestroy(){if(Instance==this)Instance=null;}
        public static Vector2 ReserveTop(Vector2 desired,Canvas canvas)
        {
            var display=Instance;if(display==null||!display.isActiveAndEnabled)return desired;
            float scale=canvas!=null?canvas.scaleFactor:1;
            desired.y=Mathf.Min(desired.y,-(display.DisplayRect.yMax+display.panelGap)/Mathf.Max(.01f,scale));return desired;
        }
        private void OnGUI()
        {
            if(_style==null)
            {
                _style=new GUIStyle{font=UIFactory.DefaultFont,fontSize=fontSize,alignment=TextAnchor.MiddleLeft,padding=new RectOffset(8,8,0,0),border=new RectOffset(12,12,12,12)};
                _style.normal.textColor=UIVisualTheme.Accent;_style.normal.background=UIVisualTheme.SurfaceSprite("panel")?.texture;
                _fpsStyle=new GUIStyle(_style);_fpsStyle.normal.background=null;
                _simulationStyle=new GUIStyle(_style){fontSize=12};_simulationStyle.normal.background=null;
            }
            int depth=GUI.depth;var color=GUI.color;GUI.depth=-2000;GUI.color=Color.white;
            // ★ 修复（防Bug回归）：仅背景半透明，文字保持清晰；0可完全取消背景，不再遮挡世界。
            var rect=DisplayRect;var background=GUI.backgroundColor;GUI.backgroundColor=new Color(1,1,1,backgroundOpacity);
            if(backgroundOpacity>0)GUI.Box(rect,GUIContent.none,_style);GUI.backgroundColor=background;GUI.Label(new Rect(offset,size),DisplayText,_fpsStyle);
            if(!string.IsNullOrEmpty(_simulationText))GUI.Label(new Rect(offset.x,offset.y+size.y-2,size.x,simulationLineHeight),_simulationText,_simulationStyle);
            GUI.depth=depth;GUI.color=color;
        }
    }
}

