        private bool EnsurePanel()
        {
            if (_panel != null) return true;
            if (!ServiceLocator.TryGet<UIRoot>(out var root) || root == null || root.MainCanvas == null) return false;
            BuildPanel(root.MainCanvas.transform);
            _panel.SetActive(false);
