        private void OnFavoriteClicked()
        {
            if (_currentEntity != null && EntityFavoritesManager.Instance != null)
            {
                EntityFavoritesManager.Instance.ToggleFavorite(_currentEntity);
                UpdateFavBtnVisual();
            }
