            float x=stats.offsetMax.x+gap,available=parent.rect.width-x-12;
            WideLayout=available>=minimumWidth;float width=WideLayout?Mathf.Min(preferredWidth,available):Mathf.Min(preferredWidth,parent.rect.width-24);
