            var inputGO = UIFactory.NewRect("ValueInput", transform, typeof(Image), typeof(InputField));
            var irt = inputGO.GetComponent<RectTransform>();
            irt.anchorMin = irt.anchorMax = new Vector2(0, 0); irt.pivot = Vector2.zero;
            irt.anchoredPosition = new Vector2(12, 38); irt.sizeDelta = new Vector2(112, 28);
            // ★ 适配：参数输入沿用原位置与应用流程，只换共用输入框皮肤。
            UIVisualTheme.Paint(inputGO.GetComponent<Image>(),"field");
            _input = inputGO.GetComponent<InputField>();
            var text = UIFactory.NewText("Text", inputGO.transform, initial, 16);
            UIFactory.Stretch(text.rectTransform, 8, 2); _input.textComponent = text;
            _input.contentType = seed ? InputField.ContentType.IntegerNumber : InputField.ContentType.DecimalNumber;
            _input.text = initial;
            float min = seed ? seedSliderMin : terrain?landPercentRange.x:temp ? temperatureMin : 0;
            float max = seed ? seedSliderMax : terrain?landPercentRange.y:temp ? temperatureMax : 100;
            float.TryParse(initial, NumberStyles.Float, CultureInfo.InvariantCulture, out float current);
            _slider = UIFactory.NewSlider("Parameter", transform, "", min, max, current, 252, out _);
            var row = _slider.transform.parent.GetComponent<RectTransform>();
            row.anchorMin = row.anchorMax = Vector2.zero; row.pivot = Vector2.zero;
            row.anchoredPosition = new Vector2(136, 36);
            var sliderRect = _slider.GetComponent<RectTransform>();
            sliderRect.offsetMin = new Vector2(4,4); sliderRect.offsetMax = new Vector2(-4,-4);
            _slider.wholeNumbers = seed;
            _slider.onValueChanged.AddListener(v => {
                _input.SetTextWithoutNotify(v.ToString(seed ? "F0" : "F1", CultureInfo.InvariantCulture));
                // ★ 修复（防Bug回归）：应用后再次改值必须恢复待提交状态，不能仍显示“已应用”。
                if (_status != null) _status.text = "待应用（Shift）";
            });
            _input.onValueChanged.AddListener(v => {
                if (_status != null) _status.text = "待应用（Shift）";
                if (float.TryParse(v, NumberStyles.Float, CultureInfo.InvariantCulture, out float f) && !float.IsNaN(f) && !float.IsInfinity(f))
                    _slider.SetValueWithoutNotify(f);
            });
            var apply = UIFactory.NewButton("Apply", transform, "应用（Shift）", Apply, new Vector2(112,25));
            UIVisualTheme.StyleButton(apply,true);
            apply.GetComponentInChildren<Text>().fontSize = 14;
            var art = apply.GetComponent<RectTransform>(); art.anchorMin = art.anchorMax = Vector2.zero;
            art.pivot = Vector2.zero; art.anchoredPosition = new Vector2(276,7);
            _status = UIFactory.NewText("Status", transform, "修改后按 Shift 应用", 12);
            var srt = _status.rectTransform; srt.anchorMin = srt.anchorMax = Vector2.zero;
            srt.pivot = Vector2.zero; srt.anchoredPosition = new Vector2(12,7); srt.sizeDelta = new Vector2(255,25);
        }
        private void Update()
        {
            if(_waiting&&WorldParameterUpdate.Instance?.Busy!=true){_status.text=WorldParameterUpdate.Instance?.LastStatus??"更新已结束";_waiting=false;}
            // ★ 适配：工具中的 Shift/回车不能提交背景游戏面板。
            if(DarwinPark.Core.GameInputGate.Blocked)return;
            // ★ 修复（防Bug回归）：右键取消独立处理，拖动滑条或点击内容不会销毁未提交草稿。
            if(Input.GetMouseButtonDown(1)||Input.GetKeyDown(KeyCode.Escape)){CancelRequested?.Invoke();return;}
            if (Input.GetKeyDown(KeyCode.LeftShift) || Input.GetKeyDown(KeyCode.RightShift)) Apply();
        }
        private void OnGUI()
        {
            if(DarwinPark.Core.GameInputGate.Blocked)return;
            // ★ 修复（防Bug回归）：输入框聚焦或按键在低帧率内快速按下/抬起时，逐个键盘事件也要接收 Shift。
            var key = Event.current;
            if (key.type == EventType.KeyDown && (key.shift || key.keyCode == KeyCode.LeftShift || key.keyCode == KeyCode.RightShift))
                Apply();
        }
        public void Apply()
        {
            if(!WorldAuthority.CanEdit||GameInputGate.Blocked)return;
            string raw=_input.text;
            if(_id.Contains("seed"))
            {if(!int.TryParse(raw,NumberStyles.Integer,CultureInfo.InvariantCulture,out _)){_status.text="请输入有效的32位整数种子";return;}}
            else
            {
                if(!float.TryParse(raw,NumberStyles.Float,CultureInfo.InvariantCulture,out float value)||!float.IsFinite(value)){_status.text="请输入有效数字";return;}
                raw=Mathf.Clamp(value,_slider.minValue,_slider.maxValue).ToString("F1",CultureInfo.InvariantCulture);_input.SetTextWithoutNotify(raw);
            }
            // ★ 适配：统一使用后台更新入口，客户端保留完整整数文本，不经float丢失32位种子精度。
            bool applied=LanEditActions.Submit(new LanCommand{kind="parameter",parameter=_id,name=raw});
            _waiting=applied&&!WorldAuthority.IsReplica&&WorldParameterUpdate.Instance?.Busy==true;
            _status.text=!applied?"参数未应用":WorldAuthority.IsReplica?"已请求管理员更新":_waiting?"正在更新":WorldParameterUpdate.Instance?.LastStatus??"已应用";
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using DarwinPark.Core;
using DarwinPark.Entities;
using DarwinPark.Entities.Ecology;
using UnityEngine;

namespace DarwinPark.UI
{
    public sealed class PopulationChartValue {public string Label;public int Count;public Color Color;}
    // ★ 新增：基因按实体去重；扇形图是携带人次构成，个体携带率单独列出，避免把多基因比例误当互斥分类。
    public static class PopulationDistributions
    {
        public static List<PopulationChartValue> Genes(string id,bool expressed)
        {
            var record=PopulationArchive.Find(id);var counts=new Dictionary<string,int>();var members=PopulationArchive.Members(id);
            if(members.Count>0)foreach(var entity in members)
            {
                var ids=expressed?entity.Genes.Evaluation.Genes.Where(g=>g.IsActive).Select(g=>g.Definition.Id):entity.Genes.Genome.Genes.Select(g=>g.DefinitionId);
                foreach(string gene in ids.Distinct()){counts.TryGetValue(gene,out int count);counts[gene]=count+1;}
            }
            else if(record!=null)foreach(var gene in record.genes)counts[gene.id]=expressed?gene.expressed:gene.carried;
            return counts.Where(p=>p.Value>0).OrderByDescending(p=>p.Value).ThenBy(p=>p.Key).Select(p=>new PopulationChartValue{Label=Genetics.GeneDatabase.Get(p.Key)?.DisplayName??p.Key,Count=p.Value,Color=ColonyAppearance.DefaultColorFor(p.Key)}).ToList();
        }
        public static List<PopulationChartValue> Ages(string id)
        {
            var record=PopulationArchive.Find(id);var members=PopulationArchive.Members(id);int infants,adults,elders;
            if(members.Count>0){infants=members.Count(e=>e.Genes.CurrentAge==AgeState.Infant);adults=members.Count(e=>e.Genes.CurrentAge==AgeState.Adult);elders=members.Count-infants-adults;}
            else{infants=record?.infants??0;adults=record?.adults??0;elders=record?.elders??0;}
            return new List<PopulationChartValue>{new PopulationChartValue{Label="幼年",Count=infants,Color=new Color(.3f,.85f,.6f)},new PopulationChartValue{Label="成年",Count=adults,Color=new Color(.3f,.65f,1)},new PopulationChartValue{Label="老年",Count=elders,Color=new Color(1,.65f,.3f)}};
        }
    }
    // ★ 新增：图表是游戏原生UI，按数据签名更新扇形贴图；关闭窗口后不继续生成图形。
    public sealed class PopulationCharts:IDisposable
    {
        private Texture2D _pie;private string _signature;
        public void Draw(Rect area,IReadOnlyList<PopulationChartValue> values,bool pie,float labelWidth=140)
        {
            if(values.Sum(v=>v.Count)==0){GUI.Label(area,"暂无可统计数据");return;}
            if(pie)
            {
                string signature=string.Join("|",values.Select(v=>v.Label+":"+v.Count+":"+v.Color));
                if(_pie==null||_signature!=signature){BuildPie(values);_signature=signature;}
                float side=Mathf.Min(area.width,area.height);GUI.DrawTexture(new Rect(area.x+(area.width-side)/2,area.y,side,side),_pie,ScaleMode.ScaleToFit,true);return;
            }
            // ★ 适配：发展历史改用年月日后需更宽的标签区域，避免日期覆盖柱形。
            labelWidth=Mathf.Min(labelWidth,Mathf.Max(0,area.width-100));
            float maximum=Mathf.Max(1,values.Max(v=>v.Count)),row=Mathf.Max(22,Mathf.Min(32,area.height/values.Count));
            for(int i=0;i<values.Count;i++)
            {
                var value=values[i];float y=area.y+i*row;GUI.Label(new Rect(area.x,y,labelWidth,row),value.Label);
                var old=GUI.color;GUI.color=value.Color;GUI.DrawTexture(new Rect(area.x+labelWidth+5,y+5,Mathf.Max(1,(area.width-labelWidth-65)*value.Count/maximum),row-10),Texture2D.whiteTexture);GUI.color=old;
                GUI.Label(new Rect(area.xMax-54,y,54,row),value.Count.ToString());
            }
        }
        private void BuildPie(IReadOnlyList<PopulationChartValue> values)
        {
            const int size=256;var pixels=new Color[size*size];float sum=values.Sum(v=>v.Count);var cumulative=new List<float>();float total=0;
            foreach(var value in values){total+=value.Count/sum;cumulative.Add(total);}
            for(int y=0;y<size;y++)for(int x=0;x<size;x++)
            {
                Vector2 p=new Vector2(x+.5f-size*.5f,y+.5f-size*.5f);float distance=p.magnitude;if(distance>size*.5f)continue;
                float angle=Mathf.Repeat(Mathf.Atan2(p.y,p.x)/(2*Mathf.PI)+.25f,1);int slice=0;while(slice<cumulative.Count-1&&angle>cumulative[slice])slice++;
                var color=values[slice].Color;color.a=Mathf.Clamp01(size*.5f-distance);pixels[y*size+x]=color;
            }
            if(_pie==null)_pie=new Texture2D(size,size,TextureFormat.RGBA32,false){name="种群分布图",filterMode=FilterMode.Bilinear};_pie.SetPixels(pixels);_pie.Apply();
        }
        public void Dispose(){if(_pie!=null)UnityEngine.Object.Destroy(_pie);_pie=null;}
    }
}

using System;
