Shader "DarwinPark/PlanetAtmosphere"
{
    Properties
    {
        _AtmosphereColor ("Atmosphere Color", Color) = (0.3, 0.6, 1.0, 1.0)
        _RimPower ("Rim Power", Float) = 3.0
    }
    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" "RenderPipeline"="UniversalPipeline" }
        Blend SrcAlpha OneMinusSrcAlpha 
        ZWrite Off 
        Cull Off // ★ 改为双面，保证任何角度都能看到大气光晕

        Pass
        {
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            struct Attributes
            {
                float4 positionOS : POSITION;
                float3 normalOS : NORMAL;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float3 normalWS : TEXCOORD0;
                float3 viewDirWS : TEXCOORD1;
            };

            CBUFFER_START(UnityPerMaterial)
                float4 _AtmosphereColor;
                float _RimPower;
            CBUFFER_END

            Varyings vert(Attributes input)
            {
                Varyings output;
                VertexPositionInputs vertexInput = GetVertexPositionInputs(input.positionOS.xyz);
                output.positionCS = vertexInput.positionCS;
                output.normalWS = TransformObjectToWorldNormal(input.normalOS);

                float3 cameraPos = GetCameraPositionWS();
                output.viewDirWS = normalize(cameraPos - vertexInput.positionWS);
                return output;
            }

            half4 frag(Varyings input) : SV_Target
            {
                float3 normalWS = normalize(input.normalWS);
                float3 viewDirWS = normalize(input.viewDirWS);

                // 菲涅尔边缘发光
                float rim = 1.0 - saturate(abs(dot(normalWS, viewDirWS)));
                rim = pow(rim, _RimPower);

                // 乘一个基础亮度，确保边缘够亮
                float alpha = rim * _AtmosphereColor.a * 1.5;
                alpha = saturate(alpha);

                return half4(_AtmosphereColor.rgb, alpha);
            }
            ENDHLSL
        }
    }
}

Shader "DarwinPark/PlanetAtmosphere"
{
    Properties
    {
        _AtmosphereColor ("Atmosphere Color", Color) = (0.3, 0.6, 1.0, 0.5)
        _RimPower ("Rim Power", Float) = 3.0
    }
    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" "RenderPipeline"="UniversalPipeline" }
        Blend SrcAlpha OneMinusSrcAlpha // 标准透明混合
        ZWrite Off // 不写深度，防止遮挡星球
        Cull Back

        Pass
        {
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            struct Attributes
            {
                float4 positionOS : POSITION;
                float3 normalOS : NORMAL;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float3 normalWS : TEXCOORD0;
                float3 viewDirWS : TEXCOORD1;
            };

            CBUFFER_START(UnityPerMaterial)
                float4 _AtmosphereColor;
                float _RimPower;
            CBUFFER_END

            Varyings vert(Attributes input)
            {
                Varyings output;
                VertexPositionInputs vertexInput = GetVertexPositionInputs(input.positionOS.xyz);
                output.positionCS = vertexInput.positionCS;
                output.normalWS = TransformObjectToWorldNormal(input.normalOS);

                // 计算视线方向
                float3 cameraPos = GetCameraPositionWS();
                output.viewDirWS = normalize(cameraPos - vertexInput.positionWS);
                return output;
            }

            half4 frag(Varyings input) : SV_Target
            {
                float3 normalWS = normalize(input.normalWS);
                float3 viewDirWS = normalize(input.viewDirWS);

                // 菲涅尔效应：只有球体的边缘（Rim）才会发光
                float rim = 1.0 - saturate(dot(normalWS, viewDirWS));
                rim = pow(rim, _RimPower);

                float alpha = rim * _AtmosphereColor.a;

                return half4(_AtmosphereColor.rgb, alpha);
            }
            ENDHLSL
        }
    }
}

Shader "DarwinPark/PlanetCloudVolume"
{
 Properties {
 _BottomRadius("Cloud base",Float)=350
 _TopRadius("Cloud top",Float)=355
 _Coverage("Coverage",Range(0,1))=.48
 _Frequency("Weather scale",Float)=5
 _Detail("Cloud detail",Float)=28
 _Density("Density",Float)=1.7
 _Steps("Ray steps",Float)=12
 }
 SubShader {
 Tags {"RenderType"="Transparent" "Queue"="Transparent-10" "RenderPipeline"="UniversalPipeline"}
 // ★ 修复（防Bug回归）：用背面代理与场景深度积分，避免前壳与山峰相交形成硬三角切口。
 Blend One OneMinusSrcAlpha ZWrite Off Cull Front ZTest Always
 Pass {
 HLSLPROGRAM
 #pragma target 3.5
 #pragma vertex vert
 #pragma fragment frag
 #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
 #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"
 #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareDepthTexture.hlsl"
 CBUFFER_START(UnityPerMaterial)
 float _BottomRadius,_TopRadius,_Coverage,_Frequency,_Detail,_Density,_Steps;
 CBUFFER_END
 struct A{float4 p:POSITION;};
 struct V{float4 p:SV_POSITION;float3 local:TEXCOORD0;};
 V vert(A i){V o;o.p=TransformObjectToHClip(i.p.xyz);o.local=i.p.xyz;return o;}
 float hash(float3 p){p=frac(p*.1031);p+=dot(p,p.yzx+33.33);return frac((p.x+p.y)*p.z);}
 float noise(float3 p){float3 a=floor(p),f=frac(p); f=f*f*(3-2*f);return lerp(lerp(lerp(hash(a),hash(a+float3(1,0,0)),f.x),lerp(hash(a+float3(0,1,0)),hash(a+float3(1,1,0)),f.x),f.y),lerp(lerp(hash(a+float3(0,0,1)),hash(a+float3(1,0,1)),f.x),lerp(hash(a+float3(0,1,1)),hash(a+1),f.x),f.y),f.z);}
 float fbm(float3 p){return noise(p)*.57+noise(p*2.03+7.1)*.28+noise(p*4.1+13.5)*.15;}
 float density(float3 p){
  float3 d=normalize(p);
  // ★ 新增：球面三维采样无经线接缝；低频天气场经旋流扭曲，细节侵蚀云体边缘。
  float swirl=fbm(d*2.7+19)*1.8;
  float3 q=d*_Frequency+float3(d.z,0,-d.x)*swirl;
  float weather=fbm(q);
  float detail=fbm(d*_Detail+weather*4);
  float cloud=smoothstep(1-_Coverage,1-_Coverage+.17,weather+(detail-.5)*.3);
  float h=saturate((length(p)-_BottomRadius)/max(.01,_TopRadius-_BottomRadius));
  return cloud*smoothstep(0,.2,h)*(1-smoothstep(.65,1,h));
 }
 float2 sphere(float3 o,float3 d,float r){float b=dot(o,d),c=dot(o,o)-r*r;float h=b*b-c;if(h<0)return float2(-1,-1);h=sqrt(h);return float2(-b-h,-b+h);}
 half4 frag(V i):SV_Target{
  float3 origin=TransformWorldToObject(GetCameraPositionWS());
  float3 dir=normalize(i.local-origin);
  float2 outer=sphere(origin,dir,_TopRadius);
  float2 inner=sphere(origin,dir,_BottomRadius);
  float start=max(0,outer.x),end=outer.y;
  if(inner.x>start)end=min(end,inner.x);
  float2 uv=GetNormalizedScreenSpaceUV(i.p);
  float depth=SampleSceneDepth(uv);
  #if !UNITY_REVERSED_Z
   depth=lerp(UNITY_NEAR_CLIP_VALUE,1,depth);
  #endif
  float3 scene=TransformWorldToObject(ComputeWorldSpacePosition(uv,depth,UNITY_MATRIX_I_VP));
  end=min(end,length(scene-origin));
  float stride=min((end-start)/_Steps,(_TopRadius-_BottomRadius)*.65);
  if(stride<=0)return 0;
  float3 light=normalize(TransformWorldToObjectDir(GetMainLight().direction));
  float alpha=0; float3 color=0;
  [loop]for(int n=0;n<(int)_Steps;n++){
   float3 p=origin+dir*(start+(n+.5)*stride);
   float den=density(p);
   float shadow=density(p+light*(_TopRadius-_BottomRadius)*.65);
   float sunlight=smoothstep(-.15,.45,dot(normalize(p),light));
   float shade=lerp(.68,1.15,exp(-shadow*1.2))*lerp(.3,1,sunlight);
   float a=1-exp(-den*_Density*stride/max(.01,_TopRadius-_BottomRadius));
   color+=(1-alpha)*a*float3(.94,.97,1)*shade;
   alpha+=(1-alpha)*a;
   if(alpha>.96)break;
  }
  return half4(color,alpha);
 }
 ENDHLSL
 }
 }
}

Shader "DarwinPark/PlanetOcean"
{
 Properties {
  _ShallowColor("Shallow water", Color)=(.12,.62,.82,1)
  _DeepColor("Deep water", Color)=(.015,.13,.32,1)
  _LayerMode("Layer",Float)=0
  _ClimateReady("Climate ready",Float)=0
  _ClimateMap("Climate",2D)="gray"{}
  _OreMap("Ore",2D)="black"{}
 }
 SubShader {
 Tags {"RenderType"="Opaque" "Queue"="Geometry+1" "RenderPipeline"="UniversalPipeline"}
 Pass {
 ZWrite On Cull Back
 HLSLPROGRAM
 #pragma vertex vert
 #pragma fragment frag
 #pragma target 3.5
 #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
 #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"
 #include "Terrain/PopulationRangeOverlay.hlsl"
 struct A {float4 positionOS:POSITION; float3 normalOS:NORMAL; float4 color:COLOR;};
 struct V {float4 positionCS:SV_POSITION; float3 positionOS:TEXCOORD0; float3 normalWS:TEXCOORD1; float depth:TEXCOORD2;};
 CBUFFER_START(UnityPerMaterial)
 float4 _ShallowColor,_DeepColor; float _LayerMode,_ClimateReady;
 CBUFFER_END
 TEXTURE2D(_ClimateMap); SAMPLER(sampler_ClimateMap);
 TEXTURE2D(_OreMap); SAMPLER(sampler_OreMap);
 V vert(A i) { V o; o.positionCS=TransformObjectToHClip(i.positionOS.xyz); o.positionOS=i.positionOS.xyz; o.normalWS=TransformObjectToWorldNormal(i.normalOS);o.depth=i.color.r;return o; }
 half4 frag(V i):SV_Target {
  float3 d=normalize(i.positionOS);
  float2 uv=float2(atan2(d.x,d.z)/6.2831853+.5,asin(clamp(d.y,-1,1))/3.14159265+.5);
  float3 color=lerp(_ShallowColor.rgb,_DeepColor.rgb,smoothstep(0,1,i.depth));
  if(_LayerMode>2.5) return half4(lerp(float3(.02,.02,.02),float3(1,.85,0),SAMPLE_TEXTURE2D(_OreMap,sampler_OreMap,uv).r),1);
  if(_LayerMode>1.5 && _ClimateReady>.5) color=SAMPLE_TEXTURE2D(_ClimateMap,sampler_ClimateMap,uv).rgb;
  float light=saturate(dot(normalize(i.normalWS),GetMainLight().direction));
  // ★ 适配：范围跨海岸时水面也显示同一合并区域，避免被海面盖掉形成缺口。
  return half4(ApplyPopulationRange(color*lerp(.55,1.12,light),i.positionOS),1);
 }
 ENDHLSL
 }
  // ★ 修复（防Bug回归）：天气积分需要地形/海面的真实深度，深度预通道也必须绘制这些不透明表面。
 UsePass "Universal Render Pipeline/Lit/DepthOnly"
 UsePass "Universal Render Pipeline/Lit/DepthNormals"
}
}

Shader "DarwinPark/PlanetScattering"
{
 Properties {
 _SurfaceRadius("Sea radius",Float)=340
 _OuterRadius("Atmosphere radius",Float)=375
 _Density("Optical density",Float)=.08
 _ScatterColor("Rayleigh color",Color)=(.2,.52,1,1)
 }
 SubShader {
 Tags {"RenderType"="Transparent" "Queue"="Transparent+10" "RenderPipeline"="UniversalPipeline"}
 // ★ 修复（防Bug回归）：背面代理覆盖整条视线，近距离进入气壳时仍可渲染；遮挡由真实深度截断。
 Blend One OneMinusSrcAlpha ZWrite Off Cull Front ZTest Always
 Pass {
 HLSLPROGRAM
 #pragma vertex vert
 #pragma target 3.5
 #pragma fragment frag
 #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
 #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"
 #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareDepthTexture.hlsl"
 CBUFFER_START(UnityPerMaterial)
 float _SurfaceRadius,_OuterRadius,_Density;float4 _ScatterColor;
 CBUFFER_END
 struct A{float4 p:POSITION;};struct V{float4 p:SV_POSITION;float3 local:TEXCOORD0;};
 V vert(A i){V o;o.p=TransformObjectToHClip(i.p.xyz);o.local=i.p.xyz;return o;}
 half4 frag(V i):SV_Target{
  float3 origin=TransformWorldToObject(GetCameraPositionWS()),ray=normalize(i.local-origin);
  float b=dot(origin,ray),c=dot(origin,origin),h=b*b-c+_OuterRadius*_OuterRadius;
  if(h<=0)return 0;
  float start=max(0,-b-sqrt(h)),end=-b+sqrt(h);
  float ground=b*b-c+_SurfaceRadius*_SurfaceRadius;
  if(ground>0 && -b-sqrt(ground)>0)end=min(end,-b-sqrt(ground));
  float2 uv=GetNormalizedScreenSpaceUV(i.p);
  float depth=SampleSceneDepth(uv);
  #if !UNITY_REVERSED_Z
   depth=lerp(UNITY_NEAR_CLIP_VALUE,1,depth);
  #endif
  float3 scene=TransformWorldToObject(ComputeWorldSpacePosition(uv,depth,UNITY_MATRIX_I_VP));
  end=min(end,length(scene-origin));
  float step=max(0,end-start)/8;
  float scale=max(.1,(_OuterRadius-_SurfaceRadius)*.18);
  float optical=0;float3 light=normalize(TransformWorldToObjectDir(GetMainLight().direction));
  // ★ 新增：沿视线积分指数密度；外缘路径长度趋零，避免旧 Fresnel 球壳出现硬蓝圈。
  [unroll]for(int n=0;n<8;n++){
   float3 p=origin+ray*(start+(n+.5)*step);
   float daylight=smoothstep(-.25,.4,dot(normalize(p),light));
   optical+=exp(-max(0,length(p)-_SurfaceRadius)/scale)*step/scale*lerp(.12,1,daylight);
  }
  float alpha=saturate(1-exp(-optical*_Density));
  return half4(_ScatterColor.rgb*alpha,alpha);
 }
 ENDHLSL
 }
 }
}

Shader "DarwinPark/PlanetSurface"
{
    Properties {}
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        LOD 100
        Cull Off // ★ 关键：关闭背面剔除，解决星球缺口

        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"

            struct appdata
            {
                float4 vertex : POSITION;
                float3 normal : NORMAL;
                float4 color : COLOR;
            };

            struct v2f
            {
                float4 vertex : SV_POSITION;
                float3 normal : TEXCOORD0;
                float4 color : COLOR;
                float3 worldPos : TEXCOORD1;
            };

            v2f vert (appdata v)
            {
                v2f o;
                o.vertex = UnityObjectToClipPos(v.vertex);
                o.normal = UnityObjectToWorldNormal(v.normal);
                o.color = v.color;
                o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz;
                return o;
            }

            fixed4 frag (v2f i) : SV_Target
            {
                // 基础顶点色（代码里根据高度生成的）
                fixed4 col = i.color;

                // 如果顶点色是白的，就根据高度给个颜色兜底
                if(col.r > 0.95 && col.g > 0.95 && col.b > 0.95) {
                     col = fixed4(0.4, 0.6, 0.4, 1); // 陆地绿
                }

                // 简单的方向光照
                float3 lightDir = normalize(_WorldSpaceLightPos0.xyz);
                // Cull Off 会导致法线翻转，取绝对值确保两面都能受光
                float ndl = max(0.0, abs(dot(normalize(i.normal), lightDir)));

                // ★ 增强基础环境光，防止背面死黑
                col.rgb *= (0.3 + 0.7 * ndl); 

                return col;
            }
            ENDCG
        }
    }
}

Shader "DarwinPark/URP_PlanetSurface"
{
    Properties
    {
        // ★ 新增：图三风格地形配色与高度阈值独立配置，气候图层仍使用真实气候数据。
        _DetailScale ("Surface detail scale", Float) = 85
        _DetailStrength ("Surface detail strength", Range(0,1)) = 0.35
        _NearDetailDensity ("Near detail per metre", Float) = 4
        _NearDetailStrength ("Near detail contrast", Range(0,1)) = 0.45
        _NearDetailFade ("Near detail fade metres", Vector) = (20,100,0,0)
        _LowlandColor ("Lowland", Color) = (0.43, 0.68, 0.30, 1)
        _HillColor ("Foothills", Color) = (0.72, 0.72, 0.39, 1)
        _RockColor ("Mountain rock", Color) = (0.60, 0.32, 0.16, 1)
        _PeakColor ("Peak", Color) = (0.90, 0.93, 0.94, 1)
        _ElevationBands ("Elevation bands", Vector) = (0.08, 0.23, 0.36, 0.62)
        _SeaLevel ("Sea Level", Float) = 0.45
        _PlanetRadius ("Planet Radius", Float) = 300.0
        _HeightScale ("Height Scale", Float) = 90.0
        _MaxHeight ("Max Normalized Height", Float) = 1.0
        _LayerMode ("Layer Mode", Float) = 0 
        _OreMap ("Ore Map", 2D) = "black" {} 
        _ClimateMap ("Climate Map", 2D) = "gray" {} 
        _ClimateReady ("Climate Ready", Float) = 0
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" "RenderPipeline"="UniversalPipeline" }
        LOD 100
        Pass
        {
            Name "ForwardLit"
            Tags { "LightMode"="UniversalForward" }
            Cull Off 
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma target 3.5
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"

            #include "Terrain/PlanetSurfaceDetail.hlsl"
            #include "Terrain/PlanetNearSurfaceDetail.hlsl"
            #include "Terrain/PopulationRangeOverlay.hlsl"

            struct Attributes { float4 positionOS : POSITION; float3 normalOS : NORMAL; };
            struct Varyings { float4 positionCS : SV_POSITION; float3 normalWS : TEXCOORD0; float3 viewDirWS : TEXCOORD1; float3 positionWS : TEXCOORD2; float3 positionOS : TEXCOORD3; };

            CBUFFER_START(UnityPerMaterial)
                float4 _LowlandColor, _HillColor, _RockColor, _PeakColor, _ElevationBands;
                float _DetailScale, _DetailStrength;
                float _NearDetailDensity, _NearDetailStrength;
                float4 _NearDetailFade;
                float _SeaLevel; 
                float _PlanetRadius;
                float _HeightScale;
                float _MaxHeight;
                float _LayerMode;
                float _ClimateReady;
            CBUFFER_END

            TEXTURE2D(_OreMap); SAMPLER(sampler_OreMap);
            TEXTURE2D(_ClimateMap); SAMPLER(sampler_ClimateMap);

            Varyings vert(Attributes input)
            {
                Varyings output;
                VertexPositionInputs vertexInput = GetVertexPositionInputs(input.positionOS.xyz);
                VertexNormalInputs normalInput = GetVertexNormalInputs(input.normalOS);
                output.positionCS = vertexInput.positionCS;
                output.normalWS = normalInput.normalWS;
                output.viewDirWS = GetCameraPositionWS() - vertexInput.positionWS;
                output.positionWS = vertexInput.positionWS;
                // ★ 修复：UV 不能在顶点里算完再插值。等距柱状投影在 x=0,z<0
                // 的经线处 u 从 ~1 跳回 ~0，跨接缝的三角形会把整张气候图
                // 横向压缩进一条窄带，形成一条笔直的“断层”。改为把物体空间
                // 坐标传到片元，在片元里逐像素求 UV。
                output.positionOS = input.positionOS.xyz;
                return output;
            }

            float2 SphereUVFromDirection(float3 dir)
            {
                dir = normalize(dir);
                float u = atan2(dir.x, dir.z) / (2.0 * 3.14159265) + 0.5;
                float v = asin(clamp(dir.y, -1.0, 1.0)) / 3.14159265 + 0.5;
                return float2(u, v);
            }

            half4 frag(Varyings input) : SV_Target
            {
                float3 normalWS = normalize(input.normalWS);
                float3 viewDirWS = normalize(input.viewDirWS);
                if (dot(normalWS, viewDirWS) < 0.0) normalWS = -normalWS;

                float2 sphereUV = SphereUVFromDirection(input.positionOS);

                // ★ 核心修复：使用动态传入的半径和高度倍数
                // ★ 修复（防Bug回归）：高度与地形生成共用本地空间，星球移动不应把整片陆地变成高山雪地。
                float distanceToCenter = length(input.positionOS);
                float heightRatio = (distanceToCenter - _PlanetRadius) / _HeightScale; 

                float seaLevel = _SeaLevel;
                float3 surfaceColor = float3(0,0,0);
                bool isMapLayer = false; 

                if (_LayerMode < 0.5) // === 0: 默认地形 ===
                {
                    if (heightRatio < seaLevel) {
                        // 海洋
                        surfaceColor = lerp(float3(0.1, 0.3, 0.6), float3(0.02, 0.05, 0.2), smoothstep(seaLevel, 0.0, heightRatio));
                    } else {
                        // ★ 修复（防Bug回归）：默认地形应呈现山系/低地层次，不能用气候纹理把所有山地刷成同一绿色。
                        float landH = saturate((heightRatio - seaLevel) / max(0.01, _MaxHeight - seaLevel));
                        // ★ 适配：连续三维微地貌为平原、山脊增加地表层次；只修饰颜色，不改变真实气候与碰撞。
                        float detail = SurfaceDetail(normalize(input.positionOS), _DetailScale);
                        float reliefH = saturate(landH + (detail - .5) * _DetailStrength * .22);
                        surfaceColor = lerp(_LowlandColor.rgb, _HillColor.rgb,
                            smoothstep(_ElevationBands.x, _ElevationBands.y, reliefH));
                        surfaceColor = lerp(surfaceColor, _RockColor.rgb,
                            smoothstep(_ElevationBands.y, _ElevationBands.z, reliefH));
                        surfaceColor = lerp(surfaceColor, _PeakColor.rgb,
                            smoothstep(_ElevationBands.z, _ElevationBands.w, reliefH));
                        surfaceColor *= lerp(1.0 - _DetailStrength, 1.0 + _DetailStrength * .25, detail);
                        float beach = 1.0 - smoothstep(0.0, 0.012, heightRatio - seaLevel);
                        surfaceColor = lerp(surfaceColor, float3(.80,.77,.52), beach*.55);
                    }
                }
                else if (_LayerMode < 1.5) // === 1: 高程图 ===
                {
                    isMapLayer = true;
                    if (heightRatio < seaLevel) {
                        surfaceColor = lerp(float3(0.0, 0.0, 0.4), float3(0.1, 0.4, 0.8), heightRatio / seaLevel);
                    } else {
                        float t = saturate((heightRatio - seaLevel) / max(0.01, _MaxHeight - seaLevel));
                        // ★ 修复：旧版用 if/else 分四段硬切颜色，高程图会出现明显的等高线色带。
                        // 改成连续 lerp，山体起伏才能平滑显示。
                        float3 low = float3(0.2, 0.8, 0.2);      // 平原绿
                        float3 mid = float3(0.8, 0.8, 0.2);      // 丘陵黄
                        float3 high = float3(0.8, 0.4, 0.1);     // 高山橙
                        float3 peak = float3(1.0, 1.0, 1.0);     // 峰顶白
                        surfaceColor = lerp(low, mid, smoothstep(0.08, 0.30, t));
                        surfaceColor = lerp(surfaceColor, high, smoothstep(0.30, 0.62, t));
                        surfaceColor = lerp(surfaceColor, peak, smoothstep(0.68, 0.92, t));
                    }
                }
                else if (_LayerMode < 2.5) // === 2: 真实气候图 ===
                {
                    isMapLayer = true;
                    if (_ClimateReady > 0.5) {
                        // ★ 修复：气候图已经在 CPU 端平滑混合为连续颜色，Shader 不再用
                        // if/else 硬分类，从根源上消除色块断层。
                        surfaceColor = SAMPLE_TEXTURE2D(_ClimateMap, sampler_ClimateMap, sphereUV).rgb;
                    } else {
                        // 气候图尚未生成时的程序化兜底：连续色带，绝不能输出全白。
                        float latAbs = abs(normalize(input.positionOS).y);
                        // ★ 修复（防Bug回归）：浮点归一化的微小越界会让分数次pow收到负底数，发布版Shader编译也会告警。
                        float temp = lerp(32.0, -35.0, pow(saturate(1.0 - latAbs), 1.2));
                        temp -= saturate((heightRatio - seaLevel) / max(0.01, _MaxHeight - seaLevel)) * 25.0;
                        float hum = lerp(80.0, 40.0, latAbs);
                        float cold = 1.0 - smoothstep(-8.0, 6.0, temp);
                        float wet = smoothstep(30.0, 75.0, hum);
                        surfaceColor = lerp(float3(0.42, 0.58, 0.32), float3(0.18, 0.42, 0.22), wet);
                        surfaceColor = lerp(surfaceColor, float3(0.80, 0.71, 0.48), (1.0 - wet) * smoothstep(10.0, 28.0, temp));
                        surfaceColor = lerp(surfaceColor, float3(0.92, 0.94, 0.98), cold);
                    }
                }
                else // === 3: 矿石图 ===
                {
                    isMapLayer = true;
                    float oreAmount = SAMPLE_TEXTURE2D(_OreMap, sampler_OreMap, sphereUV).r;
                    // 确保底色纯黑，矿石纯黄
                    surfaceColor = lerp(float3(0.02, 0.02, 0.02), float3(1.0, 0.85, 0.0), oreAmount);
                }

                // ★ 适配：近看时叠加米级地表纹理；矿量等数据图层不添加颜色噪声。
                if (_LayerMode < .5 && heightRatio >= seaLevel)
                    surfaceColor = ApplyNearSurfaceDetail(surfaceColor,input.positionOS,length(input.viewDirWS),
                        _NearDetailDensity,_NearDetailStrength,_NearDetailFade.xy);
                Light mainLight = GetMainLight();
                float ndl = saturate(dot(normalWS, mainLight.direction));

                if (isMapLayer) {
                    // ★ 修复：数据图层也叠加轻微山体阴影，山脉/盆地不会因“无光照”而看起来是平的。
                    float mapShade = 0.78 + 0.22 * ndl;
                    return half4(surfaceColor * mapShade, 1.0);
                }

                // 将光照的乘算系数从 1.5 降到 1.0，防止过曝
                // ★ 修复（防Bug回归）：URP 光方向指向光源，旧符号反转把受光面变成黑坑。
                // 地图风格保留可读的环境照明，同时让山脊坡度清楚可辨。
                float3 litColor = surfaceColor * (0.60 + mainLight.color * ndl * 0.55);
                // ★ 适配：范围只在原地表最终颜色上透明混合，无额外球壳网格和共面闪烁。
                return half4(ApplyPopulationRange(litColor,input.positionOS), 1.0);
            }
            ENDHLSL
        }
     // ★ 修复（防Bug回归）：天气积分需要地形/海面的真实深度，深度预通道也必须绘制这些不透明表面。
 UsePass "Universal Render Pipeline/Lit/DepthOnly"
 UsePass "Universal Render Pipeline/Lit/DepthNormals"
}
}

// ★ 新增：以米为尺度的近景细节；三维采样跨面连续，导数抗锯齿防止拉远后闪烁。
#ifndef DARWIN_NEAR_SURFACE_DETAIL_INCLUDED
#define DARWIN_NEAR_SURFACE_DETAIL_INCLUDED
float NearSurfaceGrain(float3 p)
{
    float footprint = max(length(ddx(p)), length(ddy(p)));
    float fine = SurfaceNoise(p) - .5;
    float micro = SurfaceNoise(p * 3.07 + 11.3) - .5;
    return fine * saturate(1 - footprint) + micro * .35 * saturate(1 - footprint * 3.07);
}
float3 ApplyNearSurfaceDetail(float3 color, float3 positionOS, float distanceToCamera,
    float density, float strength, float2 fadeDistance)
{
    float fade = 1 - smoothstep(fadeDistance.x, fadeDistance.y, distanceToCamera);
    float grain = NearSurfaceGrain(positionOS * density);
    return color * (1 + grain * strength * fade);
}
#endif

// ★ 新增：球面三维细节，直接采样方向而不使用面 UV，避免重新引入经线/六面接缝。
#ifndef DARWIN_SURFACE_DETAIL_INCLUDED
#define DARWIN_SURFACE_DETAIL_INCLUDED
float SurfaceHash(float3 p)
{
    p = frac(p * .1031);
    p += dot(p, p.yzx + 33.33);
    return frac((p.x + p.y) * p.z);
}
float SurfaceNoise(float3 p)
{
    float3 a = floor(p), f = frac(p);
    f = f * f * (3 - 2 * f);
    return lerp(lerp(lerp(SurfaceHash(a), SurfaceHash(a + float3(1,0,0)), f.x),
        lerp(SurfaceHash(a + float3(0,1,0)), SurfaceHash(a + float3(1,1,0)), f.x), f.y),
        lerp(lerp(SurfaceHash(a + float3(0,0,1)), SurfaceHash(a + float3(1,0,1)), f.x),
        lerp(SurfaceHash(a + float3(0,1,1)), SurfaceHash(a + 1), f.x), f.y), f.z);
}
float SurfaceDetail(float3 direction, float scale)
{
    float3 p = direction * scale;
    return SurfaceNoise(p) * .57 + SurfaceNoise(p * 2.03 + 7.1) * .28
        + SurfaceNoise(p * 4.1 + 13.5) * .15;
}
#endif

// ★ 新增：同群各圆先求并集，再填色或绘制并集外沿；内侧重叠边界不会成为线条，也不叠加透明度。
TEXTURE2D(_PopulationData);
float _PopulationCount;
float4 _PopulationStyle; // x显示模式(0关/1填色/2边界)，y不透明度，z边界角宽

float3 ApplyPopulationRange(float3 color,float3 positionOS)
{
    if(_PopulationStyle.x<.5||_PopulationCount<.5)return color;
    float3 direction=normalize(positionOS);
    float distance=10,group=-1,opacity=0;float3 tint=0;
    float4 paint=0;
    [loop] for(int i=0;i<(int)_PopulationCount;i++)
    {
        float4 circle=LOAD_TEXTURE2D(_PopulationData,int2(0,i));
        float4 data=LOAD_TEXTURE2D(_PopulationData,int2(1,i));
        if(data.w!=group&&group>=0)
        {
            // ★ 适配：同群填色和外沿都使用该群不透明度，重叠圆不重复累积。
            float alpha=opacity*(_PopulationStyle.x<1.5?(distance<=0?1:0):1-smoothstep(_PopulationStyle.z,_PopulationStyle.z+max(fwidth(distance),.00001),abs(distance)));
            if(alpha>paint.a)paint=float4(tint,alpha);
            distance=10;
        }
        group=data.w;tint=data.rgb;opacity=LOAD_TEXTURE2D(_PopulationData,int2(2,i)).r;
        // 圆边界等价于dot=cos(radius)；只在边界附近换算线宽，不需要每像素acos。
        distance=min(distance,(circle.w-dot(direction,circle.xyz))/max(sqrt(saturate(1-circle.w*circle.w)),.0001));
    }
    float alpha=opacity*(_PopulationStyle.x<1.5?(distance<=0?1:0):1-smoothstep(_PopulationStyle.z,_PopulationStyle.z+max(fwidth(distance),.00001),abs(distance)));
    if(alpha>paint.a)paint=float4(tint,alpha);
    return lerp(color,paint.rgb,paint.a);
}

