landH = saturate((heightRatio - seaLevel) / max(0.01, _MaxHeight - seaLevel))
detail = SurfaceDetail(normalize(input.positionOS), _DetailScale)
reliefH = saturate(landH + (detail - .5) * _DetailStrength * .22)
surfaceColor = lerp(_LowlandColor.rgb, _HillColor.rgb, smoothstep(_ElevationBands.x, _ElevationBands.y, reliefH));
surfaceColor = lerp(surfaceColor, _RockColor.rgb, smoothstep(_ElevationBands.y, _ElevationBands.z, reliefH));
surfaceColor = lerp(surfaceColor, _PeakColor.rgb, smoothstep(_ElevationBands.z, _ElevationBands.w, reliefH));
surfaceColor *= lerp(1.0 - _DetailStrength, 1.0 + _DetailStrength * .25, detail);
beach = 1.0 - smoothstep(0.0, 0.012, heightRatio - seaLevel)
surfaceColor = lerp(surfaceColor, float3(.80,.77,.52), beach*.55);

t = saturate((heightRatio - seaLevel) / max(0.01, _MaxHeight - seaLevel))
low = float3(0.2, 0.8, 0.2)
mid = float3(0.8, 0.8, 0.2)
high = float3(0.8, 0.4, 0.1)
peak = float3(1.0, 1.0, 1.0)
surfaceColor = lerp(low, mid, smoothstep(0.08, 0.30, t));
surfaceColor = lerp(surfaceColor, high, smoothstep(0.30, 0.62, t));
surfaceColor = lerp(surfaceColor, peak, smoothstep(0.68, 0.92, t));

latAbs = abs(normalize(input.positionOS).y)
temp = lerp(32.0, -35.0, pow(saturate(1.0 - latAbs), 1.2))
temp -= saturate((heightRatio - seaLevel) / max(0.01, _MaxHeight - seaLevel)) * 25.0;
hum = lerp(80.0, 40.0, latAbs)
cold = 1.0 - smoothstep(-8.0, 6.0, temp)
wet = smoothstep(30.0, 75.0, hum)
surfaceColor = lerp(float3(0.42, 0.58, 0.32), float3(0.18, 0.42, 0.22), wet);
surfaceColor = lerp(surfaceColor, float3(0.80, 0.71, 0.48), (1.0 - wet) * smoothstep(10.0, 28.0, temp));
surfaceColor = lerp(surfaceColor, float3(0.92, 0.94, 0.98), cold);

