data = new PlanetTerrainData { Subdivisions = sub, Radius = cfg.radius, HeightScale = cfg.heightScale, FaceHeights = new float[6][] }

u = (float)x / sub * 2f - 1f
v = (float)y / sub * 2f - 1f
dir = FacePoint(FaceNormals[face], u, v).normalized
c = Noise01(continentNoise, dir)
heights[y * (sub + 1) + x] = c;
allHeights.Add(c);

allHeights.Sort();
landFraction = Mathf.Clamp01(continentRatio)
seaIndex = Mathf.FloorToInt((1.0f - landFraction) * allHeights.Count)
seaIndex = Mathf.Clamp(seaIndex, 0, allHeights.Count - 1);
seaLevelThreshold = allHeights[seaIndex]
landRange = Mathf.Max(0.0001f, allHeights[allHeights.Count - 1] - seaLevelThreshold)
data.SeaLevel = seaLevelThreshold;

floor = Mathf.Lerp( seaLevelThreshold * cfg.oceanFloorRatio, seaLevelThreshold, Mathf.Pow(oceanT, 1.8f))
floor += detailNoise.Sample(dir) * cfg.detailStrength * 0.4f * (1f - oceanT);
height = floor;

land = Mathf.Clamp01((c - seaLevelThreshold) / landRange)
baseHeight = seaLevelThreshold + cfg.coastalRise + cfg.inlandRise * Mathf.Pow(land, Mathf.Max(0.1f, cfg.inlandCurve))
baseHeight += detailNoise.Sample(dir) * cfg.detailStrength * (0.4f + land * 0.8f);
mountainMask = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(cfg.mountainStart, cfg.mountainFull, land))
headroom = Mathf.Max(0f, PlanetTerrainData.MaxNormalizedHeight - baseHeight)
baseHeight += mountains.Sample(dir) * cfg.mountainHeight * mountainMask * headroom;
basinNoiseValue = Noise01(basinNoise, dir)
basinMask = Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(cfg.basinThreshold, cfg.basinThreshold + cfg.basinWidth, basinNoiseValue))
baseHeight -= basinMask * cfg.basinDepth * (0.35f + land * 0.65f);
valleyRaw = valleyNoise.Sample(dir)
valley = Mathf.Pow(Mathf.Clamp01(1f - Mathf.Abs(valleyRaw)), Mathf.Max(0.5f, cfg.valleySharpness))
valleyMask = Mathf.SmoothStep(0.04f, 0.55f, land)
baseHeight -= valley * cfg.valleyDepth * valleyMask;
height = baseHeight;

